//! First closed AV1 leaf-block reconstruction class.
//!
//! This module is decoder-private codec machinery. It is deliberately not a
//! reusable transform, prediction, color-conversion, or raster-processing API.

// AV1 block coordinates are validated against the frame and tile geometry
// before reaching this module. The decoder then uses saturating/checked
// coordinate arithmetic together with bounded slice accessors while mirroring
// the specification's fixed-size block equations. Keep this exception local
// to the block decoder; it does not weaken the crate's no-raw-pointer policy.
#![allow(clippy::arithmetic_side_effects)]

use super::entropy::RangeDecoder;
use super::quantization;
use super::transform;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) struct PortableUnavailable;

pub(super) type PortableResult<T> = Result<T, PortableUnavailable>;

trait PortableOptionExt<T> {
    fn portable(self) -> PortableResult<T>;
}

impl<T> PortableOptionExt<T> for Option<T> {
    fn portable(self) -> PortableResult<T> {
        self.ok_or(PortableUnavailable)
    }
}

type TransformCoefficients = [i32; 16];
type PlaneCoefficients = [TransformCoefficients; 64];
type LossyTransformCoefficients = [i32; 64];
type Lossy4x8TransformCoefficients = [i32; 32];
type Lossy16x16TransformCoefficients = [i32; 256];
type Lossy32x32TransformCoefficients = [i32; 1024];
type Lossy16x32TransformCoefficients = [i32; 512];
type Lossy16x64TransformCoefficients = [i32; 512];
type LossyRectTransformCoefficients = [i32; 128];
type Lossy16x8TransformCoefficients = [i32; 128];
type Lossy8x32TransformCoefficients = [i32; 256];
type Lossy8x16TransformCoefficients = [i32; 128];
type Lossy4x16TransformCoefficients = [i32; 64];
type Lossy32x16TransformCoefficients = [i32; 512];
type Lossy64x16TransformCoefficients = [i32; 512];
type Lossy32x8TransformCoefficients = [i32; 256];
type Lossy16x4TransformCoefficients = [i32; 64];
type LossyLuma4x4SplitCoefficients = [Option<TransformCoefficients>; 4];
type LossyLuma8x8SplitCoefficients = [Option<LossyTransformCoefficients>; 4];
type LossyLuma8x8GridSplitCoefficients = [Option<LossyTransformCoefficients>; 8];
type LossyLuma16x16SplitCoefficients = [Option<Lossy16x16TransformCoefficients>; 4];

const PALETTE_CAPACITY: usize = 8;
const PALETTE_MAP_SAMPLES: usize = 1024;

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct PalettePlane {
    size: u8,
    colors: [u16; PALETTE_CAPACITY],
}

impl PalettePlane {
    const fn is_present(self) -> bool {
        self.size != 0
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(super) struct PaletteCacheState {
    y: PalettePlane,
    u: PalettePlane,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PaletteSyntax {
    y: PalettePlane,
    u: PalettePlane,
    v: PalettePlane,
    y_indices: [u8; PALETTE_MAP_SAMPLES],
    uv_indices: [u8; PALETTE_MAP_SAMPLES],
}

impl Default for PaletteSyntax {
    fn default() -> Self {
        Self {
            y: PalettePlane::default(),
            u: PalettePlane::default(),
            v: PalettePlane::default(),
            y_indices: [0; PALETTE_MAP_SAMPLES],
            uv_indices: [0; PALETTE_MAP_SAMPLES],
        }
    }
}

impl PaletteSyntax {
    const fn is_present(self) -> bool {
        self.y.is_present() || self.u.is_present() || self.v.is_present()
    }

    const fn cache_state(self) -> PaletteCacheState {
        PaletteCacheState {
            y: self.y,
            u: self.u,
        }
    }
}

