pub(in crate::codecs::avif) enum ChromaPredictor {
    Dc,
    Cfl { alpha_u: i32, alpha_v: i32 },
    Vertical,
    Horizontal,
    Diagonal45,
    DiagonalDownRight,
    Diagonal113,
    Diagonal157,
    Diagonal203,
    Diagonal67,
    Smooth,
    SmoothVertical,
    SmoothHorizontal,
    Paeth,
}

#[derive(Clone, Copy, Debug)]
enum LossyTransformKind {
    IdentityIdentity,
    IdentityDct,
    DctDct,
    DctAdst,
    AdstDct,
    DctIdentity,
    AdstAdst,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Lossy4x8TransformKind {
    IdentityIdentity,
    DctDct,
    IdentityDct,
    DctIdentity,
    AdstAdst,
    AdstDct,
    DctAdst,
}

#[derive(Clone, Copy)]
enum LossyOneDimensionalGeometry {
    /// The existing R8x16 sentence stores the V/H axis in the reference's
    /// transposed 16-byte level grid.
    R8x16,
    /// The R16x8 sentence uses the same 16-byte level stride, but its H/V
    /// coefficient placement is the transpose of the R8x16 sentence.
    R16x8,
}

#[derive(Clone, Copy, Debug)]
enum Lossy16x16TransformKind {
    IdentityIdentity,
    DctDct,
    AdstAdst,
    AdstDct,
    DctAdst,
}

fn lossy_transform_kind_from_intra1(symbol: u32) -> PortableResult<LossyTransformKind> {
    // `dav1d_tx_types_per_set[idx + 5]` is ordered as IDTX, DCT_DCT,
    // V_DCT, H_DCT, ADST_ADST, ADST_DCT, DCT_ADST. The two reduced
    // one-dimensional symbols retain the transform-dispatch order used by
    // the safe kernels below: symbol 2 is identity/DCT and symbol 3 is
    // DCT/identity.
    match symbol {
        0 => Ok(LossyTransformKind::IdentityIdentity),
        1 => Ok(LossyTransformKind::DctDct),
        2 => Ok(LossyTransformKind::IdentityDct),
        3 => Ok(LossyTransformKind::DctIdentity),
        4 => Ok(LossyTransformKind::AdstAdst),
        5 => Ok(LossyTransformKind::AdstDct),
        6 => Ok(LossyTransformKind::DctAdst),
        _ => Err(PortableUnavailable),
    }
}

const fn chroma_transform_kind(predictor: ChromaPredictor) -> LossyTransformKind {
    match predictor {
        ChromaPredictor::Dc => LossyTransformKind::DctDct,
        ChromaPredictor::Cfl { .. } => LossyTransformKind::DctDct,
        ChromaPredictor::Vertical => LossyTransformKind::AdstDct,
        ChromaPredictor::Horizontal => LossyTransformKind::DctAdst,
        ChromaPredictor::Diagonal45 => LossyTransformKind::DctDct,
        ChromaPredictor::DiagonalDownRight => LossyTransformKind::AdstAdst,
        ChromaPredictor::Diagonal113 | ChromaPredictor::Diagonal67 => LossyTransformKind::AdstDct,
        ChromaPredictor::Diagonal157 | ChromaPredictor::Diagonal203 => LossyTransformKind::DctAdst,
        ChromaPredictor::Smooth => LossyTransformKind::AdstAdst,
        ChromaPredictor::SmoothVertical => LossyTransformKind::AdstDct,
        ChromaPredictor::SmoothHorizontal => LossyTransformKind::DctAdst,
        // AV1 derives the chroma transform from the coded UV mode, not from
        // the availability-adjusted predictor used for reconstruction. The
        // reference `dav1d_txtp_from_uvmode` table assigns PAETH_ADST_ADST.
        ChromaPredictor::Paeth => LossyTransformKind::AdstAdst,
    }
}

const fn is_smooth_chroma_predictor(predictor: Option<ChromaPredictor>) -> bool {
    matches!(
        predictor,
        Some(
            ChromaPredictor::Smooth
                | ChromaPredictor::SmoothVertical
                | ChromaPredictor::SmoothHorizontal
        )
    )
}

const fn chroma_rect_transform_kind(predictor: ChromaPredictor) -> Lossy4x8TransformKind {
    match predictor {
        ChromaPredictor::Dc | ChromaPredictor::Cfl { .. } | ChromaPredictor::Diagonal45 => {
            Lossy4x8TransformKind::DctDct
        }
        ChromaPredictor::Vertical
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal67
        | ChromaPredictor::SmoothVertical => Lossy4x8TransformKind::AdstDct,
        ChromaPredictor::Horizontal
        | ChromaPredictor::Diagonal157
        | ChromaPredictor::Diagonal203
        | ChromaPredictor::SmoothHorizontal => Lossy4x8TransformKind::DctAdst,
        ChromaPredictor::DiagonalDownRight | ChromaPredictor::Smooth | ChromaPredictor::Paeth => {
            Lossy4x8TransformKind::AdstAdst
        }
    }
}

impl ChromaSampling {
    const fn transform_grid(
        self,
        luma_grid_width: usize,
        luma_grid_height: usize,
        plane: usize,
    ) -> (usize, usize) {
        if plane != 0 && matches!(self, Self::Subsampled420) {
            (luma_grid_width.div_ceil(2), luma_grid_height.div_ceil(2))
        } else {
            (luma_grid_width, luma_grid_height)
        }
    }

    const fn subsampled_cfl_allowed(
        luma_grid_width: usize,
        luma_grid_height: usize,
        all_lossless: bool,
    ) -> bool {
        // ✅ VERIFIED: dav1d 1.5.3 src/tables.h `cfl_allowed_mask` and
        // src/decode.c:1084-1088. Lossless frames use the separate 4×4-only
        // rule; lossy frames use the explicit block-size mask rather than a
        // loose rectangular-size bound.
        let width = luma_grid_width.saturating_mul(4);
        let height = luma_grid_height.saturating_mul(4);
        if all_lossless {
            // In 4:2:0 the lossless rule is expressed in coded chroma
            // units: the chroma block must be one 4×4 transform, so a
            // luma 4×4, 4×8, 8×4, or 8×8 block is eligible.
            return luma_grid_width <= 2 && luma_grid_height <= 2;
        }
        matches!(
            (width, height),
            (4, 4)
                | (4, 8)
                | (4, 16)
                | (8, 4)
                | (8, 8)
                | (8, 16)
                | (8, 32)
                | (16, 4)
                | (16, 8)
                | (16, 16)
                | (16, 32)
                | (32, 8)
                | (32, 16)
                | (32, 32)
        )
    }

    const fn full_cfl_allowed(
        luma_grid_width: usize,
        luma_grid_height: usize,
        all_lossless: bool,
    ) -> bool {
        if all_lossless {
            luma_grid_width == 1 && luma_grid_height == 1
        } else {
            Self::subsampled_cfl_allowed(luma_grid_width, luma_grid_height, false)
        }
    }
}

#[derive(Clone, Copy)]
enum ReconstructionPolicy {
    LosslessWht4x4,
    Lossy420Dct4x4,
    Lossy420Dct4x8,
    Lossy420Dct4x16,
    Lossy420Dct8x4,
    Lossy420Dct16x4,
    Lossy420Dct8x8,
    Lossy420Dct16x16,
    Lossy420Dct32x32,
    Lossy420Dct64x64,
    Lossy420Dct16x32,
    Lossy420Dct32x8,
    Lossy420Dct16x64,
    Lossy420Dct32x16,
    Lossy420Dct64x16,
    Lossy420Dct8x32,
    Lossy420Dct16x8,
    #[allow(
        dead_code,
        reason = "the safe R8x16 terminal is test-backed before full-frame walker integration"
    )]
    Lossy420Rectangular,
}

/// Complete set of coded transform grids admitted by the closed AV1 class.
#[derive(Clone, Copy, Debug)]
pub(super) enum TransformGrid {
    Square4,
    Vertical4x8,
    Vertical4x16,
    Square8,
    Horizontal8x4,
    Square16,
    Horizontal16x4,
    Horizontal16x8,
    Vertical16x32,
    Vertical16x64,
    Horizontal32x16,
    Horizontal64x16,
    Vertical8x16,
    Horizontal32x8,
    Vertical8x32,
    Square32,
    Square64,
}

impl TransformGrid {
    pub(super) fn from_luma_dimensions(width: u32, height: u32) -> PortableResult<Self> {
        match (width, height) {
            (4, 4) => Ok(Self::Square4),
            (4, 8) => Ok(Self::Vertical4x8),
            (4, 16) => Ok(Self::Vertical4x16),
            (8, 4) => Ok(Self::Horizontal8x4),
            (16, 4) => Ok(Self::Horizontal16x4),
            (8, 8) => Ok(Self::Square8),
            (16, 16) => Ok(Self::Square16),
            (32, 32) => Ok(Self::Square32),
            (64, 64) => Ok(Self::Square64),
            (16, 64) => Ok(Self::Vertical16x64),
            (8, 16) => Ok(Self::Vertical8x16),
            (8, 32) => Ok(Self::Vertical8x32),
            (16, 8) => Ok(Self::Horizontal16x8),
            (16, 32) => Ok(Self::Vertical16x32),
            (32, 16) => Ok(Self::Horizontal32x16),
            (64, 16) => Ok(Self::Horizontal64x16),
            (32, 8) => Ok(Self::Horizontal32x8),
            _ => Err(PortableUnavailable),
        }
    }

    const fn properties(self) -> (usize, usize, [u16; 2]) {
        match self {
            // ✅ VERIFIED: AOM/libdav1d default CDF for BLOCK_4X4 is
            // AOM_CDF2(4621); this decoder stores the complemented value.
            Self::Square4 => (1, 1, [28_147, 0]),
            // ✅ VERIFIED: AOM/libdav1d default CDF for BLOCK_4X8 is
            // AOM_CDF2(6743); this decoder stores the complemented value.
            Self::Vertical4x8 => (1, 2, [26_025, 0]),
            // ✅ VERIFIED: AOM/libdav1d default CDF for BLOCK_4X16 is
            // AOM_CDF2(12770); this decoder stores the complemented value.
            Self::Vertical4x16 => (1, 4, [19_998, 0]),
            Self::Square8 => (2, 2, [24_902, 0]),
            // ✅ VERIFIED: AOM/libdav1d default CDF for BLOCK_8X4 is
            // AOM_CDF2(5893); this decoder stores the complemented value.
            Self::Horizontal8x4 => (2, 1, [26_875, 0]),
            Self::Square16 => (4, 4, [20_360, 0]),
            // ✅ VERIFIED: AOM/libdav1d default CDF for BLOCK_16X4 is
            // AOM_CDF2(10368); this decoder stores the complemented value.
            Self::Horizontal16x4 => (4, 1, [22_400, 0]),
            Self::Horizontal16x8 => (4, 2, [23_374, 0]),
            Self::Vertical16x32 => (4, 8, [18_467, 0]),
            Self::Vertical16x64 => (4, 16, [16_384, 0]),
            Self::Horizontal32x16 => (8, 4, [20_012, 0]),
            // ✅ VERIFIED: dav1d 1.1.0 `use_filter_intra` for BLOCK_64X16
            // (index five); this decoder stores the complement.
            Self::Horizontal64x16 => (16, 4, [16_384, 0]),
            Self::Vertical8x16 => (2, 4, [20_217, 0]),
            Self::Horizontal32x8 => (8, 2, [14_667, 0]),
            Self::Vertical8x32 => (2, 8, [12_539, 0]),
            // ✅ VERIFIED: dav1d 1.1.0 src/cdf.rs `use_filter_intra` for
            // BLOCK_32X32 (index seven); this decoder stores the complement.
            Self::Square32 => (8, 8, [10_425, 0]),
            // ✅ VERIFIED: dav1d 1.1.0 `src/cdf.rs` `use_filter_intra` for
            // BLOCK_64X64 (index three); this decoder stores the complement.
            Self::Square64 => (16, 16, [16_384, 0]),
        }
    }

    /// AV1's maximum transform-size level for this coded luma block.
    ///
    /// The value is the `TxfmInfo::max` level used to select `txsz[max - 1]`
    /// in dav1d. It is deliberately kept separate from the transform-grid
    /// dimensions: rectangular blocks use the AV1 rectangular transform
    /// families, whose maximum level is not always the smaller grid axis.
    const fn transform_size_max(self) -> usize {
        match self {
            Self::Square4 => 0,
            Self::Vertical4x8 | Self::Horizontal8x4 | Self::Square8 => 1,
            Self::Vertical4x16
            | Self::Horizontal16x4
            | Self::Horizontal16x8
            | Self::Vertical8x16
            | Self::Square16 => 2,
            Self::Vertical16x32
            | Self::Horizontal32x16
            | Self::Horizontal32x8
            | Self::Vertical8x32
            | Self::Square32 => 3,
            Self::Vertical16x64 | Self::Horizontal64x16 | Self::Square64 => 4,
        }
    }

    /// Whether this block's AV1 mode syntax carries `angle_delta_y`.
    ///
    /// The bitstream syntax starts the angle-delta symbol at `BLOCK_8X8`.
    /// The two smaller grids below therefore leave the symbol in the range
    /// decoder for the following syntax element.
    const fn has_angle_delta(self) -> bool {
        let (width, height, _) = self.properties();
        // `b_dim[2] + b_dim[3] >= 2` in AV1 is the log2 transform-grid
        // condition. Rectangles such as 16×4 and 4×16 therefore carry the
        // symbol too, while 8×4 and 4×8 do not.
        width >= 4 || height >= 4 || (width >= 2 && height >= 2)
    }

    /// Index of the AV1 palette-size CDF for this coded block size.
    const fn palette_size_context(self) -> usize {
        let (width, height, _) = self.properties();
        width
            .ilog2()
            .saturating_add(height.ilog2())
            .saturating_sub(2) as usize
    }

    /// Index of the AV1 `use_filter_intra` CDF for this coded block size.
    ///
    /// AV1 keeps one adaptive pair per block size, rather than one pair per
    /// transform grid. The closed decoder only admits the grids below, but
    /// retaining the bitstream's block-size index keeps CDF history correct
    /// when a partition mixes 16×16 and 8×8 leaves.
    const fn filter_intra_cdf_index(self) -> usize {
        match self {
            Self::Square32 => 7,
            Self::Square64 => 3,
            Self::Vertical16x64 => 10,
            Self::Horizontal32x16 => 8,
            Self::Horizontal64x16 => 5,
            Self::Horizontal32x8 => 9,
            Self::Vertical16x32 => 11,
            Self::Square16 => 12,
            Self::Horizontal16x8 => 13,
            Self::Horizontal16x4 => 14,
            Self::Vertical8x32 => 15,
            Self::Vertical8x16 => 16,
            Self::Square8 => 17,
            Self::Horizontal8x4 => 18,
            Self::Vertical4x16 => 19,
            Self::Vertical4x8 => 20,
            Self::Square4 => 21,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum LumaPredictor {
    Dc,
    Vertical,
    Horizontal,
    Diagonal45,
    DiagonalDownRight,
    Diagonal113,
    Diagonal157,
    Diagonal203,
    Diagonal67,
    Smooth,
    SmoothVertical,
    SmoothHorizontal,
    Paeth,
}

impl LumaPredictor {
    const fn sample(self) -> u16 {
        match self {
            Self::Dc => 128,
            Self::Vertical => 127,
            Self::Horizontal => 129,
            Self::Diagonal45 => 128,
            Self::DiagonalDownRight => 128,
            Self::Diagonal113 => 128,
            Self::Diagonal157 => 128,
            Self::Diagonal203 => 128,
            Self::Diagonal67 => 128,
            Self::Smooth => 128,
            Self::SmoothVertical => 128,
            Self::SmoothHorizontal => 128,
            Self::Paeth => 128,
        }
    }

    const fn cdf_index(self) -> usize {
        match self {
            Self::Dc => 0,
            Self::Vertical => 1,
            Self::Horizontal => 2,
            Self::Diagonal45 => 3,
            Self::DiagonalDownRight => 4,
            Self::Diagonal113 => 5,
            Self::Diagonal157 => 6,
            Self::Diagonal203 => 7,
            Self::Diagonal67 => 8,
            Self::Smooth => 9,
            Self::SmoothVertical => 10,
            Self::SmoothHorizontal => 11,
            Self::Paeth => 12,
        }
    }

    /// AV1's five-way intra-neighbor context used by `kfym`.
    ///
    /// These groups are a syntax context, not the decoded predictor number.
    const fn intra_mode_context(self) -> usize {
        match self {
            Self::Dc | Self::Smooth | Self::Paeth => 0,
            Self::Vertical | Self::SmoothVertical => 1,
            Self::Horizontal | Self::SmoothHorizontal => 2,
            Self::Diagonal45 | Self::Diagonal67 => 3,
            Self::DiagonalDownRight | Self::Diagonal113 | Self::Diagonal157 | Self::Diagonal203 => {
                4
            }
        }
    }
}

#[derive(Clone, Copy)]
enum SpatialLumaContext {
    Origin,
    Standard(usize),
}

impl SpatialLumaContext {
    const fn from_neighbor(orientation: SplitOrientation, predictor: LumaPredictor) -> Self {
        let group = predictor.intra_mode_context();
        match orientation {
            SplitOrientation::Horizontal => Self::Standard(group),
            SplitOrientation::Vertical => Self::Standard(group.saturating_mul(5)),
        }
    }

    const fn index(self) -> usize {
        match self {
            Self::Origin => 0,
            Self::Standard(index) => index,
        }
    }

    fn from_two_neighbors(above: LumaPredictor, left: LumaPredictor) -> PortableResult<Self> {
        let above_context = above.intra_mode_context();
        let left_context = left.intra_mode_context();
        Ok(Self::Standard(
            above_context.saturating_mul(5).saturating_add(left_context),
        ))
    }

    fn from_two_monochrome_neighbors(
        above: LumaPredictor,
        left: LumaPredictor,
    ) -> PortableResult<Self> {
        Self::from_two_neighbors(above, left)
    }

    const fn accepts(self, predictor: LumaPredictor) -> bool {
        if matches!(
            predictor,
            LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
        ) {
            return true;
        }
        match self {
            Self::Origin => true,
            Self::Standard(_) => true,
        }
    }
}

