impl MonochromeLeaf {
    pub(super) fn contains_sample(&self, x: u32, y: u32) -> bool {
        x >= self.origin_x
            && y >= self.origin_y
            && x.saturating_sub(self.origin_x) < self.width
            && y.saturating_sub(self.origin_y) < self.height
    }

    pub(super) const fn origin_x(&self) -> u32 {
        self.origin_x
    }

    pub(super) const fn origin_y(&self) -> u32 {
        self.origin_y
    }

    pub(super) const fn width(&self) -> u32 {
        self.width
    }

    pub(super) const fn height(&self) -> u32 {
        self.height
    }

    pub(super) fn plane(&self) -> &ReconstructedPlane {
        &self.plane
    }

    pub(super) fn into_first_leaf(self) -> FirstLeaf {
        let plane = self.plane;
        FirstLeaf {
            width: self.width,
            height: self.height,
            planes: [plane.clone(), plane.clone(), plane],
            luma_predictor: self.predictor,
            chroma_predictor: None,
            luma_context: 0x40,
            chroma_contexts: [0x40; 2],
            chroma_right_contexts: [[0x40; 8]; 2],
            chroma_bottom_contexts: [[0x40; 8]; 2],
            tx_context_width: 0,
            tx_context_height: 0,
            luma_transform_split: false,
            luma_right_contexts: std::array::from_fn(|index| self.right_contexts[index]),
            luma_bottom_contexts: std::array::from_fn(|index| self.bottom_contexts[index]),
            palette_cache: PaletteCacheState::default(),
            #[cfg(coverage)]
            entropy_operations: Vec::new(),
        }
    }
}

