// ✅ VERIFIED: rav1d 1.1.0 qcat-zero `base_tok`/`br_tok`, transform-context
// one, chroma. The first 26 low-context rows are the complete CDF sentence
// needed by the 8x8 chroma transform; its high-token rows are shared with the
// existing R8x4 chroma sentence.
const fn first_26_cdf_rows(rows: [[u16; 4]; 41]) -> [[u16; 4]; 26] {
    let mut result = [[0_u16; 4]; 26];
    let mut index = 0_usize;
    while index < 26 {
        result[index] = rows[index];
        index = index.saturating_add(1);
    }
    result
}

