// ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:318-643,
// src/msac.c:187-201, src/cdf.c:308-336, 749-755, 839-865, and
// 1316-1465. The admitted lossy leaf has one 8x8 luma transform and one
// subsampled 4x4 transform per chroma plane. The proven luma classes include
// a skipped residual, a DC-only residual, and the bounded EOB-bin-five/six AC
// classes. Chroma now consumes the general 4x4 coefficient sentence, while
// frame-wide reconstruction remains an explicit pure-Rust gap.
fn lossy_420_chroma_skip_cdf(
    transform_grid: TransformGrid,
    above_contexts: [u8; 8],
    left_contexts: [u8; 8],
) -> CoefficientSkipCdf {
    // `get_skip_ctx` in dav1d starts subsampled chroma at context seven when
    // the coded chroma transform covers the block's complete chroma
    // footprint. A coded 16x16 luma block maps to one 8x8 chroma transform,
    // so it belongs to that same context family; the neighbor bits are added
    // after the geometry-dependent base.
    let skip_context_base = match transform_grid {
        TransformGrid::Square4
        | TransformGrid::Vertical4x8
        | TransformGrid::Horizontal8x4
        | TransformGrid::Square8
        | TransformGrid::Horizontal16x4
        | TransformGrid::Square16
        | TransformGrid::Horizontal32x16
        | TransformGrid::Vertical16x32
        | TransformGrid::Vertical16x64
        | TransformGrid::Square32 => 7,
        _ => 10,
    };
    let transform_context = match transform_grid {
        TransformGrid::Square4
        | TransformGrid::Vertical4x8
        | TransformGrid::Horizontal8x4
        | TransformGrid::Square8 => 0,
        TransformGrid::Vertical4x16
        | TransformGrid::Horizontal16x4
        | TransformGrid::Horizontal16x8
        | TransformGrid::Square16
        | TransformGrid::Vertical8x16
        | TransformGrid::Horizontal32x8
        | TransformGrid::Vertical8x32 => 1,
        TransformGrid::Vertical16x32 | TransformGrid::Horizontal32x16 | TransformGrid::Square32 => {
            2
        }
        // R16x64 maps to one 8x32 chroma transform. dav1d's `t_dim.ctx`
        // selects the fourth subsampled coefficient-skip row for that shape.
        TransformGrid::Vertical16x64 => 3,
        // BLOCK_64X16 maps to R32x8 in 4:2:0, whose t_dim.ctx is two.
        TransformGrid::Horizontal64x16 => 2,
        TransformGrid::Square64 => 3,
    };
    let (luma_width, luma_height, _) = transform_grid.properties();
    let above_count = luma_width.div_ceil(2).min(8);
    let left_count = luma_height.div_ceil(2).min(8);
    let above_non_neutral = above_contexts[..above_count]
        .iter()
        .any(|&context| context != 0x40);
    let left_non_neutral = left_contexts[..left_count]
        .iter()
        .any(|&context| context != 0x40);
    let neighbor_context = usize::from(above_non_neutral) + usize::from(left_non_neutral);
    CoefficientSkipCdf::Subsampled {
        transform_context,
        skip_context: skip_context_base + neighbor_context,
    }
}

fn lossy_full_chroma_skip_cdf(
    transform_grid: TransformGrid,
    above_contexts: [u8; 8],
    left_contexts: [u8; 8],
) -> CoefficientSkipCdf {
    // Full-resolution chroma uses the same AV1 chroma skip CDF family as
    // 4:2:0, but its transform context is the context of the full-size
    // transform. The 4:2:0 helper above intentionally lowers that context
    // after the two subsampling shifts; reusing it for I444 consumes a
    // different CDF row and desynchronizes the following partition syntax.
    let transform_context = match transform_grid {
        TransformGrid::Square4 => 0,
        TransformGrid::Vertical4x8
        | TransformGrid::Horizontal8x4
        | TransformGrid::Vertical4x16
        | TransformGrid::Horizontal16x4
        | TransformGrid::Square8 => 1,
        TransformGrid::Vertical8x16
        | TransformGrid::Horizontal16x8
        | TransformGrid::Horizontal32x8
        | TransformGrid::Square16 => 2,
        TransformGrid::Vertical8x32 => 3,
        TransformGrid::Vertical16x32
        | TransformGrid::Horizontal32x16
        | TransformGrid::Vertical16x64
        | TransformGrid::Horizontal64x16
        | TransformGrid::Square32 => 3,
        TransformGrid::Square64 => 4,
    };
    let (width, height, _) = transform_grid.properties();
    let above_non_neutral = above_contexts[..width.min(8)]
        .iter()
        .any(|&context| context != 0x40);
    let left_non_neutral = left_contexts[..height.min(8)]
        .iter()
        .any(|&context| context != 0x40);
    let skip_context = 7 + usize::from(above_non_neutral) + usize::from(left_non_neutral);
    CoefficientSkipCdf::Subsampled {
        transform_context,
        skip_context,
    }
}

fn lossy_chroma_skip_cdf_for_sampling(
    chroma_sampling: ChromaSampling,
    transform_grid: TransformGrid,
    above_contexts: [u8; 8],
    left_contexts: [u8; 8],
) -> CoefficientSkipCdf {
    if matches!(chroma_sampling, ChromaSampling::Full) {
        lossy_full_chroma_skip_cdf(transform_grid, above_contexts, left_contexts)
    } else {
        lossy_420_chroma_skip_cdf(transform_grid, above_contexts, left_contexts)
    }
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 4:2:0 coefficient path passes the independent luma/chroma CDF and neighbor-context state"
)]
fn decode_lossy_420_dc_or_skipped_coefficients(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    luma_mode: usize,
    _luma_predictor: LumaPredictor,
    transform_grid: TransformGrid,
    quantization: LossyQuantization,
    cdfs: &mut BlockCdfs,
    above_luma_contexts: [u8; 16],
    left_luma_contexts: [u8; 16],
    above_chroma_contexts: [u8; 8],
    left_chroma_contexts: [u8; 8],
) -> PortableResult<DecodedLossy420Coefficients> {
    if plane != 0 {
        let skipped = decode_contextual_skip(
            decoder,
            1,
            lossy_420_chroma_skip_cdf(transform_grid, above_chroma_contexts, left_chroma_contexts),
            cdfs,
        );

        if skipped {
            return Ok((
                [[0_i32; 16]; 64],
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
            ));
        }
        if matches!(transform_grid, TransformGrid::Square32) {
            let chroma =
                decode_lossy_chroma_16x16_coefficients(decoder, plane, cdfs, quantization)?;
            return Ok((
                [[0_i32; 16]; 64],
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                Some(chroma),
                None,
            ));
        }
        if matches!(transform_grid, TransformGrid::Vertical8x32) {
            let chroma = decode_lossy_chroma_4x16_coefficients(decoder, plane, cdfs, quantization)?;
            return Ok((
                [[0_i32; 16]; 64],
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                Some(chroma),
            ));
        }
        if matches!(
            transform_grid,
            TransformGrid::Vertical4x16 | TransformGrid::Vertical8x16
        ) {
            let chroma = decode_lossy_chroma_4x8_coefficients(
                decoder,
                plane,
                cdfs,
                quantization,
                coefficient_dc_sign_context_for_dimensions(
                    1,
                    2,
                    &above_chroma_contexts,
                    &left_chroma_contexts,
                ),
            )?;
            return Ok((
                [[0_i32; 16]; 64],
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                Some(chroma),
                None,
                None,
                None,
                None,
            ));
        }
        if matches!(transform_grid, TransformGrid::Horizontal16x4) {
            let chroma = decode_lossy_chroma_8x4_coefficients(
                decoder,
                plane,
                cdfs,
                quantization,
                coefficient_dc_sign_context_for_dimensions(
                    2,
                    1,
                    &above_chroma_contexts,
                    &left_chroma_contexts,
                ),
            )?;
            return Ok((
                [[0_i32; 16]; 64],
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                Some(chroma),
                None,
                None,
                None,
                None,
            ));
        }
        if matches!(transform_grid, TransformGrid::Horizontal16x8) {
            let chroma = decode_lossy_chroma_8x4_coefficients(
                decoder,
                plane,
                cdfs,
                quantization,
                coefficient_dc_sign_context_for_dimensions(
                    2,
                    1,
                    &above_chroma_contexts,
                    &left_chroma_contexts,
                ),
            )?;
            return Ok((
                [[0_i32; 16]; 64],
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                Some(chroma),
                None,
                None,
                None,
                None,
            ));
        }
        let chroma = decode_lossy_chroma_4x4_coefficients(
            decoder,
            plane,
            cdfs,
            quantization,
            coefficient_dc_sign_context(above_chroma_contexts[0], left_chroma_contexts[0]),
        )?;

        let mut plane_coefficients = [[0_i32; 16]; 64];
        plane_coefficients[0] = chroma;
        return Ok((
            plane_coefficients,
            None,
            Some(chroma),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        ));
    }
    let luma_skipped = match transform_grid {
        TransformGrid::Square4 => decoder.adaptive_bool(&mut cdfs.luma_coefficient_skip[0]),
        TransformGrid::Square16 => {
            decoder.adaptive_bool(&mut cdfs.lossy_luma_16x16_coefficient_skip)
        }
        TransformGrid::Square32 => {
            decoder.adaptive_bool(&mut cdfs.lossy_luma_32x32_coefficient_skip)
        }
        TransformGrid::Vertical8x32 => {
            decoder.adaptive_bool(&mut cdfs.lossy_luma_32x32_coefficient_skip)
        }
        _ => decoder.adaptive_bool(&mut cdfs.lossy_luma_8x8_coefficient_skip[0]),
    };

    if luma_skipped {
        if matches!(transform_grid, TransformGrid::Square32) {
            return Ok((
                [[0_i32; 16]; 64],
                None,
                None,
                Some(LossyTransformKind::DctDct),
                None,
                None,
                None,
                None,
                None,
                None,
                Some([0_i32; 1024]),
                None,
                None,
                None,
            ));
        }
        if matches!(transform_grid, TransformGrid::Vertical8x32) {
            return Ok((
                [[0_i32; 16]; 64],
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                Some([0_i32; 256]),
                None,
                None,
            ));
        }
        if matches!(transform_grid, TransformGrid::Vertical4x8) {
            return Ok((
                [[0_i32; 16]; 64],
                None,
                None,
                Some(LossyTransformKind::DctDct),
                Some([0_i32; 32]),
                Some(Lossy4x8TransformKind::DctDct),
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
            ));
        }
        if matches!(transform_grid, TransformGrid::Vertical4x16) {
            return Ok((
                [[0_i32; 16]; 64],
                Some([0_i32; 64]),
                None,
                None,
                None,
                Some(Lossy4x8TransformKind::DctDct),
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
            ));
        }
        return Ok((
            [[0_i32; 16]; 64],
            Some([0_i32; 64]),
            None,
            Some(LossyTransformKind::DctDct),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        ));
    }

    if matches!(transform_grid, TransformGrid::Square16) {
        let transform_type = decoder.adaptive_symbol(
            cdfs.lossy_luma_16x16_transform_type
                .get_mut(luma_mode)
                .portable()?,
            4,
        );
        let transform_kind = match transform_type {
            // `dav1d_tx_types_per_set[idx + 0]`: the baseline fixture uses
            // IDTX or DCT_DCT. Other 16x16 transform families remain separate
            // work until their safe scalar kernels have independent pixel
            // evidence.
            0 => Lossy16x16TransformKind::IdentityIdentity,
            1 => Lossy16x16TransformKind::DctDct,
            2 => Lossy16x16TransformKind::AdstAdst,
            3 => Lossy16x16TransformKind::AdstDct,
            4 => Lossy16x16TransformKind::DctAdst,
            _ => return Err(PortableUnavailable),
        };
        let eob_bin = decoder.adaptive_symbol(&mut cdfs.lossy_luma_16x16_eob_bin, 8);
        let dc_sign_context = coefficient_dc_sign_context_for_grid(
            TransformGrid::Square16,
            &above_luma_contexts,
            &left_luma_contexts,
        );
        let (coefficients, residual_context) = decode_lossy_luma_16x16_coefficients(
            decoder,
            cdfs,
            quantization,
            eob_bin,
            dc_sign_context,
        )?;
        cdfs.last_lossy_luma_residual_context = Some(residual_context);
        return Ok((
            [[0_i32; 16]; 64],
            None,
            None,
            Some(LossyTransformKind::DctDct),
            None,
            None,
            Some(coefficients),
            Some(transform_kind),
            None,
            None,
            None,
            None,
            None,
            None,
        ));
    }

    if matches!(transform_grid, TransformGrid::Square32) {
        let eob_bin = decoder.adaptive_symbol(&mut cdfs.lossy_luma_32x32_eob_bin, 10);
        let coefficients =
            decode_lossy_luma_32x32_coefficients(decoder, cdfs, quantization, eob_bin)?;
        return Ok((
            [[0_i32; 16]; 64],
            None,
            None,
            Some(LossyTransformKind::DctDct),
            None,
            None,
            None,
            None,
            None,
            None,
            Some(coefficients),
            None,
            None,
            None,
        ));
    }

    if matches!(transform_grid, TransformGrid::Vertical8x32) {
        let eob_bin = decoder.adaptive_symbol(&mut cdfs.lossy_luma_16x16_eob_bin, 8);
        let coefficients =
            decode_lossy_luma_8x32_coefficients(decoder, cdfs, quantization, eob_bin)?;
        return Ok((
            [[0_i32; 16]; 64],
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            Some(coefficients),
            None,
            None,
        ));
    }

    if matches!(transform_grid, TransformGrid::Vertical4x16) {
        let transform_type = decoder.adaptive_symbol(
            cdfs.lossy_luma_4x8_transform_type
                .get_mut(luma_mode)
                .portable()?,
            6,
        );
        let transform_kind = match transform_type {
            0 => Lossy4x8TransformKind::IdentityIdentity,
            1 => Lossy4x8TransformKind::DctDct,
            2 => Lossy4x8TransformKind::IdentityDct,
            3 => Lossy4x8TransformKind::DctIdentity,
            4 => Lossy4x8TransformKind::AdstAdst,
            5 => Lossy4x8TransformKind::AdstDct,
            6 => Lossy4x8TransformKind::DctAdst,
            _ => return Err(PortableUnavailable),
        };
        let coefficients = decode_lossy_luma_4x16_coefficients(decoder, cdfs, quantization)?;
        return Ok((
            [[0_i32; 16]; 64],
            Some(coefficients),
            None,
            None,
            None,
            Some(transform_kind),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        ));
    }

    if matches!(transform_grid, TransformGrid::Horizontal16x4) {
        let transform_type = decoder.adaptive_symbol(
            cdfs.lossy_luma_4x8_transform_type
                .get_mut(luma_mode)
                .portable()?,
            6,
        );
        let transform_kind = match transform_type {
            // `dav1d_tx_types_per_set[idx + 5]` from rav1d 1.1.0. The
            // rectangular transform has the same seven transform classes as
            // the 4x8/8x4 decoder, but its coefficient sentence is separate.
            0 => Lossy4x8TransformKind::IdentityIdentity,
            1 => Lossy4x8TransformKind::DctDct,
            2 => Lossy4x8TransformKind::IdentityDct,
            3 => Lossy4x8TransformKind::DctIdentity,
            4 => Lossy4x8TransformKind::AdstAdst,
            5 => Lossy4x8TransformKind::AdstDct,
            6 => Lossy4x8TransformKind::DctAdst,
            _ => return Err(PortableUnavailable),
        };
        let one_dimensional = matches!(transform_type, 2 | 3);
        let eob_bin = if one_dimensional {
            decoder.adaptive_symbol(&mut cdfs.lossy_luma_8x8_eob_bin_1d, 6)
        } else {
            decoder.adaptive_symbol(&mut cdfs.lossy_luma_8x8_eob_bin, 6)
        };
        let dc_sign_context = coefficient_dc_sign_context_for_grid(
            TransformGrid::Horizontal16x4,
            &above_luma_contexts,
            &left_luma_contexts,
        );
        if one_dimensional {
            let (coefficients, residual_context) = decode_lossy_luma_16x4_1d_coefficients(
                decoder,
                cdfs,
                quantization,
                eob_bin,
                dc_sign_context,
                transform_type == 2,
            )?;
            cdfs.last_lossy_luma_residual_context = Some(residual_context);
            return Ok((
                [[0_i32; 16]; 64],
                Some(coefficients),
                None,
                None,
                None,
                None,
                None,
                None,
                Some(transform_kind),
                None,
                None,
                None,
                None,
                None,
            ));
        }
        let matrix_values = match transform_kind {
            Lossy4x8TransformKind::IdentityIdentity
            | Lossy4x8TransformKind::IdentityDct
            | Lossy4x8TransformKind::DctIdentity => None,
            Lossy4x8TransformKind::DctDct
            | Lossy4x8TransformKind::AdstAdst
            | Lossy4x8TransformKind::AdstDct
            | Lossy4x8TransformKind::DctAdst => luma_16x4_matrix(quantization)?,
        };
        let (coefficients, residual_context) = decode_lossy_luma_16x4_coefficients(
            decoder,
            cdfs,
            quantization,
            eob_bin,
            dc_sign_context,
            matrix_values,
        )?;
        cdfs.last_lossy_luma_residual_context = Some(residual_context);
        return Ok((
            [[0_i32; 16]; 64],
            Some(coefficients),
            None,
            None,
            None,
            None,
            None,
            None,
            Some(transform_kind),
            None,
            None,
            None,
            None,
            None,
        ));
    }

    // The AV1 intra transform-type CDF is indexed by the luma predictor mode
    // for this 8x8 class. The 7-symbol row is `dav1d_tx_types_per_set[idx +
    // 5]`: keeping that table mapping explicit prevents a coded symbol from
    // silently selecting the wrong scalar transform.
    if matches!(transform_grid, TransformGrid::Square4) {
        let transform_type = decoder.adaptive_symbol(
            cdfs.lossy_luma_4x8_transform_type
                .get_mut(luma_mode)
                .portable()?,
            6,
        );
        let transform_kind = lossy_transform_kind_from_intra1(transform_type)?;

        let (coefficients, context) = decode_lossy_luma_4x4_coefficients(
            decoder,
            cdfs,
            quantization,
            coefficient_dc_sign_context(above_luma_contexts[0], left_luma_contexts[0]),
            transform_kind,
        )?;
        cdfs.last_lossy_luma_residual_context = Some(context);
        let mut expanded = [0_i32; 64];
        expanded[..16].copy_from_slice(&coefficients);
        return Ok((
            [[0_i32; 16]; 64],
            Some(expanded),
            None,
            Some(transform_kind),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        ));
    }

    if matches!(transform_grid, TransformGrid::Vertical4x8) {
        let transform_type = decoder.adaptive_symbol(
            cdfs.lossy_luma_4x8_transform_type
                .get_mut(luma_mode)
                .portable()?,
            6,
        );
        let transform_kind = match transform_type {
            // `dav1d_tx_types_per_set[idx + 5]` from rav1d 1.1.0.
            0 => Lossy4x8TransformKind::IdentityIdentity,
            1 => Lossy4x8TransformKind::DctDct,
            2 => Lossy4x8TransformKind::IdentityDct,
            3 => Lossy4x8TransformKind::DctIdentity,
            4 => Lossy4x8TransformKind::AdstAdst,
            5 => Lossy4x8TransformKind::AdstDct,
            6 => Lossy4x8TransformKind::DctAdst,
            _ => return Err(PortableUnavailable),
        };

        let eob_bin = decoder.adaptive_symbol(&mut cdfs.lossy_luma_4x8_eob_bin, 5);

        let coefficients =
            decode_lossy_luma_4x8_coefficients(decoder, cdfs, quantization, eob_bin)?;
        return Ok((
            [[0_i32; 16]; 64],
            None,
            None,
            Some(LossyTransformKind::DctDct),
            Some(coefficients),
            Some(transform_kind),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        ));
    }

    if matches!(transform_grid, TransformGrid::Horizontal8x4) {
        let transform_type = decoder.adaptive_symbol(
            cdfs.lossy_luma_4x8_transform_type
                .get_mut(luma_mode)
                .portable()?,
            6,
        );
        let transform_kind = match transform_type {
            // `dav1d_tx_types_per_set[idx + 5]` from rav1d 1.1.0. The
            // transform-kind names are horizontal-axis/vertical-axis.
            0 => Lossy4x8TransformKind::IdentityIdentity,
            1 => Lossy4x8TransformKind::DctDct,
            2 => Lossy4x8TransformKind::IdentityDct,
            3 => Lossy4x8TransformKind::DctIdentity,
            4 => Lossy4x8TransformKind::AdstAdst,
            5 => Lossy4x8TransformKind::AdstDct,
            6 => Lossy4x8TransformKind::DctAdst,
            _ => return Err(PortableUnavailable),
        };
        let one_dimensional = matches!(transform_type, 2 | 3);
        let eob_bin = if one_dimensional {
            decoder.adaptive_symbol(&mut cdfs.lossy_luma_8x4_eob_bin_1d, 5)
        } else {
            decoder.adaptive_symbol(&mut cdfs.lossy_luma_4x8_eob_bin, 5)
        };
        let coefficients = decode_lossy_luma_8x4_coefficients(
            decoder,
            cdfs,
            quantization,
            eob_bin,
            one_dimensional,
        )?;
        return Ok((
            [[0_i32; 16]; 64],
            None,
            None,
            Some(LossyTransformKind::DctDct),
            Some(coefficients),
            Some(transform_kind),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        ));
    }

    let transform_type = decoder.adaptive_symbol(
        cdfs.lossy_luma_8x8_transform_type
            .get_mut(luma_mode)
            .portable()?,
        6,
    );
    let transform_kind = lossy_transform_kind_from_intra1(transform_type)?;

    let one_dimensional = matches!(
        transform_kind,
        LossyTransformKind::IdentityDct | LossyTransformKind::DctIdentity
    );
    let eob_bin = if one_dimensional {
        decoder.adaptive_symbol(&mut cdfs.lossy_luma_8x8_eob_bin_1d, 6)
    } else {
        decoder.adaptive_symbol(&mut cdfs.lossy_luma_8x8_eob_bin, 6)
    };

    let dc_sign_context = coefficient_dc_sign_context_8x8(
        [above_luma_contexts[0], above_luma_contexts[1]],
        [left_luma_contexts[0], left_luma_contexts[1]],
    );
    let (coefficients, residual_context) = if one_dimensional {
        decode_lossy_luma_8x8_1d_coefficients(
            decoder,
            cdfs,
            quantization,
            eob_bin,
            dc_sign_context,
            // The bitstream's one-dimensional scan is keyed by the AV1
            // transform type: V_DCT (symbol 2) scans the transposed axis,
            // even though the portable transform helper is named
            // `IdentityDct` after its pass order.
            matches!(transform_type, 2),
        )?
    } else {
        decode_lossy_luma_8x8_coefficients(decoder, cdfs, quantization, eob_bin, dc_sign_context)?
    };

    cdfs.last_lossy_luma_residual_context = Some(residual_context);
    Ok((
        [[0_i32; 16]; 64],
        Some(coefficients),
        None,
        Some(transform_kind),
        None,
        None,
        None,
        None,
        None,
        None,
        None,
        None,
        None,
        None,
    ))
}

fn decode_lossy_420_rectangular_coefficients(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    luma_mode: usize,
    _luma_predictor: LumaPredictor,
    quantization: LossyQuantization,
    dc_sign_context: usize,
    cdfs: &mut BlockCdfs,
) -> PortableResult<(LossyRectTransformCoefficients, LossyTransformKind)> {
    // R8x16 uses AV1's transform-context-two luma skip CDF.  It is tempting
    // to reuse the 8x8 row because this path stores a 128-coefficient
    // rectangle, but the CDF is selected by the transform dimensions, not by
    // the storage helper used below.
    let luma_skipped = decoder.adaptive_bool(&mut cdfs.lossy_luma_16x16_coefficient_skip);
    if luma_skipped {
        return Ok(([0_i32; 128], LossyTransformKind::DctDct));
    }
    let transform_type = decoder.adaptive_symbol(
        cdfs.lossy_luma_8x8_transform_type
            .get_mut(luma_mode)
            .portable()?,
        6,
    );
    let transform_kind = match transform_type {
        0 => LossyTransformKind::IdentityIdentity,
        1 => LossyTransformKind::DctDct,
        2 => LossyTransformKind::IdentityDct,
        3 => LossyTransformKind::DctIdentity,
        4 => LossyTransformKind::AdstAdst,
        5 => LossyTransformKind::AdstDct,
        6 => LossyTransformKind::DctAdst,
        _ => return Err(PortableUnavailable),
    };
    let one_dimensional = matches!(
        transform_kind,
        LossyTransformKind::IdentityDct | LossyTransformKind::DctIdentity
    );
    let eob_bin = if one_dimensional {
        decoder.adaptive_symbol(&mut cdfs.lossy_luma_8x16_eob_bin_1d, 7)
    } else {
        decoder.adaptive_symbol(&mut cdfs.lossy_luma_8x16_eob_bin, 7)
    };
    let (coefficients, residual_context) = if one_dimensional {
        decode_lossy_luma_8x16_1d_coefficients(
            decoder,
            cdfs,
            quantization,
            eob_bin,
            matches!(transform_type, 2),
            dc_sign_context,
            LossyOneDimensionalGeometry::R8x16,
        )?
    } else {
        decode_lossy_luma_8x16_coefficients(decoder, cdfs, quantization, eob_bin, dc_sign_context)?
    };
    cdfs.last_lossy_luma_residual_context = Some(residual_context);
    Ok((coefficients, transform_kind))
}

fn coefficient_qindex(quantization: LossyQuantization, plane: usize, index: usize) -> usize {
    let delta = match (plane, index == 0) {
        (0, true) => quantization.y_dc_delta,
        (0, false) => quantization.y_ac_delta,
        (1, true) => quantization.u_dc_delta,
        (1, false) => quantization.u_ac_delta,
        (2, true) => quantization.v_dc_delta,
        (2, false) => quantization.v_ac_delta,
        _ => 0,
    };
    let qindex = i64::from(quantization.qindex)
        .saturating_add(i64::from(delta))
        .clamp(0, 255);
    usize::try_from(qindex).unwrap_or(0)
}

fn dequantize_lossy_coefficient_with_token(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    token: u32,
    negative: bool,
    index: usize,
    quantization: LossyQuantization,
) -> PortableResult<(i32, u32)> {
    dequantize_lossy_coefficient_with_token_using_matrix(
        decoder,
        token,
        negative,
        index,
        quantization,
        None,
    )
}

/// Dequantize a coefficient for an AV1 one-dimensional transform.
///
/// Quantization matrices are selected only for two-dimensional transforms;
/// the reference syntax sets its matrix table to null for every transform
/// type at or above `IDTX`. Keeping this as a separate helper prevents the
/// matrix-enabled square and rectangular paths from being changed by the
/// one-dimensional rule.
fn dequantize_lossy_coefficient_with_token_without_matrix(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    token: u32,
    negative: bool,
    index: usize,
    mut quantization: LossyQuantization,
) -> PortableResult<(i32, u32)> {
    quantization.using_matrix = false;
    dequantize_lossy_coefficient_with_token_using_matrix(
        decoder,
        token,
        negative,
        index,
        quantization,
        None,
    )
}

fn dequantize_lossy_coefficient_with_optional_matrix(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    token: u32,
    negative: bool,
    index: usize,
    quantization: LossyQuantization,
    matrix_values: Option<&[u8]>,
) -> PortableResult<(i32, u32)> {
    match matrix_values {
        Some(matrix_values) => dequantize_lossy_coefficient_with_token_using_matrix(
            decoder,
            token,
            negative,
            index,
            quantization,
            Some(matrix_values),
        ),
        None => dequantize_lossy_coefficient_with_token_without_matrix(
            decoder,
            token,
            negative,
            index,
            quantization,
        ),
    }
}

fn dequantize_lossy_coefficient_with_token_using_matrix(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    token: u32,
    negative: bool,
    index: usize,
    quantization: LossyQuantization,
    matrix_values: Option<&[u8]>,
) -> PortableResult<(i32, u32)> {
    dequantize_lossy_coefficient_with_token_using_matrix_and_shift(
        decoder,
        token,
        negative,
        index,
        quantization,
        matrix_values,
        0,
    )
}

fn dequantize_lossy_coefficient_with_token_using_matrix_and_shift(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    token: u32,
    negative: bool,
    index: usize,
    quantization: LossyQuantization,
    matrix_values: Option<&[u8]>,
    dequant_shift: u32,
) -> PortableResult<(i32, u32)> {
    let token = if token == 15 {
        read_golomb(decoder).wrapping_add(15)
    } else {
        token
    } & 0x000f_ffff;
    let qindex = coefficient_qindex(quantization, 0, index);
    let mut quantizer = u32::from(quantization::Y_8BIT[qindex][usize::from(index != 0)]);
    // The admitted lossy leaf is the closed 4:2:0 frame class, whose frame
    // header selects luma matrix 10. AV1 scales the DC/AC dequantizer before
    // multiplying by the coefficient token; applying the matrix afterwards
    // would change both direct and Golomb-extended coefficient values.
    if quantization.using_matrix {
        let matrix_values = if let Some(matrix_values) = matrix_values {
            matrix_values
        } else {
            match quantization.matrix_y {
                9 => &quantization::Y_8X8_MATRIX_9,
                10 => &quantization::Y_8X8_MATRIX_10,
                _ => return Err(PortableUnavailable),
            }
        };
        let matrix = u32::from(matrix_values.get(index).copied().unwrap_or(32));
        quantizer = quantizer.saturating_mul(matrix).saturating_add(16) >> 5;
    }
    // AV1 applies the coefficient product mask before its sign-dependent
    // clamp. The order matters for the pinned Golomb and twenty-bit token
    // controls, and keeps this boundary equivalent to the safe fixed-width
    // arithmetic used by the reference decoder.
    let dequantized = quantizer.wrapping_mul(token) & 0x00ff_ffff;
    let coefficient_max = 32_767_u32.wrapping_add(u32::from(negative));
    let magnitude = (dequantized >> dequant_shift).min(coefficient_max) as i32;
    let coefficient = if negative {
        magnitude.wrapping_neg()
    } else {
        magnitude
    };
    Ok((coefficient, token))
}

