fn dequantize_lossy_coefficient(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    token: u32,
    negative: bool,
    index: usize,
    quantization: LossyQuantization,
) -> PortableResult<i32> {
    dequantize_lossy_coefficient_with_token(decoder, token, negative, index, quantization)
        .map(|(coefficient, _)| coefficient)
}

fn dequantize_lossy_chroma_coefficient_with_token_using_matrix(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    token: u32,
    negative: bool,
    index: usize,
    plane: usize,
    quantization: LossyQuantization,
    matrix_values: Option<&[u8]>,
) -> PortableResult<(i32, u32)> {
    let token = if token == 15 {
        read_golomb(decoder).wrapping_add(15)
    } else {
        token
    } & 0x000f_ffff;
    let qindex = coefficient_qindex(quantization, plane, index);
    let mut quantizer = u32::from(quantization::UV_8BIT[qindex][usize::from(index != 0)]);
    if quantization.using_matrix {
        let matrix_index = match plane {
            1 => quantization.matrix_u,
            2 => quantization.matrix_v,
            _ => return Err(PortableUnavailable),
        };
        let matrix_values = if let Some(matrix_values) = matrix_values {
            matrix_values
        } else {
            match matrix_index {
                9 => &quantization::UV_8X8_MATRIX_9,
                10 => &quantization::UV_8X8_MATRIX_10,
                _ => return Err(PortableUnavailable),
            }
        };
        let matrix = u32::from(
            matrix_values
                .get(index)
                .copied()
                .ok_or(PortableUnavailable)?,
        );
        quantizer = quantizer.saturating_mul(matrix).saturating_add(16) >> 5;
    }
    let dequantized = quantizer.wrapping_mul(token) & 0x00ff_ffff;
    let coefficient_max = 32_767_u32.wrapping_add(u32::from(negative));
    let magnitude = dequantized.min(coefficient_max) as i32;
    let coefficient = if negative {
        magnitude.wrapping_neg()
    } else {
        magnitude
    };
    Ok((coefficient, token))
}

