// ✅ VERIFIED: dav1d 1.5.3 src/itx_1d.c:1066-1080.
fn inverse_wht_4(values: &mut [i32; 4]) {
    let input_zero = values[0];
    let input_one = values[1];
    let input_two = values[2];
    let input_three = values[3];
    let temporary_zero = input_zero.wrapping_add(input_one);
    let temporary_two = input_two.wrapping_sub(input_three);
    let temporary_four = temporary_zero.wrapping_sub(temporary_two) >> 1;
    let temporary_three = temporary_four.wrapping_sub(input_three);
    let temporary_one = temporary_four.wrapping_sub(input_one);
    *values = [
        temporary_zero.wrapping_sub(temporary_three),
        temporary_three,
        temporary_one,
        temporary_two.wrapping_add(temporary_one),
    ];
}

// ✅ VERIFIED: dav1d 1.5.3 src/itx_tmpl.c:184-207.
fn inverse_wht_4x4(coefficients: TransformCoefficients) -> [i32; 16] {
    let mut values = [0_i32; 16];
    let columns = [[0, 4, 8, 12], [1, 5, 9, 13], [2, 6, 10, 14], [3, 7, 11, 15]];
    for (row, indices) in values.as_chunks_mut::<4>().0.iter_mut().zip(columns) {
        let mut vector = [
            coefficients[indices[0]] >> 2,
            coefficients[indices[1]] >> 2,
            coefficients[indices[2]] >> 2,
            coefficients[indices[3]] >> 2,
        ];
        inverse_wht_4(&mut vector);
        row.copy_from_slice(&vector);
    }
    for indices in columns {
        let mut vector = [
            values[indices[0]],
            values[indices[1]],
            values[indices[2]],
            values[indices[3]],
        ];
        inverse_wht_4(&mut vector);
        for (index, value) in indices.into_iter().zip(vector) {
            values[index] = value;
        }
    }
    values
}

fn reconstruct_transform(predictor: u16, coefficients: TransformCoefficients) -> [u16; 16] {
    let residual = inverse_wht_4x4(coefficients);
    let mut samples = [0_u16; 16];
    for (sample, value) in samples.iter_mut().zip(residual) {
        let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
        #[expect(
            clippy::cast_sign_loss,
            reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
        )]
        let reconstructed = reconstructed as u16;
        *sample = reconstructed;
    }
    samples
}

fn reconstruct_lossy_luma_4x8(
    top: [u16; 4],
    left: [u16; 8],
    coefficients: Option<Lossy4x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> ReconstructedPlane {
    let predictor = rectangular_dc_predictor(&top, &left);
    let prediction = [predictor; 32];
    reconstruct_lossy_luma_4x8_from_prediction(prediction, coefficients, transform_kind)
}

fn reconstruct_lossy_luma_4x8_from_prediction(
    prediction: [u16; 32],
    coefficients: Option<Lossy4x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 32]);
    let residual = match transform_kind {
        Lossy4x8TransformKind::IdentityIdentity => transform::inverse_identity4x8(&coefficients),
        Lossy4x8TransformKind::DctDct => transform::inverse_dct4x8(&coefficients),
        Lossy4x8TransformKind::IdentityDct => transform::inverse_identity_dct4x8(&coefficients),
        Lossy4x8TransformKind::DctIdentity => transform::inverse_dct_identity4x8(&coefficients),
        Lossy4x8TransformKind::AdstAdst => transform::inverse_adst_adst4x8(&coefficients),
        Lossy4x8TransformKind::AdstDct => transform::inverse_adst_dct4x8(&coefficients),
        Lossy4x8TransformKind::DctAdst => transform::inverse_dct_adst4x8(&coefficients),
    };
    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_4x8_smooth(
    top: [u16; 4],
    top_right: u16,
    left: [u16; 8],
    coefficients: Option<Lossy4x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> ReconstructedPlane {
    const SMOOTH_WEIGHTS_4: [i32; 4] = [255, 149, 85, 64];
    const SMOOTH_WEIGHTS_8: [i32; 8] = [255, 197, 146, 105, 73, 50, 37, 32];
    let right = i32::from(top_right);
    let bottom = i32::from(left[7]);
    let prediction: [u16; 32] = std::array::from_fn(|index| {
        let y = index / 4;
        let x = index % 4;
        let vertical_weight = SMOOTH_WEIGHTS_8[y];
        let horizontal_weight = SMOOTH_WEIGHTS_4[x];
        let value = vertical_weight
            .saturating_mul(i32::from(top[x]))
            .saturating_add(
                256_i32
                    .saturating_sub(vertical_weight)
                    .saturating_mul(bottom),
            )
            .saturating_add(horizontal_weight.saturating_mul(i32::from(left[y])))
            .saturating_add(
                256_i32
                    .saturating_sub(horizontal_weight)
                    .saturating_mul(right),
            )
            .saturating_add(256)
            >> 9;
        #[expect(
            clippy::cast_sign_loss,
            reason = "the smooth predictor is explicitly clamped to eight-bit range"
        )]
        {
            value.clamp(0, 255) as u16
        }
    });
    reconstruct_lossy_luma_4x8_from_prediction(prediction, coefficients, transform_kind)
}

