fn reconstruct_lossy_luma_4x16_from_prediction(
    prediction: [u16; 64],
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        Lossy4x8TransformKind::IdentityIdentity => transform::inverse_identity4x16(&coefficients),
        Lossy4x8TransformKind::DctDct => transform::inverse_dct4x16(&coefficients),
        Lossy4x8TransformKind::IdentityDct => transform::inverse_identity_dct4x16(&coefficients),
        Lossy4x8TransformKind::DctIdentity => transform::inverse_dct_identity4x16(&coefficients),
        Lossy4x8TransformKind::AdstAdst => transform::inverse_adst_adst4x16(&coefficients),
        Lossy4x8TransformKind::AdstDct => transform::inverse_adst_dct4x16(&coefficients),
        Lossy4x8TransformKind::DctAdst => transform::inverse_dct_adst4x16(&coefficients),
    };
    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

