fn reconstruct_lossy_luma_4x16_diagonal_z2(
    top: [u16; 4],
    left: [u16; 16],
    top_left: u16,
    angle: i32,
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;

    let upsample_above = angle.saturating_sub(90) < 40;
    let mut edge = [0_u16; 64];
    const TOP_LEFT_INDEX: usize = 24;
    edge[TOP_LEFT_INDEX] = top_left;
    if upsample_above {
        let source = [top_left, top[0], top[1], top[2], top[3]];
        let mut upsampled = [0_u16; 9];
        const KERNEL: [i32; 4] = [-1, 9, 9, -1];
        for index in 0_usize..4 {
            upsampled[index.saturating_mul(2)] = source[index];
            let mut sum = 0_i32;
            for (tap, weight) in KERNEL.into_iter().enumerate() {
                let source_index = index
                    .saturating_add(tap)
                    .saturating_sub(1)
                    .min(source.len().saturating_sub(1));
                sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
            }
            #[expect(
                clippy::cast_sign_loss,
                reason = "the upsampled angular edge is explicitly clamped"
            )]
            {
                upsampled[index.saturating_mul(2).saturating_add(1)] =
                    ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
            }
        }
        upsampled[8] = source[4];
        edge[TOP_LEFT_INDEX..TOP_LEFT_INDEX.saturating_add(9)].copy_from_slice(&upsampled);
    } else {
        edge[TOP_LEFT_INDEX.saturating_add(1)..TOP_LEFT_INDEX.saturating_add(5)]
            .copy_from_slice(&top);
    }
    for (index, sample) in left.into_iter().enumerate() {
        edge[TOP_LEFT_INDEX.saturating_sub(1).saturating_sub(index)] = sample;
    }

    let base_increment = if upsample_above { 2_i32 } else { 1_i32 };
    let dx = if upsample_above {
        dx.saturating_mul(2)
    } else {
        dx
    };
    let mut prediction = [0_u16; 64];
    for y_index in 0_usize..16 {
        let y = i32::try_from(y_index).map_err(|_| PortableUnavailable)?;
        let top_scale: i32 = if upsample_above { 2 } else { 1 };
        let xpos = top_scale
            .saturating_mul(64)
            .saturating_sub(dx.saturating_mul(y.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x_index in 0_usize..4 {
            let x = i32::try_from(x_index).map_err(|_| PortableUnavailable)?;
            let base_x = base_x.saturating_add(base_increment.saturating_mul(x));
            let sample = if base_x >= 0 {
                let first = usize::try_from(
                    i32::try_from(TOP_LEFT_INDEX)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_add(base_x),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = first.saturating_add(1);
                let first = i32::from(*edge.get(first).portable()?);
                let second = i32::from(*edge.get(second).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let ypos = y
                    .saturating_mul(64)
                    .saturating_sub(dy.saturating_mul(x.saturating_add(1)));
                let base_y = ypos >> 6;
                let frac_y = ypos & 0x3e;
                let first = usize::try_from(
                    i32::try_from(TOP_LEFT_INDEX)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(1)
                        .saturating_sub(base_y),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = usize::try_from(
                    i32::try_from(TOP_LEFT_INDEX)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(1)
                        .saturating_sub(base_y.saturating_add(1)),
                )
                .map_err(|_| PortableUnavailable)?;
                let first = i32::from(*edge.get(first).portable()?);
                let second = i32::from(*edge.get(second).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            #[expect(
                clippy::cast_sign_loss,
                reason = "the angular predictor is explicitly clamped to eight-bit range"
            )]
            let sample = sample.clamp(0, 255) as u16;
            prediction[y_index.saturating_mul(4).saturating_add(x_index)] = sample;
        }
    }
    Ok(reconstruct_lossy_luma_4x16_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn reconstruct_lossy_luma_4x8_diagonal_z2(
    top: [u16; 4],
    left: [u16; 8],
    top_left: u16,
    angle: i32,
    coefficients: Option<Lossy4x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> PortableResult<ReconstructedPlane> {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:965-1098 and
    // src/tables.rs:1083-1085. This is the Zone-2 angular predictor for a
    // 4×8 transform. For the admitted 113° sentence the top edge is
    // upsampled and the left edge remains at native resolution.
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;
    let upsample_above = angle.saturating_sub(90) < 40;
    let mut edge = [0_u16; 32];
    const TOP_LEFT_INDEX: usize = 12;
    edge[TOP_LEFT_INDEX] = top_left;
    if upsample_above {
        let mut source = [0_u16; 5];
        source[0] = top_left;
        source[1..].copy_from_slice(&top);
        let mut upsampled = [0_u16; 9];
        const KERNEL: [i32; 4] = [-1, 9, 9, -1];
        for index in 0_usize..4 {
            upsampled[index.saturating_mul(2)] = source[index];
            let mut sum = 0_i32;
            for (tap, weight) in KERNEL.into_iter().enumerate() {
                let source_index = index
                    .saturating_add(tap)
                    .saturating_sub(1)
                    .min(source.len().saturating_sub(1));
                sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
            }
            #[expect(
                clippy::cast_sign_loss,
                reason = "the upsampled angular edge is explicitly clamped"
            )]
            let value = ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
            upsampled[index.saturating_mul(2).saturating_add(1)] = value;
        }
        upsampled[8] = source[4];
        edge[TOP_LEFT_INDEX..TOP_LEFT_INDEX.saturating_add(9)].copy_from_slice(&upsampled);
    } else {
        edge[TOP_LEFT_INDEX.saturating_add(1)..TOP_LEFT_INDEX.saturating_add(5)]
            .copy_from_slice(&top);
    }
    for (index, sample) in left.into_iter().enumerate() {
        edge[TOP_LEFT_INDEX.saturating_sub(1).saturating_sub(index)] = sample;
    }

    let base_increment = if upsample_above { 2_i32 } else { 1_i32 };
    let dx = if upsample_above {
        dx.saturating_mul(2)
    } else {
        dx
    };
    let mut prediction = [0_u16; 32];
    for y_index in 0_usize..8 {
        let y = i32::try_from(y_index).map_err(|_| PortableUnavailable)?;
        let top_scale: i32 = if upsample_above { 2 } else { 1 };
        let xpos = top_scale
            .saturating_mul(64)
            .saturating_sub(dx.saturating_mul(y.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x_index in 0_usize..4 {
            let x = i32::try_from(x_index).map_err(|_| PortableUnavailable)?;
            let base_x = base_x.saturating_add(base_increment.saturating_mul(x));
            let sample = if base_x >= 0 {
                let first = usize::try_from(
                    i32::try_from(TOP_LEFT_INDEX)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_add(base_x),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = first.saturating_add(1);
                let first = i32::from(*edge.get(first).portable()?);
                let second = i32::from(*edge.get(second).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let ypos = y
                    .saturating_mul(64)
                    .saturating_sub(dy.saturating_mul(x.saturating_add(1)));
                let base_y = ypos >> 6;
                let frac_y = ypos & 0x3e;
                let first = usize::try_from(
                    i32::try_from(TOP_LEFT_INDEX)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(1)
                        .saturating_sub(base_y),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = usize::try_from(
                    i32::try_from(TOP_LEFT_INDEX)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(1)
                        .saturating_sub(base_y.saturating_add(1)),
                )
                .map_err(|_| PortableUnavailable)?;
                let first = i32::from(*edge.get(first).portable()?);
                let second = i32::from(*edge.get(second).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            #[expect(
                clippy::cast_sign_loss,
                reason = "the angular predictor is explicitly clamped to eight-bit range"
            )]
            let sample = sample.clamp(0, 255) as u16;
            let prediction_index = y_index.saturating_mul(4).saturating_add(x_index);
            prediction[prediction_index] = sample;
        }
    }
    Ok(reconstruct_lossy_luma_4x8_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn reconstruct_lossy_luma_8x4_diagonal_z2(
    top: [u16; 8],
    left: [u16; 4],
    top_left: u16,
    angle: i32,
    coefficients: Option<Lossy4x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> PortableResult<ReconstructedPlane> {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:965-1098. This is the same
    // checked Zone-2 predictor as the 4×8 implementation above, with the
    // dimensions and edge-upsample rules applied to an 8×4 terminal.
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let mut dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let mut dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;
    let upsample_above = angle.saturating_sub(90) < 40;
    let upsample_left = 180_i32.saturating_sub(angle) < 40;

    let mut edge = [0_u16; 64];
    const TOP_LEFT_INDEX: usize = 32;
    edge[TOP_LEFT_INDEX] = top_left;
    if upsample_above {
        let mut source = [0_u16; 9];
        source[0] = top_left;
        source[1..].copy_from_slice(&top);
        let mut upsampled = [0_u16; 17];
        const KERNEL: [i32; 4] = [-1, 9, 9, -1];
        for index in 0_usize..8 {
            upsampled[index.saturating_mul(2)] = source[index];
            let mut sum = 0_i32;
            for (tap, weight) in KERNEL.into_iter().enumerate() {
                let source_index = index
                    .saturating_add(tap)
                    .saturating_sub(1)
                    .min(source.len().saturating_sub(1));
                sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
            }
            #[expect(
                clippy::cast_sign_loss,
                reason = "the upsampled angular edge is explicitly clamped"
            )]
            {
                upsampled[index.saturating_mul(2).saturating_add(1)] =
                    ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
            }
        }
        upsampled[16] = source[8];
        edge[TOP_LEFT_INDEX..TOP_LEFT_INDEX.saturating_add(17)].copy_from_slice(&upsampled);
        dx = dx.saturating_mul(2);
    } else {
        edge[TOP_LEFT_INDEX.saturating_add(1)..TOP_LEFT_INDEX.saturating_add(9)]
            .copy_from_slice(&top);
    }

    if upsample_left {
        let mut source = [0_u16; 5];
        source[..4].copy_from_slice(&[left[3], left[2], left[1], left[0]]);
        source[4] = top_left;
        let mut upsampled = [0_u16; 9];
        const KERNEL: [i32; 4] = [-1, 9, 9, -1];
        for index in 0_usize..4 {
            upsampled[index.saturating_mul(2)] = source[index];
            let mut sum = 0_i32;
            for (tap, weight) in KERNEL.into_iter().enumerate() {
                let source_index = index
                    .saturating_add(tap)
                    .saturating_sub(1)
                    .min(source.len().saturating_sub(1));
                sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
            }
            #[expect(
                clippy::cast_sign_loss,
                reason = "the upsampled angular edge is explicitly clamped"
            )]
            {
                upsampled[index.saturating_mul(2).saturating_add(1)] =
                    ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
            }
        }
        upsampled[8] = source[4];
        edge[TOP_LEFT_INDEX.saturating_sub(8)..=TOP_LEFT_INDEX].copy_from_slice(&upsampled);
        dy = dy.saturating_mul(2);
    } else {
        for (index, sample) in left.into_iter().enumerate() {
            edge[TOP_LEFT_INDEX.saturating_sub(1).saturating_sub(index)] = sample;
        }
    }

    let base_increment = if upsample_above { 2_i32 } else { 1_i32 };
    let left_index = TOP_LEFT_INDEX.saturating_sub(if upsample_left { 2 } else { 1 });
    let mut prediction = [0_u16; 32];
    for y_index in 0_usize..4 {
        let y = i32::try_from(y_index).map_err(|_| PortableUnavailable)?;
        let xpos = (if upsample_above { 2_i32 } else { 1_i32 })
            .saturating_mul(64)
            .saturating_sub(dx.saturating_mul(y.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x_index in 0_usize..8 {
            let x = i32::try_from(x_index).map_err(|_| PortableUnavailable)?;
            let base_x = base_x.saturating_add(base_increment.saturating_mul(x));
            let ypos = y
                .saturating_mul(if upsample_left { 128 } else { 64 })
                .saturating_sub(dy.saturating_mul(x.saturating_add(1)));
            let sample = if base_x >= 0 {
                let first = usize::try_from(
                    i32::try_from(TOP_LEFT_INDEX)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_add(base_x),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = first.saturating_add(1);
                let first = i32::from(*edge.get(first).portable()?);
                let second = i32::from(*edge.get(second).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let base_y = ypos >> 6;
                let frac_y = ypos & 0x3e;
                let first = usize::try_from(
                    i32::try_from(left_index)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(base_y),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = usize::try_from(
                    i32::try_from(left_index)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(base_y.saturating_add(1)),
                )
                .map_err(|_| PortableUnavailable)?;
                let first = i32::from(*edge.get(first).portable()?);
                let second = i32::from(*edge.get(second).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            #[expect(
                clippy::cast_sign_loss,
                reason = "the angular predictor is explicitly clamped to eight-bit range"
            )]
            let sample = sample.clamp(0, 255) as u16;
            prediction[y_index.saturating_mul(8).saturating_add(x_index)] = sample;
        }
    }
    Ok(reconstruct_lossy_luma_8x4_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn reconstruct_lossy_luma_8x8(
    predictor: u16,
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };

    let samples: Vec<u16> = residual
        .into_iter()
        .map(|value| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();

    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_8x8_diagonal_z1(
    top: [u16; 8],
    top_left: u16,
    angle: i32,
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (0 < angle && angle < 90).then_some(()).portable()?;
    let dx_index = usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?;
    let dx = *DR_INTRA_DERIVATIVE
        .get(dx_index)
        .filter(|&&value| value > 0)
        .portable()?;
    let upsample = 50 < angle;
    let upsampled_edge = upsample_intra_top_edge(top, top_left);
    let (edge, max_base_x, dx, base_increment) = if upsample {
        (&upsampled_edge[..], 14, dx.saturating_mul(2), 2)
    } else {
        (&top[..], 7, dx, 1)
    };
    let mut prediction = [0_u16; 64];
    for y in 0_usize..8 {
        for x in 0_usize..8 {
            prediction[y.saturating_mul(8).saturating_add(x)] =
                diagonal_z1_predictor_sample(edge, max_base_x, dx, base_increment, x, y)?;
        }
    }

    Ok(reconstruct_lossy_luma_8x8_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn reconstruct_lossy_luma_8x8_diagonal_z1_extended(
    top: [u16; 16],
    top_left: u16,
    angle: i32,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (0 < angle && angle < 90).then_some(()).portable()?;
    let dx_index = usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?;
    let dx = *DR_INTRA_DERIVATIVE
        .get(dx_index)
        .filter(|&&value| value > 0)
        .portable()?;

    let filtered_top = if enable_intra_edge_filter {
        let strength = intra_edge_filter_strength(16, 90_i32.saturating_sub(angle), smooth_edges);
        if strength == 0 {
            top
        } else {
            filter_intra_top_edge_16(top, top_left, strength)
        }
    } else {
        top
    };
    // dav1d suppresses edge upsampling for smooth-neighbor blocks.  Its
    // generic rule is `angle_delta < 40 && width + height <= 16 >> is_sm`;
    // this helper is specifically for an 8×8 terminal, so a smooth edge
    // makes the 16-sample span fail that size check.
    let upsample = 50 < angle && !smooth_edges;
    let upsampled_edge = upsample_intra_top_edge_16(filtered_top, top_left);
    let (edge, max_base_x, dx, base_increment) = if upsample {
        (&upsampled_edge[..], 30, dx.saturating_mul(2), 2)
    } else {
        (&filtered_top[..], 15, dx, 1)
    };
    let mut prediction = [0_u16; 64];
    for y in 0_usize..8 {
        for x in 0_usize..8 {
            prediction[y.saturating_mul(8).saturating_add(x)] =
                diagonal_z1_predictor_sample(edge, max_base_x, dx, base_increment, x, y)?;
        }
    }

    let result =
        reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform_kind);

    Ok(result)
}

fn reconstruct_lossy_luma_8x8_from_prediction(
    prediction: [u16; 64],
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };

    reconstruct_lossy_predicted_plane(&prediction, &residual)
}

fn reconstruct_lossy_residual_plane(predictor: u16, residual: &[i32]) -> ReconstructedPlane {
    let samples = residual
        .iter()
        .map(|&value| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_predicted_plane(prediction: &[u16], residual: &[i32]) -> ReconstructedPlane {
    let samples = prediction
        .iter()
        .zip(residual)
        .map(|(&predictor, &value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to eight-bit range"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_16x16(
    predictor: u16,
    coefficients: Option<Lossy16x16TransformCoefficients>,
    transform_kind: Lossy16x16TransformKind,
) -> ReconstructedPlane {
    reconstruct_lossy_luma_16x16_from_prediction([predictor; 256], coefficients, transform_kind)
}

fn reconstruct_lossy_luma_16x16_from_prediction(
    prediction: [u16; 256],
    coefficients: Option<Lossy16x16TransformCoefficients>,
    transform_kind: Lossy16x16TransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 256]);
    let residual = match transform_kind {
        Lossy16x16TransformKind::IdentityIdentity => {
            transform::inverse_identity16x16(&coefficients)
        }
        Lossy16x16TransformKind::DctDct => transform::inverse_dct16x16(&coefficients),
        Lossy16x16TransformKind::AdstAdst => transform::inverse_adst_adst16x16(&coefficients),
        Lossy16x16TransformKind::AdstDct => transform::inverse_adst_dct16x16(&coefficients),
        Lossy16x16TransformKind::DctAdst => transform::inverse_dct_adst16x16(&coefficients),
    };

    reconstruct_lossy_predicted_plane(&prediction, &residual)
}

fn reconstruct_lossy_luma_16x16_split_from_prediction(
    prediction: [u16; 256],
    split: LossyLuma8x8Split,
) -> ReconstructedPlane {
    let mut samples = vec![0_u16; 256];
    for transform_index in 0_usize..4 {
        let row = transform_index / 2;
        let column = transform_index % 2;
        let offset_x = column.saturating_mul(8);
        let offset_y = row.saturating_mul(8);
        let block_prediction = std::array::from_fn(|index| {
            let block_row = index / 8;
            let block_column = index % 8;
            prediction[(offset_y + block_row).saturating_mul(16) + offset_x + block_column]
        });
        let block = reconstruct_lossy_luma_8x8_from_prediction(
            block_prediction,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        );
        for (block_row, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
            let output_start = (offset_y + block_row).saturating_mul(16) + offset_x;
            samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
        }
    }
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_16x16_smooth_horizontal(
    left: [u16; 16],
    right: u16,
    coefficients: Option<Lossy16x16TransformCoefficients>,
    transform_kind: Lossy16x16TransformKind,
) -> ReconstructedPlane {
    const SMOOTH_WEIGHTS_16: [i32; 16] = [
        255, 225, 196, 170, 145, 123, 102, 84, 68, 54, 43, 33, 26, 20, 17, 16,
    ];
    let right = i32::from(right);
    let prediction = std::array::from_fn(|index| {
        let x = index % 16;
        let value = SMOOTH_WEIGHTS_16[x]
            .saturating_mul(i32::from(left[index / 16]))
            .saturating_add(
                256_i32
                    .saturating_sub(SMOOTH_WEIGHTS_16[x])
                    .saturating_mul(right),
            )
            .saturating_add(128)
            >> 8;
        #[expect(
            clippy::cast_sign_loss,
            reason = "the smooth predictor is explicitly clamped to eight-bit range"
        )]
        {
            value.clamp(0, 255) as u16
        }
    });
    reconstruct_lossy_luma_16x16_from_prediction(prediction, coefficients, transform_kind)
}

fn reconstruct_lossy_luma_32x32(
    predictor: u16,
    coefficients: Option<Lossy32x32TransformCoefficients>,
) -> ReconstructedPlane {
    reconstruct_lossy_32x32_from_prediction([predictor; 1024], coefficients)
}

fn reconstruct_lossy_32x32_from_prediction(
    prediction: [u16; 1024],
    coefficients: Option<Lossy32x32TransformCoefficients>,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 1024]);
    let residual = transform::inverse_dct32x32(&coefficients);
    reconstruct_lossy_predicted_plane(&prediction, &residual)
}

fn reconstruct_lossy_luma_16x64(
    predictor: u16,
    coefficients: Option<Lossy16x64TransformCoefficients>,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 512]);
    let residual = transform::inverse_dct16x64(&coefficients);
    reconstruct_lossy_residual_plane(predictor, &residual)
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R16x32 predictor needs its complete coded edges and transform syntax"
)]
fn reconstruct_lossy_luma_16x32_from_edges(
    predictor: LumaPredictor,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 32],
    top_left: u16,
    has_left: bool,
    coefficients: Lossy16x32TransformCoefficients,
    transform_kind: Lossy16x16TransformKind,
) -> PortableResult<ReconstructedPlane> {
    let prediction: [u16; 512] = if let Some(mode) = filter_intra_mode {
        reconstruct_filter_intra_prediction(mode, 16, 32, top_left, &top, &left)?
            .try_into()
            .map_err(|_| PortableUnavailable)?
    } else {
        match predictor {
            LumaPredictor::Dc => {
                let value = if has_left {
                    rectangular_dc_predictor(&top, &left)
                } else {
                    one_sided_dc_predictor_16(top)
                };
                [value; 512]
            }
            LumaPredictor::Vertical => std::array::from_fn(|index| top[index % 16]),
            LumaPredictor::Horizontal => std::array::from_fn(|index| left[index / 16]),
            LumaPredictor::Smooth => {
                const SMOOTH_WEIGHTS_16: [i32; 16] = [
                    255, 225, 196, 170, 145, 123, 102, 84, 68, 54, 43, 33, 26, 20, 17, 16,
                ];
                const SMOOTH_WEIGHTS_32: [i32; 32] = [
                    255, 240, 225, 210, 196, 182, 169, 157, 145, 133, 122, 111, 101, 92, 83, 74,
                    66, 59, 52, 45, 39, 34, 29, 25, 21, 17, 14, 12, 10, 9, 8, 8,
                ];
                let bottom = i32::from(left[31]);
                let right = i32::from(top[15]);
                std::array::from_fn(|index| {
                    let row = index / 16;
                    let column = index % 16;
                    let vertical_weight = SMOOTH_WEIGHTS_32[row];
                    let horizontal_weight = SMOOTH_WEIGHTS_16[column];
                    let value = vertical_weight
                        .saturating_mul(i32::from(top[column]))
                        .saturating_add(
                            256_i32
                                .saturating_sub(vertical_weight)
                                .saturating_mul(bottom),
                        )
                        .saturating_add(horizontal_weight.saturating_mul(i32::from(left[row])))
                        .saturating_add(
                            256_i32
                                .saturating_sub(horizontal_weight)
                                .saturating_mul(right),
                        )
                        .saturating_add(256)
                        >> 9;
                    #[expect(
                        clippy::cast_sign_loss,
                        reason = "the smooth predictor is explicitly clamped to eight-bit range"
                    )]
                    {
                        value.clamp(0, 255) as u16
                    }
                })
            }
            LumaPredictor::SmoothVertical => {
                const SMOOTH_WEIGHTS_32: [i32; 32] = [
                    255, 240, 225, 210, 196, 182, 169, 157, 145, 133, 122, 111, 101, 92, 83, 74,
                    66, 59, 52, 45, 39, 34, 29, 25, 21, 17, 14, 12, 10, 9, 8, 8,
                ];
                let bottom = i32::from(left[31]);
                std::array::from_fn(|index| {
                    let weight = SMOOTH_WEIGHTS_32[index / 16];
                    let value = weight
                        .saturating_mul(i32::from(top[index % 16]))
                        .saturating_add(256_i32.saturating_sub(weight).saturating_mul(bottom))
                        .saturating_add(128)
                        >> 8;
                    #[expect(
                        clippy::cast_sign_loss,
                        reason = "the smooth predictor is explicitly clamped to eight-bit range"
                    )]
                    {
                        value.clamp(0, 255) as u16
                    }
                })
            }
            LumaPredictor::SmoothHorizontal => {
                const SMOOTH_WEIGHTS_16: [i32; 16] = [
                    255, 225, 196, 170, 145, 123, 102, 84, 68, 54, 43, 33, 26, 20, 17, 16,
                ];
                let right = i32::from(top[15]);
                std::array::from_fn(|index| {
                    let weight = SMOOTH_WEIGHTS_16[index % 16];
                    let value = weight
                        .saturating_mul(i32::from(left[index / 16]))
                        .saturating_add(256_i32.saturating_sub(weight).saturating_mul(right))
                        .saturating_add(128)
                        >> 8;
                    #[expect(
                        clippy::cast_sign_loss,
                        reason = "the smooth predictor is explicitly clamped to eight-bit range"
                    )]
                    {
                        value.clamp(0, 255) as u16
                    }
                })
            }
            LumaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(top[index % 16], left[index / 16], top_left)
            }),
            LumaPredictor::Diagonal45
            | LumaPredictor::DiagonalDownRight
            | LumaPredictor::Diagonal113
            | LumaPredictor::Diagonal157
            | LumaPredictor::Diagonal203
            | LumaPredictor::Diagonal67 => return Err(PortableUnavailable),
        }
    };
    let residual = match transform_kind {
        Lossy16x16TransformKind::DctDct => transform::inverse_dct16x32(&coefficients),
        Lossy16x16TransformKind::AdstDct => transform::inverse_adst_dct16x32(&coefficients),
        _ => return Err(PortableUnavailable),
    };
    Ok(reconstruct_lossy_predicted_plane(&prediction, &residual))
}

fn reconstruct_lossy_luma_32x16(
    predictor: u16,
    coefficients: Option<Lossy32x16TransformCoefficients>,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 512]);
    let residual = transform::inverse_dct32x16(&coefficients);
    reconstruct_lossy_residual_plane(predictor, &residual)
}

