/// Reconstruct an R64x16 luma block with AV1's smooth-horizontal predictor.
///
/// The predictor blends the right-most top sample with each sample on the
/// left edge using the width-specific smooth weights.  R64x16 has an
/// implicitly selected DCT-DCT residual transform because its transform
/// dimensions reach the AV1 large-transform limit.
fn reconstruct_lossy_luma_64x16_smooth_horizontal(
    top: [u16; 64],
    left: [u16; 16],
    coefficients: Option<Lossy64x16TransformCoefficients>,
) -> ReconstructedPlane {
    const SMOOTH_WEIGHTS_64: [i32; 64] = [
        255, 248, 240, 233, 225, 218, 210, 203, 196, 189, 182, 176, 169, 163, 156, 150, 144, 138,
        133, 127, 121, 116, 111, 106, 101, 96, 91, 86, 82, 77, 73, 69, 65, 61, 57, 54, 50, 47, 44,
        41, 38, 35, 32, 29, 27, 25, 22, 20, 18, 16, 15, 13, 12, 10, 9, 8, 7, 6, 6, 5, 5, 4, 4, 4,
    ];
    let right = i32::from(top[63]);
    let prediction: [u16; 1024] = std::array::from_fn(|index| {
        let row = index / 64;
        let column = index % 64;
        let weight = SMOOTH_WEIGHTS_64[column];
        let value = weight
            .saturating_mul(i32::from(left[row]))
            .saturating_add((256_i32.saturating_sub(weight)).saturating_mul(right))
            .saturating_add(128)
            >> 8;
        #[expect(
            clippy::cast_sign_loss,
            reason = "the smooth predictor is explicitly clamped to eight-bit range"
        )]
        {
            value.clamp(0, 255) as u16
        }
    });
    reconstruct_lossy_luma_64x16_from_prediction(prediction, coefficients)
}

