fn reconstruct_lossy_luma_4x8_diagonal_z1(
    top: [u16; 4],
    top_left: u16,
    angle: i32,
    coefficients: Option<Lossy4x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> PortableResult<ReconstructedPlane> {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:881-963. Zone 1 uses the
    // top edge only; the eight-row terminal extends the final top sample in
    // the same checked edge layout as the reference decoder.
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (0 < angle && angle < 90).then_some(()).portable()?;
    let dx_index = usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?;
    let dx = *DR_INTRA_DERIVATIVE
        .get(dx_index)
        .filter(|&&value| value > 0)
        .portable()?;
    let edge = [
        top[0], top[1], top[2], top[3], top[3], top[3], top[3], top[3],
    ];
    let upsample = 50 < angle;
    let upsampled_edge = upsample_intra_top_edge(edge, top_left);
    let (edge, max_base_x, dx, base_increment) = if upsample {
        (&upsampled_edge[..], 14, dx.saturating_mul(2), 2)
    } else {
        (&edge[..], 7, dx, 1)
    };
    let mut prediction = [0_u16; 32];
    for y in 0_usize..8 {
        for x in 0_usize..4 {
            prediction[y.saturating_mul(4).saturating_add(x)] =
                diagonal_z1_predictor_sample(edge, max_base_x, dx, base_increment, x, y)?;
        }
    }
    Ok(reconstruct_lossy_luma_4x8_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn reconstruct_lossy_luma_8x4_diagonal_z1(
    top: [u16; 8],
    top_left: u16,
    angle: i32,
    coefficients: Option<Lossy4x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (0 < angle && angle < 90).then_some(()).portable()?;
    let dx_index = usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?;
    let dx = *DR_INTRA_DERIVATIVE
        .get(dx_index)
        .filter(|&&value| value > 0)
        .portable()?;
    let upsample = 50 < angle;
    let upsampled_edge = upsample_intra_top_edge(top, top_left);
    let (edge, max_base_x, dx, base_increment) = if upsample {
        (&upsampled_edge[..], 14, dx.saturating_mul(2), 2)
    } else {
        (&top[..], 7, dx, 1)
    };
    let mut prediction = [0_u16; 32];
    for y in 0_usize..4 {
        for x in 0_usize..8 {
            prediction[y.saturating_mul(8).saturating_add(x)] =
                diagonal_z1_predictor_sample(edge, max_base_x, dx, base_increment, x, y)?;
        }
    }
    Ok(reconstruct_lossy_luma_8x4_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn reconstruct_lossy_luma_8x4_diagonal_z3(
    left: [u16; 4],
    top_left: u16,
    angle: i32,
    coefficients: Option<Lossy4x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (180 < angle && angle < 270).then_some(()).portable()?;
    let dy_index =
        usize::try_from(270_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let upsample = angle < 220;
    let (edge, max_base_y, dy, base_increment) = if upsample {
        (
            upsample_intra_left_edge_4(left, top_left).to_vec(),
            6,
            dy.saturating_mul(2),
            2,
        )
    } else {
        (left.to_vec(), 3, dy, 1)
    };
    let mut prediction = [0_u16; 32];
    for y in 0_usize..4 {
        for x in 0_usize..8 {
            prediction[y.saturating_mul(8).saturating_add(x)] =
                diagonal_z3_predictor_sample(&edge, max_base_y, dy, base_increment, x, y)?;
        }
    }
    Ok(reconstruct_lossy_luma_8x4_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn reconstruct_lossy_chroma_4x4(
    predictor: u16,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    reconstruct_lossy_4x4(predictor, coefficients, transform_kind)
}

fn reconstruct_cfl_sample(predictor: u16, alpha: i32, ac: i32, residual: i32) -> u16 {
    let scaled = alpha.saturating_mul(ac);
    let magnitude = scaled.abs().saturating_add(32) >> 6;
    let signed = if scaled < 0 {
        magnitude.saturating_neg()
    } else {
        magnitude
    };
    // AV1 clips the CFL predictor before adding the inverse-transform
    // residual. Clipping only the final sum changes saturated predictors.
    let prediction = i32::from(predictor).saturating_add(signed).clamp(0, 255);
    let reconstructed = prediction.saturating_add(residual).clamp(0, 255);
    #[expect(
        clippy::cast_sign_loss,
        reason = "the reconstructed eight-bit sample is explicitly clamped to eight-bit range"
    )]
    {
        reconstructed as u16
    }
}

/// Reconstruct one 4×4 chroma block using AV1's chroma-from-luma predictor.
///
/// CFL derives a zero-mean 4×4 luma AC block from the reconstructed luma
/// footprint corresponding to the 4:2:0 chroma transform. For an 8×8 luma
/// block that footprint is directly available. A 4×4 luma block still has a
/// coded 4×4 chroma transform, so the missing right and bottom halves of its
/// 8×8 luma footprint are edge-extended from the reconstructed block before
/// the AC values are formed. This is the same padding rule used by AV1's CFL
/// AC preparation for a block whose chroma transform extends past its luma
/// samples.
///
/// The signed alpha syntax scales each AC value, and the result is added to
/// the ordinary chroma DC predictor before inverse transform residuals are
/// applied.
fn reconstruct_lossy_chroma_4x4_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    let (luma_width, luma_height): (usize, usize) = match luma.samples.len() {
        16 => (4, 4),
        32 => (4, 8),
        64 => (8, 8),
        _ => return Err(PortableUnavailable),
    };
    reconstruct_lossy_chroma_4x4_cfl_with_shape(
        luma,
        predictor,
        alpha,
        coefficients,
        luma_width,
        luma_height,
    )
}

/// Reconstruct an 8×8 chroma transform with AV1's chroma-from-luma predictor.
///
/// A subsampled 8×8 chroma block corresponds to a 16×16 reconstructed luma
/// block. The four luma samples covered by each chroma sample are averaged in
/// the same signed-AC preparation used by the 4×4 helper below; only the
/// transform and the number of AC samples change.
fn reconstruct_lossy_chroma_8x8_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<LossyTransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    let (luma_width, luma_height) = match luma.samples.len() {
        256 => (16_usize, 16_usize),
        _ => return Err(PortableUnavailable),
    };
    let mut ac = [0_i32; 64];
    let mut sum = 32_i32;
    for y in 0_usize..8 {
        for x in 0_usize..8 {
            let luma_x = x.saturating_mul(2);
            let luma_y = y.saturating_mul(2);
            let sample = |x: usize, y: usize| -> PortableResult<u16> {
                let x = x.min(luma_width.saturating_sub(1));
                let y = y.min(luma_height.saturating_sub(1));
                let index = y.saturating_mul(luma_width).saturating_add(x);
                luma.samples.get(index).copied().portable()
            };
            let value = i32::from(sample(luma_x, luma_y)?)
                .saturating_add(i32::from(sample(luma_x.saturating_add(1), luma_y)?))
                .saturating_add(i32::from(sample(luma_x, luma_y.saturating_add(1))?))
                .saturating_add(i32::from(sample(
                    luma_x.saturating_add(1),
                    luma_y.saturating_add(1),
                )?));
            let index = y.saturating_mul(8).saturating_add(x);
            ac[index] = value.saturating_mul(2);
            sum = sum.saturating_add(ac[index]);
        }
    }
    let mean = sum >> 6;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }

    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = transform::inverse_dct8x8(&coefficients);
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();

    Ok(ReconstructedPlane { samples })
}

/// Reconstruct an 8×4 4:2:0 chroma transform from the two luma leaves that
/// cover its 16×8 source footprint.
///
/// A `PARTITION_H4` luma leaf is 16×4, while its chroma owner is an R8×4
/// transform. The reference decoder anchors CFL at the preceding even luma
/// row, so the chroma transform consumes the preceding 16×4 leaf and the
/// current 16×4 leaf together.
fn reconstruct_lossy_chroma_8x4_cfl(
    luma_above: &ReconstructedPlane,
    luma_current: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy4x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma_above.samples.len() != 64 || luma_current.samples.len() != 64 {
        return Err(PortableUnavailable);
    }

    let sample = |plane: &ReconstructedPlane, row: usize, column: usize| {
        plane
            .samples
            .get(row.saturating_mul(16).saturating_add(column))
            .copied()
            .ok_or(PortableUnavailable)
    };
    let mut ac = [0_i32; 32];
    let mut sum = 16_i32;
    for y in 0_usize..4 {
        for x in 0_usize..8 {
            let source_y = y.saturating_mul(2);
            let source = if source_y < 4 {
                luma_above
            } else {
                luma_current
            };
            let source_y = if source_y < 4 {
                source_y
            } else {
                source_y.saturating_sub(4)
            };
            let source_x = x.saturating_mul(2);
            let value = i32::from(sample(source, source_y, source_x)?)
                .saturating_add(i32::from(sample(
                    source,
                    source_y,
                    source_x.saturating_add(1),
                )?))
                .saturating_add(i32::from(sample(
                    source,
                    source_y.saturating_add(1),
                    source_x,
                )?))
                .saturating_add(i32::from(sample(
                    source,
                    source_y.saturating_add(1),
                    source_x.saturating_add(1),
                )?));
            let index = y.saturating_mul(8).saturating_add(x);
            ac[index] = value.saturating_mul(2);
            sum = sum.saturating_add(ac[index]);
        }
    }
    let mean = sum >> 5;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }

    let coefficients = coefficients.unwrap_or([0_i32; 32]);
    let residual = transform::inverse_dct8x4(&coefficients);
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

/// Reconstruct an 8×8 full-resolution chroma transform with CFL.
///
/// Unlike 4:2:0 CFL, I444 uses one luma sample for each chroma sample. The
/// AV1 `cfl_ac_444` operation therefore doubles the reconstructed luma sample
/// directly before centering the 8×8 AC plane.
fn reconstruct_lossy_full_8x8_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<LossyTransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 64 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 64];
    let mut sum = 32_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        // AV1's I444 cfl_ac_444 uses a q3 luma scale: one luma sample is
        // shifted by 1 + !ss_ver + !ss_hor = 3 before centering.
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 6;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }

    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = transform::inverse_dct8x8(&coefficients);
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

/// Reconstruct a 16×8 4:2:0 chroma transform with AV1's CFL predictor.
///
/// The corresponding luma footprint is 32×16. Each chroma AC sample is built
/// from the average of its four luma samples, then centered before the signed
/// alpha is applied. The residual transform remains DCT-DCT for CFL.
fn reconstruct_lossy_chroma_16x8_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy16x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 512 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 128];
    let mut sum = 64_i32;
    for y in 0_usize..8 {
        for x in 0_usize..16 {
            let luma_x = x.saturating_mul(2);
            let luma_y = y.saturating_mul(2);
            let index = luma_y.saturating_mul(32).saturating_add(luma_x);
            let value = i32::from(luma.samples[index])
                .saturating_add(i32::from(luma.samples[index + 1]))
                .saturating_add(i32::from(luma.samples[index + 32]))
                .saturating_add(i32::from(luma.samples[index + 33]));
            let chroma_index = y.saturating_mul(16).saturating_add(x);
            ac[chroma_index] = value.saturating_mul(2);
            sum = sum.saturating_add(ac[chroma_index]);
        }
    }
    let mean = sum >> 7;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }

    let coefficients = coefficients.unwrap_or([0_i32; 128]);
    let residual = transform::inverse_dct16x8(&coefficients);
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

/// Reconstruct a 16×4 4:2:0 chroma transform with AV1's CFL predictor.
///
/// An R32×8 luma transform covers this 16×4 chroma footprint. CFL derives
/// one signed AC value from each 2×2 luma group, centers those 64 values, and
/// applies the coded alpha before the DCT-DCT residual.
fn reconstruct_lossy_chroma_16x4_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy16x4TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 256 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 64];
    let mut sum = 32_i32;
    for y in 0_usize..4 {
        for x in 0_usize..16 {
            let luma_x = x.saturating_mul(2);
            let luma_y = y.saturating_mul(2);
            let index = luma_y.saturating_mul(32).saturating_add(luma_x);
            let value = i32::from(luma.samples[index])
                .saturating_add(i32::from(luma.samples[index + 1]))
                .saturating_add(i32::from(luma.samples[index + 32]))
                .saturating_add(i32::from(luma.samples[index + 33]));
            let chroma_index = y.saturating_mul(16).saturating_add(x);
            ac[chroma_index] = value.saturating_mul(2);
            sum = sum.saturating_add(ac[chroma_index]);
        }
    }
    let mean = sum >> 6;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }

    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = transform::inverse_dct16x4(&coefficients);
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

/// Reconstruct an 8×16 4:2:0 chroma transform with AV1's CFL predictor.
///
/// The chroma footprint corresponds to a 16×32 luma block. CFL averages each
/// 2×2 luma group, centers the resulting 8×16 AC plane, and applies the
/// signed alpha before adding the decoded R8x16 residual.
fn reconstruct_lossy_chroma_8x16_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy8x16TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 512 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 128];
    let mut sum = 64_i32;
    for y in 0_usize..16 {
        for x in 0_usize..8 {
            let luma_x = x.saturating_mul(2);
            let luma_y = y.saturating_mul(2);
            let index = luma_y.saturating_mul(16).saturating_add(luma_x);
            let value = i32::from(luma.samples[index])
                .saturating_add(i32::from(luma.samples[index + 1]))
                .saturating_add(i32::from(luma.samples[index + 16]))
                .saturating_add(i32::from(luma.samples[index + 17]));
            let chroma_index = y.saturating_mul(8).saturating_add(x);
            // For 4:2:0, dav1d's cfl_ac_420 scales the four-sample sum by
            // 1 << (1 + !ss_ver + !ss_hor) = 2 before mean subtraction.
            ac[chroma_index] = value.saturating_mul(2);
            sum = sum.saturating_add(ac[chroma_index]);
        }
    }
    let mean = sum >> 7;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }

    let coefficients = coefficients.unwrap_or([0_i32; 128]);
    let residual = transform::inverse_dct8x16(&coefficients);
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_chroma_4x4_cfl_with_shape(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<TransformCoefficients>,
    luma_width: usize,
    luma_height: usize,
) -> PortableResult<ReconstructedPlane> {
    let mut ac = [0_i32; 16];
    let mut sum = 8_i32;
    for y in 0_usize..4 {
        for x in 0_usize..4 {
            let luma_y = y.saturating_mul(2);
            let luma_x = x.saturating_mul(2);
            let sample = |x: usize, y: usize| -> PortableResult<u16> {
                let x = x.min(luma_width.saturating_sub(1));
                let y = y.min(luma_height.saturating_sub(1));
                let index = y.saturating_mul(luma_width).saturating_add(x);
                luma.samples.get(index).copied().portable()
            };
            let value = i32::from(sample(luma_x, luma_y)?)
                .saturating_add(i32::from(sample(luma_x.saturating_add(1), luma_y)?))
                .saturating_add(i32::from(sample(luma_x, luma_y.saturating_add(1))?))
                .saturating_add(i32::from(sample(
                    luma_x.saturating_add(1),
                    luma_y.saturating_add(1),
                )?));
            let index = y.saturating_mul(4).saturating_add(x);
            ac[index] = value.saturating_mul(2);
            sum = sum.saturating_add(ac[index]);
        }
    }
    let mean = sum >> 4;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }

    let coefficients = coefficients.unwrap_or([0_i32; 16]);
    let residual = transform::inverse_dct4x4(&coefficients);

    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();

    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_luma_8x8_horizontal(
    edge: [u16; 8],
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| {
            let reconstructed = i32::from(edge[index / 8])
                .saturating_add(value)
                .clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_8x8_vertical(
    edge: [u16; 8],
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };

    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| {
            let reconstructed = i32::from(edge[index % 8])
                .saturating_add(value)
                .clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_8x8_paeth(
    top: [u16; 8],
    left: [u16; 8],
    top_left: u16,
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| {
            let y = index / 8;
            let x = index % 8;
            let top_value = i32::from(top[x]);
            let left_value = i32::from(left[y]);
            let top_left_value = i32::from(top_left);
            let prediction = top_value
                .saturating_add(left_value)
                .saturating_sub(top_left_value);
            let top_distance = prediction.saturating_sub(top_value).abs();
            let left_distance = prediction.saturating_sub(left_value).abs();
            let top_left_distance = prediction.saturating_sub(top_left_value).abs();
            let predictor = if top_distance <= left_distance && top_distance <= top_left_distance {
                top_value
            } else if left_distance <= top_left_distance {
                left_value
            } else {
                top_left_value
            };
            let reconstructed = predictor.saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();

    ReconstructedPlane { samples }
}

const FILTER_INTRA_TAPS: [[[i32; 7]; 8]; 5] = [
    [
        [-6, 10, 0, 0, 0, 12, 0],
        [-5, 2, 10, 0, 0, 9, 0],
        [-3, 1, 1, 10, 0, 7, 0],
        [-3, 1, 1, 2, 10, 5, 0],
        [-4, 6, 0, 0, 0, 2, 12],
        [-3, 2, 6, 0, 0, 2, 9],
        [-3, 2, 2, 6, 0, 2, 7],
        [-3, 1, 2, 2, 6, 3, 5],
    ],
    [
        [-10, 16, 0, 0, 0, 10, 0],
        [-6, 0, 16, 0, 0, 6, 0],
        [-4, 0, 0, 16, 0, 4, 0],
        [-2, 0, 0, 0, 16, 2, 0],
        [-10, 16, 0, 0, 0, 0, 10],
        [-6, 0, 16, 0, 0, 0, 6],
        [-4, 0, 0, 16, 0, 0, 4],
        [-2, 0, 0, 0, 16, 0, 2],
    ],
    [
        [-8, 8, 0, 0, 0, 16, 0],
        [-8, 0, 8, 0, 0, 16, 0],
        [-8, 0, 0, 8, 0, 16, 0],
        [-8, 0, 0, 0, 8, 16, 0],
        [-4, 4, 0, 0, 0, 0, 16],
        [-4, 0, 4, 0, 0, 0, 16],
        [-4, 0, 0, 4, 0, 0, 16],
        [-4, 0, 0, 0, 4, 0, 16],
    ],
    [
        [-2, 8, 0, 0, 0, 10, 0],
        [-1, 3, 8, 0, 0, 6, 0],
        [-1, 2, 3, 8, 0, 4, 0],
        [0, 1, 2, 3, 8, 2, 0],
        [-1, 4, 0, 0, 0, 3, 10],
        [-1, 3, 4, 0, 0, 4, 6],
        [-1, 2, 3, 4, 0, 4, 4],
        [-1, 2, 2, 3, 4, 3, 3],
    ],
    [
        [-12, 14, 0, 0, 0, 14, 0],
        [-10, 0, 14, 0, 0, 12, 0],
        [-9, 0, 0, 14, 0, 11, 0],
        [-8, 0, 0, 0, 14, 10, 0],
        [-10, 12, 0, 0, 0, 0, 14],
        [-9, 1, 12, 0, 0, 0, 12],
        [-8, 0, 0, 12, 0, 1, 11],
        [-7, 0, 0, 1, 12, 1, 9],
    ],
];

fn reconstruct_lossy_luma_8x8_filter_intra_no_top(
    left: [u16; 8],
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
    mode: usize,
) -> PortableResult<ReconstructedPlane> {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:1229-1288 and
    // src/tables.rs:1088-1147. Filter-intra has five seven-tap modes.
    (mode < FILTER_INTRA_TAPS.len()).then_some(()).portable()?;

    let mut prediction = [0_u16; 64];
    for y in (0_usize..8).step_by(2) {
        let mut topleft = if y == 0 {
            left[0]
        } else {
            left[y.saturating_sub(1)]
        };
        let top = if y == 0 {
            [left[0]; 8]
        } else {
            std::array::from_fn(|x| {
                prediction[y.saturating_sub(1).saturating_mul(8).saturating_add(x)]
            })
        };
        for x in (0_usize..8).step_by(4) {
            let p0 = i32::from(topleft);
            let p1 = i32::from(top[x]);
            let p2 = i32::from(top[x.saturating_add(1)]);
            let p3 = i32::from(top[x.saturating_add(2)]);
            let p4 = i32::from(top[x.saturating_add(3)]);
            let p5 = if x == 0 {
                i32::from(left[y])
            } else {
                i32::from(prediction[y.saturating_mul(8).saturating_add(x.saturating_sub(1))])
            };
            let p6 = if x == 0 {
                i32::from(left[y.saturating_add(1)])
            } else {
                i32::from(
                    prediction[(y.saturating_add(1))
                        .saturating_mul(8)
                        .saturating_add(x.saturating_sub(1))],
                )
            };
            let inputs = [p0, p1, p2, p3, p4, p5, p6];
            for yy in 0_usize..2 {
                for xx in 0_usize..4 {
                    let tap = FILTER_INTRA_TAPS[mode][yy.saturating_mul(4).saturating_add(xx)];
                    let accumulator = tap
                        .into_iter()
                        .zip(inputs)
                        .fold(0_i32, |sum, (weight, input)| {
                            sum.saturating_add(weight.saturating_mul(input))
                        });
                    let value = accumulator.saturating_add(8).div_euclid(16).clamp(0, 255);
                    #[expect(
                        clippy::cast_sign_loss,
                        reason = "filter-intra output is explicitly clamped to eight-bit range"
                    )]
                    let value = value as u16;
                    prediction[(y.saturating_add(yy))
                        .saturating_mul(8)
                        .saturating_add(x.saturating_add(xx))] = value;
                }
            }
            topleft = top[x.saturating_add(3)];
        }
    }

    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };
    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    Ok(ReconstructedPlane { samples })
}

/// Reconstruct the prediction-only portion of an AV1 filter-intra block.
///
/// The reference predictor consumes two rows at a time and four columns at a
/// time. For the first two rows it reads the prepared top-left/top/left edge;
/// subsequent groups use the already predicted row above and the previous
/// pixel in the current rows. Keeping this as a checked slice operation makes
/// the same state transition explicit without requiring a scratch pointer.
#[expect(
    clippy::arithmetic_side_effects,
    reason = "filter-intra dimensions and edge lengths are validated before bounded indexing"
)]
fn reconstruct_filter_intra_prediction(
    mode: usize,
    width: usize,
    height: usize,
    top_left: u16,
    top: &[u16],
    left: &[u16],
) -> PortableResult<Vec<u16>> {
    if mode >= FILTER_INTRA_TAPS.len()
        || width == 0
        || height == 0
        || !width.is_multiple_of(4)
        || !height.is_multiple_of(2)
        || top.len() < width
        || left.len() < height
    {
        return Err(PortableUnavailable);
    }

    let mut prediction = vec![0_u16; width.saturating_mul(height)];
    for y in (0..height).step_by(2) {
        let mut topleft = if y == 0 { top_left } else { left[y - 1] };
        for x in (0..width).step_by(4) {
            let p = [
                topleft,
                if y == 0 {
                    top[x]
                } else {
                    prediction[(y - 1).saturating_mul(width).saturating_add(x)]
                },
                if y == 0 {
                    top[x + 1]
                } else {
                    prediction[(y - 1).saturating_mul(width).saturating_add(x + 1)]
                },
                if y == 0 {
                    top[x + 2]
                } else {
                    prediction[(y - 1).saturating_mul(width).saturating_add(x + 2)]
                },
                if y == 0 {
                    top[x + 3]
                } else {
                    prediction[(y - 1).saturating_mul(width).saturating_add(x + 3)]
                },
                if x == 0 {
                    left[y]
                } else {
                    prediction[y.saturating_mul(width).saturating_add(x.saturating_sub(1))]
                },
                if x == 0 {
                    left[y.saturating_add(1)]
                } else {
                    prediction[(y.saturating_add(1))
                        .saturating_mul(width)
                        .saturating_add(x.saturating_sub(1))]
                },
            ];
            let p = p.map(i32::from);
            for yy in 0_usize..2 {
                for xx in 0_usize..4 {
                    let taps = FILTER_INTRA_TAPS[mode][yy.saturating_mul(4).saturating_add(xx)];
                    let accumulator =
                        taps.into_iter().zip(p).fold(0_i32, |sum, (weight, input)| {
                            sum.saturating_add(weight.saturating_mul(input))
                        });
                    let value = (accumulator.saturating_add(8) >> 4).clamp(0, 255);
                    #[expect(
                        clippy::cast_sign_loss,
                        reason = "filter-intra output is explicitly clamped to eight-bit range"
                    )]
                    let value = value as u16;
                    let index = y
                        .saturating_add(yy)
                        .saturating_mul(width)
                        .saturating_add(x)
                        .saturating_add(xx);
                    *prediction.get_mut(index).ok_or(PortableUnavailable)? = value;
                }
            }
            topleft = u16::try_from(p[4]).map_err(|_| PortableUnavailable)?;
        }
    }
    Ok(prediction)
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 diagonal predictor needs its explicit top/left edges, angle, and transform coefficients"
)]
fn reconstruct_lossy_luma_8x8_diagonal(
    top: [u16; 16],
    left: [u16; 8],
    top_left: u16,
    angle: i32,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:975-1050 and
    // src/tables.rs:1083-1085. This is the bounded 90°..180° Z2 predictor
    // used by the first vertical-neighbor proof. The edge array mirrors the
    // reference's top-left-centered layout, but every access is checked.
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;

    // Index sixteen is the top-left sample. Keeping sixteen samples on both
    // sides lets the same checked coordinate system represent either of the
    // reference implementation's optional two-times-upsampled edges.
    let mut edge = [0_i32; 33];
    let top_left_i32 = i32::from(top_left);
    edge[16] = top_left_i32;
    let use_intra_edge_filter = enable_intra_edge_filter;
    let upsample_above = use_intra_edge_filter && angle.saturating_sub(90) < 40 && !smooth_edges;
    let upsample_left =
        use_intra_edge_filter && 180_i32.saturating_sub(angle) < 40 && !smooth_edges;
    let top = if use_intra_edge_filter && !upsample_above {
        filter_z2_top_edge(
            top,
            top_left,
            intra_edge_filter_strength(16, angle.saturating_sub(90), smooth_edges),
        )
    } else {
        top
    };

    if upsample_above {
        let upsampled = upsample_z2_top_edge(top, top_left);
        for (index, sample) in upsampled.into_iter().enumerate() {
            edge[16_usize.saturating_add(index)] = i32::from(sample);
        }
    } else {
        for (index, sample) in top.into_iter().enumerate() {
            edge[17_usize.saturating_add(index)] = i32::from(sample);
        }
    }

    if upsample_left {
        let upsampled = upsample_z2_left_edge(left, top_left);
        for (index, sample) in upsampled.into_iter().enumerate() {
            edge[index] = i32::from(sample);
        }
    } else {
        let left = if use_intra_edge_filter {
            filter_z2_left_edge(
                left,
                top_left,
                intra_edge_filter_strength(16, 180 - angle, smooth_edges),
            )
        } else {
            left
        };
        for (index, sample) in left.into_iter().enumerate() {
            edge[15_usize.saturating_sub(index)] = i32::from(sample);
        }
    }

    let dx = if upsample_above {
        dx.saturating_mul(2)
    } else {
        dx
    };
    let dy = if upsample_left {
        dy.saturating_mul(2)
    } else {
        dy
    };
    let base_increment = if upsample_above { 2_i32 } else { 1_i32 };

    let mut prediction = [0_u16; 64];
    for y in 0_usize..8 {
        let y_i32 = i32::try_from(y).map_err(|_| PortableUnavailable)?;
        let xpos = (if upsample_above { 128_i32 } else { 64_i32 })
            .saturating_sub(dx.saturating_mul(y_i32.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x in 0_usize..8 {
            let x_i32 = i32::try_from(x).map_err(|_| PortableUnavailable)?;
            let sample = if base_x.saturating_add(x_i32.saturating_mul(base_increment)) >= 0 {
                let first = usize::try_from(
                    16_i32
                        .saturating_add(base_x)
                        .saturating_add(x_i32.saturating_mul(base_increment)),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = first.saturating_add(1);
                let first = *edge.get(first).portable()?;
                let second = *edge.get(second).portable()?;
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let ypos = y_i32
                    .saturating_mul(if upsample_left { 128 } else { 64 })
                    .saturating_sub(dy.saturating_mul(x_i32.saturating_add(1)));
                let base_y = ypos >> 6;
                let frac_y = ypos & 0x3e;
                let left_origin = 16_i32.saturating_sub(if upsample_left { 2 } else { 1 });
                let first = usize::try_from(left_origin.saturating_sub(base_y))
                    .map_err(|_| PortableUnavailable)?;
                let second = usize::try_from(left_origin.saturating_sub(base_y.saturating_add(1)))
                    .map_err(|_| PortableUnavailable)?;
                let first = *edge.get(first).portable()?;
                let second = *edge.get(second).portable()?;
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            #[expect(
                clippy::cast_sign_loss,
                reason = "the directional predictor is explicitly clamped to eight-bit range"
            )]
            let sample = sample.clamp(0, 255) as u16;
            prediction[y.saturating_mul(8).saturating_add(x)] = sample;
        }
    }

    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };
    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_luma_8x8_diagonal_z3(
    left: [u16; 8],
    top_left: u16,
    angle: i32,
    enable_intra_edge_filter: bool,
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
        left,
        top_left,
        None,
        angle,
        enable_intra_edge_filter,
        false,
        coefficients,
        transform_kind,
    )
}

#[expect(
    clippy::too_many_arguments,
    reason = "the zone-three predictor receives the complete edge state and transform syntax as one AV1 kernel"
)]
fn reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
    left: [u16; 8],
    top_left: u16,
    bottom_left: Option<[u16; 8]>,
    angle: i32,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:1101-1210 and
    // src/tables.rs:1083-1085. Zone 3 walks the prepared left edge for an
    // 8×8 terminal; the upsampled path is used for the shallow part of the
    // zone and keeps every edge access inside the fixed checked array.
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (180 < angle && angle < 270).then_some(()).portable()?;
    let dy_index =
        usize::try_from(270_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let upsample = enable_intra_edge_filter && angle < 220 && !smooth_edges;

    let mut full_left = [0_u16; 16];
    full_left[..8].copy_from_slice(&left);
    if let Some(bottom_left) = bottom_left {
        full_left[8..].copy_from_slice(&bottom_left);
    } else {
        full_left[8..].fill(left[7]);
    }
    let filtered_left = if enable_intra_edge_filter && !upsample {
        let strength = intra_edge_filter_strength(16, angle.saturating_sub(180), smooth_edges);
        filter_z3_left_edge_16(full_left, top_left, strength)
    } else {
        full_left
    };
    let mut prediction = [0_u16; 64];
    if upsample {
        let edge = upsample_intra_left_edge_16(full_left, top_left);
        for y in 0_usize..8 {
            for x in 0_usize..8 {
                prediction[y.saturating_mul(8).saturating_add(x)] =
                    diagonal_z3_predictor_sample(&edge, 30, dy.saturating_mul(2), 2, x, y)?;
            }
        }
    } else {
        for y in 0_usize..8 {
            for x in 0_usize..8 {
                prediction[y.saturating_mul(8).saturating_add(x)] =
                    diagonal_z3_predictor_sample(&filtered_left, 15, dy, 1, x, y)?;
            }
        }
    }

    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };

    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the directional predictor is explicitly clamped to eight-bit range"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();

    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_luma_8x8_smooth(
    top: [u16; 8],
    top_right: u16,
    left: [u16; 8],
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:631-665 and
    // src/tables.rs:1073-1080. Width eight uses the table slice beginning at
    // offset eight. The predictor is kept separate from the residual so the
    // same safe transform and clamping rules apply to every intra mode.
    const SMOOTH_WEIGHTS_8: [i32; 8] = [255, 197, 146, 105, 73, 50, 37, 32];
    let right = i32::from(top_right);
    let bottom = i32::from(left[7]);
    let mut prediction = [0_u16; 64];
    for y in 0_usize..8 {
        for x in 0_usize..8 {
            let vertical_weight = SMOOTH_WEIGHTS_8[y];
            let horizontal_weight = SMOOTH_WEIGHTS_8[x];
            let value = vertical_weight
                .saturating_mul(i32::from(top[x]))
                .saturating_add(
                    256_i32
                        .saturating_sub(vertical_weight)
                        .saturating_mul(bottom),
                )
                .saturating_add(horizontal_weight.saturating_mul(i32::from(left[y])))
                .saturating_add(
                    256_i32
                        .saturating_sub(horizontal_weight)
                        .saturating_mul(right),
                )
                .saturating_add(256)
                >> 9;
            #[expect(
                clippy::cast_sign_loss,
                reason = "the smooth predictor is explicitly clamped to eight-bit range"
            )]
            let value = value.clamp(0, 255) as u16;
            prediction[y.saturating_mul(8).saturating_add(x)] = value;
        }
    }

    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };

    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_8x8_smooth_vertical(
    top: [u16; 8],
    bottom: u16,
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    const SMOOTH_WEIGHTS_8: [i32; 8] = [255, 197, 146, 105, 73, 50, 37, 32];
    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| {
            let y = index / 8;
            let weight = SMOOTH_WEIGHTS_8[y];
            let prediction = weight
                .saturating_mul(i32::from(top[index % 8]))
                .saturating_add(
                    256_i32
                        .saturating_sub(weight)
                        .saturating_mul(i32::from(bottom)),
                )
                .saturating_add(128)
                >> 8;
            let reconstructed = prediction.saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_8x8_smooth_horizontal(
    left: [u16; 8],
    right: u16,
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    const SMOOTH_WEIGHTS_8: [i32; 8] = [255, 197, 146, 105, 73, 50, 37, 32];
    let right = i32::from(right);
    let prediction = std::array::from_fn(|index| {
        let weight = SMOOTH_WEIGHTS_8[index % 8];
        let value = weight
            .saturating_mul(i32::from(left[index / 8]))
            .saturating_add(256_i32.saturating_sub(weight).saturating_mul(right))
            .saturating_add(128)
            >> 8;
        #[expect(
            clippy::cast_sign_loss,
            reason = "the smooth predictor is explicitly clamped to eight-bit range"
        )]
        {
            value.clamp(0, 255) as u16
        }
    });

    reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform_kind)
}

fn reconstruct_lossy_chroma_4x4_horizontal(
    edge: [u16; 4],
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 16]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity4x4(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct4x4(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct4x4(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst4x4(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct4x4(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity4x4(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst4x4(&coefficients),
    };
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| {
            let reconstructed = i32::from(edge[index / 4])
                .saturating_add(value)
                .clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_chroma_4x4_diagonal(
    top: [u16; 8],
    left: [u16; 4],
    angle: i32,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    reconstruct_lossy_chroma_4x4_diagonal_with_filter(
        top,
        left,
        top[0],
        angle,
        coefficients,
        transform_kind,
        false,
    )
}

fn reconstruct_lossy_chroma_4x4_diagonal_with_filter(
    top: [u16; 8],
    left: [u16; 4],
    top_left: u16,
    angle: i32,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
    enable_intra_edge_filter: bool,
) -> PortableResult<ReconstructedPlane> {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:965-1050. This is the same
    // checked Z2 construction as the luma helper, narrowed to a subsampled
    // 4x4 block and its eight-sample top extension.
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;

    let upsample_above = enable_intra_edge_filter && angle.saturating_sub(90) < 40;
    let upsampled_top = upsample_z2_top_edge_4(top, top_left);
    let mut edge = [0_i32; 13];
    if upsample_above {
        for (index, sample) in upsampled_top.into_iter().enumerate() {
            edge[4_usize.saturating_add(index)] = i32::from(sample);
        }
    } else {
        edge[4] = i32::from(top_left);
        for (index, sample) in top.into_iter().enumerate() {
            edge[5_usize.saturating_add(index)] = i32::from(sample);
        }
    }
    for (index, sample) in left.into_iter().enumerate() {
        edge[3_usize.saturating_sub(index)] = i32::from(sample);
    }

    let mut prediction = [0_u16; 16];
    for y in 0_usize..4 {
        let y_i32 = i32::try_from(y).map_err(|_| PortableUnavailable)?;
        let dx = if upsample_above {
            dx.saturating_mul(2)
        } else {
            dx
        };
        let base_increment = if upsample_above { 2_i32 } else { 1_i32 };
        let xpos = (if upsample_above { 128_i32 } else { 64_i32 })
            .saturating_sub(dx.saturating_mul(y_i32.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x in 0_usize..4 {
            let x_i32 = i32::try_from(x).map_err(|_| PortableUnavailable)?;
            let sample_x = base_x.saturating_add(x_i32.saturating_mul(base_increment));
            let sample = if sample_x >= 0 {
                let first = usize::try_from(4_i32.saturating_add(sample_x))
                    .map_err(|_| PortableUnavailable)?;
                let second = first.saturating_add(1);
                let first = *edge.get(first).portable()?;
                let second = *edge.get(second).portable()?;
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let ypos = y_i32
                    .saturating_mul(64)
                    .saturating_sub(dy.saturating_mul(x_i32.saturating_add(1)));
                let base_y = ypos >> 6;
                let frac_y = ypos & 0x3e;
                let first = usize::try_from(3_i32.saturating_sub(base_y))
                    .map_err(|_| PortableUnavailable)?;
                let second = usize::try_from(3_i32.saturating_sub(base_y.saturating_add(1)))
                    .map_err(|_| PortableUnavailable)?;
                let first = *edge.get(first).portable()?;
                let second = *edge.get(second).portable()?;
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            #[expect(
                clippy::cast_sign_loss,
                reason = "the directional predictor is explicitly clamped to eight-bit range"
            )]
            let sample = sample.clamp(0, 255) as u16;
            prediction[y.saturating_mul(4).saturating_add(x)] = sample;
        }
    }

    let coefficients = coefficients.unwrap_or([0_i32; 16]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_dct4x4(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct4x4(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct4x4(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst4x4(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct4x4(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity4x4(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst4x4(&coefficients),
    };
    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();

    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_chroma_4x4_diagonal_z3(
    left: [u16; 4],
    top_left: u16,
    angle: i32,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    reconstruct_lossy_chroma_4x4_diagonal_z3_with_bottom_left(
        left,
        None,
        top_left,
        angle,
        coefficients,
        transform_kind,
    )
}

fn reconstruct_lossy_chroma_4x4_diagonal_z3_with_bottom_left(
    left: [u16; 4],
    bottom_left: Option<[u16; 4]>,
    top_left: u16,
    angle: i32,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (180 < angle && angle < 270).then_some(()).portable()?;
    let dy_index =
        usize::try_from(270_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let mut edge = [0_u16; 8];
    edge[..4].copy_from_slice(&left);
    edge[4..].copy_from_slice(&bottom_left.unwrap_or([left[3]; 4]));
    let upsampled_edge = upsample_intra_left_edge(edge, top_left);
    let mut prediction = [0_u16; 16];
    for y in 0_usize..4 {
        for x in 0_usize..4 {
            prediction[y.saturating_mul(4).saturating_add(x)] =
                diagonal_z3_predictor_sample(&upsampled_edge, 14, dy.saturating_mul(2), 2, x, y)?;
        }
    }

    let coefficients = coefficients.unwrap_or([0_i32; 16]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity4x4(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct4x4(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct4x4(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst4x4(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct4x4(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity4x4(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst4x4(&coefficients),
    };

    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_4x4_smooth(
    top: [u16; 4],
    top_right: u16,
    left: [u16; 4],
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:631-665 and
    // src/tables.rs:1073-1080. Width four uses the weights at table offset
    // four: [255, 149, 85, 64]. Missing left-edge samples are extended from
    // the top-left sample before this helper is called.
    const SMOOTH_WEIGHTS_4: [i32; 4] = [255, 149, 85, 64];
    let right = i32::from(top_right);
    let bottom = i32::from(left[3]);
    let mut prediction = [0_u16; 16];
    for y in 0_usize..4 {
        for x in 0_usize..4 {
            let vertical_weight = SMOOTH_WEIGHTS_4[y];
            let horizontal_weight = SMOOTH_WEIGHTS_4[x];
            let value = vertical_weight
                .saturating_mul(i32::from(top[x]))
                .saturating_add(
                    256_i32
                        .saturating_sub(vertical_weight)
                        .saturating_mul(bottom),
                )
                .saturating_add(horizontal_weight.saturating_mul(i32::from(left[y])))
                .saturating_add(
                    256_i32
                        .saturating_sub(horizontal_weight)
                        .saturating_mul(right),
                )
                .saturating_add(256)
                >> 9;
            #[expect(
                clippy::cast_sign_loss,
                reason = "the smooth predictor is explicitly clamped to eight-bit range"
            )]
            let value = value.clamp(0, 255) as u16;
            prediction[y.saturating_mul(4).saturating_add(x)] = value;
        }
    }

    let coefficients = coefficients.unwrap_or([0_i32; 16]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity4x4(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct4x4(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct4x4(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst4x4(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct4x4(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity4x4(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst4x4(&coefficients),
    };
    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();

    ReconstructedPlane { samples }
}

fn reconstruct_lossy_chroma_4x4_smooth(
    top: [u16; 4],
    top_right: u16,
    left: [u16; 4],
    coefficients: Option<TransformCoefficients>,
) -> ReconstructedPlane {
    reconstruct_lossy_4x4_smooth(
        top,
        top_right,
        left,
        coefficients,
        LossyTransformKind::AdstAdst,
    )
}

#[expect(
    clippy::too_many_arguments,
    reason = "the 4:2:0 square leaf receives the complete neighboring luma/chroma edge state"
)]
fn reconstruct_following_lossy_420_square4_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    _above_right: &ClosedLeaf,
    top_left_neighbor: Option<&ClosedLeaf>,
    left_neighbor: Option<&ClosedLeaf>,
    above_chroma_neighbor: Option<&ClosedLeaf>,
    above_chroma_width: u32,
    above_chroma_x_offset: u32,
    left_chroma_neighbor: Option<&ClosedLeaf>,
    left_chroma_width: u32,
    left_chroma_height: u32,
    left_chroma_y_offset: u32,
    top_available: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        lossy_luma_coefficients,
        lossy_luma_transform,
        lossy_chroma_coefficients,
        reconstruction: ReconstructionPolicy::Lossy420Dct4x4,
        ..
    } = syntax
    else {
        return Err(PortableUnavailable);
    };

    let luma_top = bottom_edge_for_square4(&above_left.planes[0]);
    let luma_top_left = top_left_neighbor.map_or_else(
        || bottom_right_for_square4(&above_left.planes[0]),
        |neighbor| bottom_right_for_square4(&neighbor.planes[0]),
    );
    let luma_left = left_neighbor.map_or([luma_top[0]; 4], |neighbor| {
        right_edge_for_square4(&neighbor.planes[0])
    });
    let luma_left = if left_neighbor.is_some() {
        luma_left
    } else {
        [luma_top_left; 4]
    };
    let luma_coefficients = lossy_luma_coefficients
        .map(|coefficients| std::array::from_fn(|index| coefficients[index]));

    let luma = match luma_predictor {
        LumaPredictor::Dc => reconstruct_lossy_4x4(
            if left_neighbor.is_some() && top_available {
                dc_predictor(luma_top, luma_left)
            } else {
                one_sided_dc_predictor_4(if left_neighbor.is_some() {
                    luma_left
                } else {
                    luma_top
                })
            },
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::Vertical => reconstruct_lossy_4x4_from_prediction(
            std::array::from_fn(|index| luma_top[index % 4]),
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::Horizontal => reconstruct_lossy_4x4_from_prediction(
            std::array::from_fn(|index| luma_left[index / 4]),
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::Smooth => reconstruct_lossy_4x4_smooth(
            luma_top,
            luma_top[3],
            luma_left,
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            luma_top,
            luma_left[3],
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            luma_left,
            luma_top[3],
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            luma_top,
            luma_left,
            luma_top_left,
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::DiagonalDownRight
        | LumaPredictor::Diagonal113
        | LumaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            [
                luma_top[0],
                luma_top[1],
                luma_top[2],
                luma_top[3],
                luma_top[3],
                luma_top[3],
                luma_top[3],
                luma_top[3],
            ],
            luma_left,
            luma_angle.ok_or(PortableUnavailable)?,
            luma_coefficients,
            lossy_luma_transform,
        )?,
        LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => reconstruct_lossy_4x4_diagonal_z1(
            luma_top,
            bottom_right_for_square4(&above_left.planes[0]),
            luma_angle.ok_or(PortableUnavailable)?,
            luma_coefficients,
            lossy_luma_transform,
        )?,
        LumaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
            luma_left,
            luma_left[0],
            luma_angle.ok_or(PortableUnavailable)?,
            luma_coefficients,
            lossy_luma_transform,
        )?,
    };
    // Chroma availability follows the subsampled block grid, not the luma
    // leaf grid. When top is unavailable but left is present, dav1d's
    // prepare_intra_edges() synthesizes the top edge from the first left
    // sample; when neither edge is present it uses top=127 and left=129.
    let chroma_left_u = left_chroma_neighbor.map_or([129; 4], |neighbor| {
        right_edge_at::<4>(
            &neighbor.planes[1],
            left_chroma_width.div_ceil(2).max(4),
            left_chroma_height.div_ceil(2).max(4),
            left_chroma_y_offset,
        )
    });
    let chroma_left_v = left_chroma_neighbor.map_or([129; 4], |neighbor| {
        right_edge_at::<4>(
            &neighbor.planes[2],
            left_chroma_width.div_ceil(2).max(4),
            left_chroma_height.div_ceil(2).max(4),
            left_chroma_y_offset,
        )
    });
    let chroma_top_u = above_chroma_neighbor.map_or_else(
        || {
            if left_chroma_neighbor.is_some() {
                [chroma_left_u[0]; 4]
            } else {
                [127; 4]
            }
        },
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[1],
                above_chroma_width.div_ceil(2).max(4),
                above_chroma_x_offset,
            )
        },
    );
    let chroma_top_v = above_chroma_neighbor.map_or_else(
        || {
            if left_chroma_neighbor.is_some() {
                [chroma_left_v[0]; 4]
            } else {
                [127; 4]
            }
        },
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[2],
                above_chroma_width.div_ceil(2).max(4),
                above_chroma_x_offset,
            )
        },
    );
    // When only the top edge exists, dav1d extends the missing left edge from
    // the first top sample. Keep the all-unavailable fallback at 129, but do
    // not use it when a real top edge is available.
    let chroma_left_u = if left_chroma_neighbor.is_none() && above_chroma_neighbor.is_some() {
        [chroma_top_u[0]; 4]
    } else {
        chroma_left_u
    };
    let chroma_left_v = if left_chroma_neighbor.is_none() && above_chroma_neighbor.is_some() {
        [chroma_top_v[0]; 4]
    } else {
        chroma_left_v
    };
    let chroma_top_left_u = match (above_chroma_neighbor, left_chroma_neighbor) {
        (None, None) => 128,
        (None, Some(_)) => chroma_left_u[0],
        (Some(_), None) => chroma_top_u[0],
        (Some(above), Some(left)) => {
            if left_chroma_y_offset > 0 {
                right_edge_at::<1>(
                    &left.planes[1],
                    left_chroma_width.div_ceil(2).max(4),
                    left_chroma_height.div_ceil(2).max(4),
                    left_chroma_y_offset.saturating_sub(1),
                )[0]
            } else if above_chroma_x_offset > 0 {
                bottom_edge_at::<1>(
                    &above.planes[1],
                    above_chroma_width.div_ceil(2).max(4),
                    above_chroma_x_offset.saturating_sub(1),
                )[0]
            } else {
                top_left_neighbor.map_or(128, |neighbor| {
                    bottom_right_for_square4(&neighbor.planes[1])
                })
            }
        }
    };
    let chroma_top_left_v = match (above_chroma_neighbor, left_chroma_neighbor) {
        (None, None) => 128,
        (None, Some(_)) => chroma_left_v[0],
        (Some(_), None) => chroma_top_v[0],
        (Some(above), Some(left)) => {
            if left_chroma_y_offset > 0 {
                right_edge_at::<1>(
                    &left.planes[2],
                    left_chroma_width.div_ceil(2).max(4),
                    left_chroma_height.div_ceil(2).max(4),
                    left_chroma_y_offset.saturating_sub(1),
                )[0]
            } else if above_chroma_x_offset > 0 {
                bottom_edge_at::<1>(
                    &above.planes[2],
                    above_chroma_width.div_ceil(2).max(4),
                    above_chroma_x_offset.saturating_sub(1),
                )[0]
            } else {
                top_left_neighbor.map_or(128, |neighbor| {
                    bottom_right_for_square4(&neighbor.planes[2])
                })
            }
        }
    };
    let chroma_u = match chroma_predictor {
        ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
            if above_chroma_neighbor.is_some() {
                dc_predictor(chroma_top_u, chroma_left_u)
            } else {
                one_sided_dc_predictor_4(chroma_left_u)
            },
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Vertical => reconstruct_lossy_chroma_4x4_vertical(
            chroma_top_u,
            lossy_chroma_coefficients[0],
            chroma_transform_kind(chroma_predictor),
        ),
        ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
            chroma_left_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
            chroma_left_u,
            chroma_top_u[0],
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        )?,
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            [
                chroma_top_u[0],
                chroma_top_u[1],
                chroma_top_u[2],
                chroma_top_u[3],
                chroma_top_u[3],
                chroma_top_u[3],
                chroma_top_u[3],
                chroma_top_u[3],
            ],
            chroma_left_u,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        )?,
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1(
                chroma_top_u,
                chroma_top_left_u,
                chroma_angle.ok_or(PortableUnavailable)?,
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            )?
        }
        ChromaPredictor::Smooth => reconstruct_lossy_chroma_4x4_smooth(
            chroma_top_u,
            chroma_top_u[3],
            chroma_left_u,
            lossy_chroma_coefficients[0],
        ),
        ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            chroma_top_u,
            chroma_left_u[3],
            lossy_chroma_coefficients[0],
            LossyTransformKind::AdstDct,
        ),
        ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            chroma_left_u,
            chroma_top_u[3],
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            chroma_top_u,
            chroma_left_u,
            chroma_top_left_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Cfl { alpha_u, .. } => {
            let result = reconstruct_lossy_chroma_4x4_cfl(
                &luma,
                dc_predictor(chroma_top_u, chroma_left_u),
                alpha_u,
                lossy_chroma_coefficients[0],
            );
            result?
        }
    };
    let chroma_v = match chroma_predictor {
        ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
            if above_chroma_neighbor.is_some() {
                dc_predictor(chroma_top_v, chroma_left_v)
            } else {
                one_sided_dc_predictor_4(chroma_left_v)
            },
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Vertical => reconstruct_lossy_chroma_4x4_vertical(
            chroma_top_v,
            lossy_chroma_coefficients[1],
            chroma_transform_kind(chroma_predictor),
        ),
        ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
            chroma_left_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
            chroma_left_v,
            chroma_top_v[0],
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        )?,
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            [
                chroma_top_v[0],
                chroma_top_v[1],
                chroma_top_v[2],
                chroma_top_v[3],
                chroma_top_v[3],
                chroma_top_v[3],
                chroma_top_v[3],
                chroma_top_v[3],
            ],
            chroma_left_v,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        )?,
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1(
                chroma_top_v,
                chroma_top_left_v,
                chroma_angle.ok_or(PortableUnavailable)?,
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            )?
        }
        ChromaPredictor::Smooth => reconstruct_lossy_chroma_4x4_smooth(
            chroma_top_v,
            chroma_top_v[3],
            chroma_left_v,
            lossy_chroma_coefficients[1],
        ),
        ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            chroma_top_v,
            chroma_left_v[3],
            lossy_chroma_coefficients[1],
            LossyTransformKind::AdstDct,
        ),
        ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            chroma_left_v,
            chroma_top_v[3],
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            chroma_top_v,
            chroma_left_v,
            chroma_top_left_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Cfl { alpha_v, .. } => {
            let result = reconstruct_lossy_chroma_4x4_cfl(
                &luma,
                dc_predictor(chroma_top_v, chroma_left_v),
                alpha_v,
                lossy_chroma_coefficients[1],
            );
            result?
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

/// Reconstruct a genuine 4×4 leaf reached from the left edge of a partition.
///
/// The horizontal traversal has no decoded block above the current leaf, but
/// AV1 still prepares a top edge when a left edge exists. Reuse the complete
/// square-4 predictor implementation by supplying a checked synthetic top
/// block whose edge and top-left sample are the first left-edge sample.
fn reconstruct_following_lossy_420_square4_horizontal_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
) -> PortableResult<ClosedLeaf> {
    let above_left = ClosedLeaf {
        luma_predictor: neighbor.luma_predictor,
        planes: std::array::from_fn(|plane| {
            let left_edge = right_edge_for_square4(&neighbor.planes[plane]);
            ReconstructedPlane {
                samples: vec![left_edge[0]; 16],
            }
        }),
    };
    reconstruct_following_lossy_420_square4_leaf(
        syntax,
        &above_left,
        &above_left,
        None,
        Some(neighbor),
        None,
        0,
        0,
        Some(neighbor),
        4,
        4,
        0,
        false,
    )
}

#[expect(
    clippy::too_many_arguments,
    reason = "the monochrome square leaf receives the complete neighboring luma edge state"
)]
fn reconstruct_following_lossy_monochrome_square4_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    top_left_neighbor: Option<&ClosedLeaf>,
    left_neighbor: Option<&ClosedLeaf>,
    left_luma_edge: Option<[u16; 4]>,
    top_luma_edge: Option<[u16; 4]>,
    top_luma_edge_extended: Option<[u16; 8]>,
    top_luma_left: Option<u16>,
    top_available: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        lossy_luma_coefficients,
        lossy_luma_transform,
        ..
    } = syntax;
    let luma_top = top_luma_edge.unwrap_or_else(|| bottom_edge_for_square4(&above_left.planes[0]));
    let top_left = top_luma_left.unwrap_or_else(|| {
        top_left_neighbor.map_or_else(
            || luma_top[0],
            |neighbor| bottom_right_for_square4(&neighbor.planes[0]),
        )
    });
    let luma_left = left_luma_edge.unwrap_or_else(|| {
        left_neighbor.map_or([top_left; 4], |neighbor| {
            right_edge_for_square4(&neighbor.planes[0])
        })
    });
    let coefficients = lossy_luma_coefficients
        .map(|coefficients| std::array::from_fn(|index| coefficients[index]));

    let luma = if let Some(mode) = filter_intra_mode {
        let prediction =
            reconstruct_filter_intra_prediction(mode, 4, 4, top_left, &luma_top, &luma_left)?
                .try_into()
                .map_err(|_| PortableUnavailable)?;
        reconstruct_lossy_4x4_from_prediction(prediction, coefficients, lossy_luma_transform)
    } else {
        match luma_predictor {
            LumaPredictor::Dc => reconstruct_lossy_4x4(
                if left_neighbor.is_some() && top_available {
                    dc_predictor(luma_top, luma_left)
                } else {
                    one_sided_dc_predictor_4(if left_neighbor.is_some() {
                        luma_left
                    } else {
                        luma_top
                    })
                },
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Vertical => reconstruct_lossy_4x4_from_prediction(
                std::array::from_fn(|index| luma_top[index % 4]),
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Horizontal => reconstruct_lossy_4x4_from_prediction(
                std::array::from_fn(|index| luma_left[index / 4]),
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Smooth => reconstruct_lossy_4x4_smooth(
                luma_top,
                luma_top[3],
                luma_left,
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
                luma_top,
                luma_left[3],
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
                luma_left,
                luma_top[3],
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
                luma_top,
                luma_left,
                top_left,
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                if let Some(top) = top_luma_edge_extended {
                    reconstruct_lossy_4x4_diagonal_z1_extended(
                        top,
                        top_left,
                        luma_angle.ok_or(PortableUnavailable)?,
                        coefficients,
                        lossy_luma_transform,
                    )?
                } else {
                    reconstruct_lossy_4x4_diagonal_z1(
                        luma_top,
                        top_left,
                        luma_angle.ok_or(PortableUnavailable)?,
                        coefficients,
                        lossy_luma_transform,
                    )?
                }
            }
            LumaPredictor::DiagonalDownRight
            | LumaPredictor::Diagonal113
            | LumaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
                [
                    luma_top[0],
                    luma_top[1],
                    luma_top[2],
                    luma_top[3],
                    luma_top[3],
                    luma_top[3],
                    luma_top[3],
                    luma_top[3],
                ],
                luma_left,
                luma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                lossy_luma_transform,
            )?,
            LumaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
                luma_left,
                top_left,
                luma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                lossy_luma_transform,
            )?,
        }
    };
    let mut leaf = reconstruct_leaf(syntax, [luma_predictor.sample(), 128, 128]);
    leaf.planes[0] = luma;
    Ok(leaf)
}

fn reconstruct_following_lossy_monochrome_square4_horizontal_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
) -> PortableResult<ClosedLeaf> {
    let left_edge = right_edge_for_square4(&neighbor.planes[0]);
    let above_left = ClosedLeaf {
        luma_predictor: neighbor.luma_predictor,
        planes: [
            ReconstructedPlane {
                samples: vec![left_edge[0]; 16],
            },
            ReconstructedPlane {
                samples: Vec::new(),
            },
            ReconstructedPlane {
                samples: Vec::new(),
            },
        ],
    };
    reconstruct_following_lossy_monochrome_square4_leaf(
        syntax,
        &above_left,
        None,
        Some(neighbor),
        None,
        None,
        None,
        None,
        false,
    )
}

// ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:1176-1545. For the accepted
// first-frame leaves, dav1d visits the 2x2, 4x2, 2x4, or 4x4 transform grid in
// row-major order. The first DC-only transform reconstructs one constant
// value. With every trailing transform skipped, the accepted DC, vertical,
// and horizontal predictors propagate that value through the remaining coded
// plane.
fn reconstruct_coded_plane(
    predictor: u16,
    coefficients: PlaneCoefficients,
    transform_grid: TransformGrid,
    chroma_sampling: ChromaSampling,
) -> ReconstructedPlane {
    let (mut transform_grid_width, mut transform_grid_height, _) = transform_grid.properties();
    if matches!(chroma_sampling, ChromaSampling::Subsampled420) {
        // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:1176-1545 and the pinned
        // Slice 32 traces. Both chroma shifts reduce the 2x2 luma transform
        // grid to one 4x4 transform.
        transform_grid_width = transform_grid_width.div_ceil(2);
        transform_grid_height = transform_grid_height.div_ceil(2);
    }
    let coded_width = transform_grid_width.saturating_mul(4);
    let coded_height = transform_grid_height.saturating_mul(4);
    let transform_count = transform_grid_width.saturating_mul(transform_grid_height);
    let mut coded_samples = vec![0_u16; coded_width.saturating_mul(coded_height)];
    let mut propagated_predictor = predictor;
    for (transform_index, coefficient) in coefficients.into_iter().take(transform_count).enumerate()
    {
        let transform = reconstruct_transform(propagated_predictor, coefficient);
        if transform_index == 0 {
            propagated_predictor = transform[0];
        }
        let transform_x = transform_index.rem_euclid(transform_grid_width);
        let transform_y = transform_index.div_euclid(transform_grid_width);
        for (row_index, row) in transform.as_chunks::<4>().0.iter().enumerate() {
            let output_start = transform_y
                .saturating_mul(4)
                .saturating_add(row_index)
                .saturating_mul(coded_width)
                .saturating_add(transform_x.saturating_mul(4));
            let output_end = output_start.saturating_add(4);
            coded_samples[output_start..output_end].copy_from_slice(row);
        }
    }
    ReconstructedPlane {
        samples: coded_samples,
    }
}

fn visible_plane(
    coded: &ReconstructedPlane,
    coded_width: usize,
    width: u32,
    height: u32,
) -> ReconstructedPlane {
    // ✅ VERIFIED: dav1d retains the top-left declared rectangle from the
    // padded 8x8, 16x8, 8x16, or 16x16 reconstruction for the accepted
    // dimensions.
    let visible_width = width as usize;
    let visible_height = height as usize;
    if coded_width == 0 {
        return ReconstructedPlane {
            samples: Vec::new(),
        };
    }
    let mut samples = Vec::with_capacity(visible_width.saturating_mul(visible_height));
    for coded_row in coded.samples.chunks_exact(coded_width).take(visible_height) {
        let Some(visible_row) = coded_row.get(..visible_width) else {
            // A syntax-driven reconstruction must never turn an internal
            // geometry mismatch into a panic. The empty sentinel is rejected
            // by FrameCanvas's exact-plane-length check before any pixels are
            // published.
            return ReconstructedPlane {
                samples: Vec::new(),
            };
        };
        samples.extend_from_slice(visible_row);
    }
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_8x16_from_prediction(
    prediction: [u16; 128],
    coefficients: Option<LossyRectTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 128]);
    let residual = match transform_kind {
        // These identity variants are decoded only for the square 8×8
        // syntax class. Keep this shared rectangular helper total for callers
        // that use the common transform-kind enum.
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x16(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x16(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x16(&coefficients),
        // AV1 names the rectangular transform components in vertical,
        // horizontal order, while the safe rectangular kernel receives the
        // width pass before the height pass.
        LossyTransformKind::DctAdst => transform::inverse_adst_dct8x16(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_dct_adst8x16(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x16(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x16(&coefficients),
    };
    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_8x16(
    predictor: u16,
    coefficients: Option<LossyRectTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    reconstruct_lossy_luma_8x16_from_prediction([predictor; 128], coefficients, transform_kind)
}

fn reconstruct_lossy_luma_8x16_diagonal_z1(
    top: [u16; 16],
    top_left: u16,
    angle: i32,
    coefficients: Option<LossyRectTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    // AV1 zone-1 prediction for an R8x16 transform. The top edge spans the
    // block width plus the smaller block dimension; when intra-edge
    // upsampling is enabled, the edge and derivative are doubled together.
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (0 < angle && angle < 90).then_some(()).portable()?;
    let dx_index = usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?;
    let dx = *DR_INTRA_DERIVATIVE
        .get(dx_index)
        .filter(|&&value| value > 0)
        .portable()?;
    let upsample = 50 < angle;
    let upsampled_edge = upsample_intra_top_edge_16(top, top_left);
    let (edge, max_base_x, dx, base_increment) = if upsample {
        (&upsampled_edge[..], 30, dx.saturating_mul(2), 2)
    } else {
        (&top[..], 15, dx, 1)
    };
    let mut prediction = [0_u16; 128];
    for y in 0_usize..16 {
        for x in 0_usize..8 {
            prediction[y.saturating_mul(8).saturating_add(x)] =
                diagonal_z1_predictor_sample(edge, max_base_x, dx, base_increment, x, y)?;
        }
    }
    Ok(reconstruct_lossy_luma_8x16_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn reconstruct_lossy_luma_8x16_diagonal(
    top: [u16; 16],
    left: [u16; 16],
    angle: i32,
    enable_intra_edge_filter: bool,
    coefficients: LossyRectTransformCoefficients,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:965-1098 and
    // src/tables.rs:1083-1085. This is the safe Z2 (90°..180°) predictor
    // for the baseline R8x16 terminal. The reference stores the left edge
    // backwards from the top-left sample; the checked array below preserves
    // that layout without pointer arithmetic.
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;

    const WIDTH: usize = 8;
    const HEIGHT: usize = 16;
    const TOP_LEFT: usize = HEIGHT;
    // The AV1 intra-edge filter is selected from the complete transform
    // extent. R8x16 has an extent of 24, so this geometry does not use the
    // optional two-times edge upsample; it only filters the prepared top and
    // left edges before directional interpolation.
    let top_left = top[0];
    let top = if enable_intra_edge_filter {
        filter_z2_top_edge(
            top,
            top_left,
            intra_edge_filter_strength(
                HEIGHT.saturating_add(WIDTH),
                angle.saturating_sub(90),
                false,
            ),
        )
    } else {
        top
    };
    let left = if enable_intra_edge_filter {
        filter_z3_left_edge_16(
            left,
            top_left,
            intra_edge_filter_strength(HEIGHT.saturating_add(WIDTH), 180 - angle, false),
        )
    } else {
        left
    };
    let mut edge = [0_i32; HEIGHT * 2 + 1];
    edge[TOP_LEFT] = i32::from(top[0]);
    for (index, sample) in top.into_iter().enumerate() {
        *edge
            .get_mut(TOP_LEFT.saturating_add(1).saturating_add(index))
            .portable()? = i32::from(sample);
    }
    for (index, sample) in left.into_iter().enumerate() {
        *edge
            .get_mut(TOP_LEFT.saturating_sub(1).saturating_sub(index))
            .portable()? = i32::from(sample);
    }

    let mut prediction = [0_u16; WIDTH * HEIGHT];
    for y in 0..HEIGHT {
        let y_i32 = i32::try_from(y).map_err(|_| PortableUnavailable)?;
        let xpos = 64_i32.saturating_sub(dx.saturating_mul(y_i32.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x in 0..WIDTH {
            let x_i32 = i32::try_from(x).map_err(|_| PortableUnavailable)?;
            let sample = if base_x >= 0 {
                let first_index = i32::try_from(TOP_LEFT)
                    .map_err(|_| PortableUnavailable)?
                    .saturating_add(base_x)
                    .saturating_add(x_i32);
                let first_index = usize::try_from(first_index).map_err(|_| PortableUnavailable)?;
                let second_index = first_index.saturating_add(1);
                let first = *edge
                    .get(first_index.min(edge.len().saturating_sub(1)))
                    .portable()?;
                let second = *edge
                    .get(second_index.min(edge.len().saturating_sub(1)))
                    .portable()?;
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let ypos = y_i32
                    .saturating_mul(64)
                    .saturating_sub(dy.saturating_mul(x_i32.saturating_add(1)));
                let base_y = ypos >> 6;
                let first_index = i32::try_from(TOP_LEFT.saturating_sub(1))
                    .map_err(|_| PortableUnavailable)?
                    .saturating_sub(base_y);
                // AV1's zone-2 left pointer starts at the first sample below
                // the top-left corner and walks toward that corner for the
                // interpolated second sample. In the forward edge
                // representation this is the preceding slot, not the
                // following slot used by the above edge.
                let second_index = first_index.saturating_sub(1);
                let first_index = usize::try_from(first_index).map_err(|_| PortableUnavailable)?;
                let second_index =
                    usize::try_from(second_index).map_err(|_| PortableUnavailable)?;
                let frac_y = ypos & 0x3e;
                let first = *edge
                    .get(first_index.min(edge.len().saturating_sub(1)))
                    .portable()?;
                let second = *edge
                    .get(second_index.min(edge.len().saturating_sub(1)))
                    .portable()?;
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            #[expect(
                clippy::cast_sign_loss,
                reason = "the directional predictor is explicitly clamped to eight-bit range"
            )]
            let sample = sample.clamp(0, 255) as u16;
            *prediction
                .get_mut(y.saturating_mul(WIDTH).saturating_add(x))
                .portable()? = sample;
        }
    }

    Ok(reconstruct_lossy_luma_8x16_from_prediction(
        prediction,
        Some(coefficients),
        transform_kind,
    ))
}

#[expect(
    clippy::too_many_arguments,
    reason = "the zone-three predictor receives both positioned edges and the rectangular transform syntax"
)]
fn reconstruct_lossy_luma_8x16_diagonal_z3(
    left: [u16; 16],
    top_left: u16,
    bottom_left: Option<[u16; 8]>,
    angle: i32,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
    coefficients: Option<LossyRectTransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (180 < angle && angle < 270).then_some(()).portable()?;
    let dy_index =
        usize::try_from(270_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    // dav1d's `get_upsample(width + height, angle - 180, is_sm)` only
    // upsamples extents up to sixteen pixels. R8x16 has a 24-pixel edge, so
    // angle 186 uses the ordinary filtered/unfiltered Zone-3 edge path.
    let upsample = enable_intra_edge_filter
        && intra_edge_upsample(24, angle.saturating_sub(180), smooth_edges);

    let mut full_left = [0_u16; 24];
    full_left[..16].copy_from_slice(&left);
    if let Some(bottom_left) = bottom_left {
        full_left[16..].copy_from_slice(&bottom_left);
    } else {
        full_left[16..].fill(left[15]);
    }
    let filtered_left = if enable_intra_edge_filter && !upsample {
        filter_z3_left_edge_24(
            full_left,
            top_left,
            intra_edge_filter_strength(24, angle.saturating_sub(180), smooth_edges),
        )
    } else {
        full_left
    };

    let mut prediction = [0_u16; 128];
    if upsample {
        let edge = upsample_intra_left_edge_24(full_left, top_left);
        for y in 0_usize..16 {
            for x in 0_usize..8 {
                prediction[y.saturating_mul(8).saturating_add(x)] =
                    diagonal_z3_predictor_sample(&edge, 46, dy.saturating_mul(2), 2, x, y)?;
            }
        }
    } else {
        for y in 0_usize..16 {
            for x in 0_usize..8 {
                prediction[y.saturating_mul(8).saturating_add(x)] =
                    diagonal_z3_predictor_sample(&filtered_left, 23, dy, 1, x, y)?;
            }
        }
    }

    Ok(reconstruct_lossy_luma_8x16_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

#[allow(
    dead_code,
    reason = "the safe R8x16 terminal is test-backed before full-frame walker integration"
)]
fn rectangular_dc_predictor(top: &[u16], left: &[u16]) -> u16 {
    // dav1d's `dc_gen()` first rounds the edge sum at the power-of-two
    // boundary, then applies the reciprocal for a rectangular block.  A
    // single divide by `width + height` is not equivalent for all sums and
    // produces occasional one-level CFL mismatches on R8x16 chroma blocks.
    let width = top.len();
    let height = left.len();
    let count = width.saturating_add(height);
    let sum = top
        .iter()
        .chain(left)
        .fold(0_u32, |sum, sample| sum.saturating_add(u32::from(*sample)));
    let rounded = sum.saturating_add(u32::try_from(count / 2).unwrap_or(u32::MAX));
    let shift = count.trailing_zeros();
    let mut predictor = rounded >> shift;
    if width != height {
        let multiplier = if width > height.saturating_mul(2) || height > width.saturating_mul(2) {
            0x3334_u32
        } else {
            0x5556_u32
        };
        predictor = predictor.saturating_mul(multiplier) >> 16;
    }
    u16::try_from(predictor.min(u32::from(u16::MAX))).unwrap_or(u16::MAX)
}

#[allow(
    dead_code,
    reason = "the safe R8x16 terminal is test-backed before full-frame walker integration"
)]
fn reconstruct_lossy_chroma_4x8_dc(top: [u16; 8], left: [u16; 8]) -> ReconstructedPlane {
    let predictor = rectangular_dc_predictor(&top[..4], &left);
    ReconstructedPlane {
        samples: vec![predictor; 32],
    }
}

#[derive(Clone)]
struct ClosedLeaf {
    luma_predictor: LumaPredictor,
    planes: [ReconstructedPlane; 3],
}

fn palette_prediction(
    palette: PalettePlane,
    indices: [u8; PALETTE_MAP_SAMPLES],
) -> Option<[u16; PALETTE_MAP_SAMPLES]> {
    (2..=PALETTE_CAPACITY)
        .contains(&usize::from(palette.size))
        .then_some(())?;
    let mut prediction = [0_u16; PALETTE_MAP_SAMPLES];
    for (index, sample) in prediction.iter_mut().enumerate() {
        let palette_index = usize::from(*indices.get(index)?);
        *sample = *palette.colors.get(palette_index)?;
    }
    Some(prediction)
}

fn reconstruct_palette_square8_leaf(syntax: BlockSyntax) -> Option<ClosedLeaf> {
    if !syntax.palette.is_present()
        || !matches!(syntax.transform_grid, TransformGrid::Square8)
        || !matches!(syntax.chroma_sampling, ChromaSampling::Full)
        || !matches!(syntax.chroma_predictor, ChromaPredictor::Dc)
    {
        return None;
    }
    let luma_prediction = palette_prediction(syntax.palette.y, syntax.palette.y_indices)?;
    let luma_prediction = std::array::from_fn(|index| luma_prediction[index]);
    let chroma_u_prediction = palette_prediction(syntax.palette.u, syntax.palette.uv_indices)?;
    let chroma_u_prediction = std::array::from_fn(|index| chroma_u_prediction[index]);
    let chroma_v_prediction = palette_prediction(syntax.palette.v, syntax.palette.uv_indices)?;
    let chroma_v_prediction = std::array::from_fn(|index| chroma_v_prediction[index]);
    let luma = syntax.lossy_luma_4x4_split.map_or_else(
        || {
            reconstruct_lossy_luma_8x8_from_prediction(
                luma_prediction,
                syntax.lossy_luma_coefficients,
                syntax.lossy_luma_transform,
            )
        },
        |split| reconstruct_lossy_luma_8x8_split_from_prediction(luma_prediction, split),
    );
    let chroma_transform = chroma_transform_kind(syntax.chroma_predictor);
    let chroma_u = reconstruct_lossy_luma_8x8_from_prediction(
        chroma_u_prediction,
        syntax.lossy_chroma_8x8_coefficients[0],
        chroma_transform,
    );
    let chroma_v = reconstruct_lossy_luma_8x8_from_prediction(
        chroma_v_prediction,
        syntax.lossy_chroma_8x8_coefficients[1],
        chroma_transform,
    );
    Some(ClosedLeaf {
        luma_predictor: syntax.luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_palette_square16_leaf(syntax: BlockSyntax) -> Option<ClosedLeaf> {
    if !syntax.palette.is_present()
        || !matches!(syntax.transform_grid, TransformGrid::Square16)
        || !matches!(syntax.chroma_sampling, ChromaSampling::Subsampled420)
        || !matches!(syntax.chroma_predictor, ChromaPredictor::Dc)
        || !syntax.palette.y.is_present()
        || !syntax.palette.u.is_present()
        || !syntax.palette.v.is_present()
    {
        return None;
    }

    let luma_prediction = palette_prediction(syntax.palette.y, syntax.palette.y_indices)?;
    let luma_prediction = std::array::from_fn(|index| luma_prediction[index]);
    let luma = syntax.lossy_luma_8x8_split.map_or_else(
        || {
            reconstruct_lossy_luma_16x16_from_prediction(
                luma_prediction,
                syntax.lossy_luma_16x16_coefficients,
                syntax.lossy_luma_16x16_transform,
            )
        },
        |split| reconstruct_lossy_luma_16x16_split_from_prediction(luma_prediction, split),
    );
    let chroma_transform = chroma_transform_kind(syntax.chroma_predictor);
    let chroma = |palette: PalettePlane, coefficients| {
        let prediction = palette_prediction(palette, syntax.palette.uv_indices)?;
        let prediction = std::array::from_fn(|index| prediction[index]);
        Some(reconstruct_lossy_luma_8x8_from_prediction(
            prediction,
            coefficients,
            chroma_transform,
        ))
    };
    let chroma_u = chroma(syntax.palette.u, syntax.lossy_chroma_8x8_coefficients[0])?;
    let chroma_v = chroma(syntax.palette.v, syntax.lossy_chroma_8x8_coefficients[1])?;

    Some(ClosedLeaf {
        luma_predictor: syntax.luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_leaf(syntax: BlockSyntax, predictors: [u16; 3]) -> ClosedLeaf {
    reconstruct_leaf_with_luma_override(syntax, predictors, None)
}

fn reconstruct_leaf_with_luma_override(
    syntax: BlockSyntax,
    predictors: [u16; 3],
    luma_override: Option<ReconstructedPlane>,
) -> ClosedLeaf {
    if luma_override.is_none()
        && let Some(leaf) = reconstruct_palette_square8_leaf(syntax)
    {
        return leaf;
    }
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle: _,
        coefficients,
        lossy_luma_coefficients,
        lossy_luma_4x8_coefficients,
        lossy_luma_4x8_transform,
        lossy_luma_16x16_coefficients,
        lossy_luma_16x16_transform,
        lossy_luma_32x32_coefficients,
        lossy_luma_16x32_coefficients,
        lossy_luma_16x32_transform,
        lossy_luma_64x64_coefficients,
        lossy_luma_8x32_coefficients,
        lossy_luma_16x64_coefficients,
        lossy_luma_32x16_coefficients,
        lossy_luma_32x8_coefficients,
        lossy_luma_64x16_coefficients,
        lossy_luma_16x8_coefficients,
        lossy_luma_16x8_transform,
        lossy_luma_transform,
        lossy_luma_residual_context: _,
        lossy_luma_4x4_split,
        lossy_luma_8x8_split,
        lossy_luma_8x8_grid_split,
        lossy_luma_16x16_split: _,
        lossy_luma_16x16_horizontal_split: _,
        lossy_luma_16x16_vertical_split,
        lossy_luma_16x4_transform,
        lossy_luma_rect_coefficients,
        lossy_luma_rect_transform,
        lossy_chroma_coefficients,
        lossy_chroma_8x8_coefficients,
        lossy_chroma_8x4_coefficients,
        lossy_chroma_16x16_coefficients,
        lossy_chroma_32x32_coefficients,
        lossy_chroma_8x32_coefficients,
        lossy_chroma_8x16_coefficients,
        lossy_chroma_32x8_coefficients,
        lossy_chroma_4x16_coefficients,
        lossy_chroma_16x4_coefficients,
        lossy_chroma_16x8_coefficients,
        lossy_chroma_4x4_splits: _,
        lossy_chroma_residual_contexts: _,
        lossy_quantization: _,
        transform_grid,
        chroma_sampling,
        palette: _,
        reconstruction,
    } = syntax;
    let planes = match reconstruction {
        ReconstructionPolicy::LosslessWht4x4 => [
            reconstruct_coded_plane(
                predictors[0],
                coefficients[0],
                transform_grid,
                ChromaSampling::Full,
            ),
            reconstruct_coded_plane(
                predictors[1],
                coefficients[1],
                transform_grid,
                chroma_sampling,
            ),
            reconstruct_coded_plane(
                predictors[2],
                coefficients[2],
                transform_grid,
                chroma_sampling,
            ),
        ],
        ReconstructionPolicy::Lossy420Dct4x4 => {
            let luma_coefficients = lossy_luma_coefficients
                .map(|coefficients| std::array::from_fn(|index| coefficients[index]));
            let luma =
                reconstruct_lossy_4x4(predictors[0], luma_coefficients, lossy_luma_transform);
            let chroma_u = reconstruct_lossy_chroma_4x4(
                predictors[1],
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            );
            let chroma_v = reconstruct_lossy_chroma_4x4(
                predictors[2],
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            );
            [luma, chroma_u, chroma_v]
        }
        ReconstructionPolicy::Lossy420Dct4x8 => {
            let luma = reconstruct_lossy_luma_4x8(
                [predictors[0]; 4],
                [predictors[0]; 8],
                lossy_luma_4x8_coefficients,
                lossy_luma_4x8_transform,
            );
            let chroma_u = reconstruct_lossy_chroma_4x4(
                predictors[1],
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            );
            let chroma_v = reconstruct_lossy_chroma_4x4(
                predictors[2],
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            );
            [luma, chroma_u, chroma_v]
        }
        ReconstructionPolicy::Lossy420Dct4x16 => {
            let luma = reconstruct_lossy_luma_4x16(
                predictors[0],
                lossy_luma_coefficients,
                lossy_luma_4x8_transform,
            );
            let chroma_transform = chroma_rect_transform_kind(chroma_predictor);
            let chroma_u = reconstruct_lossy_luma_4x8(
                [predictors[1]; 4],
                [predictors[1]; 8],
                lossy_chroma_8x4_coefficients[0],
                chroma_transform,
            );
            let chroma_v = reconstruct_lossy_luma_4x8(
                [predictors[2]; 4],
                [predictors[2]; 8],
                lossy_chroma_8x4_coefficients[1],
                chroma_transform,
            );
            [luma, chroma_u, chroma_v]
        }
        ReconstructionPolicy::Lossy420Dct8x4 => {
            let luma = reconstruct_lossy_luma_8x4(
                predictors[0],
                lossy_luma_4x8_coefficients,
                lossy_luma_4x8_transform,
            );
            if matches!(chroma_sampling, ChromaSampling::Full) {
                let luma_for_chroma = luma.clone();
                let chroma = |plane: usize| match chroma_predictor {
                    ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                        let alpha = if plane == 1 { alpha_u } else { alpha_v };
                        // `reconstruct_lossy_luma_8x4` always returns exactly 32 samples;
                        // the CFL helper's fallible extent check protects other callers.
                        reconstruct_lossy_full_8x4_cfl(
                            &luma_for_chroma,
                            predictors[plane],
                            alpha,
                            lossy_chroma_8x4_coefficients[plane - 1],
                        )
                        .unwrap_or_else(|_| {
                            unreachable!("8x4 luma reconstruction must have 32 samples")
                        })
                    }
                    _ => reconstruct_lossy_luma_8x4(
                        predictors[plane],
                        lossy_chroma_8x4_coefficients[plane - 1],
                        chroma_rect_transform_kind(chroma_predictor),
                    ),
                };
                [luma, chroma(1), chroma(2)]
            } else {
                let chroma_u = reconstruct_lossy_chroma_4x4(
                    predictors[1],
                    lossy_chroma_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                );
                let chroma_v = reconstruct_lossy_chroma_4x4(
                    predictors[2],
                    lossy_chroma_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                );
                [luma, chroma_u, chroma_v]
            }
        }
        ReconstructionPolicy::Lossy420Dct16x4 => {
            let luma = reconstruct_lossy_luma_16x4(
                predictors[0],
                lossy_luma_coefficients,
                lossy_luma_16x4_transform,
            );
            let chroma_transform = chroma_rect_transform_kind(chroma_predictor);
            let chroma_u = reconstruct_lossy_luma_8x4(
                predictors[1],
                lossy_chroma_8x4_coefficients[0],
                chroma_transform,
            );
            let chroma_v = reconstruct_lossy_luma_8x4(
                predictors[2],
                lossy_chroma_8x4_coefficients[1],
                chroma_transform,
            );
            [luma, chroma_u, chroma_v]
        }
        ReconstructionPolicy::Lossy420Dct8x8 => {
            let luma = if let Some(luma_override) = luma_override {
                luma_override
            } else if let Some(split) = lossy_luma_4x4_split {
                reconstruct_lossy_luma_8x8_split_from_prediction([predictors[0]; 64], split)
            } else {
                reconstruct_lossy_luma_8x8(
                    predictors[0],
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                )
            };
            if matches!(chroma_sampling, ChromaSampling::Full) {
                let luma_for_chroma = luma.clone();
                let chroma = |plane: usize| match chroma_predictor {
                    ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                        let alpha = if plane == 1 { alpha_u } else { alpha_v };
                        reconstruct_lossy_full_8x8_cfl(
                            &luma_for_chroma,
                            predictors[plane],
                            alpha,
                            lossy_chroma_8x8_coefficients[plane - 1],
                        )
                        .unwrap_or_else(|_| {
                            reconstruct_lossy_chroma_8x8(
                                predictors[plane],
                                lossy_chroma_8x8_coefficients[plane - 1],
                                LossyTransformKind::DctDct,
                            )
                        })
                    }
                    _ => reconstruct_lossy_chroma_8x8(
                        predictors[plane],
                        lossy_chroma_8x8_coefficients[plane - 1],
                        chroma_transform_kind(chroma_predictor),
                    ),
                };
                return ClosedLeaf {
                    luma_predictor,
                    planes: [luma, chroma(1), chroma(2)],
                };
            }
            let chroma_u = match chroma_predictor {
                ChromaPredictor::Cfl { alpha_u, .. } => reconstruct_lossy_chroma_4x4_cfl(
                    &luma,
                    predictors[1],
                    alpha_u,
                    lossy_chroma_coefficients[0],
                )
                .unwrap_or_else(|_| {
                    reconstruct_lossy_chroma_4x4(
                        predictors[1],
                        lossy_chroma_coefficients[0],
                        LossyTransformKind::DctDct,
                    )
                }),
                _ => reconstruct_lossy_chroma_4x4(
                    predictors[1],
                    lossy_chroma_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                ),
            };
            let chroma_v = match chroma_predictor {
                ChromaPredictor::Cfl { alpha_v, .. } => reconstruct_lossy_chroma_4x4_cfl(
                    &luma,
                    predictors[2],
                    alpha_v,
                    lossy_chroma_coefficients[1],
                )
                .unwrap_or_else(|_| {
                    reconstruct_lossy_chroma_4x4(
                        predictors[2],
                        lossy_chroma_coefficients[1],
                        LossyTransformKind::DctDct,
                    )
                }),
                _ => reconstruct_lossy_chroma_4x4(
                    predictors[2],
                    lossy_chroma_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                ),
            };
            [luma, chroma_u, chroma_v]
        }
        ReconstructionPolicy::Lossy420Dct16x16 => {
            let luma = if let Some(split) = lossy_luma_8x8_split {
                reconstruct_lossy_luma_16x16_split(
                    luma_predictor,
                    luma_angle,
                    filter_intra_mode,
                    [predictors[0]; 16],
                    [predictors[0]; 16],
                    predictors[0],
                    false,
                    false,
                    split,
                )
                .unwrap_or_else(|_| ReconstructedPlane {
                    samples: vec![predictors[0]; 256],
                })
            } else {
                reconstruct_lossy_luma_16x16(
                    predictors[0],
                    lossy_luma_16x16_coefficients,
                    lossy_luma_16x16_transform,
                )
            };
            if matches!(chroma_sampling, ChromaSampling::Full) {
                let chroma = |plane: usize| {
                    reconstruct_lossy_chroma_16x16(
                        predictors[plane],
                        lossy_chroma_16x16_coefficients[plane - 1],
                    )
                };
                return ClosedLeaf {
                    luma_predictor,
                    planes: [luma, chroma(1), chroma(2)],
                };
            }
            let chroma_u = match chroma_predictor {
                ChromaPredictor::Cfl { alpha_u, .. } => reconstruct_lossy_chroma_8x8_cfl(
                    &luma,
                    predictors[1],
                    alpha_u,
                    lossy_chroma_8x8_coefficients[0],
                )
                .unwrap_or_else(|_| {
                    reconstruct_lossy_chroma_8x8(
                        predictors[1],
                        lossy_chroma_8x8_coefficients[0],
                        LossyTransformKind::DctDct,
                    )
                }),
                _ => reconstruct_lossy_chroma_8x8(
                    predictors[1],
                    lossy_chroma_8x8_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                ),
            };
            let chroma_v = match chroma_predictor {
                ChromaPredictor::Cfl { alpha_v, .. } => reconstruct_lossy_chroma_8x8_cfl(
                    &luma,
                    predictors[2],
                    alpha_v,
                    lossy_chroma_8x8_coefficients[1],
                )
                .unwrap_or_else(|_| {
                    reconstruct_lossy_chroma_8x8(
                        predictors[2],
                        lossy_chroma_8x8_coefficients[1],
                        LossyTransformKind::DctDct,
                    )
                }),
                _ => reconstruct_lossy_chroma_8x8(
                    predictors[2],
                    lossy_chroma_8x8_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                ),
            };
            [luma, chroma_u, chroma_v]
        }
        ReconstructionPolicy::Lossy420Dct32x32 => {
            let luma = reconstruct_lossy_luma_32x32(predictors[0], lossy_luma_32x32_coefficients);
            let chroma = |plane: usize| {
                if matches!(chroma_sampling, ChromaSampling::Full) {
                    reconstruct_lossy_chroma_32x32(
                        predictors[plane],
                        lossy_chroma_32x32_coefficients[plane - 1],
                    )
                } else {
                    reconstruct_lossy_chroma_16x16(
                        predictors[plane],
                        lossy_chroma_16x16_coefficients[plane - 1],
                    )
                }
            };
            let chroma_u = chroma(1);
            let chroma_v = chroma(2);
            [luma, chroma_u, chroma_v]
        }
        ReconstructionPolicy::Lossy420Dct64x64 => [
            reconstruct_lossy_luma_64x64(predictors[0], lossy_luma_64x64_coefficients),
            reconstruct_lossy_chroma_32x32(predictors[1], lossy_chroma_32x32_coefficients[0]),
            reconstruct_lossy_chroma_32x32(predictors[2], lossy_chroma_32x32_coefficients[1]),
        ],
        ReconstructionPolicy::Lossy420Dct16x32 => {
            let luma = if let Some(split) = lossy_luma_8x8_grid_split {
                reconstruct_lossy_luma_16x32_split(
                    luma_predictor,
                    None,
                    None,
                    [predictors[0]; 16],
                    [predictors[0]; 32],
                    predictors[0],
                    false,
                    split,
                )
                .unwrap_or_else(|_| ReconstructedPlane {
                    samples: vec![predictors[0]; 512],
                })
            } else if let Some(coefficients) = lossy_luma_16x32_coefficients {
                reconstruct_lossy_luma_16x32_from_edges(
                    luma_predictor,
                    None,
                    [predictors[0]; 16],
                    [predictors[0]; 32],
                    predictors[0],
                    false,
                    coefficients,
                    lossy_luma_16x32_transform,
                )
                .unwrap_or_else(|_| ReconstructedPlane {
                    samples: vec![predictors[0]; 512],
                })
            } else {
                ReconstructedPlane {
                    samples: vec![predictors[0]; 512],
                }
            };
            let luma_for_chroma = luma.clone();
            let chroma = |plane: usize, predictor: u16| match chroma_predictor {
                ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                    let alpha = if plane == 0 { alpha_u } else { alpha_v };
                    reconstruct_lossy_chroma_8x16_cfl(
                        &luma_for_chroma,
                        predictor,
                        alpha,
                        lossy_chroma_8x16_coefficients[plane],
                    )
                    .unwrap_or_else(|_| ReconstructedPlane {
                        samples: vec![predictor; 128],
                    })
                }
                _ => reconstruct_lossy_luma_8x16_from_prediction(
                    [predictor; 128],
                    lossy_chroma_8x16_coefficients[plane],
                    chroma_transform_kind(chroma_predictor),
                ),
            };
            [luma, chroma(0, predictors[1]), chroma(1, predictors[2])]
        }
        ReconstructionPolicy::Lossy420Dct32x8 => [
            reconstruct_lossy_luma_32x8(predictors[0], lossy_luma_32x8_coefficients),
            reconstruct_lossy_luma_16x4(
                predictors[1],
                lossy_chroma_16x4_coefficients[0],
                Lossy4x8TransformKind::DctDct,
            ),
            reconstruct_lossy_luma_16x4(
                predictors[2],
                lossy_chroma_16x4_coefficients[1],
                Lossy4x8TransformKind::DctDct,
            ),
        ],
        ReconstructionPolicy::Lossy420Dct16x64 => {
            let luma = if let Some(split) = lossy_luma_16x16_vertical_split {
                reconstruct_lossy_luma_16x64_vertical_split(
                    luma_predictor,
                    luma_angle,
                    filter_intra_mode,
                    [predictors[0]; 16],
                    [predictors[0]; 64],
                    predictors[0],
                    false,
                    split,
                )
                .unwrap_or_else(|_| ReconstructedPlane {
                    samples: vec![predictors[0]; 1024],
                })
            } else {
                reconstruct_lossy_luma_16x64(predictors[0], lossy_luma_16x64_coefficients)
            };
            [
                luma,
                reconstruct_lossy_residual_plane(
                    predictors[1],
                    &transform::inverse_dct8x32(
                        &lossy_chroma_8x32_coefficients[0].unwrap_or([0_i32; 256]),
                    ),
                ),
                reconstruct_lossy_residual_plane(
                    predictors[2],
                    &transform::inverse_dct8x32(
                        &lossy_chroma_8x32_coefficients[1].unwrap_or([0_i32; 256]),
                    ),
                ),
            ]
        }
        ReconstructionPolicy::Lossy420Dct32x16 => {
            let luma = if let Some(split) = lossy_luma_8x8_grid_split {
                reconstruct_lossy_luma_32x16_split(
                    luma_predictor,
                    None,
                    None,
                    [predictors[0]; 32],
                    [predictors[0]; 16],
                    predictors[0],
                    false,
                    split,
                )
                .unwrap_or_else(|_| ReconstructedPlane {
                    samples: vec![predictors[0]; 512],
                })
            } else {
                reconstruct_lossy_luma_32x16(predictors[0], lossy_luma_32x16_coefficients)
            };
            [
                luma,
                reconstruct_lossy_chroma_16x8(
                    predictors[1],
                    lossy_chroma_16x8_coefficients[0],
                    chroma_rect_transform_kind(chroma_predictor),
                ),
                reconstruct_lossy_chroma_16x8(
                    predictors[2],
                    lossy_chroma_16x8_coefficients[1],
                    chroma_rect_transform_kind(chroma_predictor),
                ),
            ]
        }
        ReconstructionPolicy::Lossy420Dct64x16 => [
            reconstruct_lossy_luma_64x16(predictors[0], lossy_luma_64x16_coefficients),
            reconstruct_lossy_chroma_32x8(predictors[1], lossy_chroma_32x8_coefficients[0]),
            reconstruct_lossy_chroma_32x8(predictors[2], lossy_chroma_32x8_coefficients[1]),
        ],
        ReconstructionPolicy::Lossy420Dct8x32 => {
            let luma = reconstruct_lossy_luma_8x32(predictors[0], lossy_luma_8x32_coefficients);
            let chroma_u =
                reconstruct_lossy_chroma_4x16(predictors[1], lossy_chroma_4x16_coefficients[0]);
            let chroma_v =
                reconstruct_lossy_chroma_4x16(predictors[2], lossy_chroma_4x16_coefficients[1]);
            [luma, chroma_u, chroma_v]
        }
        ReconstructionPolicy::Lossy420Dct16x8 => {
            let luma = reconstruct_lossy_luma_16x8(
                predictors[0],
                lossy_luma_16x8_coefficients,
                lossy_luma_16x8_transform,
            );
            let chroma_transform = chroma_rect_transform_kind(chroma_predictor);
            let chroma_u = reconstruct_lossy_luma_8x4(
                predictors[1],
                lossy_chroma_8x4_coefficients[0],
                chroma_transform,
            );
            let chroma_v = reconstruct_lossy_luma_8x4(
                predictors[2],
                lossy_chroma_8x4_coefficients[1],
                chroma_transform,
            );
            [luma, chroma_u, chroma_v]
        }
        ReconstructionPolicy::Lossy420Rectangular => {
            let luma = reconstruct_lossy_luma_8x16(
                predictors[0],
                lossy_luma_rect_coefficients,
                lossy_luma_rect_transform,
            );
            let chroma_transform = chroma_rect_transform_kind(chroma_predictor);
            let chroma_u = reconstruct_lossy_luma_4x8(
                [predictors[1]; 4],
                [predictors[1]; 8],
                lossy_chroma_8x4_coefficients[0],
                chroma_transform,
            );
            let chroma_v = reconstruct_lossy_luma_4x8(
                [predictors[2]; 4],
                [predictors[2]; 8],
                lossy_chroma_8x4_coefficients[1],
                chroma_transform,
            );
            [luma, chroma_u, chroma_v]
        }
    };
    ClosedLeaf {
        luma_predictor,
        planes,
    }
}

fn origin_predictors(luma_predictor: LumaPredictor) -> [u16; 3] {
    [luma_predictor.sample(), 128, 128]
}

#[derive(Clone, Copy)]
enum LosslessPredictor {
    Dc,
    Vertical,
    Horizontal,
    Diagonal45,
    DiagonalDownRight,
    Diagonal113,
    Diagonal157,
    Diagonal203,
    Diagonal67,
    Smooth,
    SmoothVertical,
    SmoothHorizontal,
    Paeth,
}

fn lossless_luma_predictor(predictor: LumaPredictor) -> LosslessPredictor {
    match predictor {
        LumaPredictor::Dc => LosslessPredictor::Dc,
        LumaPredictor::Vertical => LosslessPredictor::Vertical,
        LumaPredictor::Horizontal => LosslessPredictor::Horizontal,
        LumaPredictor::Diagonal45 => LosslessPredictor::Diagonal45,
        LumaPredictor::DiagonalDownRight => LosslessPredictor::DiagonalDownRight,
        LumaPredictor::Diagonal113 => LosslessPredictor::Diagonal113,
        LumaPredictor::Diagonal157 => LosslessPredictor::Diagonal157,
        LumaPredictor::Diagonal203 => LosslessPredictor::Diagonal203,
        LumaPredictor::Diagonal67 => LosslessPredictor::Diagonal67,
        LumaPredictor::Smooth => LosslessPredictor::Smooth,
        LumaPredictor::SmoothVertical => LosslessPredictor::SmoothVertical,
        LumaPredictor::SmoothHorizontal => LosslessPredictor::SmoothHorizontal,
        LumaPredictor::Paeth => LosslessPredictor::Paeth,
    }
}

fn lossless_chroma_predictor(predictor: ChromaPredictor) -> LosslessPredictor {
    match predictor {
        ChromaPredictor::Dc => LosslessPredictor::Dc,
        ChromaPredictor::Cfl { .. } => LosslessPredictor::Dc,
        ChromaPredictor::Vertical => LosslessPredictor::Vertical,
        ChromaPredictor::Horizontal => LosslessPredictor::Horizontal,
        ChromaPredictor::Diagonal45 => LosslessPredictor::Diagonal45,
        ChromaPredictor::DiagonalDownRight => LosslessPredictor::DiagonalDownRight,
        ChromaPredictor::Diagonal113 => LosslessPredictor::Diagonal113,
        ChromaPredictor::Diagonal157 => LosslessPredictor::Diagonal157,
        ChromaPredictor::Diagonal203 => LosslessPredictor::Diagonal203,
        ChromaPredictor::Diagonal67 => LosslessPredictor::Diagonal67,
        ChromaPredictor::Smooth => LosslessPredictor::Smooth,
        ChromaPredictor::SmoothVertical => LosslessPredictor::SmoothVertical,
        ChromaPredictor::SmoothHorizontal => LosslessPredictor::SmoothHorizontal,
        ChromaPredictor::Paeth => LosslessPredictor::Paeth,
    }
}

/// Resolve an angular AV1 mode into the predictor zone selected by the
/// transform block's available edges.
///
/// The bitstream stores the base mode and an angle delta.  AV1's edge
/// preparation changes that mode to zone 1/2/3 when the resulting angle
/// crosses a zone boundary; treating `H + 6°` as plain horizontal, for
/// example, produces a valid-looking but different lossless image.
fn resolve_lossless_predictor(
    predictor: LosslessPredictor,
    angle: Option<i32>,
    has_top: bool,
    has_left: bool,
) -> LosslessPredictor {
    let Some(angle) = angle else {
        return predictor;
    };
    if !matches!(
        predictor,
        LosslessPredictor::Vertical
            | LosslessPredictor::Horizontal
            | LosslessPredictor::Diagonal45
            | LosslessPredictor::DiagonalDownRight
            | LosslessPredictor::Diagonal113
            | LosslessPredictor::Diagonal157
            | LosslessPredictor::Diagonal203
            | LosslessPredictor::Diagonal67
    ) {
        return predictor;
    }
    if angle <= 90 {
        if angle < 90 && has_top {
            LosslessPredictor::Diagonal45
        } else {
            LosslessPredictor::Vertical
        }
    } else if angle < 180 {
        LosslessPredictor::DiagonalDownRight
    } else if angle > 180 && has_left {
        LosslessPredictor::Diagonal203
    } else {
        LosslessPredictor::Horizontal
    }
}

fn lossless444_sample_at(leaf: &Lossless444Leaf, plane: usize, x: u32, y: u32) -> Option<u16> {
    let local_x = usize::try_from(x.checked_sub(leaf.origin_x)?).ok()?;
    let local_y = usize::try_from(y.checked_sub(leaf.origin_y)?).ok()?;
    let width = usize::try_from(leaf.width).ok()?;
    let height = usize::try_from(leaf.height).ok()?;
    if local_x >= width || local_y >= height {
        return None;
    }
    let index = local_y.checked_mul(width)?.checked_add(local_x)?;
    leaf.closed.planes.get(plane)?.samples.get(index).copied()
}

fn lossless444_external_edges(
    neighbors: [Option<&Lossless444Leaf>; 8],
    above_right: Option<&Lossless444Leaf>,
    geometry: Lossless444BlockGeometry,
    plane: usize,
    above: bool,
) -> PortableResult<(Vec<u16>, bool)> {
    let length = if above {
        usize::try_from(geometry.width)
            .map_err(|_| PortableUnavailable)?
            .saturating_add(4)
    } else {
        usize::try_from(geometry.height).map_err(|_| PortableUnavailable)?
    };
    let has_neighbor = neighbors.iter().any(Option::is_some) || (above && above_right.is_some());
    let mut edge = vec![128_u16; length];
    if !has_neighbor {
        return Ok((edge, false));
    }
    let mut previous_sample = 128_u16;
    for (index, sample) in edge.iter_mut().enumerate() {
        let offset = u32::try_from(index).map_err(|_| PortableUnavailable)?;
        let (x, y) = if above {
            (
                geometry
                    .origin_x
                    .checked_add(offset)
                    .ok_or(PortableUnavailable)?,
                geometry
                    .origin_y
                    .checked_sub(1)
                    .ok_or(PortableUnavailable)?,
            )
        } else {
            (
                geometry
                    .origin_x
                    .checked_sub(1)
                    .ok_or(PortableUnavailable)?,
                geometry
                    .origin_y
                    .checked_add(offset)
                    .ok_or(PortableUnavailable)?,
            )
        };
        if let Some(value) = neighbors
            .iter()
            .flatten()
            .find_map(|leaf| lossless444_sample_at(leaf, plane, x, y))
            .or_else(|| {
                above
                    .then_some(above_right)
                    .flatten()
                    .and_then(|leaf| lossless444_sample_at(leaf, plane, x, y))
            })
        {
            *sample = value;
        } else if has_neighbor {
            *sample = previous_sample;
        }
        previous_sample = *sample;
    }
    Ok((edge, has_neighbor))
}

fn lossless444_external_below_left_edge(
    neighbors: [Option<&Lossless444Leaf>; 8],
    geometry: Lossless444BlockGeometry,
    plane: usize,
) -> PortableResult<Vec<u16>> {
    if !neighbors.iter().any(Option::is_some) {
        return Ok(Vec::new());
    }
    let mut edge = vec![128_u16; 8];
    let Some(left_x) = geometry.origin_x.checked_sub(1) else {
        return Ok(edge);
    };
    for index in 0..edge.len() {
        let offset = u32::try_from(index).map_err(|_| PortableUnavailable)?;
        let y = geometry
            .origin_y
            .saturating_add(geometry.height)
            .saturating_add(offset);
        if let Some(value) = neighbors
            .iter()
            .flatten()
            .find_map(|leaf| lossless444_sample_at(leaf, plane, left_x, y))
        {
            edge[index] = value;
        } else if neighbors.iter().any(Option::is_some) {
            edge[index] = index
                .checked_sub(1)
                .and_then(|previous| edge.get(previous).copied())
                .unwrap_or(128);
        }
    }
    Ok(edge)
}

fn lossless444_top_left(
    above_left: Option<&Lossless444Leaf>,
    geometry: Lossless444BlockGeometry,
    plane: usize,
) -> u16 {
    if geometry.origin_x == 0 || geometry.origin_y == 0 {
        return 128;
    }
    above_left
        .and_then(|leaf| {
            lossless444_sample_at(
                leaf,
                plane,
                geometry.origin_x.saturating_sub(1),
                geometry.origin_y.saturating_sub(1),
            )
        })
        .unwrap_or(128)
}

fn lossless_dc_predictor(top: [u16; 4], left: [u16; 4], has_top: bool, has_left: bool) -> u16 {
    match (has_top, has_left) {
        (true, true) => dc_predictor(top, left),
        (true, false) => one_sided_dc_predictor_4(top),
        (false, true) => one_sided_dc_predictor_4(left),
        (false, false) => 128,
    }
}

#[expect(
    clippy::arithmetic_side_effects,
    reason = "all transform dimensions and sample edges are validated before indexing"
)]
#[expect(
    clippy::too_many_arguments,
    reason = "the safe predictor receives each independently validated AV1 plane and edge explicitly"
)]
fn reconstruct_lossless_plane(
    geometry: Lossless444BlockGeometry,
    predictor: LosslessPredictor,
    angle: Option<i32>,
    coefficients: PlaneCoefficients,
    top: &[u16],
    left: &[u16],
    has_top: bool,
    has_left: bool,
    top_left: u16,
    below_left: &[u16],
    enable_intra_edge_filter: bool,
    filter_intra_mode: Option<usize>,
) -> PortableResult<ReconstructedPlane> {
    let (grid_width, grid_height, _) = geometry.transform_grid.properties();
    let coded_width = grid_width.saturating_mul(4);
    let coded_height = grid_height.saturating_mul(4);
    let width = usize::try_from(geometry.width).map_err(|_| PortableUnavailable)?;
    let height = usize::try_from(geometry.height).map_err(|_| PortableUnavailable)?;
    if width != coded_width || height != coded_height || top.len() < width || left.len() != height {
        return Err(PortableUnavailable);
    }
    let z1_upsample =
        enable_intra_edge_filter && angle.is_some_and(|angle| 50 < angle && angle < 90);
    let z3_upsample =
        enable_intra_edge_filter && angle.is_some_and(|angle| 180 < angle && angle < 220);
    // ✅ VERIFIED: rav1d 1.5.3 src/ipred_prepare.rs:232-306. Missing
    // directional edges are extended with 127 above and 129 on the left;
    // when only the top edge exists, the left extension uses that block's
    // first top sample. DC keeps its explicit 128 fallback below.
    let effective_top = if has_top {
        top.to_vec()
    } else if has_left {
        vec![left.first().copied().unwrap_or(129); width]
    } else {
        vec![127_u16; width]
    };
    let effective_left = if has_left {
        left.to_vec()
    } else if has_top {
        vec![effective_top.first().copied().unwrap_or(127); height]
    } else {
        vec![129_u16; height]
    };
    let diagonal_z2_edges = if angle.is_some_and(|angle| 90 < angle && angle < 180) {
        const DR_INTRA_DERIVATIVE: [i32; 44] = [
            0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0,
            71, 64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
        ];
        let angle = angle.ok_or(PortableUnavailable)?;
        let dy_index =
            usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
        let dx_index =
            usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
        let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
        let dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;
        let left_length = height;
        let top_length = width.saturating_mul(2);
        let mut edge = vec![0_u16; left_length.saturating_add(top_length).saturating_add(1)];
        edge[left_length] = top_left;
        for (index, sample) in effective_left.iter().copied().enumerate() {
            let edge_index = left_length
                .checked_sub(1)
                .and_then(|value| value.checked_sub(index))
                .ok_or(PortableUnavailable)?;
            *edge.get_mut(edge_index).portable()? = sample;
        }
        let top_right = effective_top
            .get(width.saturating_sub(1))
            .copied()
            .unwrap_or(127);
        for index in 0..top_length {
            let sample = effective_top.get(index).copied().unwrap_or(top_right);
            let edge_index = left_length
                .checked_add(1)
                .and_then(|value| value.checked_add(index))
                .ok_or(PortableUnavailable)?;
            *edge.get_mut(edge_index).portable()? = sample;
        }
        Some((edge, left_length, dx, dy))
    } else {
        None
    };
    let diagonal_z3_edges = if angle.is_some_and(|angle| angle > 180) {
        const DR_INTRA_DERIVATIVE: [i32; 44] = [
            0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0,
            71, 64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
        ];
        let angle = angle.ok_or(PortableUnavailable)?;
        let dy_index =
            usize::try_from(270_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
        let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
        let max_base_y = width.saturating_add(height).saturating_sub(1);
        let mut edge = Vec::with_capacity(max_base_y.saturating_add(1));
        let mut last = effective_left.first().copied().unwrap_or(129);
        for row in 0..=max_base_y {
            if let Some(sample) = effective_left.get(row).copied() {
                last = sample;
            }
            edge.push(last);
        }
        Some((edge, max_base_y, dy))
    } else {
        None
    };
    let diagonal_z1_edges = if angle.is_some_and(|angle| angle < 90) {
        const DR_INTRA_DERIVATIVE: [i32; 44] = [
            0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0,
            71, 64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
        ];
        let angle = angle.ok_or(PortableUnavailable)?;
        let dx_index = usize::try_from(angle.saturating_div(2)).map_err(|_| PortableUnavailable)?;
        let dx = *DR_INTRA_DERIVATIVE
            .get(dx_index)
            .filter(|&&value| value > 0)
            .portable()?;
        let max_base_x = width.saturating_add(height).saturating_sub(1);
        let mut edge = Vec::with_capacity(max_base_x.saturating_add(1));
        let mut last = top_left;
        for column in 0..=max_base_x {
            if let Some(sample) = effective_top.get(column).copied() {
                last = sample;
            }
            edge.push(last);
        }
        Some((edge, max_base_x, dx))
    } else {
        None
    };
    let smooth_vertical = if matches!(predictor, LosslessPredictor::SmoothVertical) {
        Some((
            smooth_weight_table(height)?,
            effective_left.last().copied().unwrap_or(129),
        ))
    } else {
        None
    };
    let smooth_horizontal = if matches!(predictor, LosslessPredictor::SmoothHorizontal) {
        Some((
            smooth_weight_table(width)?,
            effective_top
                .get(width.saturating_sub(1))
                .copied()
                .unwrap_or(127),
        ))
    } else {
        None
    };
    let smooth = if matches!(predictor, LosslessPredictor::Smooth) {
        Some((smooth_weight_table(width)?, smooth_weight_table(height)?))
    } else {
        None
    };
    let mut samples = vec![0_u16; coded_width.saturating_mul(coded_height)];
    let transform_count = grid_width.saturating_mul(grid_height);
    for (transform_index, coefficient) in coefficients.into_iter().enumerate().take(transform_count)
    {
        let column = transform_index % grid_width;
        let row = transform_index / grid_width;
        let block_x = column.saturating_mul(4);
        let block_y = row.saturating_mul(4);
        let mut top_edge = [128_u16; 4];
        let mut left_edge = [128_u16; 4];
        let top_available = row > 0 || has_top;
        let left_available = column > 0 || has_left;
        if row > 0 {
            let start = (block_y.saturating_sub(1))
                .saturating_mul(coded_width)
                .saturating_add(block_x);
            top_edge.copy_from_slice(samples.get(start..start.saturating_add(4)).portable()?);
        } else {
            top_edge.copy_from_slice(
                effective_top
                    .get(block_x..block_x.saturating_add(4))
                    .portable()?,
            );
        }
        if column > 0 {
            for (offset, value) in left_edge.iter_mut().enumerate() {
                let index = block_y
                    .saturating_add(offset)
                    .saturating_mul(coded_width)
                    .saturating_add(block_x.saturating_sub(1));
                *value = *samples.get(index).portable()?;
            }
        } else {
            left_edge.copy_from_slice(
                effective_left
                    .get(block_y..block_y.saturating_add(4))
                    .portable()?,
            );
        }
        // ✅ VERIFIED: rav1d 1.5.3 src/ipred_prepare.rs:224-257. A
        // directional transform with no top edge is converted to vertical
        // prediction and its synthetic top edge is the first left sample.
        // The symmetric rule supplies the left edge when horizontal
        // prediction has no left neighbor but does have a top neighbor.
        if row == 0 && !has_top && left_available {
            top_edge.fill(left_edge[0]);
        }
        if column == 0 && !has_left && top_available {
            left_edge.fill(top_edge[0]);
        }
        let prediction_top_left = if row > 0 {
            if column > 0 {
                *samples
                    .get(
                        block_y
                            .saturating_sub(1)
                            .saturating_mul(coded_width)
                            .saturating_add(block_x.saturating_sub(1)),
                    )
                    .portable()?
            } else if has_left {
                effective_left
                    .get(block_y.saturating_sub(1))
                    .copied()
                    .unwrap_or(top_edge[0])
            } else {
                top_edge[0]
            }
        } else if column > 0 {
            if has_top {
                effective_top
                    .get(block_x.saturating_sub(1))
                    .copied()
                    .unwrap_or(left_edge[0])
            } else {
                left_edge[0]
            }
        } else if has_top {
            top_left
        } else if has_left {
            left_edge[0]
        } else {
            top_left
        };
        let dc = lossless_dc_predictor(top_edge, left_edge, top_available, left_available);
        let residual = inverse_wht_4x4(coefficient);
        let transform_predictor =
            resolve_lossless_predictor(predictor, angle, top_available, left_available);
        let filter_block_prediction = filter_intra_mode
            .map(|mode| {
                reconstruct_filter_intra_prediction(
                    mode,
                    4,
                    4,
                    prediction_top_left,
                    &top_edge,
                    &left_edge,
                )
            })
            .transpose()?;
        for (offset, value) in residual.into_iter().enumerate() {
            let local_row = offset / 4;
            let local_column = offset % 4;
            let x = block_x.saturating_add(local_column);
            let y = block_y.saturating_add(local_row);
            let prediction = if let Some(filter_block_prediction) = filter_block_prediction.as_ref()
            {
                *filter_block_prediction.get(offset).portable()?
            } else {
                match transform_predictor {
                    LosslessPredictor::Dc => dc,
                    LosslessPredictor::Vertical => top_edge[local_column],
                    LosslessPredictor::Horizontal => left_edge[local_row],
                    LosslessPredictor::Diagonal45 | LosslessPredictor::Diagonal67 => {
                        let (_, _, dx) = diagonal_z1_edges.as_ref().portable()?;
                        // Each 4x4 lossless transform gets its own intra
                        // prediction edge.  For a lower transform row the
                        // top-right samples come from the already reconstructed
                        // row above, not from the coded leaf's outer edge.
                        let mut edge = [127_u16; 8];
                        if block_y > 0 {
                            let start = (block_y.saturating_sub(1))
                                .saturating_mul(coded_width)
                                .saturating_add(block_x);
                            let count = 8_usize.min(coded_width.saturating_sub(block_x));
                            let available =
                                samples.get(start..start.saturating_add(count)).portable()?;
                            for (index, sample) in available.iter().copied().enumerate() {
                                edge[index] = sample;
                            }
                            if let Some(&last) = available.last() {
                                edge[available.len()..].fill(last);
                            }
                        } else {
                            let available = effective_top
                                .get(block_x..block_x.saturating_add(8))
                                .portable()?;
                            for (index, sample) in available.iter().copied().enumerate() {
                                edge[index] = sample;
                            }
                            if let Some(&last) = available.last() {
                                edge[available.len()..].fill(last);
                            }
                        }
                        let upsampled_edge = upsample_intra_top_edge(edge, prediction_top_left);
                        let (edge, max_base_x, dx) = if z1_upsample {
                            (&upsampled_edge[..], 14, (*dx).saturating_mul(2))
                        } else {
                            (&edge[..], 7, *dx)
                        };
                        diagonal_z1_predictor_sample(
                            edge,
                            max_base_x,
                            dx,
                            if z1_upsample { 2 } else { 1 },
                            local_column,
                            local_row,
                        )?
                    }
                    LosslessPredictor::DiagonalDownRight
                    | LosslessPredictor::Diagonal113
                    | LosslessPredictor::Diagonal157 => {
                        let (edge, left_length, dx, dy) = diagonal_z2_edges.as_ref().portable()?;
                        diagonal_predictor_sample(edge, *left_length, *dx, *dy, x, y)?
                    }
                    LosslessPredictor::Diagonal203 => {
                        let (_, _, dy) = diagonal_z3_edges.as_ref().portable()?;
                        // AV1 prepares an angular edge for each transform.  For
                        // an inner transform column, the left edge is the
                        // already reconstructed previous column and its
                        // bottom-left extension repeats the last available
                        // sample; it is not the outer leaf edge.
                        let mut edge = [129_u16; 8];
                        if block_x > 0 {
                            let start = block_y
                                .saturating_mul(coded_width)
                                .saturating_add(block_x.saturating_sub(1));
                            let available_height =
                                4_usize.min(coded_height.saturating_sub(block_y));
                            for (offset, sample) in
                                edge.iter_mut().take(available_height).enumerate()
                            {
                                *sample = *samples
                                    .get(start.saturating_add(offset.saturating_mul(coded_width)))
                                    .portable()?;
                            }
                            let last = edge
                                .get(available_height.saturating_sub(1))
                                .copied()
                                .unwrap_or(129);
                            edge[available_height..].fill(last);
                        } else {
                            let fallback = effective_left.last().copied().unwrap_or(129);
                            for (index, sample) in edge.iter_mut().enumerate() {
                                let global_index = block_y.saturating_add(index);
                                if let Some(value) = effective_left.get(global_index) {
                                    *sample = *value;
                                } else if let Some(value) =
                                    below_left.get(global_index.saturating_sub(height))
                                {
                                    *sample = *value;
                                } else {
                                    *sample = fallback;
                                }
                            }
                        }
                        let upsampled_edge = upsample_intra_left_edge(edge, prediction_top_left);
                        let (edge, max_base_y, dy) = if z3_upsample {
                            (&upsampled_edge[..], 14, (*dy).saturating_mul(2))
                        } else {
                            (&edge[..], 7, *dy)
                        };
                        diagonal_z3_predictor_sample(
                            edge,
                            max_base_y,
                            dy,
                            if z3_upsample { 2 } else { 1 },
                            local_column,
                            local_row,
                        )?
                    }
                    LosslessPredictor::SmoothVertical => {
                        let (weights, bottom) = smooth_vertical.as_ref().portable()?;
                        let weight = i32::from(*weights.get(y).portable()?);
                        let value = weight
                            .saturating_mul(i32::from(*effective_top.get(x).portable()?))
                            .saturating_add(
                                256_i32
                                    .saturating_sub(weight)
                                    .saturating_mul(i32::from(*bottom)),
                            )
                            .saturating_add(128)
                            >> 8;
                        u16::try_from(value.clamp(0, 255)).map_err(|_| PortableUnavailable)?
                    }
                    LosslessPredictor::SmoothHorizontal => {
                        let (weights, right) = smooth_horizontal.as_ref().portable()?;
                        let weight = i32::from(*weights.get(x).portable()?);
                        let value = weight
                            .saturating_mul(i32::from(*effective_left.get(y).portable()?))
                            .saturating_add(
                                256_i32
                                    .saturating_sub(weight)
                                    .saturating_mul(i32::from(*right)),
                            )
                            .saturating_add(128)
                            >> 8;
                        u16::try_from(value.clamp(0, 255)).map_err(|_| PortableUnavailable)?
                    }
                    LosslessPredictor::Smooth => {
                        let (horizontal_weights, vertical_weights) = smooth.as_ref().portable()?;
                        let vertical_weight = i32::from(*vertical_weights.get(y).portable()?);
                        let horizontal_weight = i32::from(*horizontal_weights.get(x).portable()?);
                        let right = effective_top
                            .get(width.saturating_sub(1))
                            .copied()
                            .unwrap_or(127);
                        let bottom = effective_left.last().copied().unwrap_or(129);
                        let value = vertical_weight
                            .saturating_mul(i32::from(*effective_top.get(x).portable()?))
                            .saturating_add(
                                256_i32
                                    .saturating_sub(vertical_weight)
                                    .saturating_mul(i32::from(bottom)),
                            )
                            .saturating_add(
                                horizontal_weight
                                    .saturating_mul(i32::from(*effective_left.get(y).portable()?)),
                            )
                            .saturating_add(
                                256_i32
                                    .saturating_sub(horizontal_weight)
                                    .saturating_mul(i32::from(right)),
                            )
                            .saturating_add(256)
                            >> 9;
                        u16::try_from(value.clamp(0, 255)).map_err(|_| PortableUnavailable)?
                    }
                    LosslessPredictor::Paeth => paeth_predictor(
                        top_edge[local_column],
                        left_edge[local_row],
                        prediction_top_left,
                    ),
                }
            };
            let reconstructed = i32::from(prediction).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed lossless sample is explicitly clamped to eight-bit range"
            )]
            let reconstructed = reconstructed as u16;
            *samples
                .get_mut(y.saturating_mul(coded_width).saturating_add(x))
                .portable()? = reconstructed;
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the leaf boundary keeps syntax, geometry, neighbors, and tools explicit"
)]
fn reconstruct_lossless444_leaf(
    syntax: BlockSyntax,
    geometry: Lossless444BlockGeometry,
    above_left: Option<&Lossless444Leaf>,
    above: [Option<&Lossless444Leaf>; 8],
    above_right: Option<&Lossless444Leaf>,
    left: [Option<&Lossless444Leaf>; 8],
    left_below: [Option<&Lossless444Leaf>; 8],
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        coefficients,
        transform_grid,
        chroma_sampling: ChromaSampling::Full,
        reconstruction: ReconstructionPolicy::LosslessWht4x4,
        ..
    } = syntax
    else {
        return Err(PortableUnavailable);
    };
    let geometry = Lossless444BlockGeometry {
        transform_grid,
        ..geometry
    };
    let luma_edges = lossless444_external_edges(above, above_right, geometry, 0, true)?;
    let luma_left = lossless444_external_edges(left, None, geometry, 0, false)?;
    let u_edges = lossless444_external_edges(above, above_right, geometry, 1, true)?;
    let u_left = lossless444_external_edges(left, None, geometry, 1, false)?;
    let v_edges = lossless444_external_edges(above, above_right, geometry, 2, true)?;
    let v_left = lossless444_external_edges(left, None, geometry, 2, false)?;
    let luma_below_left = lossless444_external_below_left_edge(left_below, geometry, 0)?;
    let u_below_left = lossless444_external_below_left_edge(left_below, geometry, 1)?;
    let v_below_left = lossless444_external_below_left_edge(left_below, geometry, 2)?;
    let luma = reconstruct_lossless_plane(
        geometry,
        lossless_luma_predictor(luma_predictor),
        luma_angle,
        coefficients[0],
        &luma_edges.0,
        &luma_left.0,
        luma_edges.1,
        luma_left.1,
        lossless444_top_left(above_left, geometry, 0),
        &luma_below_left,
        enable_intra_edge_filter,
        filter_intra_mode,
    )?;
    let u = reconstruct_lossless_plane(
        geometry,
        lossless_chroma_predictor(chroma_predictor),
        chroma_angle,
        coefficients[1],
        &u_edges.0,
        &u_left.0,
        u_edges.1,
        u_left.1,
        lossless444_top_left(above_left, geometry, 1),
        &u_below_left,
        enable_intra_edge_filter,
        None,
    )?;
    let v = reconstruct_lossless_plane(
        geometry,
        lossless_chroma_predictor(chroma_predictor),
        chroma_angle,
        coefficients[2],
        &v_edges.0,
        &v_left.0,
        v_edges.1,
        v_left.1,
        lossless444_top_left(above_left, geometry, 2),
        &v_below_left,
        enable_intra_edge_filter,
        None,
    )?;
    let planes = [luma, u, v];
    Ok(ClosedLeaf {
        luma_predictor,
        planes,
    })
}

fn neighbor_edge_sample(plane: &ReconstructedPlane, orientation: SplitOrientation) -> u16 {
    let index = match orientation {
        SplitOrientation::Horizontal => 7,
        SplitOrientation::Vertical => 56,
    };
    plane.samples.get(index).copied().unwrap_or(128)
}

fn neighbor_predictors(first: &ClosedLeaf, orientation: SplitOrientation) -> [u16; 3] {
    [
        neighbor_edge_sample(&first.planes[0], orientation),
        neighbor_edge_sample(&first.planes[1], orientation),
        neighbor_edge_sample(&first.planes[2], orientation),
    ]
}

fn bottom_edge(plane: &ReconstructedPlane) -> [u16; 8] {
    if plane.samples.len() >= 1024 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(992_usize.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 256 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(240_usize.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 64 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(56_usize.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 16 {
        let edge: [u16; 4] = std::array::from_fn(|index| {
            plane
                .samples
                .get(12_usize.saturating_add(index))
                .copied()
                .unwrap_or(128)
        });
        [
            edge[0], edge[1], edge[2], edge[3], edge[0], edge[1], edge[2], edge[3],
        ]
    } else {
        [128; 8]
    }
}

fn bottom_edge_at<const N: usize>(
    plane: &ReconstructedPlane,
    row_width: u32,
    x_offset: u32,
) -> [u16; N] {
    let row_width = usize::try_from(row_width).unwrap_or(0);
    let x_offset = usize::try_from(x_offset).unwrap_or(0);
    let row_start = row_width
        .saturating_mul(
            plane
                .samples
                .len()
                .checked_div(row_width)
                .unwrap_or(0)
                .saturating_sub(1),
        )
        .saturating_add(x_offset);
    std::array::from_fn(|index| {
        plane
            .samples
            .get(row_start.saturating_add(index))
            .copied()
            .unwrap_or(128)
    })
}

fn combined_bottom_edge<const N: usize>(
    first: &ReconstructedPlane,
    first_width: u32,
    first_offset: u32,
    second: &ReconstructedPlane,
    second_width: u32,
    second_offset: u32,
) -> [u16; N] {
    let first_available = usize::try_from(
        first_width
            .saturating_sub(first_offset)
            .min(u32::try_from(N).unwrap_or(0)),
    )
    .unwrap_or(0);
    std::array::from_fn(|index| {
        if index < first_available {
            bottom_edge_at::<1>(
                first,
                first_width,
                first_offset.saturating_add(u32::try_from(index).unwrap_or(0)),
            )[0]
        } else {
            bottom_edge_at::<1>(
                second,
                second_width,
                second_offset.saturating_add(
                    u32::try_from(index.saturating_sub(first_available)).unwrap_or(0),
                ),
            )[0]
        }
    })
}

fn bottom_sample_at(plane: &ReconstructedPlane, row_width: u32, x_offset: u32) -> u16 {
    bottom_edge_at::<1>(plane, row_width, x_offset)[0]
}

fn bottom_edge_16(plane: &ReconstructedPlane) -> [u16; 16] {
    if plane.samples.len() >= 256 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(240_usize.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 64 {
        let edge = bottom_edge(plane);
        std::array::from_fn(|index| edge[index % 8])
    } else if plane.samples.len() >= 16 {
        let edge = bottom_edge_4(plane);
        std::array::from_fn(|index| edge[index % 4])
    } else {
        [128; 16]
    }
}

fn bottom_edge_32(plane: &ReconstructedPlane) -> [u16; 32] {
    if plane.samples.len() >= 512 {
        let start = plane.samples.len().saturating_sub(32);
        std::array::from_fn(|index| {
            plane
                .samples
                .get(start.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else {
        let edge = bottom_edge_16(plane);
        std::array::from_fn(|index| edge[index % 16])
    }
}

fn bottom_edge_64(plane: &ReconstructedPlane) -> [u16; 64] {
    if plane.samples.len() >= 1024 {
        let start = plane.samples.len().saturating_sub(64);
        std::array::from_fn(|index| {
            plane
                .samples
                .get(start.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else {
        let edge = bottom_edge_32(plane);
        std::array::from_fn(|index| edge[index % 32])
    }
}

fn bottom_edge_16x8(plane: &ReconstructedPlane) -> [u16; 16] {
    if plane.samples.len() >= 128 {
        let start = plane.samples.len().saturating_sub(16);
        std::array::from_fn(|index| {
            plane
                .samples
                .get(start.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else {
        bottom_edge_16(plane)
    }
}

fn bottom_edge_32x8(plane: &ReconstructedPlane) -> [u16; 32] {
    if plane.samples.len() >= 256 {
        let start = plane.samples.len().saturating_sub(32);
        std::array::from_fn(|index| {
            plane
                .samples
                .get(start.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else {
        let edge = bottom_edge_16x8(plane);
        std::array::from_fn(|index| edge[index % 16])
    }
}

fn bottom_edge_16x64(plane: &ReconstructedPlane) -> [u16; 16] {
    if plane.samples.len() >= 1024 {
        let start = plane.samples.len().saturating_sub(16);
        std::array::from_fn(|index| {
            plane
                .samples
                .get(start.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else {
        bottom_edge_16(plane)
    }
}

fn right_edge_16x64(plane: &ReconstructedPlane) -> [u16; 64] {
    if plane.samples.len() >= 1024 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(16).saturating_add(15))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 256 {
        let edge = right_edge_16(plane);
        std::array::from_fn(|index| edge[index % 16])
    } else {
        let edge = right_edge(plane);
        std::array::from_fn(|index| edge[index % 8])
    }
}

