fn right_edge_4_for_16x4(plane: &ReconstructedPlane) -> [u16; 4] {
    if plane.samples.len() >= 256 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(
                    index
                        .saturating_add(12)
                        .saturating_mul(16)
                        .saturating_add(15),
                )
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 64 {
        let edge = right_edge(plane);
        [edge[0], edge[1], edge[2], edge[3]]
    } else {
        right_edge_4(plane)
    }
}

fn bottom_edge_8_for_16x4_chroma(plane: &ReconstructedPlane) -> [u16; 8] {
    if plane.samples.len() >= 64 {
        bottom_edge(plane)
    } else if plane.samples.len() >= 32 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(24_usize.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else {
        let edge = bottom_edge_4(plane);
        [
            edge[0], edge[1], edge[2], edge[3], edge[0], edge[1], edge[2], edge[3],
        ]
    }
}

fn right_edge_4_for_8x4_chroma(plane: &ReconstructedPlane) -> [u16; 4] {
    if plane.samples.len() >= 64 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(8).saturating_add(7))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 32 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(8).saturating_add(7))
                .copied()
                .unwrap_or(128)
        })
    } else {
        right_edge_4(plane)
    }
}

fn right_edge(plane: &ReconstructedPlane) -> [u16; 8] {
    if plane.samples.len() >= 1024 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(32).saturating_add(31))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 256 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(16).saturating_add(15))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 64 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(8).saturating_add(7))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 16 {
        let edge: [u16; 4] = std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(4).saturating_add(3))
                .copied()
                .unwrap_or(128)
        });
        [
            edge[0], edge[1], edge[2], edge[3], edge[0], edge[1], edge[2], edge[3],
        ]
    } else {
        [128; 8]
    }
}

pub(super) fn right_edge_at<const N: usize>(
    plane: &ReconstructedPlane,
    width: u32,
    height: u32,
    row_offset: u32,
) -> [u16; N] {
    let width = usize::try_from(width).unwrap_or(0);
    let height = usize::try_from(height).unwrap_or(0);
    if width == 0 || height == 0 {
        return [128; N];
    }
    let row_offset = usize::try_from(row_offset)
        .unwrap_or(0)
        .min(height.saturating_sub(1));
    std::array::from_fn(|index| {
        let row = row_offset
            .saturating_add(index)
            .min(height.saturating_sub(1));
        plane
            .samples
            .get(
                row.saturating_mul(width)
                    .saturating_add(width.saturating_sub(1)),
            )
            .copied()
            .unwrap_or(128)
    })
}

fn right_edge_16(plane: &ReconstructedPlane) -> [u16; 16] {
    if plane.samples.len() >= 1024 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(32).saturating_add(31))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 256 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(16).saturating_add(15))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 64 {
        let edge = right_edge(plane);
        std::array::from_fn(|index| edge[index % 8])
    } else if plane.samples.len() >= 32 {
        let edge = right_edge_for_4x8(plane);
        std::array::from_fn(|index| edge[index % 8])
    } else if plane.samples.len() >= 16 {
        let edge = right_edge_4(plane);
        std::array::from_fn(|index| edge[index % 4])
    } else {
        [128; 16]
    }
}

fn adjacent_edge(plane: &ReconstructedPlane, orientation: SplitOrientation) -> [u16; 8] {
    match orientation {
        SplitOrientation::Horizontal => right_edge(plane),
        SplitOrientation::Vertical => bottom_edge(plane),
    }
}

fn bottom_edge_4(plane: &ReconstructedPlane) -> [u16; 4] {
    if plane.samples.len() >= 16 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(12_usize.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else {
        [128; 4]
    }
}

fn bottom_edge_4_for_4x8(plane: &ReconstructedPlane) -> [u16; 4] {
    if plane.samples.len() >= 64 {
        let edge = bottom_edge(plane);
        [edge[0], edge[1], edge[2], edge[3]]
    } else if plane.samples.len() >= 32 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(28_usize.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else {
        bottom_edge_4(plane)
    }
}

fn bottom_edge_4_padded(plane: &ReconstructedPlane) -> [u16; 4] {
    if plane.samples.len() >= 16 {
        bottom_edge_4(plane)
    } else if plane.samples.len() >= 8 {
        let right = plane.samples.get(5).copied().unwrap_or(128);
        [
            plane.samples.get(4).copied().unwrap_or(128),
            right,
            right,
            right,
        ]
    } else if plane.samples.len() >= 4 {
        let right = plane.samples.get(3).copied().unwrap_or(128);
        [
            plane.samples.get(2).copied().unwrap_or(128),
            right,
            right,
            right,
        ]
    } else {
        [128; 4]
    }
}

fn bottom_edge_for_square4(plane: &ReconstructedPlane) -> [u16; 4] {
    if plane.samples.len() >= 64 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(56_usize.saturating_add(index))
                .copied()
                .unwrap_or(128)
        })
    } else {
        bottom_edge_4(plane)
    }
}

fn right_edge_4(plane: &ReconstructedPlane) -> [u16; 4] {
    if plane.samples.len() >= 16 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(4).saturating_add(3))
                .copied()
                .unwrap_or(128)
        })
    } else {
        [128; 4]
    }
}

fn right_edge_4_padded(plane: &ReconstructedPlane) -> [u16; 4] {
    if plane.samples.len() >= 16 {
        right_edge_4(plane)
    } else if plane.samples.len() >= 8 {
        [
            plane.samples.get(1).copied().unwrap_or(128),
            plane.samples.get(3).copied().unwrap_or(128),
            plane.samples.get(5).copied().unwrap_or(128),
            plane.samples.get(7).copied().unwrap_or(128),
        ]
    } else if plane.samples.len() >= 4 {
        // A visible 2x2 4:2:0 neighbour has already been cropped from its
        // coded 4x4 transform. AV1 extends the final available row/column
        // when preparing an edge for the next coded block.
        let right_top = plane.samples.get(1).copied().unwrap_or(128);
        let right_bottom = plane.samples.get(3).copied().unwrap_or(right_top);
        [right_top, right_bottom, right_bottom, right_bottom]
    } else {
        [128; 4]
    }
}

fn right_edge_for_4x8(plane: &ReconstructedPlane) -> [u16; 8] {
    if plane.samples.len() >= 32 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(4).saturating_add(3))
                .copied()
                .unwrap_or(128)
        })
    } else if plane.samples.len() >= 16 {
        let edge = right_edge_4(plane);
        [
            edge[0], edge[1], edge[2], edge[3], edge[0], edge[1], edge[2], edge[3],
        ]
    } else {
        [128; 8]
    }
}

fn right_edge_for_square4(plane: &ReconstructedPlane) -> [u16; 4] {
    if plane.samples.len() >= 64 {
        std::array::from_fn(|index| {
            plane
                .samples
                .get(index.saturating_mul(8).saturating_add(7))
                .copied()
                .unwrap_or(128)
        })
    } else {
        right_edge_4(plane)
    }
}

fn bottom_right_for_square4(plane: &ReconstructedPlane) -> u16 {
    plane
        .samples
        .get(if plane.samples.len() >= 64 { 63 } else { 15 })
        .copied()
        .unwrap_or(128)
}

fn bottom_right_for_4x4_padded(plane: &ReconstructedPlane) -> u16 {
    let index = match plane.samples.len() {
        64.. => 63,
        16.. => 15,
        8.. => 7,
        4.. => 3,
        _ => return 128,
    };
    plane.samples.get(index).copied().unwrap_or(128)
}

fn one_sided_dc_predictor(edge: [u16; 8]) -> u16 {
    let sum = edge
        .iter()
        .fold(0_u32, |sum, sample| sum.saturating_add(u32::from(*sample)));
    u16::try_from(sum.saturating_add(4).div_euclid(8)).unwrap_or(128)
}

fn one_sided_dc_predictor_16(edge: [u16; 16]) -> u16 {
    let sum = edge
        .iter()
        .fold(0_u32, |sum, sample| sum.saturating_add(u32::from(*sample)));
    u16::try_from(sum.saturating_add(8).div_euclid(16)).unwrap_or(128)
}

fn one_sided_dc_predictor_32(edge: [u16; 32]) -> u16 {
    let sum = edge
        .iter()
        .fold(0_u32, |sum, sample| sum.saturating_add(u32::from(*sample)));
    u16::try_from(sum.saturating_add(16).div_euclid(32)).unwrap_or(128)
}

fn dc_predictor_16(top: [u16; 16], left: [u16; 16]) -> u16 {
    let sum = top
        .iter()
        .chain(&left)
        .fold(0_u32, |sum, sample| sum.saturating_add(u32::from(*sample)));
    u16::try_from(sum.saturating_add(16).div_euclid(32)).unwrap_or(128)
}

fn one_sided_dc_predictor_8(edge: [u16; 8]) -> u16 {
    let sum = edge
        .iter()
        .fold(0_u32, |sum, sample| sum.saturating_add(u32::from(*sample)));
    u16::try_from(sum.saturating_add(4).div_euclid(8)).unwrap_or(128)
}

fn dc_predictor_8(top: [u16; 8], left: [u16; 8]) -> u16 {
    let sum = top
        .iter()
        .chain(&left)
        .fold(0_u32, |sum, sample| sum.saturating_add(u32::from(*sample)));
    u16::try_from(sum.saturating_add(8).div_euclid(16)).unwrap_or(128)
}

fn dc_predictor_8_with_availability(
    top: [u16; 8],
    left: [u16; 8],
    has_top: bool,
    has_left: bool,
) -> u16 {
    match (has_top, has_left) {
        (true, true) => dc_predictor_8(top, left),
        (true, false) => one_sided_dc_predictor_8(top),
        (false, true) => one_sided_dc_predictor_8(left),
        (false, false) => 128,
    }
}

fn one_sided_dc_predictor_4(edge: [u16; 4]) -> u16 {
    let sum = edge
        .iter()
        .fold(0_u32, |sum, sample| sum.saturating_add(u32::from(*sample)));
    u16::try_from(sum.saturating_add(2).div_euclid(4)).unwrap_or(128)
}

fn dc_predictor_4_with_availability(
    top: [u16; 4],
    left: [u16; 4],
    has_top: bool,
    has_left: bool,
) -> u16 {
    match (has_top, has_left) {
        (true, true) => dc_predictor(top, left),
        (true, false) => one_sided_dc_predictor_4(top),
        (false, true) => one_sided_dc_predictor_4(left),
        (false, false) => 128,
    }
}

fn reconstruct_directional_plane(
    edge: [u16; 8],
    orientation: SplitOrientation,
) -> ReconstructedPlane {
    let mut samples = Vec::with_capacity(64);
    match orientation {
        SplitOrientation::Horizontal => {
            for sample in edge {
                samples.extend_from_slice(&[sample; 8]);
            }
        }
        SplitOrientation::Vertical => {
            for _ in 0..8 {
                samples.extend_from_slice(&edge);
            }
        }
    }
    ReconstructedPlane { samples }
}

fn dc_predictor(top: [u16; 4], left: [u16; 4]) -> u16 {
    let sum = top
        .iter()
        .chain(&left)
        .fold(0_u32, |sum, sample| sum.saturating_add(u32::from(*sample)));
    u16::try_from(sum.saturating_add(4).div_euclid(8)).unwrap_or(128)
}

fn reconstruct_dc_transform(
    top: [u16; 4],
    left: [u16; 4],
    coefficients: TransformCoefficients,
) -> [u16; 16] {
    reconstruct_transform(dc_predictor(top, left), coefficients)
}

fn reconstruct_boundary_plane(
    above: &ReconstructedPlane,
    left: &ReconstructedPlane,
    coefficients: PlaneCoefficients,
) -> ReconstructedPlane {
    let top = bottom_edge(above);
    let left = right_edge(left);
    let top_left = reconstruct_dc_transform(
        [top[0], top[1], top[2], top[3]],
        [left[0], left[1], left[2], left[3]],
        coefficients[0],
    );
    let top_right = reconstruct_dc_transform(
        [top[4], top[5], top[6], top[7]],
        [top_left[3], top_left[7], top_left[11], top_left[15]],
        coefficients[1],
    );
    let bottom_left = reconstruct_dc_transform(
        [top_left[12], top_left[13], top_left[14], top_left[15]],
        [left[4], left[5], left[6], left[7]],
        coefficients[2],
    );
    let bottom_right = reconstruct_dc_transform(
        [top_right[12], top_right[13], top_right[14], top_right[15]],
        [
            bottom_left[3],
            bottom_left[7],
            bottom_left[11],
            bottom_left[15],
        ],
        coefficients[3],
    );
    let mut samples = Vec::with_capacity(64);
    for (first, second) in top_left
        .as_chunks::<4>()
        .0
        .iter()
        .zip(top_right.as_chunks::<4>().0.iter())
    {
        samples.extend_from_slice(first);
        samples.extend_from_slice(second);
    }
    for (first, second) in bottom_left
        .as_chunks::<4>()
        .0
        .iter()
        .zip(bottom_right.as_chunks::<4>().0.iter())
    {
        samples.extend_from_slice(first);
        samples.extend_from_slice(second);
    }
    ReconstructedPlane { samples }
}

fn reconstruct_subsampled_boundary_plane(
    above: &ReconstructedPlane,
    left: &ReconstructedPlane,
    coefficients: PlaneCoefficients,
) -> ReconstructedPlane {
    let transform =
        reconstruct_dc_transform(bottom_edge_4(above), right_edge_4(left), coefficients[0]);
    ReconstructedPlane {
        samples: transform.to_vec(),
    }
}

fn reconstruct_following_square_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
    orientation: SplitOrientation,
) -> ClosedLeaf {
    let BlockSyntax {
        luma_predictor,
        luma_angle: _,
        filter_intra_mode: _,
        chroma_predictor: _,
        chroma_angle: _,
        coefficients,
        lossy_luma_coefficients: _,
        lossy_luma_4x8_coefficients: _,
        lossy_luma_4x8_transform: _,
        lossy_luma_16x16_coefficients: _,
        lossy_luma_16x16_transform: _,
        lossy_luma_32x32_coefficients: _,
        lossy_luma_16x32_coefficients: _,
        lossy_luma_16x32_transform: _,
        lossy_luma_64x64_coefficients: _,
        lossy_luma_16x64_coefficients: _,
        lossy_luma_32x16_coefficients: _,
        lossy_luma_32x8_coefficients: _,
        lossy_luma_64x16_coefficients: _,
        lossy_luma_8x32_coefficients: _,
        lossy_luma_16x8_coefficients: _,
        lossy_luma_16x8_transform: _,
        lossy_luma_transform: _,
        lossy_luma_residual_context: _,
        lossy_luma_4x4_split: _,
        lossy_luma_8x8_split: _,
        lossy_luma_8x8_grid_split: _,
        lossy_luma_16x16_split: _,
        lossy_luma_16x16_horizontal_split: _,
        lossy_luma_16x16_vertical_split: _,
        lossy_luma_16x4_transform: _,
        lossy_luma_rect_coefficients: _,
        lossy_luma_rect_transform: _,
        lossy_chroma_coefficients: _,
        lossy_chroma_8x8_coefficients: _,
        lossy_chroma_8x4_coefficients: _,
        lossy_chroma_16x16_coefficients: _,
        lossy_chroma_32x32_coefficients: _,
        lossy_chroma_8x32_coefficients: _,
        lossy_chroma_8x16_coefficients: _,
        lossy_chroma_32x8_coefficients: _,
        lossy_chroma_4x16_coefficients: _,
        lossy_chroma_16x4_coefficients: _,
        lossy_chroma_16x8_coefficients: _,
        lossy_chroma_4x4_splits: _,
        lossy_chroma_residual_contexts: _,
        lossy_quantization: _,
        transform_grid,
        chroma_sampling: _,
        palette: _,
        reconstruction: _,
    } = syntax;
    let edges = neighbor
        .planes
        .each_ref()
        .map(|plane| adjacent_edge(plane, orientation));
    let luma = if matches!(luma_predictor, LumaPredictor::Dc) {
        reconstruct_coded_plane(
            one_sided_dc_predictor(edges[0]),
            coefficients[0],
            transform_grid,
            ChromaSampling::Full,
        )
    } else {
        reconstruct_directional_plane(edges[0], orientation)
    };
    let planes = [
        luma,
        reconstruct_coded_plane(
            one_sided_dc_predictor(edges[1]),
            coefficients[1],
            transform_grid,
            ChromaSampling::Full,
        ),
        reconstruct_coded_plane(
            one_sided_dc_predictor(edges[2]),
            coefficients[2],
            transform_grid,
            ChromaSampling::Full,
        ),
    ];
    ClosedLeaf {
        luma_predictor,
        planes,
    }
}

fn reconstruct_following_420_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
    orientation: SplitOrientation,
) -> ClosedLeaf {
    let luma_edge = adjacent_edge(&neighbor.planes[0], orientation);
    let chroma_edges = [1_usize, 2].map(|plane| match orientation {
        SplitOrientation::Horizontal => right_edge_4_for_8x4_chroma(&neighbor.planes[plane]),
        SplitOrientation::Vertical => bottom_edge_4_for_4x8(&neighbor.planes[plane]),
    });
    let planes = [
        reconstruct_coded_plane(
            one_sided_dc_predictor(luma_edge),
            syntax.coefficients[0],
            syntax.transform_grid,
            ChromaSampling::Full,
        ),
        reconstruct_coded_plane(
            one_sided_dc_predictor_4(chroma_edges[0]),
            syntax.coefficients[1],
            syntax.transform_grid,
            ChromaSampling::Subsampled420,
        ),
        reconstruct_coded_plane(
            one_sided_dc_predictor_4(chroma_edges[1]),
            syntax.coefficients[2],
            syntax.transform_grid,
            ChromaSampling::Subsampled420,
        ),
    ];
    ClosedLeaf {
        luma_predictor: syntax.luma_predictor,
        planes,
    }
}

fn reconstruct_following_lossy_420_16x16_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
    top_neighbor: Option<&ClosedLeaf>,
    top_neighbor_is_distinct: bool,
    luma_left_edge_16: Option<[u16; 16]>,
    chroma_left_edges_8: [Option<[u16; 8]>; 2],
) -> PortableResult<ClosedLeaf> {
    if let Some(leaf) = reconstruct_palette_square16_leaf(syntax) {
        return Ok(leaf);
    }
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_16x16_coefficients,
        lossy_luma_16x16_transform,
        lossy_luma_8x8_split,
        lossy_chroma_8x8_coefficients,
        lossy_chroma_16x16_coefficients,
        lossy_chroma_4x4_splits,
        chroma_sampling,
        palette,
        ..
    } = syntax;
    let luma_left = luma_left_edge_16.unwrap_or_else(|| {
        if top_neighbor_is_distinct {
            let top = top_neighbor.map_or([128; 8], |neighbor| right_edge(&neighbor.planes[0]));
            let bottom = right_edge(&neighbor.planes[0]);
            [
                top[0], top[1], top[2], top[3], top[4], top[5], top[6], top[7], bottom[0],
                bottom[1], bottom[2], bottom[3], bottom[4], bottom[5], bottom[6], bottom[7],
            ]
        } else {
            right_edge_16(&neighbor.planes[0])
        }
    });
    // With no above neighbor but an existing left neighbor, AV1 prepares the
    // top edge by repeating the block's first left sample. This is distinct
    // from the 128 midpoint used when both edges are absent.
    let luma_top = [luma_left[0]; 16];
    let luma = if palette.y.is_present() {
        let prediction =
            palette_prediction(palette.y, palette.y_indices).ok_or(PortableUnavailable)?;
        let prediction = std::array::from_fn(|index| prediction[index]);
        lossy_luma_8x8_split.map_or_else(
            || {
                reconstruct_lossy_luma_16x16_from_prediction(
                    prediction,
                    lossy_luma_16x16_coefficients,
                    lossy_luma_16x16_transform,
                )
            },
            |split| reconstruct_lossy_luma_16x16_split_from_prediction(prediction, split),
        )
    } else if let Some(split) = lossy_luma_8x8_split {
        reconstruct_lossy_luma_16x16_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_left[0],
            false,
            true,
            split,
        )?
    } else {
        match luma_predictor {
            LumaPredictor::Dc => reconstruct_lossy_luma_16x16(
                one_sided_dc_predictor_16(luma_left),
                lossy_luma_16x16_coefficients,
                lossy_luma_16x16_transform,
            ),
            LumaPredictor::Smooth | LumaPredictor::SmoothHorizontal => {
                reconstruct_lossy_luma_16x16_smooth_horizontal(
                    luma_left,
                    luma_left[0],
                    lossy_luma_16x16_coefficients,
                    lossy_luma_16x16_transform,
                )
            }
            LumaPredictor::Horizontal => reconstruct_lossy_luma_16x16_from_prediction(
                std::array::from_fn(|index| luma_left[index / 16]),
                lossy_luma_16x16_coefficients,
                lossy_luma_16x16_transform,
            ),
            _ => return Err(PortableUnavailable),
        }
    };
    let luma_for_chroma = luma.clone();

    let chroma_left = |plane: usize| {
        chroma_left_edges_8[plane - 1].unwrap_or_else(|| {
            if top_neighbor_is_distinct {
                let top =
                    top_neighbor.map_or([128; 4], |neighbor| right_edge_4(&neighbor.planes[plane]));
                let bottom = right_edge_4(&neighbor.planes[plane]);
                [
                    top[0], top[1], top[2], top[3], bottom[0], bottom[1], bottom[2], bottom[3],
                ]
            } else {
                let edge = right_edge_4(&neighbor.planes[plane]);
                [
                    edge[0], edge[1], edge[2], edge[3], edge[0], edge[1], edge[2], edge[3],
                ]
            }
        })
    };
    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        if matches!(chroma_sampling, ChromaSampling::Full) {
            let left = right_edge_16(&neighbor.planes[plane]);
            let top = top_neighbor.map_or([left[0]; 16], |neighbor| {
                bottom_edge_16(&neighbor.planes[plane])
            });
            return match chroma_predictor {
                ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                    let alpha = if plane == 1 { alpha_u } else { alpha_v };
                    reconstruct_lossy_full_16x16_cfl(
                        &luma_for_chroma,
                        if top_neighbor.is_some() {
                            dc_predictor_16(top, left)
                        } else {
                            one_sided_dc_predictor_16(top)
                        },
                        alpha,
                        lossy_chroma_16x16_coefficients[plane - 1],
                    )
                }
                _ => reconstruct_lossy_full_16x16_chroma(
                    chroma_predictor,
                    top,
                    left,
                    top[0],
                    true,
                    lossy_chroma_16x16_coefficients[plane - 1],
                ),
            };
        }
        let left = chroma_left(plane);
        let chroma_top = [left[0]; 8];
        let chroma_dc = one_sided_dc_predictor_8(left);
        let coefficients = lossy_chroma_8x8_coefficients[plane - 1];

        let palette_plane = if plane == 1 { palette.u } else { palette.v };
        if palette_plane.is_present() {
            let prediction =
                palette_prediction(palette_plane, palette.uv_indices).ok_or(PortableUnavailable)?;
            let prediction = std::array::from_fn(|index| prediction[index]);
            let transform = chroma_transform_kind(chroma_predictor);
            return Ok(reconstruct_lossy_luma_8x8_from_prediction(
                prediction,
                coefficients,
                transform,
            ));
        }

        if let Some(split) = lossy_chroma_4x4_splits[plane - 1] {
            return reconstruct_lossy_chroma_8x8_split(
                chroma_predictor,
                chroma_angle,
                chroma_top,
                left,
                left[0],
                true,
                split,
                &luma,
            );
        }
        let transform = chroma_transform_kind(chroma_predictor);
        match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_chroma_8x8_cfl(&luma, chroma_dc, alpha, coefficients)
            }
            ChromaPredictor::Dc => Ok(reconstruct_lossy_chroma_8x8(
                chroma_dc,
                coefficients,
                transform,
            )),
            ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_8x8_vertical(
                chroma_top,
                coefficients,
                transform,
            )),
            ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_8x8_horizontal(
                left,
                coefficients,
                transform,
            )),
            ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
                reconstruct_lossy_luma_8x8_diagonal_z1(
                    chroma_top,
                    128,
                    chroma_angle.ok_or(PortableUnavailable)?,
                    coefficients,
                    transform,
                )
            }
            ChromaPredictor::DiagonalDownRight
            | ChromaPredictor::Diagonal113
            | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                [128; 16],
                left,
                128,
                chroma_angle.ok_or(PortableUnavailable)?,
                false,
                false,
                coefficients,
                transform,
            ),
            ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                left,
                128,
                chroma_angle.ok_or(PortableUnavailable)?,
                false,
                coefficients,
                transform,
            ),
            ChromaPredictor::Smooth => Ok(reconstruct_lossy_luma_8x8_smooth(
                chroma_top,
                chroma_top[7],
                left,
                coefficients,
                transform,
            )),
            ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_luma_8x8_smooth_vertical(
                chroma_top,
                left[7],
                coefficients,
                transform,
            )),
            ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_luma_8x8_smooth_horizontal(
                left,
                chroma_top[7],
                coefficients,
                transform,
            )),
            ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_8x8_paeth(
                chroma_top,
                left,
                128,
                coefficients,
                transform,
            )),
        }
    };
    let chroma_u = chroma(1)?;
    let chroma_v = chroma(2)?;
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_420_8x4_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        chroma_predictor,
        chroma_angle,
        lossy_luma_4x8_coefficients,
        lossy_luma_4x8_transform,
        lossy_chroma_coefficients,
        ..
    } = syntax;
    let luma_edge = right_edge(&neighbor.planes[0]);
    let luma_left = [luma_edge[0], luma_edge[1], luma_edge[2], luma_edge[3]];
    let luma = match luma_predictor {
        LumaPredictor::Dc => reconstruct_lossy_luma_8x4(
            one_sided_dc_predictor_4(luma_left),
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        _ => return Err(PortableUnavailable),
    };
    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let edge = right_edge_4(&neighbor.planes[plane]);
        let coefficients = lossy_chroma_coefficients[plane.saturating_sub(1)];
        match chroma_predictor {
            ChromaPredictor::Dc => Ok(reconstruct_lossy_chroma_4x4(
                one_sided_dc_predictor_4(edge),
                coefficients,
                LossyTransformKind::DctDct,
            )),
            ChromaPredictor::Vertical => Ok(reconstruct_lossy_chroma_4x4_vertical(
                [128; 4],
                coefficients,
                chroma_transform_kind(chroma_predictor),
            )),
            ChromaPredictor::Horizontal => Ok(reconstruct_lossy_chroma_4x4_horizontal(
                edge,
                coefficients,
                LossyTransformKind::DctAdst,
            )),
            ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
                reconstruct_lossy_4x4_diagonal_z1(
                    [128; 4],
                    128,
                    chroma_angle.ok_or(PortableUnavailable)?,
                    coefficients,
                    chroma_transform_kind(chroma_predictor),
                )
            }
            ChromaPredictor::DiagonalDownRight
            | ChromaPredictor::Diagonal113
            | ChromaPredictor::Diagonal157
            | ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal(
                [128; 8],
                edge,
                chroma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                chroma_transform_kind(chroma_predictor),
            ),
            ChromaPredictor::Paeth => Ok(reconstruct_lossy_4x4_paeth(
                [128; 4],
                edge,
                128,
                coefficients,
                LossyTransformKind::DctDct,
            )),
            _ => Err(PortableUnavailable),
        }
    };
    let chroma_u = chroma(1)?;
    let chroma_v = chroma(2)?;
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_full_8x4_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        lossy_luma_4x8_coefficients,
        lossy_luma_4x8_transform,
        lossy_chroma_8x4_coefficients,
        ..
    } = syntax;
    let luma_edge = right_edge(&neighbor.planes[0]);
    let luma_left = [luma_edge[0], luma_edge[1], luma_edge[2], luma_edge[3]];
    let luma = match luma_predictor {
        LumaPredictor::Dc => reconstruct_lossy_luma_8x4(
            one_sided_dc_predictor_4(luma_left),
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Horizontal => reconstruct_lossy_luma_8x4_from_prediction(
            std::array::from_fn(|index| luma_left[index / 8]),
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Vertical => reconstruct_lossy_luma_8x4_from_prediction(
            [luma_left[0]; 32],
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_8x4_diagonal_z1(
                [luma_left[0]; 8],
                luma_left[0],
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_4x8_coefficients,
                lossy_luma_4x8_transform,
            )?
        }
        LumaPredictor::DiagonalDownRight
        | LumaPredictor::Diagonal113
        | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x4_diagonal_z2(
            [luma_left[0]; 8],
            luma_left,
            luma_left[0],
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        )?,
        LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x4_diagonal_z3(
            luma_left,
            luma_left[0],
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        )?,
        LumaPredictor::Smooth => reconstruct_lossy_luma_8x4_smooth(
            [luma_edge[0]; 8],
            luma_edge[0],
            luma_left,
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x4_smooth_vertical(
            [luma_left[0]; 8],
            luma_left[3],
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x4_smooth_horizontal(
            luma_left,
            luma_edge[0],
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Paeth => reconstruct_lossy_luma_8x4_from_prediction(
            std::array::from_fn(|index| {
                paeth_predictor(luma_edge[index % 8], luma_left[index / 8], luma_left[0])
            }),
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
    };
    let luma_for_chroma = luma.clone();
    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let left = right_edge_4_for_8x4_chroma(&neighbor.planes[plane]);
        let top = [left[0]; 8];
        match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_full_8x4_cfl(
                    &luma_for_chroma,
                    top[0],
                    alpha,
                    lossy_chroma_8x4_coefficients[plane - 1],
                )
            }
            _ => reconstruct_lossy_full_8x4_chroma(
                chroma_predictor,
                chroma_angle,
                top,
                left,
                lossy_chroma_8x4_coefficients[plane - 1],
            ),
        }
    };
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

fn reconstruct_following_lossy_420_vertical_8x4_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        chroma_sampling,
        lossy_luma_4x8_coefficients,
        lossy_luma_4x8_transform,
        lossy_chroma_coefficients,
        lossy_chroma_8x4_coefficients,
        ..
    } = syntax;
    let mut luma_top = bottom_edge(&above_left.planes[0]);
    if !std::ptr::eq(above_left, above_right) {
        let right = bottom_edge(&above_right.planes[0]);
        luma_top.copy_from_slice(&right);
    }
    let luma_left = left_neighbor.map_or([luma_top[0]; 4], |neighbor| {
        right_edge_4_for_8x4_chroma(&neighbor.planes[0])
    });
    let luma = match luma_predictor {
        LumaPredictor::Dc => reconstruct_lossy_luma_8x4(
            one_sided_dc_predictor(luma_top),
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Vertical => {
            let prediction: [u16; 32] = std::array::from_fn(|index| luma_top[index % 8]);
            reconstruct_lossy_luma_8x4_from_prediction(
                prediction,
                lossy_luma_4x8_coefficients,
                lossy_luma_4x8_transform,
            )
        }
        LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_8x4_diagonal_z1(
                luma_top,
                luma_top[0],
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_4x8_coefficients,
                lossy_luma_4x8_transform,
            )?
        }
        LumaPredictor::DiagonalDownRight
        | LumaPredictor::Diagonal113
        | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x4_diagonal_z2(
            luma_top,
            luma_left,
            luma_top[0],
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        )?,
        LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x4_diagonal_z3(
            luma_left,
            luma_top[0],
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        )?,
        LumaPredictor::Paeth => reconstruct_lossy_luma_8x4_from_prediction(
            std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 8], luma_top[0], luma_top[0])
            }),
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Smooth => reconstruct_lossy_luma_8x4_smooth(
            luma_top,
            luma_top[7],
            luma_left,
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x4_smooth_horizontal(
            luma_left,
            luma_top[7],
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x4_smooth_vertical(
            luma_top,
            luma_left[3],
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Horizontal => reconstruct_lossy_luma_8x4_from_prediction(
            std::array::from_fn(|index| luma_left[index / 8]),
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
    };

    if matches!(chroma_sampling, ChromaSampling::Full) {
        let luma_for_chroma = luma.clone();
        let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
            let top = if std::ptr::eq(above_left, above_right) {
                bottom_edge(&above_left.planes[plane])
            } else {
                bottom_edge(&above_right.planes[plane])
            };
            let left = left_neighbor.as_ref().map_or([top[0]; 4], |neighbor| {
                right_edge_4_for_8x4_chroma(&neighbor.planes[plane])
            });

            match chroma_predictor {
                ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                    let alpha = if plane == 1 { alpha_u } else { alpha_v };
                    reconstruct_lossy_full_8x4_cfl(
                        &luma_for_chroma,
                        top[0],
                        alpha,
                        lossy_chroma_8x4_coefficients[plane - 1],
                    )
                }
                _ => reconstruct_lossy_full_8x4_chroma(
                    chroma_predictor,
                    chroma_angle,
                    top,
                    left,
                    lossy_chroma_8x4_coefficients[plane - 1],
                ),
            }
        };
        return Ok(ClosedLeaf {
            luma_predictor,
            planes: [luma, chroma(1)?, chroma(2)?],
        });
    }

    let chroma_top_u = bottom_edge_4(&above_left.planes[1]);
    let chroma_top_v = bottom_edge_4(&above_left.planes[2]);
    let chroma = |top: [u16; 4], plane: usize| -> PortableResult<ReconstructedPlane> {
        match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_chroma_4x4_cfl_with_shape(
                    &luma,
                    one_sided_dc_predictor_4(top),
                    alpha,
                    lossy_chroma_coefficients[plane.saturating_sub(1)],
                    8,
                    4,
                )
            }
            ChromaPredictor::Dc => Ok(reconstruct_lossy_chroma_4x4(
                one_sided_dc_predictor_4(top),
                lossy_chroma_coefficients[plane.saturating_sub(1)],
                LossyTransformKind::DctDct,
            )),
            ChromaPredictor::Vertical => Ok(reconstruct_lossy_chroma_4x4_vertical(
                top,
                lossy_chroma_coefficients[plane.saturating_sub(1)],
                chroma_transform_kind(chroma_predictor),
            )),
            ChromaPredictor::Smooth => Ok(reconstruct_lossy_chroma_4x4_smooth(
                top,
                top[3],
                [top[0]; 4],
                lossy_chroma_coefficients[plane.saturating_sub(1)],
            )),
            ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_4x4_smooth_horizontal(
                [top[0]; 4],
                top[3],
                lossy_chroma_coefficients[plane.saturating_sub(1)],
                LossyTransformKind::DctAdst,
            )),
            ChromaPredictor::Paeth => Ok(reconstruct_lossy_4x4_paeth(
                top,
                [top[0]; 4],
                top[0],
                lossy_chroma_coefficients[plane.saturating_sub(1)],
                chroma_transform_kind(chroma_predictor),
            )),
            _ => Err(PortableUnavailable),
        }
    };
    let chroma_u = chroma(chroma_top_u, 1)?;
    let chroma_v = chroma(chroma_top_v, 2)?;
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_full_vertical_16x4_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
    left_width: Option<u32>,
    left_height: Option<u32>,
    left_y_offset: u32,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        lossy_luma_coefficients,
        lossy_luma_16x4_transform,
        lossy_chroma_16x4_coefficients,
        ..
    } = syntax;
    let luma_top = if std::ptr::eq(above_left, above_right) {
        bottom_edge_16(&above_left.planes[0])
    } else {
        let left = bottom_edge(&above_left.planes[0]);
        let right = bottom_edge(&above_right.planes[0]);
        std::array::from_fn(|index| {
            if index < 8 {
                left[index]
            } else {
                right[index - 8]
            }
        })
    };
    let luma_left = left_neighbor.map_or([luma_top[0]; 4], |neighbor| {
        match (left_width, left_height) {
            (Some(width), Some(height)) => {
                right_edge_at::<4>(&neighbor.planes[0], width, height, left_y_offset)
            }
            _ => right_edge_4_for_16x4(&neighbor.planes[0]),
        }
    });
    let luma = match luma_predictor {
        LumaPredictor::Dc => reconstruct_lossy_luma_16x4(
            rectangular_dc_predictor(&luma_top, &luma_left),
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Vertical => reconstruct_lossy_luma_16x4_vertical(
            luma_top,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Horizontal => reconstruct_lossy_luma_16x4_horizontal(
            luma_left,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Smooth => reconstruct_lossy_luma_16x4_smooth(
            luma_top,
            luma_top[15],
            luma_left,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_16x4_smooth_horizontal(
            luma_left,
            luma_top[15],
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Paeth => reconstruct_lossy_luma_16x4_from_prediction(
            std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 16], luma_left[index / 16], luma_top[0])
            }),
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_16x4_diagonal_z1(
                luma_top,
                luma_top[0],
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_coefficients,
                lossy_luma_16x4_transform,
            )?
        }
        LumaPredictor::DiagonalDownRight
        | LumaPredictor::Diagonal113
        | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_16x4_diagonal_z2(
            luma_top,
            luma_left,
            luma_top[0],
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        )?,
        LumaPredictor::Diagonal203 => reconstruct_lossy_luma_16x4_diagonal_z3(
            luma_left,
            luma_top[0],
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        )?,
        _ => return Err(PortableUnavailable),
    };

    let luma_for_chroma = luma.clone();
    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top = if std::ptr::eq(above_left, above_right) {
            bottom_edge_16(&above_left.planes[plane])
        } else {
            let left = bottom_edge(&above_left.planes[plane]);
            let right = bottom_edge(&above_right.planes[plane]);
            std::array::from_fn(|index| {
                if index < 8 {
                    left[index]
                } else {
                    right[index - 8]
                }
            })
        };
        let left = left_neighbor.map_or([top[0]; 4], |neighbor| match (left_width, left_height) {
            (Some(width), Some(height)) => {
                right_edge_at::<4>(&neighbor.planes[plane], width, height, left_y_offset)
            }
            _ => right_edge_4_for_16x4(&neighbor.planes[plane]),
        });
        match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_full_16x4_cfl(
                    &luma_for_chroma,
                    left[0],
                    alpha,
                    lossy_chroma_16x4_coefficients[plane - 1],
                )
            }
            _ => reconstruct_lossy_full_16x4_chroma(
                chroma_predictor,
                chroma_angle,
                top,
                left,
                lossy_chroma_16x4_coefficients[plane - 1],
            ),
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

fn reconstruct_following_lossy_420_vertical_16x4_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    luma_top: [u16; 16],
    luma_left: Option<[u16; 4]>,
    chroma_top: [Option<[u16; 8]>; 2],
    chroma_left: [Option<[u16; 4]>; 2],
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        lossy_luma_coefficients,
        lossy_luma_16x4_transform,
        lossy_chroma_8x4_coefficients,
        ..
    } = syntax;

    let luma_dc = luma_left.map_or_else(
        || one_sided_dc_predictor_16(luma_top),
        |left| rectangular_dc_predictor(&luma_top, &left),
    );
    let luma_left = luma_left.unwrap_or([luma_top[0]; 4]);

    let luma = match luma_predictor {
        LumaPredictor::Dc => {
            reconstruct_lossy_luma_16x4(luma_dc, lossy_luma_coefficients, lossy_luma_16x4_transform)
        }
        LumaPredictor::Vertical => reconstruct_lossy_luma_16x4_vertical(
            luma_top,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Horizontal => reconstruct_lossy_luma_16x4_horizontal(
            luma_left,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Smooth => reconstruct_lossy_luma_16x4_smooth(
            luma_top,
            luma_top[15],
            luma_left,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_16x4_smooth_horizontal(
            luma_left,
            luma_top[15],
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Paeth => reconstruct_lossy_luma_16x4_from_prediction(
            std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 16], luma_left[index / 16], luma_left[0])
            }),
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_16x4_diagonal_z1(
                luma_top,
                luma_top[0],
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_coefficients,
                lossy_luma_16x4_transform,
            )?
        }
        LumaPredictor::Diagonal203 => reconstruct_lossy_luma_16x4_diagonal_z3(
            luma_left,
            luma_top[0],
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        )?,
        _ => return Err(PortableUnavailable),
    };
    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let chroma_index = plane.saturating_sub(1);
        let has_chroma_top = chroma_top[chroma_index].is_some();
        let has_chroma_left = chroma_left[chroma_index].is_some();
        let top = chroma_top[chroma_index].unwrap_or([128_u16; 8]);
        let left = chroma_left[chroma_index].unwrap_or([top[0]; 4]);
        let chroma_dc = match (has_chroma_top, has_chroma_left) {
            (true, true) => rectangular_dc_predictor(&top, &left),
            (true, false) => one_sided_dc_predictor_8(top),
            (false, true) => one_sided_dc_predictor_4(left),
            (false, false) => 128,
        };
        let coefficients = lossy_chroma_8x4_coefficients[plane.saturating_sub(1)];
        let transform = chroma_rect_transform_kind(chroma_predictor);
        Ok(match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_chroma_8x4_cfl(
                    &above_left.planes[0],
                    &luma,
                    chroma_dc,
                    alpha,
                    coefficients,
                )?
            }
            ChromaPredictor::Dc => reconstruct_lossy_luma_8x4(
                rectangular_dc_predictor(&top, &left),
                coefficients,
                transform,
            ),
            ChromaPredictor::Vertical => reconstruct_lossy_luma_8x4_from_prediction(
                std::array::from_fn(|index| top[index % 8]),
                coefficients,
                transform,
            ),
            ChromaPredictor::Horizontal => reconstruct_lossy_luma_8x4_from_prediction(
                std::array::from_fn(|index| left[index / 8]),
                coefficients,
                transform,
            ),
            ChromaPredictor::Smooth => {
                reconstruct_lossy_luma_8x4_smooth(top, top[7], left, coefficients, transform)
            }
            ChromaPredictor::SmoothVertical => {
                reconstruct_lossy_luma_8x4_smooth_vertical(top, left[3], coefficients, transform)
            }
            ChromaPredictor::SmoothHorizontal => {
                reconstruct_lossy_luma_8x4_smooth_horizontal(left, top[7], coefficients, transform)
            }
            ChromaPredictor::Paeth => reconstruct_lossy_luma_8x4_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 8], left[index / 8], left[0])
                }),
                coefficients,
                transform,
            ),
            ChromaPredictor::DiagonalDownRight
            | ChromaPredictor::Diagonal113
            | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_8x4_diagonal_z2(
                top,
                left,
                left[0],
                chroma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                transform,
            )?,
            ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
                reconstruct_lossy_luma_8x4_diagonal_z1(
                    top,
                    top[0],
                    chroma_angle.ok_or(PortableUnavailable)?,
                    coefficients,
                    transform,
                )?
            }
            ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_8x4_diagonal_z3(
                left,
                top[0],
                chroma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                transform,
            )?,
        })
    };

    let chroma_u = chroma(1)?;
    let chroma_v = chroma(2)?;
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_full_vertical_16x64_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        lossy_luma_16x16_vertical_split,
        lossy_luma_16x64_coefficients,
        lossy_chroma_8x32_coefficients,
        ..
    } = syntax;

    let luma_top = if std::ptr::eq(above_left, above_right) {
        bottom_edge_16x64(&above_left.planes[0])
    } else {
        let left = bottom_edge(&above_left.planes[0]);
        let right = bottom_edge(&above_right.planes[0]);
        [
            left[0], left[1], left[2], left[3], left[4], left[5], left[6], left[7], right[0],
            right[1], right[2], right[3], right[4], right[5], right[6], right[7],
        ]
    };
    let luma_left = left_neighbor.map_or([luma_top[0]; 64], |neighbor| {
        right_edge_16x64(&neighbor.planes[0])
    });
    let luma = if let Some(split) = lossy_luma_16x16_vertical_split {
        reconstruct_lossy_luma_16x64_vertical_split(
            luma_predictor,
            luma_angle,
            None,
            luma_top,
            luma_left,
            luma_top[0],
            left_neighbor.is_some(),
            split,
        )?
    } else {
        match luma_predictor {
            LumaPredictor::Dc => reconstruct_lossy_luma_16x64(
                rectangular_dc_predictor(&luma_top, &luma_left),
                lossy_luma_16x64_coefficients,
            ),
            LumaPredictor::Vertical => {
                let prediction: [u16; 1024] = std::array::from_fn(|index| luma_top[index % 16]);
                let residual = transform::inverse_dct16x64(
                    &lossy_luma_16x64_coefficients.unwrap_or([0_i32; 512]),
                );
                reconstruct_lossy_predicted_plane(&prediction, &residual)
            }
            LumaPredictor::Horizontal => {
                let prediction: [u16; 1024] = std::array::from_fn(|index| luma_left[index / 16]);
                let residual = transform::inverse_dct16x64(
                    &lossy_luma_16x64_coefficients.unwrap_or([0_i32; 512]),
                );
                reconstruct_lossy_predicted_plane(&prediction, &residual)
            }
            LumaPredictor::Smooth => reconstruct_lossy_luma_16x64_smooth(
                luma_top,
                luma_left,
                lossy_luma_16x64_coefficients,
            ),
            LumaPredictor::DiagonalDownRight
            | LumaPredictor::Diagonal113
            | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_16x64_diagonal_z2(
                luma_top,
                luma_left,
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_16x64_coefficients,
            )?,
            LumaPredictor::Paeth => {
                let prediction: [u16; 1024] = std::array::from_fn(|index| {
                    paeth_predictor(luma_top[index % 16], luma_left[index / 16], luma_left[0])
                });
                let residual = transform::inverse_dct16x64(
                    &lossy_luma_16x64_coefficients.unwrap_or([0_i32; 512]),
                );
                reconstruct_lossy_predicted_plane(&prediction, &residual)
            }
            _ => return Err(PortableUnavailable),
        }
    };

    let luma_samples = luma.samples.clone();
    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top = if std::ptr::eq(above_left, above_right) {
            bottom_edge_8x32(&above_left.planes[plane])
        } else {
            let left = bottom_edge_4(&above_left.planes[plane]);
            let right = bottom_edge_4(&above_right.planes[plane]);
            [
                left[0], left[1], left[2], left[3], right[0], right[1], right[2], right[3],
            ]
        };
        let left = left_neighbor.map_or([top[0]; 32], |neighbor| {
            right_edge_8x32(&neighbor.planes[plane])
        });
        let coefficients = lossy_chroma_8x32_coefficients[plane - 1];
        let mut reduced_luma_samples = Vec::with_capacity(256);
        for y in 0_usize..32 {
            for x in 0_usize..8 {
                reduced_luma_samples.push(luma_samples[(y * 2).saturating_mul(16) + x * 2]);
            }
        }
        let reduced_luma = ReconstructedPlane {
            samples: reduced_luma_samples,
        };
        let reduced = match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_full_8x32_cfl(
                    &reduced_luma,
                    rectangular_dc_predictor(&top, &left),
                    alpha,
                    coefficients,
                )?
            }
            _ => reconstruct_lossy_full_8x32_chroma(
                chroma_predictor,
                chroma_angle,
                top,
                left,
                coefficients,
            )?,
        };
        let mut samples = Vec::with_capacity(1024);
        for y in 0_usize..64 {
            for x in 0_usize..16 {
                samples.push(reduced.samples[(y / 2) * 8 + x / 2]);
            }
        }
        Ok(ReconstructedPlane { samples })
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

fn reconstruct_following_lossy_420_vertical_16x64_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        lossy_luma_16x16_vertical_split,
        lossy_luma_16x64_coefficients,
        lossy_chroma_8x32_coefficients,
        ..
    } = syntax;

    let luma_top = if std::ptr::eq(above_left, above_right) {
        bottom_edge_16x64(&above_left.planes[0])
    } else {
        let left = bottom_edge(&above_left.planes[0]);
        let right = bottom_edge(&above_right.planes[0]);
        [
            left[0], left[1], left[2], left[3], left[4], left[5], left[6], left[7], right[0],
            right[1], right[2], right[3], right[4], right[5], right[6], right[7],
        ]
    };
    let luma_left = left_neighbor.map_or([luma_top[0]; 64], |neighbor| {
        right_edge_16x64(&neighbor.planes[0])
    });
    let luma = if let Some(split) = lossy_luma_16x16_vertical_split {
        reconstruct_lossy_luma_16x64_vertical_split(
            luma_predictor,
            luma_angle,
            None,
            luma_top,
            luma_left,
            luma_top[0],
            left_neighbor.is_some(),
            split,
        )?
    } else {
        match luma_predictor {
            LumaPredictor::Dc => {
                let predictor = rectangular_dc_predictor(&luma_top, &luma_left);
                reconstruct_lossy_luma_16x64(predictor, lossy_luma_16x64_coefficients)
            }
            LumaPredictor::Vertical => {
                let prediction: [u16; 1024] = std::array::from_fn(|index| luma_top[index % 16]);
                let coefficients = lossy_luma_16x64_coefficients.unwrap_or([0_i32; 512]);
                let residual = transform::inverse_dct16x64(&coefficients);
                reconstruct_lossy_predicted_plane(&prediction, &residual)
            }
            LumaPredictor::Horizontal => {
                let prediction: [u16; 1024] = std::array::from_fn(|index| luma_left[index / 16]);
                let coefficients = lossy_luma_16x64_coefficients.unwrap_or([0_i32; 512]);
                let residual = transform::inverse_dct16x64(&coefficients);
                reconstruct_lossy_predicted_plane(&prediction, &residual)
            }
            LumaPredictor::Smooth => reconstruct_lossy_luma_16x64_smooth(
                luma_top,
                luma_left,
                lossy_luma_16x64_coefficients,
            ),
            LumaPredictor::DiagonalDownRight
            | LumaPredictor::Diagonal113
            | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_16x64_diagonal_z2(
                luma_top,
                luma_left,
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_16x64_coefficients,
            )?,
            LumaPredictor::Paeth => {
                let prediction: [u16; 1024] = std::array::from_fn(|index| {
                    paeth_predictor(luma_top[index % 16], luma_left[index / 16], luma_left[0])
                });
                let coefficients = lossy_luma_16x64_coefficients.unwrap_or([0_i32; 512]);
                let residual = transform::inverse_dct16x64(&coefficients);
                reconstruct_lossy_predicted_plane(&prediction, &residual)
            }
            _ => return Err(PortableUnavailable),
        }
    };

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top = if std::ptr::eq(above_left, above_right) {
            bottom_edge_8x32(&above_left.planes[plane])
        } else {
            let left = bottom_edge_4(&above_left.planes[plane]);
            let right = bottom_edge_4(&above_right.planes[plane]);
            [
                left[0], left[1], left[2], left[3], right[0], right[1], right[2], right[3],
            ]
        };
        let left = left_neighbor.map_or([top[0]; 32], |neighbor| {
            right_edge_8x32(&neighbor.planes[plane])
        });
        let coefficients = lossy_chroma_8x32_coefficients[plane.saturating_sub(1)];
        match chroma_predictor {
            ChromaPredictor::Dc => {
                let predictor = rectangular_dc_predictor(&top, &left);
                Ok(reconstruct_lossy_residual_plane(
                    predictor,
                    &transform::inverse_dct8x32(&coefficients.unwrap_or([0_i32; 256])),
                ))
            }
            ChromaPredictor::Vertical => {
                let prediction: [u16; 256] = std::array::from_fn(|index| top[index % 8]);
                let residual = transform::inverse_dct8x32(&coefficients.unwrap_or([0_i32; 256]));
                Ok(reconstruct_lossy_predicted_plane(&prediction, &residual))
            }
            ChromaPredictor::Horizontal => {
                let prediction: [u16; 256] = std::array::from_fn(|index| left[index / 8]);
                let residual = transform::inverse_dct8x32(&coefficients.unwrap_or([0_i32; 256]));
                Ok(reconstruct_lossy_predicted_plane(&prediction, &residual))
            }
            ChromaPredictor::Smooth => Ok(reconstruct_lossy_chroma_8x32_smooth(
                top,
                left,
                coefficients,
            )),
            ChromaPredictor::DiagonalDownRight
            | ChromaPredictor::Diagonal113
            | ChromaPredictor::Diagonal157 => Ok(reconstruct_lossy_chroma_8x32_diagonal_z2(
                top,
                left,
                chroma_angle.ok_or(PortableUnavailable)?,
                coefficients,
            )?),
            ChromaPredictor::Paeth => {
                let prediction: [u16; 256] = std::array::from_fn(|index| {
                    paeth_predictor(top[index % 8], left[index / 8], left[0])
                });
                let residual = transform::inverse_dct8x32(&coefficients.unwrap_or([0_i32; 256]));
                Ok(reconstruct_lossy_predicted_plane(&prediction, &residual))
            }
            _ => Err(PortableUnavailable),
        }
    };

    let chroma_u = chroma(1)?;
    let chroma_v = chroma(2)?;
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn lossy_chroma_contexts(syntax: &BlockSyntax) -> [u8; 2] {
    syntax.lossy_chroma_residual_contexts
}

fn reconstruct_following_lossy_420_horizontal_16x8_leaf(
    syntax: BlockSyntax,
    left_neighbor: &ClosedLeaf,
    luma_left_edge_8: Option<[u16; 8]>,
    chroma_left_edges_8: [Option<[u16; 8]>; 2],
) -> PortableResult<ClosedLeaf> {
    let luma_split = syntax.lossy_luma_8x8_split;
    let luma_left = luma_left_edge_8.unwrap_or_else(|| right_edge(&left_neighbor.planes[0]));
    let chroma_left = |plane: usize| right_edge_4(&left_neighbor.planes[plane]);
    let luma_predictor = match syntax.luma_predictor {
        LumaPredictor::Dc => one_sided_dc_predictor(luma_left),
        LumaPredictor::Horizontal | LumaPredictor::Vertical => luma_left[0],
        predictor => predictor.sample(),
    };
    let predictors = [
        luma_predictor,
        one_sided_dc_predictor_4(chroma_left(1)),
        one_sided_dc_predictor_4(chroma_left(2)),
    ];
    let mut leaf = reconstruct_leaf(syntax, predictors);
    if syntax.filter_intra_mode.is_none()
        && matches!(syntax.luma_predictor, LumaPredictor::Horizontal)
    {
        // A horizontally following R16x8 leaf has no top edge, but its full
        // left edge is available. The generic leaf policy only receives the
        // first left sample, which incorrectly makes a varying horizontal
        // predictor constant across every row.
        let prediction = std::array::from_fn(|index| luma_left[index / 16]);
        leaf.planes[0] = reconstruct_lossy_luma_16x8_from_prediction(
            prediction,
            syntax.lossy_luma_16x8_coefficients,
            syntax.lossy_luma_16x8_transform,
        );
    }
    if matches!(syntax.chroma_sampling, ChromaSampling::Full) {
        for plane in 1..=2 {
            let left = chroma_left_edges_8[plane - 1]
                .unwrap_or_else(|| right_edge(&left_neighbor.planes[plane]));
            leaf.planes[plane] = match syntax.chroma_predictor {
                ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                    let alpha = if plane == 1 { alpha_u } else { alpha_v };
                    reconstruct_lossy_full_16x8_cfl(
                        &leaf.planes[0],
                        one_sided_dc_predictor(left),
                        alpha,
                        syntax.lossy_chroma_16x8_coefficients[plane - 1],
                    )?
                }
                _ => reconstruct_lossy_full_16x8_chroma(
                    syntax.chroma_predictor,
                    syntax.chroma_angle,
                    [left[0]; 16],
                    left,
                    syntax.lossy_chroma_16x8_coefficients[plane - 1],
                )?,
            };
        }
    }
    if let Some(split) = luma_split {
        leaf.planes[0] = reconstruct_lossy_luma_16x8_split(
            syntax.luma_predictor,
            syntax.luma_angle,
            syntax.filter_intra_mode,
            [luma_left[0]; 16],
            luma_left,
            luma_left[0],
            false,
            split,
        )?;
    }
    Ok(leaf)
}

fn reconstruct_following_lossy_420_horizontal_8x16_leaf(
    syntax: BlockSyntax,
    left_neighbor: &ClosedLeaf,
    luma_left_edge: Option<[u16; 16]>,
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        lossy_luma_rect_coefficients,
        lossy_luma_rect_transform,
        lossy_chroma_8x4_coefficients,
        ..
    } = syntax;

    // A horizontal continuation has the completed block on its left. The
    // walker does not expose the block above this leaf, so AV1's missing top
    // edge is extended from the top-left sample, just as the one-sided
    // 8×8 continuation path does below.
    let luma_left = luma_left_edge.unwrap_or_else(|| right_edge_16(&left_neighbor.planes[0]));
    let luma_top = [luma_left[0]; 8];
    let luma = match (luma_predictor, luma_angle) {
        (LumaPredictor::Dc, _) => reconstruct_lossy_luma_8x16(
            rectangular_dc_predictor(&luma_top, &luma_left),
            lossy_luma_rect_coefficients,
            lossy_luma_rect_transform,
        ),
        (LumaPredictor::Vertical, _) => reconstruct_lossy_luma_8x16_from_prediction(
            std::array::from_fn(|index| luma_top[index % 8]),
            lossy_luma_rect_coefficients,
            lossy_luma_rect_transform,
        ),
        (LumaPredictor::Horizontal, _) => reconstruct_lossy_luma_8x16_from_prediction(
            std::array::from_fn(|index| luma_left[index / 8]),
            lossy_luma_rect_coefficients,
            lossy_luma_rect_transform,
        ),
        (LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67, Some(angle)) => {
            reconstruct_lossy_luma_8x16_diagonal_z1(
                [luma_top[0]; 16],
                luma_top[0],
                angle,
                lossy_luma_rect_coefficients,
                lossy_luma_rect_transform,
            )?
        }
        (LumaPredictor::Diagonal113 | LumaPredictor::Diagonal157, Some(angle)) => {
            reconstruct_lossy_luma_8x16_diagonal(
                [luma_top[0]; 16],
                luma_left,
                angle,
                enable_intra_edge_filter,
                lossy_luma_rect_coefficients.unwrap_or([0_i32; 128]),
                lossy_luma_rect_transform,
            )
            .or_else(|_| {
                Ok(reconstruct_lossy_luma_8x16(
                    rectangular_dc_predictor(&luma_top, &luma_left),
                    lossy_luma_rect_coefficients,
                    lossy_luma_rect_transform,
                ))
            })?
        }
        (LumaPredictor::Paeth, _) => {
            let prediction = std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 8], luma_left[index / 8], luma_left[0])
            });
            reconstruct_lossy_luma_8x16_from_prediction(
                prediction,
                lossy_luma_rect_coefficients,
                lossy_luma_rect_transform,
            )
        }
        _ => return Err(PortableUnavailable),
    };

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top = [right_edge_for_4x8(&left_neighbor.planes[plane])[0]; 4];
        let left = right_edge_for_4x8(&left_neighbor.planes[plane]);
        let coefficients = lossy_chroma_8x4_coefficients[plane.saturating_sub(1)];
        let transform = chroma_rect_transform_kind(chroma_predictor);
        match chroma_predictor {
            ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_4x8(
                [rectangular_dc_predictor(&top, &left); 4],
                [rectangular_dc_predictor(&top, &left); 8],
                coefficients,
                transform,
            )),
            ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_4x8_from_prediction(
                std::array::from_fn(|index| top[index % 4]),
                coefficients,
                transform,
            )),
            ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_4x8_from_prediction(
                std::array::from_fn(|index| left[index / 4]),
                coefficients,
                transform,
            )),
            ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
                reconstruct_lossy_luma_4x8_diagonal_z1(
                    top,
                    top[0],
                    chroma_angle.ok_or(PortableUnavailable)?,
                    coefficients,
                    transform,
                )
            }
            ChromaPredictor::DiagonalDownRight
            | ChromaPredictor::Diagonal113
            | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_4x8_diagonal_z2(
                top,
                left,
                left[0],
                chroma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                transform,
            ),
            ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_4x8_diagonal_z3(
                left,
                top[0],
                chroma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                transform,
            ),
            ChromaPredictor::Smooth => Ok(reconstruct_lossy_luma_4x8_smooth(
                top,
                top[3],
                left,
                coefficients,
                transform,
            )),
            ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_luma_4x8_smooth_vertical(
                top,
                left[7],
                coefficients,
                transform,
            )),
            ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_luma_4x8_smooth_horizontal(
                left,
                top[3],
                coefficients,
                transform,
            )),
            ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_4x8_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 4], left[index / 4], left[0])
                }),
                coefficients,
                transform,
            )),
            ChromaPredictor::Cfl { .. } => Err(PortableUnavailable),
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

fn reconstruct_following_lossy_420_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
    orientation: SplitOrientation,
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    reconstruct_following_lossy_420_leaf_with_luma_edge(
        syntax,
        neighbor,
        orientation,
        enable_intra_edge_filter,
        None,
        None,
    )
}

fn reconstruct_following_lossy_420_leaf_with_luma_edge(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
    orientation: SplitOrientation,
    enable_intra_edge_filter: bool,
    luma_edge_override: Option<[u16; 8]>,
    luma_bottom_left_override: Option<[u16; 8]>,
) -> PortableResult<ClosedLeaf> {
    if syntax.palette.is_present()
        && let Some(leaf) = reconstruct_palette_square8_leaf(syntax)
    {
        return Ok(leaf);
    }
    if matches!(syntax.transform_grid, TransformGrid::Square64) {
        return Ok(reconstruct_following_lossy_420_vertical_64x64_leaf(
            syntax, neighbor, neighbor,
        ));
    }
    if matches!(syntax.transform_grid, TransformGrid::Square32) {
        return Ok(reconstruct_following_lossy_420_32x32_leaf(syntax, neighbor));
    }
    if matches!(syntax.transform_grid, TransformGrid::Square16) {
        return reconstruct_following_lossy_420_16x16_leaf(
            syntax, neighbor, None, false, None, [None; 2],
        );
    }
    if matches!(syntax.transform_grid, TransformGrid::Horizontal8x4) {
        return reconstruct_following_lossy_420_8x4_leaf(syntax, neighbor);
    }
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        filter_intra_mode,
        lossy_luma_coefficients,
        lossy_luma_transform,
        lossy_luma_4x4_split,
        lossy_chroma_coefficients,
        ..
    } = syntax;
    let luma_edge =
        luma_edge_override.unwrap_or_else(|| adjacent_edge(&neighbor.planes[0], orientation));
    let smooth_edges = matches!(
        neighbor.luma_predictor,
        LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
    );
    let chroma_edges = [1_usize, 2].map(|plane| match orientation {
        SplitOrientation::Horizontal => right_edge_4_for_8x4_chroma(&neighbor.planes[plane]),
        SplitOrientation::Vertical => bottom_edge_4_for_4x8(&neighbor.planes[plane]),
    });

    let luma = if let Some(split) = lossy_luma_4x4_split {
        match (orientation, filter_intra_mode, luma_predictor) {
            (SplitOrientation::Horizontal, Some(mode), _) => {
                reconstruct_lossy_luma_8x8_split_filter_intra_no_top(luma_edge, split, mode)?
            }
            (SplitOrientation::Horizontal, None, LumaPredictor::Dc) => {
                reconstruct_lossy_luma_8x8_split_dc_horizontal(luma_edge, split)
            }
            (SplitOrientation::Horizontal, None, LumaPredictor::Smooth) => {
                reconstruct_lossy_luma_8x8_split_smooth_horizontal(luma_edge, split)
            }
            (SplitOrientation::Horizontal, None, LumaPredictor::SmoothHorizontal) => {
                reconstruct_lossy_luma_8x8_split_smooth_horizontal(luma_edge, split)
            }
            (SplitOrientation::Horizontal, None, LumaPredictor::Horizontal) => {
                let angle = luma_angle.ok_or(PortableUnavailable)?;
                if angle < 180 {
                    reconstruct_lossy_luma_8x8_split_diagonal_vertical(
                        [luma_edge[0]; 8],
                        Some(luma_edge),
                        Some(luma_edge[0]),
                        angle,
                        false,
                        smooth_edges,
                        split,
                    )?
                } else if angle == 180 {
                    reconstruct_lossy_luma_8x8_split_horizontal_vertical(
                        [luma_edge[0]; 8],
                        Some(luma_edge),
                        split,
                    )
                } else {
                    reconstruct_lossy_luma_8x8_split_diagonal_z3(
                        luma_edge,
                        [128; 8],
                        luma_edge[0],
                        luma_bottom_left_override,
                        angle,
                        enable_intra_edge_filter,
                        split,
                    )?
                }
            }
            (
                SplitOrientation::Horizontal,
                None,
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157,
            ) => reconstruct_lossy_luma_8x8_split_diagonal_vertical(
                [luma_edge[0]; 8],
                Some(luma_edge),
                Some(luma_edge[0]),
                luma_angle.ok_or(PortableUnavailable)?,
                false,
                smooth_edges,
                split,
            )?,
            (
                SplitOrientation::Horizontal,
                None,
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67,
            ) => reconstruct_lossy_luma_8x8_split_diagonal_z1(
                [luma_edge[0]; 8],
                Some(luma_edge),
                Some(luma_edge[0]),
                luma_angle.ok_or(PortableUnavailable)?,
                split,
            )?,
            (SplitOrientation::Horizontal, None, LumaPredictor::Diagonal203) => {
                reconstruct_lossy_luma_8x8_split_diagonal_z3(
                    luma_edge,
                    [luma_edge[0]; 8],
                    luma_edge[0],
                    luma_bottom_left_override,
                    luma_angle.ok_or(PortableUnavailable)?,
                    enable_intra_edge_filter,
                    split,
                )?
            }
            (SplitOrientation::Horizontal, None, LumaPredictor::Paeth) => {
                reconstruct_lossy_luma_8x8_split_paeth([128; 8], Some(luma_edge), 128, split)
            }
            (SplitOrientation::Vertical, None, LumaPredictor::Smooth) => {
                reconstruct_lossy_luma_8x8_split_smooth_vertical(luma_edge, None, split)
            }
            (SplitOrientation::Vertical, None, LumaPredictor::SmoothHorizontal) => {
                reconstruct_lossy_luma_8x8_split_smooth_horizontal_vertical(luma_edge, None, split)
            }
            (SplitOrientation::Vertical, None, LumaPredictor::Diagonal203) => {
                reconstruct_lossy_luma_8x8_split_diagonal_z3(
                    luma_edge,
                    [luma_edge[0]; 8],
                    128,
                    None,
                    luma_angle.ok_or(PortableUnavailable)?,
                    enable_intra_edge_filter,
                    split,
                )?
            }
            _ => return Err(PortableUnavailable),
        }
    } else if let Some(mode) = filter_intra_mode {
        matches!(orientation, SplitOrientation::Horizontal)
            .then_some(())
            .portable()?;
        reconstruct_lossy_luma_8x8_filter_intra_no_top(
            luma_edge,
            lossy_luma_coefficients,
            lossy_luma_transform,
            mode,
        )?
    } else {
        match luma_predictor {
            LumaPredictor::Dc => reconstruct_lossy_luma_8x8(
                one_sided_dc_predictor(luma_edge),
                lossy_luma_coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Vertical => reconstruct_lossy_luma_8x8_vertical(
                luma_edge,
                lossy_luma_coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Horizontal => match (orientation, luma_angle) {
                (SplitOrientation::Horizontal, None | Some(180)) => {
                    reconstruct_lossy_luma_8x8_horizontal(
                        luma_edge,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )
                }
                (SplitOrientation::Horizontal, Some(angle)) if 90 < angle && angle < 180 => {
                    reconstruct_lossy_luma_8x8_diagonal(
                        [luma_edge[0]; 16],
                        luma_edge,
                        luma_edge[0],
                        angle,
                        false,
                        smooth_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (SplitOrientation::Horizontal, Some(angle)) if 180 < angle && angle < 270 => {
                    reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
                        luma_edge,
                        luma_edge[0],
                        luma_bottom_left_override,
                        angle,
                        enable_intra_edge_filter,
                        false,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                _ => return Err(PortableUnavailable),
            },
            LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                [luma_edge[0]; 8],
                luma_edge[0],
                luma_edge,
                lossy_luma_coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                [luma_edge[0]; 8],
                luma_edge[7],
                lossy_luma_coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x8_smooth_horizontal(
                luma_edge,
                luma_edge[0],
                lossy_luma_coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                [luma_edge[0]; 16],
                luma_edge,
                luma_edge[0],
                luma_angle.ok_or(PortableUnavailable)?,
                false,
                smooth_edges,
                lossy_luma_coefficients,
                lossy_luma_transform,
            )?,
            LumaPredictor::DiagonalDownRight | LumaPredictor::Diagonal113 => {
                reconstruct_lossy_luma_8x8_diagonal(
                    [128; 16],
                    luma_edge,
                    128,
                    luma_angle.ok_or(PortableUnavailable)?,
                    false,
                    smooth_edges,
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                )?
            }
            LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                reconstruct_lossy_luma_8x8_diagonal_z1(
                    [128; 8],
                    128,
                    luma_angle.ok_or(PortableUnavailable)?,
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                )?
            }
            LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
                luma_edge,
                128,
                luma_bottom_left_override,
                luma_angle.ok_or(PortableUnavailable)?,
                false,
                false,
                lossy_luma_coefficients,
                lossy_luma_transform,
            )?,
            LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                [128; 8],
                luma_edge,
                128,
                lossy_luma_coefficients,
                lossy_luma_transform,
            ),
        }
    };
    let chroma = (|| -> PortableResult<[ReconstructedPlane; 2]> {
        Ok(match (chroma_predictor, orientation) {
            (ChromaPredictor::Cfl { alpha_u, alpha_v }, _) => [
                reconstruct_lossy_chroma_4x4_cfl(
                    &luma,
                    one_sided_dc_predictor_4(chroma_edges[0]),
                    alpha_u,
                    lossy_chroma_coefficients[0],
                )?,
                reconstruct_lossy_chroma_4x4_cfl(
                    &luma,
                    one_sided_dc_predictor_4(chroma_edges[1]),
                    alpha_v,
                    lossy_chroma_coefficients[1],
                )?,
            ],
            (ChromaPredictor::Horizontal, SplitOrientation::Horizontal) => [
                reconstruct_lossy_chroma_4x4_horizontal(
                    chroma_edges[0],
                    lossy_chroma_coefficients[0],
                    LossyTransformKind::DctAdst,
                ),
                reconstruct_lossy_chroma_4x4_horizontal(
                    chroma_edges[1],
                    lossy_chroma_coefficients[1],
                    LossyTransformKind::DctAdst,
                ),
            ],
            (
                ChromaPredictor::DiagonalDownRight
                | ChromaPredictor::Diagonal113
                | ChromaPredictor::Diagonal157,
                SplitOrientation::Horizontal,
            ) => [
                reconstruct_lossy_chroma_4x4_diagonal(
                    [128; 8],
                    chroma_edges[0],
                    chroma_angle.ok_or(PortableUnavailable)?,
                    lossy_chroma_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                )?,
                reconstruct_lossy_chroma_4x4_diagonal(
                    [128; 8],
                    chroma_edges[1],
                    chroma_angle.ok_or(PortableUnavailable)?,
                    lossy_chroma_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                )?,
            ],
            (
                ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67,
                SplitOrientation::Horizontal,
            ) => [
                reconstruct_lossy_4x4_diagonal_z1(
                    [128; 4],
                    128,
                    chroma_angle.ok_or(PortableUnavailable)?,
                    lossy_chroma_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                )?,
                reconstruct_lossy_4x4_diagonal_z1(
                    [128; 4],
                    128,
                    chroma_angle.ok_or(PortableUnavailable)?,
                    lossy_chroma_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                )?,
            ],
            (ChromaPredictor::Diagonal203, SplitOrientation::Horizontal) => [
                reconstruct_lossy_chroma_4x4_diagonal_z3(
                    chroma_edges[0],
                    128,
                    chroma_angle.ok_or(PortableUnavailable)?,
                    lossy_chroma_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                )?,
                reconstruct_lossy_chroma_4x4_diagonal_z3(
                    chroma_edges[1],
                    128,
                    chroma_angle.ok_or(PortableUnavailable)?,
                    lossy_chroma_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                )?,
            ],
            (ChromaPredictor::Dc, _) => [
                reconstruct_lossy_chroma_4x4(
                    one_sided_dc_predictor_4(chroma_edges[0]),
                    lossy_chroma_coefficients[0],
                    LossyTransformKind::DctDct,
                ),
                reconstruct_lossy_chroma_4x4(
                    one_sided_dc_predictor_4(chroma_edges[1]),
                    lossy_chroma_coefficients[1],
                    LossyTransformKind::DctDct,
                ),
            ],
            (ChromaPredictor::Vertical, _) => [
                reconstruct_lossy_chroma_4x4_vertical(
                    [
                        chroma_edges[0][0],
                        chroma_edges[0][1],
                        chroma_edges[0][2],
                        chroma_edges[0][3],
                    ],
                    lossy_chroma_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                ),
                reconstruct_lossy_chroma_4x4_vertical(
                    [
                        chroma_edges[1][0],
                        chroma_edges[1][1],
                        chroma_edges[1][2],
                        chroma_edges[1][3],
                    ],
                    lossy_chroma_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                ),
            ],
            (ChromaPredictor::Smooth, SplitOrientation::Horizontal) => [
                reconstruct_lossy_chroma_4x4_smooth(
                    [chroma_edges[0][0]; 4],
                    chroma_edges[0][0],
                    chroma_edges[0],
                    lossy_chroma_coefficients[0],
                ),
                reconstruct_lossy_chroma_4x4_smooth(
                    [chroma_edges[1][0]; 4],
                    chroma_edges[1][0],
                    chroma_edges[1],
                    lossy_chroma_coefficients[1],
                ),
            ],
            (ChromaPredictor::SmoothVertical, SplitOrientation::Horizontal) => [
                reconstruct_lossy_4x4_smooth_vertical(
                    [chroma_edges[0][0]; 4],
                    chroma_edges[0][3],
                    lossy_chroma_coefficients[0],
                    LossyTransformKind::AdstDct,
                ),
                reconstruct_lossy_4x4_smooth_vertical(
                    [chroma_edges[1][0]; 4],
                    chroma_edges[1][3],
                    lossy_chroma_coefficients[1],
                    LossyTransformKind::AdstDct,
                ),
            ],
            (ChromaPredictor::SmoothHorizontal, SplitOrientation::Horizontal) => [
                reconstruct_lossy_4x4_smooth_horizontal(
                    chroma_edges[0],
                    chroma_edges[0][0],
                    lossy_chroma_coefficients[0],
                    LossyTransformKind::DctAdst,
                ),
                reconstruct_lossy_4x4_smooth_horizontal(
                    chroma_edges[1],
                    chroma_edges[1][0],
                    lossy_chroma_coefficients[1],
                    LossyTransformKind::DctAdst,
                ),
            ],
            (ChromaPredictor::Paeth, SplitOrientation::Horizontal) => [
                reconstruct_lossy_chroma_4x4_horizontal(
                    chroma_edges[0],
                    lossy_chroma_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                ),
                reconstruct_lossy_chroma_4x4_horizontal(
                    chroma_edges[1],
                    lossy_chroma_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                ),
            ],
            (ChromaPredictor::Paeth, SplitOrientation::Vertical) => [
                reconstruct_lossy_chroma_4x4_vertical(
                    chroma_edges[0],
                    lossy_chroma_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                ),
                reconstruct_lossy_chroma_4x4_vertical(
                    chroma_edges[1],
                    lossy_chroma_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                ),
            ],
            (ChromaPredictor::Horizontal, SplitOrientation::Vertical) => {
                return Err(PortableUnavailable);
            }
            (ChromaPredictor::Diagonal157, SplitOrientation::Vertical) => {
                return Err(PortableUnavailable);
            }
            (ChromaPredictor::Smooth, _) => return Err(PortableUnavailable),
            (
                ChromaPredictor::Diagonal45
                | ChromaPredictor::DiagonalDownRight
                | ChromaPredictor::Diagonal113
                | ChromaPredictor::Diagonal203
                | ChromaPredictor::Diagonal67
                | ChromaPredictor::SmoothVertical
                | ChromaPredictor::SmoothHorizontal,
                _,
            ) => return Err(PortableUnavailable),
        })
    })()?;
    let [chroma_u, chroma_v] = chroma;
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_420_32x32_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
) -> ClosedLeaf {
    let luma_edge = right_edge(&neighbor.planes[0]);
    let chroma_edge_u = right_edge_4(&neighbor.planes[1]);
    let chroma_edge_v = right_edge_4(&neighbor.planes[2]);
    let luma_predictor = match syntax.luma_predictor {
        LumaPredictor::Dc => one_sided_dc_predictor(luma_edge),
        LumaPredictor::Vertical | LumaPredictor::Horizontal => luma_edge[0],
        predictor => predictor.sample(),
    };
    let chroma_predictor = match syntax.chroma_predictor {
        ChromaPredictor::Dc => [
            one_sided_dc_predictor_4(chroma_edge_u),
            one_sided_dc_predictor_4(chroma_edge_v),
        ],
        _ => [128; 2],
    };
    let mut leaf = reconstruct_leaf(
        syntax,
        [luma_predictor, chroma_predictor[0], chroma_predictor[1]],
    );
    if matches!(syntax.chroma_sampling, ChromaSampling::Full) {
        for plane in 1..=2 {
            let predictor = if matches!(syntax.chroma_predictor, ChromaPredictor::Dc) {
                one_sided_dc_predictor_4(right_edge_4(&neighbor.planes[plane]))
            } else {
                128
            };
            leaf.planes[plane] = reconstruct_lossy_chroma_32x32(
                predictor,
                syntax.lossy_chroma_32x32_coefficients[plane - 1],
            );
        }
    }
    leaf
}

fn reconstruct_following_lossy_420_vertical_64x64_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    _above_right: &ClosedLeaf,
) -> ClosedLeaf {
    let luma_edge = bottom_edge(&above_left.planes[0]);
    let chroma_edge_u = bottom_edge_4(&above_left.planes[1]);
    let chroma_edge_v = bottom_edge_4(&above_left.planes[2]);
    let predictors = [
        match syntax.luma_predictor {
            LumaPredictor::Dc => one_sided_dc_predictor(luma_edge),
            predictor => predictor.sample(),
        },
        match syntax.chroma_predictor {
            ChromaPredictor::Dc => one_sided_dc_predictor_4(chroma_edge_u),
            _ => 128,
        },
        match syntax.chroma_predictor {
            ChromaPredictor::Dc => one_sided_dc_predictor_4(chroma_edge_v),
            _ => 128,
        },
    ];
    reconstruct_leaf(syntax, predictors)
}

fn reconstruct_following_lossy_420_vertical_4x8_leaf(
    syntax: BlockSyntax,
    above: &ClosedLeaf,
    left_top: Option<&ClosedLeaf>,
    left_bottom: Option<&ClosedLeaf>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        lossy_luma_4x8_coefficients,
        lossy_luma_4x8_transform,
        lossy_chroma_coefficients,
        ..
    } = syntax;

    let above_luma_edge = bottom_edge_4_for_4x8(&above.planes[0]);
    let luma_top = [
        above_luma_edge[0],
        above_luma_edge[1],
        above_luma_edge[2],
        above_luma_edge[3],
    ];
    let luma_left = match (left_top, left_bottom) {
        (Some(top), Some(bottom)) => {
            let top_edge = right_edge_for_4x8(&top.planes[0]);
            let bottom_edge = right_edge_for_4x8(&bottom.planes[0]);
            [
                top_edge[0],
                top_edge[1],
                top_edge[2],
                top_edge[3],
                bottom_edge[0],
                bottom_edge[1],
                bottom_edge[2],
                bottom_edge[3],
            ]
        }
        (Some(left), None) | (None, Some(left)) => right_edge_for_4x8(&left.planes[0]),
        (None, None) => [luma_top[0]; 8],
    };
    let luma_top_left = left_top.map_or(luma_top[0], |neighbor| {
        right_edge_for_4x8(&neighbor.planes[0])[7]
    });
    let luma = match luma_predictor {
        LumaPredictor::Dc => reconstruct_lossy_luma_4x8(
            luma_top,
            luma_left,
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Vertical => reconstruct_lossy_luma_4x8_from_prediction(
            std::array::from_fn(|index| luma_top[index % 4]),
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Horizontal => reconstruct_lossy_luma_4x8_from_prediction(
            std::array::from_fn(|index| luma_left[index / 4]),
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Paeth => reconstruct_lossy_luma_4x8_from_prediction(
            std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 4], luma_left[index / 4], luma_left[0])
            }),
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Smooth => reconstruct_lossy_luma_4x8_smooth(
            luma_top,
            luma_top[3],
            luma_left,
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::SmoothVertical => reconstruct_lossy_luma_4x8_smooth_vertical(
            luma_top,
            luma_left[7],
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_4x8_smooth_horizontal(
            luma_left,
            luma_top[3],
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        ),
        LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_4x8_diagonal_z1(
                luma_top,
                luma_top_left,
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_4x8_coefficients,
                lossy_luma_4x8_transform,
            )?
        }
        LumaPredictor::Diagonal203 => reconstruct_lossy_luma_4x8_diagonal_z3(
            luma_left,
            luma_left[0],
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        )?,
        LumaPredictor::DiagonalDownRight
        | LumaPredictor::Diagonal113
        | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_4x8_diagonal_z2(
            luma_top,
            luma_left,
            luma_left[0],
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_4x8_coefficients,
            lossy_luma_4x8_transform,
        )?,
    };

    let chroma_top_u = bottom_edge_4_padded(&above.planes[1]);
    let chroma_top_v = bottom_edge_4_padded(&above.planes[2]);
    let chroma_left = |plane: usize| -> [u16; 4] {
        match (left_top, left_bottom) {
            (Some(top), Some(bottom)) => {
                let top_edge = right_edge_4_padded(&top.planes[plane]);
                let bottom_edge = right_edge_4_padded(&bottom.planes[plane]);
                [top_edge[0], top_edge[1], bottom_edge[0], bottom_edge[1]]
            }
            (Some(left), None) | (None, Some(left)) => right_edge_4_padded(&left.planes[plane]),
            (None, None) => [chroma_top_u[0]; 4],
        }
    };
    let chroma_u_left = chroma_left(1);
    let chroma_v_left = chroma_left(2);
    let chroma_top_left_u = bottom_right_for_4x4_padded(&above.planes[1]);
    let chroma_top_left_v = bottom_right_for_4x4_padded(&above.planes[2]);
    let chroma_top_u_z2 = [
        chroma_top_u[0],
        chroma_top_u[1],
        chroma_top_u[2],
        chroma_top_u[3],
        chroma_top_u[3],
        chroma_top_u[3],
        chroma_top_u[3],
        chroma_top_u[3],
    ];
    let chroma_top_v_z2 = [
        chroma_top_v[0],
        chroma_top_v[1],
        chroma_top_v[2],
        chroma_top_v[3],
        chroma_top_v[3],
        chroma_top_v[3],
        chroma_top_v[3],
        chroma_top_v[3],
    ];
    let chroma_u = match chroma_predictor {
        ChromaPredictor::Cfl { alpha_u, .. } => reconstruct_lossy_chroma_4x4_cfl(
            &luma,
            dc_predictor(chroma_top_u, chroma_u_left),
            alpha_u,
            lossy_chroma_coefficients[0],
        )?,
        ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
            dc_predictor(chroma_top_u, chroma_u_left),
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Vertical => reconstruct_lossy_chroma_4x4_vertical(
            chroma_top_u,
            lossy_chroma_coefficients[0],
            chroma_transform_kind(chroma_predictor),
        ),
        ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
            chroma_u_left,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1(
                chroma_top_u,
                chroma_top_left_u,
                chroma_angle.ok_or(PortableUnavailable)?,
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            )?
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            chroma_top_u_z2,
            chroma_u_left,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[0],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
            chroma_u_left,
            chroma_top_left_u,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[0],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            chroma_top_u,
            chroma_u_left,
            chroma_top_left_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Smooth => reconstruct_lossy_chroma_4x4_smooth(
            chroma_top_u,
            chroma_top_u[3],
            chroma_u_left,
            lossy_chroma_coefficients[0],
        ),
        ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            chroma_top_u,
            chroma_u_left[3],
            lossy_chroma_coefficients[0],
            LossyTransformKind::AdstDct,
        ),
        ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            chroma_u_left,
            chroma_top_u[3],
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctAdst,
        ),
    };
    let chroma_v = match chroma_predictor {
        ChromaPredictor::Cfl { alpha_v, .. } => reconstruct_lossy_chroma_4x4_cfl(
            &luma,
            dc_predictor(chroma_top_v, chroma_v_left),
            alpha_v,
            lossy_chroma_coefficients[1],
        )?,
        ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
            dc_predictor(chroma_top_v, chroma_v_left),
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Vertical => reconstruct_lossy_chroma_4x4_vertical(
            chroma_top_v,
            lossy_chroma_coefficients[1],
            chroma_transform_kind(chroma_predictor),
        ),
        ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
            chroma_v_left,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1(
                chroma_top_v,
                chroma_top_left_v,
                chroma_angle.ok_or(PortableUnavailable)?,
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            )?
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            chroma_top_v_z2,
            chroma_v_left,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[1],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
            chroma_v_left,
            chroma_top_left_v,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[1],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            chroma_top_v,
            chroma_v_left,
            chroma_top_left_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Smooth => reconstruct_lossy_chroma_4x4_smooth(
            chroma_top_v,
            chroma_top_v[3],
            chroma_v_left,
            lossy_chroma_coefficients[1],
        ),
        ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            chroma_top_v,
            chroma_v_left[3],
            lossy_chroma_coefficients[1],
            LossyTransformKind::AdstDct,
        ),
        ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            chroma_v_left,
            chroma_top_v[3],
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctAdst,
        ),
    };
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_420_vertical_4x16_leaf(
    syntax: BlockSyntax,
    above: &ClosedLeaf,
    left: Option<&ClosedLeaf>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        lossy_luma_coefficients,
        lossy_luma_4x8_transform,
        lossy_chroma_8x4_coefficients,
        lossy_luma_4x4_split,
        ..
    } = syntax;

    let luma_top = bottom_edge_4_for_4x8(&above.planes[0]);
    let luma_left = left.map_or([luma_top[0]; 16], |neighbor| {
        right_edge_16(&neighbor.planes[0])
    });
    let luma = if let Some(split) = lossy_luma_4x4_split {
        reconstruct_lossy_luma_4x16_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top[0],
            left.is_some(),
            split,
        )?
    } else {
        match luma_predictor {
            LumaPredictor::Dc => reconstruct_lossy_luma_4x16_from_prediction(
                [rectangular_dc_predictor(&luma_top, &luma_left); 64],
                lossy_luma_coefficients,
                lossy_luma_4x8_transform,
            ),
            LumaPredictor::Vertical => reconstruct_lossy_luma_4x16_from_prediction(
                std::array::from_fn(|index| luma_top[index % 4]),
                lossy_luma_coefficients,
                lossy_luma_4x8_transform,
            ),
            LumaPredictor::Horizontal => reconstruct_lossy_luma_4x16_from_prediction(
                std::array::from_fn(|index| luma_left[index / 4]),
                lossy_luma_coefficients,
                lossy_luma_4x8_transform,
            ),
            LumaPredictor::Paeth => reconstruct_lossy_luma_4x16_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(luma_top[index % 4], luma_left[index / 4], luma_left[0])
                }),
                lossy_luma_coefficients,
                lossy_luma_4x8_transform,
            ),
            LumaPredictor::Diagonal203 => reconstruct_lossy_luma_4x16_diagonal_z3(
                luma_left,
                luma_left[0],
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_coefficients,
                lossy_luma_4x8_transform,
            )?,
            LumaPredictor::Diagonal113 | LumaPredictor::Diagonal157 => {
                reconstruct_lossy_luma_4x16_diagonal_z2(
                    luma_top,
                    luma_left,
                    luma_left[0],
                    luma_angle.ok_or(PortableUnavailable)?,
                    lossy_luma_coefficients,
                    lossy_luma_4x8_transform,
                )?
            }
            LumaPredictor::Smooth => reconstruct_lossy_luma_4x16_smooth(
                luma_top,
                luma_left,
                lossy_luma_coefficients,
                lossy_luma_4x8_transform,
            ),
            LumaPredictor::SmoothVertical => reconstruct_lossy_luma_4x16_smooth_vertical(
                luma_top,
                luma_left[15],
                lossy_luma_coefficients,
                lossy_luma_4x8_transform,
            ),
            LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_4x16_smooth_horizontal(
                luma_left,
                luma_top[3],
                lossy_luma_coefficients,
                lossy_luma_4x8_transform,
            ),
            _ => return Err(PortableUnavailable),
        }
    };

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top = bottom_edge_4_padded(&above.planes[plane]);
        let left = left.map_or([top[0]; 8], |neighbor| {
            right_edge_for_4x8(&neighbor.planes[plane])
        });
        let coefficients = lossy_chroma_8x4_coefficients[plane.saturating_sub(1)];
        let transform = chroma_rect_transform_kind(chroma_predictor);
        match chroma_predictor {
            ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_4x8(
                [rectangular_dc_predictor(&top, &left); 4],
                [rectangular_dc_predictor(&top, &left); 8],
                coefficients,
                transform,
            )),
            ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_4x8_from_prediction(
                std::array::from_fn(|index| top[index % 4]),
                coefficients,
                transform,
            )),
            ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_4x8_from_prediction(
                std::array::from_fn(|index| left[index / 4]),
                coefficients,
                transform,
            )),
            ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_4x8_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 4], left[index / 4], left[0])
                }),
                coefficients,
                transform,
            )),
            _ => Err(PortableUnavailable),
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

// The AV1 walker keeps each positioned upper and left neighbor tuple explicit
// so the optional edge samples cannot be detached from the current R8x16
// block's checked geometry.
#[expect(
    clippy::too_many_arguments,
    reason = "R8x16 reconstruction keeps independently positioned AV1 neighbor geometry explicit"
)]
fn reconstruct_following_lossy_420_vertical_8x16_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
    left_luma_edge_16: Option<[u16; 16]>,
    left_luma_bottom: Option<[u16; 8]>,
    left_y_offset: u32,
    left_neighbor_width: u32,
    left_neighbor_height: u32,
    top_left_sample: Option<u16>,
    above_right_is_above_left: bool,
    above_left_width: u32,
    above_right_width: u32,
    above_left_x_offset: u32,
    above_right_x_offset: u32,
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        lossy_luma_rect_coefficients,
        lossy_luma_rect_transform,
        lossy_luma_8x8_split,
        lossy_chroma_8x4_coefficients,
        ..
    } = syntax;

    let luma_top = if above_right_is_above_left {
        bottom_edge_at::<16>(&above_left.planes[0], above_left_width, above_left_x_offset)
    } else {
        combined_bottom_edge::<16>(
            &above_left.planes[0],
            above_left_width,
            above_left_x_offset,
            &above_right.planes[0],
            above_right_width,
            above_right_x_offset,
        )
    };
    let has_left = left_luma_edge_16.is_some()
        || (left_neighbor.is_some() && left_y_offset.saturating_add(16) <= left_neighbor_height);
    let luma_left = left_luma_edge_16.unwrap_or_else(|| {
        if has_left {
            left_neighbor.map_or([luma_top[0]; 16], |neighbor| {
                right_edge_at::<16>(
                    &neighbor.planes[0],
                    left_neighbor_width,
                    left_neighbor_height,
                    left_y_offset,
                )
            })
        } else {
            [luma_top[0]; 16]
        }
    });
    let smooth_edges = |predictor: LumaPredictor| {
        matches!(
            predictor,
            LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
        )
    };
    let smooth_neighbor_edges = smooth_edges(above_left.luma_predictor)
        || left_neighbor.is_some_and(|neighbor| smooth_edges(neighbor.luma_predictor));
    let luma_top_left = top_left_sample
        .or_else(|| {
            above_left_x_offset
                .checked_sub(1)
                .map(|offset| bottom_sample_at(&above_left.planes[0], above_left_width, offset))
        })
        .or_else(|| above_left.planes[0].samples.last().copied())
        .unwrap_or(luma_top[0]);

    let luma = if let Some(split) = lossy_luma_8x8_split {
        match reconstruct_lossy_luma_8x16_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top_left,
            has_left,
            split,
        ) {
            Ok(luma) => luma,
            Err(_) => {
                return Err(PortableUnavailable);
            }
        }
    } else {
        match (luma_predictor, luma_angle) {
            (LumaPredictor::Diagonal157, Some(angle)) => reconstruct_lossy_luma_8x16_diagonal(
                luma_top,
                luma_left,
                angle,
                enable_intra_edge_filter,
                lossy_luma_rect_coefficients.unwrap_or([0_i32; 128]),
                lossy_luma_rect_transform,
            )
            .or_else(|_| {
                Ok(reconstruct_lossy_luma_8x16(
                    rectangular_dc_predictor(&luma_top, &luma_left),
                    lossy_luma_rect_coefficients,
                    lossy_luma_rect_transform,
                ))
            })?,
            (LumaPredictor::Vertical, _) => reconstruct_lossy_luma_8x16_from_prediction(
                std::array::from_fn(|index| luma_top[index % 8]),
                lossy_luma_rect_coefficients,
                lossy_luma_rect_transform,
            ),
            (LumaPredictor::Horizontal | LumaPredictor::Diagonal203, Some(angle))
                if 180 < angle && angle < 270 =>
            {
                reconstruct_lossy_luma_8x16_diagonal_z3(
                    luma_left,
                    luma_top_left,
                    left_luma_bottom,
                    angle,
                    enable_intra_edge_filter,
                    smooth_neighbor_edges,
                    lossy_luma_rect_coefficients,
                    lossy_luma_rect_transform,
                )?
            }
            (LumaPredictor::Horizontal, _) => reconstruct_lossy_luma_8x16_from_prediction(
                std::array::from_fn(|index| luma_left[index / 8]),
                lossy_luma_rect_coefficients,
                lossy_luma_rect_transform,
            ),
            (LumaPredictor::Paeth, _) => {
                let prediction = if has_left {
                    std::array::from_fn(|index| {
                        paeth_predictor(luma_top[index % 8], luma_left[index / 8], luma_top_left)
                    })
                } else {
                    std::array::from_fn(|index| luma_top[index % 8])
                };
                reconstruct_lossy_luma_8x16_from_prediction(
                    prediction,
                    lossy_luma_rect_coefficients,
                    lossy_luma_rect_transform,
                )
            }
            _ => reconstruct_lossy_luma_8x16(
                rectangular_dc_predictor(&luma_top, &luma_left),
                lossy_luma_rect_coefficients,
                lossy_luma_rect_transform,
            ),
        }
    };

    let chroma = |plane: usize| -> ReconstructedPlane {
        let top = if std::ptr::eq(above_left, above_right) {
            bottom_edge_8_for_16x4_chroma(&above_left.planes[plane])
        } else {
            let left = bottom_edge_4(&above_left.planes[plane]);
            let right = bottom_edge_4(&above_right.planes[plane]);
            [
                left[0], left[1], left[2], left[3], right[0], right[1], right[2], right[3],
            ]
        };
        let left = left_neighbor.map_or([top[0]; 8], |neighbor| {
            right_edge_for_4x8(&neighbor.planes[plane])
        });
        let coefficients = lossy_chroma_8x4_coefficients[plane.saturating_sub(1)];
        let transform = chroma_rect_transform_kind(chroma_predictor);
        match chroma_predictor {
            ChromaPredictor::Vertical => reconstruct_lossy_luma_4x8_from_prediction(
                std::array::from_fn(|index| top[index % 4]),
                coefficients,
                transform,
            ),
            ChromaPredictor::Horizontal => reconstruct_lossy_luma_4x8_from_prediction(
                std::array::from_fn(|index| left[index / 4]),
                coefficients,
                transform,
            ),
            ChromaPredictor::Paeth => reconstruct_lossy_luma_4x8_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 4], left[index / 4], left[0])
                }),
                coefficients,
                transform,
            ),
            _ => reconstruct_lossy_luma_4x8(
                [rectangular_dc_predictor(&top, &left); 4],
                [rectangular_dc_predictor(&top, &left); 8],
                coefficients,
                transform,
            ),
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1), chroma(2)],
    })
}

fn reconstruct_following_lossy_full_horizontal_8x32_leaf(
    syntax: BlockSyntax,
    left_neighbor: &ClosedLeaf,
) -> PortableResult<ClosedLeaf> {
    let luma_left = right_edge_8x32(&left_neighbor.planes[0]);
    let luma_top = [luma_left[0]; 8];
    let luma_coefficients = syntax.lossy_luma_8x32_coefficients;
    let luma = match syntax.luma_predictor {
        LumaPredictor::Dc => {
            let predictor = rectangular_dc_predictor(&luma_top, &luma_left);
            reconstruct_lossy_luma_8x32(predictor, luma_coefficients)
        }
        LumaPredictor::Vertical => {
            let prediction: [u16; 256] = std::array::from_fn(|index| luma_top[index % 8]);
            let residual = transform::inverse_dct8x32(&luma_coefficients.unwrap_or([0_i32; 256]));
            reconstruct_lossy_predicted_plane(&prediction, &residual)
        }
        LumaPredictor::Horizontal => {
            let prediction: [u16; 256] = std::array::from_fn(|index| luma_left[index / 8]);
            let residual = transform::inverse_dct8x32(&luma_coefficients.unwrap_or([0_i32; 256]));
            reconstruct_lossy_predicted_plane(&prediction, &residual)
        }
        LumaPredictor::Smooth => {
            reconstruct_lossy_chroma_8x32_smooth(luma_top, luma_left, luma_coefficients)
        }
        LumaPredictor::DiagonalDownRight
        | LumaPredictor::Diagonal113
        | LumaPredictor::Diagonal157 => reconstruct_lossy_chroma_8x32_diagonal_z2(
            luma_top,
            luma_left,
            syntax.luma_angle.ok_or(PortableUnavailable)?,
            luma_coefficients,
        )?,
        LumaPredictor::Paeth => {
            let prediction: [u16; 256] = std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 8], luma_left[index / 8], luma_left[0])
            });
            let residual = transform::inverse_dct8x32(&luma_coefficients.unwrap_or([0_i32; 256]));
            reconstruct_lossy_predicted_plane(&prediction, &residual)
        }
        _ => reconstruct_lossy_luma_8x32(luma_left[0], luma_coefficients),
    };

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let left = right_edge_8x32(&left_neighbor.planes[plane]);
        let top = [left[0]; 8];
        match syntax.chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_full_8x32_cfl(
                    &luma,
                    rectangular_dc_predictor(&top, &left),
                    alpha,
                    syntax.lossy_chroma_8x32_coefficients[plane - 1],
                )
            }
            _ => reconstruct_lossy_full_8x32_chroma(
                syntax.chroma_predictor,
                syntax.chroma_angle,
                top,
                left,
                syntax.lossy_chroma_8x32_coefficients[plane - 1],
            ),
        }
    };

    let chroma_u = chroma(1)?;
    let chroma_v = chroma(2)?;
    Ok(ClosedLeaf {
        luma_predictor: syntax.luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_420_vertical_8x32_leaf(
    syntax: BlockSyntax,
    above: &ClosedLeaf,
) -> ClosedLeaf {
    // The 8×32 leaf is the first vertically extended lossy terminal. The
    // syntax and transform are fully decoded above; use the available upper
    // edge to seed the scalar predictor while the wider edge-aware predictor
    // families are integrated with the frame walker.
    let luma_top = bottom_edge(&above.planes[0]);
    let chroma_top_u = bottom_edge_4(&above.planes[1]);
    let chroma_top_v = bottom_edge_4(&above.planes[2]);
    let luma_predictor = match syntax.luma_predictor {
        LumaPredictor::Vertical => luma_top[0],
        LumaPredictor::Dc => one_sided_dc_predictor(luma_top),
        _ => syntax.luma_predictor.sample(),
    };
    let predictors = [
        luma_predictor,
        one_sided_dc_predictor_4(chroma_top_u),
        one_sided_dc_predictor_4(chroma_top_v),
    ];
    reconstruct_leaf(syntax, predictors)
}

// The upper width/offset pairs describe the original positioned leaves, while
// `above_right_is_above_left` preserves their identity after leaf cloning.
#[expect(
    clippy::too_many_arguments,
    reason = "R16x8 reconstruction carries validated upper-neighbor geometry explicitly"
)]
fn reconstruct_following_lossy_420_vertical_16x8_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_luma_edge: Option<[u16; 8]>,
    above_right_is_above_left: bool,
    above_left_width: u32,
    above_right_width: u32,
    above_left_x_offset: u32,
    above_right_x_offset: u32,
) -> PortableResult<ClosedLeaf> {
    let luma_top = if above_right_is_above_left {
        bottom_edge_at::<16>(&above_left.planes[0], above_left_width, above_left_x_offset)
    } else {
        combined_bottom_edge::<16>(
            &above_left.planes[0],
            above_left_width,
            above_left_x_offset,
            &above_right.planes[0],
            above_right_width,
            above_right_x_offset,
        )
    };
    let chroma_top = |plane: usize| {
        let left = bottom_edge_4(&above_left.planes[plane]);
        let right = bottom_edge_4(&above_right.planes[plane]);
        [
            left[0], left[1], left[2], left[3], right[0], right[1], right[2], right[3],
        ]
    };
    let luma_predictor = match syntax.luma_predictor {
        LumaPredictor::Vertical => luma_top[0],
        LumaPredictor::Dc => one_sided_dc_predictor_16(luma_top),
        _ => syntax.luma_predictor.sample(),
    };
    let predictors = [
        luma_predictor,
        one_sided_dc_predictor(chroma_top(1)),
        one_sided_dc_predictor(chroma_top(2)),
    ];
    let mut leaf = reconstruct_leaf(syntax, predictors);
    if let Some(split) = syntax.lossy_luma_8x8_split {
        // A depth-one R16x8 leaf is two TX_8X8 children side by side. The
        // generic R16x8 reconstruction policy only has the single residual
        // slot used by an unsplit transform, so replace its luma with the
        // child reconstruction while retaining the shared luma predictor.
        let left = left_luma_edge.unwrap_or([luma_top[0]; 8]);
        leaf.planes[0] = reconstruct_lossy_luma_16x8_split(
            syntax.luma_predictor,
            syntax.luma_angle,
            syntax.filter_intra_mode,
            luma_top,
            left,
            luma_top[0],
            true,
            split,
        )?;
    } else if syntax.filter_intra_mode.is_none() {
        // Smooth luma prediction is edge-aware. The generic leaf policy only
        // has a scalar predictor, so replace its luma plane with the exact
        // R16x8 reconstruction when the transform is unsplit. DC must use
        // both positioned edges for an interior block; the generic policy's
        // scalar predictor only sees the top edge.
        let left = left_luma_edge.unwrap_or([luma_top[0]; 8]);
        leaf.planes[0] = match syntax.luma_predictor {
            LumaPredictor::Dc => {
                let predictor = left_luma_edge.map_or_else(
                    || one_sided_dc_predictor_16(luma_top),
                    |left| rectangular_dc_predictor(&luma_top, &left),
                );
                reconstruct_lossy_luma_16x8(
                    predictor,
                    syntax.lossy_luma_16x8_coefficients,
                    syntax.lossy_luma_16x8_transform,
                )
            }
            LumaPredictor::Horizontal if matches!(syntax.luma_angle, None | Some(180)) => {
                let prediction = std::array::from_fn(|index| left[index / 16]);
                reconstruct_lossy_luma_16x8_from_prediction(
                    prediction,
                    syntax.lossy_luma_16x8_coefficients,
                    syntax.lossy_luma_16x8_transform,
                )
            }
            LumaPredictor::Paeth => {
                let top_left = left_luma_edge.map_or(luma_top[0], |left| left[0]);
                let prediction = std::array::from_fn(|index| {
                    left_luma_edge.map_or_else(
                        || luma_top[index % 16],
                        |left| paeth_predictor(luma_top[index % 16], left[index / 16], top_left),
                    )
                });
                reconstruct_lossy_luma_16x8_from_prediction(
                    prediction,
                    syntax.lossy_luma_16x8_coefficients,
                    syntax.lossy_luma_16x8_transform,
                )
            }
            LumaPredictor::Smooth => reconstruct_lossy_chroma_16x8_smooth(
                luma_top,
                left,
                syntax.lossy_luma_16x8_coefficients,
                syntax.lossy_luma_16x8_transform,
            ),
            LumaPredictor::SmoothVertical => reconstruct_lossy_chroma_16x8_smooth_vertical(
                luma_top,
                left,
                syntax.lossy_luma_16x8_coefficients,
                syntax.lossy_luma_16x8_transform,
            ),
            LumaPredictor::SmoothHorizontal => reconstruct_lossy_chroma_16x8_smooth_horizontal(
                luma_top,
                left,
                syntax.lossy_luma_16x8_coefficients,
                syntax.lossy_luma_16x8_transform,
            ),
            _ => leaf.planes[0].clone(),
        };
    }
    Ok(leaf)
}

fn reconstruct_following_lossy_420_vertical_64x16_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        chroma_predictor,
        chroma_angle: _,
        lossy_luma_64x16_coefficients,
        lossy_chroma_32x8_coefficients,
        ..
    } = syntax;

    let luma_top: [u16; 64] = if std::ptr::eq(above_left, above_right) {
        bottom_edge_64(&above_left.planes[0])
    } else {
        let left = bottom_edge_32(&above_left.planes[0]);
        let right = bottom_edge_32(&above_right.planes[0]);
        std::array::from_fn(|index| {
            if index < 32 {
                left[index]
            } else {
                right[index - 32]
            }
        })
    };
    let luma_left = left_neighbor.map_or([luma_top[0]; 16], |neighbor| {
        right_edge_64x16(&neighbor.planes[0])
    });
    let luma = match luma_predictor {
        LumaPredictor::Dc => reconstruct_lossy_luma_64x16_from_prediction(
            [rectangular_dc_predictor(&luma_top, &luma_left); 1024],
            lossy_luma_64x16_coefficients,
        ),
        LumaPredictor::Vertical => reconstruct_lossy_luma_64x16_from_prediction(
            std::array::from_fn(|index| luma_top[index % 64]),
            lossy_luma_64x16_coefficients,
        ),
        LumaPredictor::Horizontal => reconstruct_lossy_luma_64x16_from_prediction(
            std::array::from_fn(|index| luma_left[index / 64]),
            lossy_luma_64x16_coefficients,
        ),
        LumaPredictor::Paeth => reconstruct_lossy_luma_64x16_from_prediction(
            std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 64], luma_left[index / 64], luma_top[0])
            }),
            lossy_luma_64x16_coefficients,
        ),
        LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_64x16_smooth_horizontal(
            luma_top,
            luma_left,
            lossy_luma_64x16_coefficients,
        ),
        _ => return Err(PortableUnavailable),
    };

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top: [u16; 32] = if std::ptr::eq(above_left, above_right) {
            bottom_edge_32x8(&above_left.planes[plane])
        } else {
            let left = bottom_edge_16x8(&above_left.planes[plane]);
            let right = bottom_edge_16x8(&above_right.planes[plane]);
            std::array::from_fn(|index| {
                if index < 16 {
                    left[index]
                } else {
                    right[index - 16]
                }
            })
        };
        let left = left_neighbor.map_or([top[0]; 8], |neighbor| {
            right_edge_32x8(&neighbor.planes[plane])
        });
        let coefficients = lossy_chroma_32x8_coefficients[plane.saturating_sub(1)];
        match chroma_predictor {
            ChromaPredictor::Dc => reconstruct_lossy_chroma_32x8_from_prediction(
                [rectangular_dc_predictor(&top, &left); 256],
                coefficients,
            ),
            ChromaPredictor::Vertical => reconstruct_lossy_chroma_32x8_from_prediction(
                std::array::from_fn(|index| top[index % 32]),
                coefficients,
            ),
            ChromaPredictor::Horizontal => {
                reconstruct_lossy_chroma_32x8_from_prediction_with_transform(
                    std::array::from_fn(|index| left[index / 32]),
                    coefficients,
                    LossyTransformKind::DctAdst,
                )
            }
            ChromaPredictor::Paeth => reconstruct_lossy_chroma_32x8_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 32], left[index / 32], top[0])
                }),
                coefficients,
            ),
            _ => Err(PortableUnavailable),
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

fn reconstruct_following_lossy_420_vertical_32x8_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle: _,
        lossy_luma_32x8_coefficients,
        lossy_chroma_16x4_coefficients,
        ..
    } = syntax;

    let luma_top: [u16; 32] = if std::ptr::eq(above_left, above_right) {
        bottom_edge_32(&above_left.planes[0])
    } else {
        let left = bottom_edge_16(&above_left.planes[0]);
        let right = bottom_edge_16(&above_right.planes[0]);
        std::array::from_fn(|index| {
            if index < 16 {
                left[index]
            } else {
                right[index - 16]
            }
        })
    };
    let luma_left =
        left_neighbor.map_or([luma_top[0]; 8], |neighbor| right_edge(&neighbor.planes[0]));
    let luma = match luma_predictor {
        LumaPredictor::Dc => reconstruct_lossy_luma_32x8_from_prediction(
            [rectangular_dc_predictor(&luma_top, &luma_left); 256],
            lossy_luma_32x8_coefficients,
        ),
        LumaPredictor::Vertical => reconstruct_lossy_luma_32x8_from_prediction(
            std::array::from_fn(|index| luma_top[index % 32]),
            lossy_luma_32x8_coefficients,
        ),
        LumaPredictor::Horizontal => reconstruct_lossy_luma_32x8_from_prediction(
            std::array::from_fn(|index| luma_left[index / 32]),
            lossy_luma_32x8_coefficients,
        ),
        LumaPredictor::Paeth => reconstruct_lossy_luma_32x8_from_prediction(
            std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 32], luma_left[index / 32], luma_top[0])
            }),
            lossy_luma_32x8_coefficients,
        ),
        LumaPredictor::DiagonalDownRight
        | LumaPredictor::Diagonal113
        | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_32x8_diagonal_z2(
            luma_top,
            luma_left,
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_32x8_coefficients,
        )?,
        LumaPredictor::Diagonal203 => reconstruct_lossy_luma_32x8_diagonal_z3(
            luma_left,
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_32x8_coefficients,
        )?,
        LumaPredictor::Smooth => {
            reconstruct_lossy_luma_32x8_smooth(luma_top, luma_left, lossy_luma_32x8_coefficients)
        }
        LumaPredictor::SmoothVertical => reconstruct_lossy_luma_32x8_smooth_vertical(
            luma_top,
            luma_left,
            lossy_luma_32x8_coefficients,
        ),
        LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_32x8_smooth_horizontal(
            luma_top,
            luma_left,
            lossy_luma_32x8_coefficients,
        ),
        _ => return Err(PortableUnavailable),
    };

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top: [u16; 16] = if std::ptr::eq(above_left, above_right) {
            bottom_edge_16(&above_left.planes[plane])
        } else {
            let left = bottom_edge_8_for_16x4_chroma(&above_left.planes[plane]);
            let right = bottom_edge_8_for_16x4_chroma(&above_right.planes[plane]);
            std::array::from_fn(|index| {
                if index < 8 {
                    left[index]
                } else {
                    right[index - 8]
                }
            })
        };
        let left = left_neighbor.map_or([top[0]; 4], |neighbor| {
            right_edge_4(&neighbor.planes[plane])
        });
        let coefficients = lossy_chroma_16x4_coefficients[plane.saturating_sub(1)];

        match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_chroma_16x4_cfl(
                    &luma,
                    rectangular_dc_predictor(&top, &left),
                    alpha,
                    coefficients,
                )
            }
            ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_16x4(
                rectangular_dc_predictor(&top, &left),
                coefficients,
                Lossy4x8TransformKind::DctDct,
            )),
            ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_16x4_vertical(
                top,
                coefficients,
                Lossy4x8TransformKind::DctDct,
            )),
            ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_16x4_horizontal(
                left,
                coefficients,
                Lossy4x8TransformKind::DctDct,
            )),
            ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_16x4_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 16], left[index / 16], top[0])
                }),
                coefficients,
                Lossy4x8TransformKind::DctDct,
            )),
            _ => Err(PortableUnavailable),
        }
    };

    let chroma_u = chroma(1)?;
    let chroma_v = chroma(2)?;
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_full_vertical_32x8_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_8x8_grid_split,
        lossy_luma_32x8_coefficients,
        lossy_chroma_32x8_coefficients,
        ..
    } = syntax;

    let luma_top = if std::ptr::eq(above_left, above_right) {
        bottom_edge_32(&above_left.planes[0])
    } else {
        let left = bottom_edge_16(&above_left.planes[0]);
        let right = bottom_edge_16(&above_right.planes[0]);
        std::array::from_fn(|index| {
            if index < 16 {
                left[index]
            } else {
                right[index - 16]
            }
        })
    };
    let luma_left = left_neighbor.map_or([luma_top[0]; 8], |neighbor| {
        right_edge_32x8(&neighbor.planes[0])
    });
    let luma = if let Some(split) = lossy_luma_8x8_grid_split {
        reconstruct_lossy_luma_32x8_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top[0],
            left_neighbor.is_some(),
            split,
        )?
    } else {
        match luma_predictor {
            LumaPredictor::Dc => reconstruct_lossy_luma_32x8_from_prediction(
                [rectangular_dc_predictor(&luma_top, &luma_left); 256],
                lossy_luma_32x8_coefficients,
            ),
            LumaPredictor::Vertical => reconstruct_lossy_luma_32x8_from_prediction(
                std::array::from_fn(|index| luma_top[index % 32]),
                lossy_luma_32x8_coefficients,
            ),
            LumaPredictor::Horizontal => reconstruct_lossy_luma_32x8_from_prediction(
                std::array::from_fn(|index| luma_left[index / 32]),
                lossy_luma_32x8_coefficients,
            ),
            LumaPredictor::Paeth => reconstruct_lossy_luma_32x8_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(luma_top[index % 32], luma_left[index / 32], luma_top[0])
                }),
                lossy_luma_32x8_coefficients,
            ),
            LumaPredictor::DiagonalDownRight
            | LumaPredictor::Diagonal113
            | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_32x8_diagonal_z2(
                luma_top,
                luma_left,
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_32x8_coefficients,
            )?,
            LumaPredictor::Diagonal203 => reconstruct_lossy_luma_32x8_diagonal_z3(
                luma_left,
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_32x8_coefficients,
            )?,
            LumaPredictor::Smooth => reconstruct_lossy_luma_32x8_smooth(
                luma_top,
                luma_left,
                lossy_luma_32x8_coefficients,
            ),
            LumaPredictor::SmoothVertical => reconstruct_lossy_luma_32x8_smooth_vertical(
                luma_top,
                luma_left,
                lossy_luma_32x8_coefficients,
            ),
            LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_32x8_smooth_horizontal(
                luma_top,
                luma_left,
                lossy_luma_32x8_coefficients,
            ),
            _ => return Err(PortableUnavailable),
        }
    };

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top = if std::ptr::eq(above_left, above_right) {
            bottom_edge_32(&above_left.planes[plane])
        } else {
            let left = bottom_edge_16(&above_left.planes[plane]);
            let right = bottom_edge_16(&above_right.planes[plane]);
            std::array::from_fn(|index| {
                if index < 16 {
                    left[index]
                } else {
                    right[index - 16]
                }
            })
        };
        let left = left_neighbor.map_or([top[0]; 8], |neighbor| {
            right_edge_32x8(&neighbor.planes[plane])
        });
        let coefficients = lossy_chroma_32x8_coefficients[plane - 1];
        match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_full_32x8_cfl(
                    &luma,
                    rectangular_dc_predictor(&top, &left),
                    alpha,
                    coefficients,
                )
            }
            _ => reconstruct_lossy_full_32x8_chroma(
                chroma_predictor,
                chroma_angle,
                top,
                left,
                coefficients,
            ),
        }
    };

    let chroma_u = chroma(1)?;
    let chroma_v = chroma(2)?;
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_420_vertical_32x16_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
    above_right_is_above_left: bool,
    neighbors: &VerticalNeighbors<'_>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_16x16_horizontal_split,
        lossy_luma_8x8_grid_split,
        lossy_luma_32x16_coefficients,
        lossy_chroma_16x8_coefficients,
        ..
    } = syntax;

    let luma_top: [u16; 32] = if above_right_is_above_left {
        bottom_edge_at::<32>(
            &above_left.planes[0],
            neighbors.above_left_width,
            neighbors.above_left_x_offset,
        )
    } else {
        combined_bottom_edge::<32>(
            &above_left.planes[0],
            neighbors.above_left_width,
            neighbors.above_left_x_offset,
            &above_right.planes[0],
            neighbors.above_right_width,
            neighbors.above_right_x_offset,
        )
    };
    let luma_left = left_neighbor.map_or([luma_top[0]; 16], |neighbor| {
        right_edge_16(&neighbor.planes[0])
    });
    let luma = if let Some(split) = lossy_luma_16x16_horizontal_split {
        reconstruct_lossy_luma_32x16_horizontal_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top[0],
            left_neighbor.is_some(),
            split,
        )?
    } else if let Some(split) = lossy_luma_8x8_grid_split {
        let result = reconstruct_lossy_luma_32x16_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top[0],
            left_neighbor.is_some(),
            split,
        );

        result?
    } else {
        let luma_dc = if left_neighbor.is_some() {
            rectangular_dc_predictor(&luma_top, &luma_left)
        } else {
            one_sided_dc_predictor_32(luma_top)
        };
        match luma_predictor {
            LumaPredictor::Dc => reconstruct_lossy_luma_32x16_from_prediction(
                [luma_dc; 512],
                lossy_luma_32x16_coefficients,
            ),
            LumaPredictor::Vertical => reconstruct_lossy_luma_32x16_from_prediction(
                std::array::from_fn(|index| luma_top[index % 32]),
                lossy_luma_32x16_coefficients,
            ),
            LumaPredictor::Horizontal => reconstruct_lossy_luma_32x16_from_prediction(
                std::array::from_fn(|index| luma_left[index / 32]),
                lossy_luma_32x16_coefficients,
            ),
            LumaPredictor::Paeth => reconstruct_lossy_luma_32x16_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(luma_top[index % 32], luma_left[index / 32], luma_top[0])
                }),
                lossy_luma_32x16_coefficients,
            ),
            LumaPredictor::DiagonalDownRight
            | LumaPredictor::Diagonal113
            | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_32x16_diagonal_z2(
                luma_top,
                luma_left,
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_32x16_coefficients,
            )?,
            LumaPredictor::Diagonal203 => reconstruct_lossy_luma_32x16_diagonal_z3(
                luma_left,
                luma_top[0],
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_32x16_coefficients,
            )?,
            _ => return Err(PortableUnavailable),
        }
    };

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top: [u16; 16] = if above_right_is_above_left {
            bottom_edge_at::<16>(
                &above_left.planes[plane],
                neighbors.above_left_width.div_ceil(2).max(4),
                neighbors.above_left_x_offset.div_ceil(2),
            )
        } else {
            combined_bottom_edge::<16>(
                &above_left.planes[plane],
                neighbors.above_left_width.div_ceil(2).max(4),
                neighbors.above_left_x_offset.div_ceil(2),
                &above_right.planes[plane],
                neighbors.above_right_width.div_ceil(2).max(4),
                neighbors.above_right_x_offset.div_ceil(2),
            )
        };
        let left =
            left_neighbor.map_or([top[0]; 8], |neighbor| right_edge(&neighbor.planes[plane]));
        let coefficients = lossy_chroma_16x8_coefficients[plane.saturating_sub(1)];
        let transform_kind = chroma_rect_transform_kind(chroma_predictor);

        match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                Ok(reconstruct_lossy_chroma_16x8_cfl(
                    &luma,
                    rectangular_dc_predictor(&top, &left),
                    alpha,
                    coefficients,
                )?)
            }
            ChromaPredictor::Dc => {
                let predictor = if left_neighbor.is_some() {
                    rectangular_dc_predictor(&top, &left)
                } else {
                    one_sided_dc_predictor_16(top)
                };
                Ok(reconstruct_lossy_chroma_16x8_from_prediction(
                    [predictor; 128],
                    coefficients,
                    transform_kind,
                ))
            }
            ChromaPredictor::Vertical => Ok(reconstruct_lossy_chroma_16x8_from_prediction(
                std::array::from_fn(|index| top[index % 16]),
                coefficients,
                transform_kind,
            )),
            ChromaPredictor::Horizontal => Ok(reconstruct_lossy_chroma_16x8_from_prediction(
                std::array::from_fn(|index| left[index / 16]),
                coefficients,
                transform_kind,
            )),
            ChromaPredictor::DiagonalDownRight
            | ChromaPredictor::Diagonal113
            | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_16x8_diagonal_z2(
                top,
                left,
                chroma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                transform_kind,
            ),
            ChromaPredictor::Smooth => Ok(reconstruct_lossy_chroma_16x8_smooth(
                top,
                left,
                coefficients,
                transform_kind,
            )),
            ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_chroma_16x8_smooth_vertical(
                top,
                left,
                coefficients,
                transform_kind,
            )),
            ChromaPredictor::SmoothHorizontal => {
                Ok(reconstruct_lossy_chroma_16x8_smooth_horizontal(
                    top,
                    left,
                    coefficients,
                    transform_kind,
                ))
            }
            ChromaPredictor::Paeth => Ok(reconstruct_lossy_chroma_16x8_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 16], left[index / 16], top[0])
                }),
                coefficients,
                transform_kind,
            )),
            ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_16x8_diagonal_z3(
                left,
                top[0],
                chroma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                transform_kind,
            ),
            _ => Err(PortableUnavailable),
        }
    };

    let chroma_u = chroma(1).map_err(|_| PortableUnavailable)?;
    let chroma_v = chroma(2).map_err(|_| PortableUnavailable)?;

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_full_horizontal_16x4_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
    neighbor_width: u32,
    neighbor_height: u32,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        lossy_luma_coefficients,
        lossy_luma_16x4_transform,
        lossy_chroma_16x4_coefficients,
        ..
    } = syntax;
    let luma_left = right_edge_at::<4>(&neighbor.planes[0], neighbor_width, neighbor_height, 0);
    let luma_top = [luma_left[0]; 16];
    let luma = match luma_predictor {
        LumaPredictor::Dc => reconstruct_lossy_luma_16x4(
            rectangular_dc_predictor(&luma_top, &luma_left),
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Vertical => reconstruct_lossy_luma_16x4_vertical(
            luma_top,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Horizontal => reconstruct_lossy_luma_16x4_horizontal(
            luma_left,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Smooth => reconstruct_lossy_luma_16x4_smooth(
            luma_top,
            luma_top[15],
            luma_left,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_16x4_smooth_horizontal(
            luma_left,
            luma_top[15],
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Paeth => reconstruct_lossy_luma_16x4_from_prediction(
            std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 16], luma_left[index / 16], luma_left[0])
            }),
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        ),
        LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_16x4_diagonal_z1(
                luma_top,
                luma_left[0],
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_coefficients,
                lossy_luma_16x4_transform,
            )?
        }
        LumaPredictor::Diagonal203 => reconstruct_lossy_luma_16x4_diagonal_z3(
            luma_left,
            luma_left[0],
            luma_angle.ok_or(PortableUnavailable)?,
            lossy_luma_coefficients,
            lossy_luma_16x4_transform,
        )?,
        _ => return Err(PortableUnavailable),
    };

    let luma_for_chroma = luma.clone();
    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let left = right_edge_at::<4>(&neighbor.planes[plane], neighbor_width, neighbor_height, 0);
        let top = [left[0]; 16];
        match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_full_16x4_cfl(
                    &luma_for_chroma,
                    left[0],
                    alpha,
                    lossy_chroma_16x4_coefficients[plane - 1],
                )
            }
            _ => reconstruct_lossy_full_16x4_chroma(
                chroma_predictor,
                chroma_angle,
                top,
                left,
                lossy_chroma_16x4_coefficients[plane - 1],
            ),
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

fn reconstruct_following_lossy_full_horizontal_32x16_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
    luma_left_edge_16: Option<[u16; 16]>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_16x16_horizontal_split,
        lossy_luma_8x8_grid_split,
        lossy_luma_32x16_coefficients,
        lossy_chroma_16x8_coefficients,
        ..
    } = syntax;

    let luma_left = luma_left_edge_16.unwrap_or_else(|| right_edge_16(&neighbor.planes[0]));
    let luma_top = [luma_left[0]; 32];
    let luma = if let Some(split) = lossy_luma_16x16_horizontal_split {
        reconstruct_lossy_luma_32x16_horizontal_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_left[0],
            true,
            split,
        )?
    } else if let Some(split) = lossy_luma_8x8_grid_split {
        reconstruct_lossy_luma_32x16_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_left[0],
            true,
            split,
        )?
    } else {
        let prediction = match luma_predictor {
            LumaPredictor::Dc => [one_sided_dc_predictor_32(luma_top); 512],
            LumaPredictor::Vertical => std::array::from_fn(|index| luma_top[index % 32]),
            LumaPredictor::Horizontal => std::array::from_fn(|index| luma_left[index / 32]),
            LumaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 32], luma_left[index / 32], luma_left[0])
            }),
            LumaPredictor::Diagonal203 => {
                return reconstruct_lossy_luma_32x16_diagonal_z3(
                    luma_left,
                    luma_left[0],
                    luma_angle.ok_or(PortableUnavailable)?,
                    lossy_luma_32x16_coefficients,
                )
                .map(|luma| ClosedLeaf {
                    luma_predictor,
                    planes: [
                        luma,
                        ReconstructedPlane {
                            samples: vec![128; 512],
                        },
                        ReconstructedPlane {
                            samples: vec![128; 512],
                        },
                    ],
                });
            }
            _ => [luma_predictor.sample(); 512],
        };
        reconstruct_lossy_luma_32x16_from_prediction(prediction, lossy_luma_32x16_coefficients)
    };

    let luma_samples = luma.samples.clone();
    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let left = right_edge_16(&neighbor.planes[plane]);
        let top = [left[0]; 32];
        let prediction = match chroma_predictor {
            ChromaPredictor::Dc => [one_sided_dc_predictor_32(top); 512],
            ChromaPredictor::Vertical => std::array::from_fn(|index| top[index % 32]),
            ChromaPredictor::Horizontal => std::array::from_fn(|index| left[index / 32]),
            ChromaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(top[index % 32], left[index / 32], left[0])
            }),
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                let dc = one_sided_dc_predictor_32(top);
                std::array::from_fn(|index| {
                    reconstruct_cfl_sample(
                        dc,
                        alpha,
                        i32::from(luma_samples[index]) - i32::from(dc),
                        0,
                    )
                })
            }
            _ => [128; 512],
        };

        if let Some(coefficients) = lossy_chroma_16x8_coefficients[plane - 1] {
            let reduced = reconstruct_lossy_full_16x8_chroma(
                chroma_predictor,
                chroma_angle,
                [left[0]; 16],
                left[..8].try_into().map_err(|_| PortableUnavailable)?,
                Some(coefficients),
            )?;
            let mut samples = Vec::with_capacity(512);
            for y in 0..16 {
                for x in 0..32 {
                    samples.push(reduced.samples[y / 2 * 16 + x / 2]);
                }
            }
            Ok(ReconstructedPlane { samples })
        } else {
            Ok(ReconstructedPlane {
                samples: prediction.to_vec(),
            })
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

fn reconstruct_following_lossy_full_horizontal_16x32_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_8x8_grid_split,
        lossy_luma_16x32_coefficients,
        lossy_luma_16x32_transform,
        lossy_chroma_8x16_coefficients,
        ..
    } = syntax;
    let luma_left: [u16; 32] = if neighbor.planes[0].samples.len() >= 512 {
        right_edge_at::<32>(&neighbor.planes[0], 16, 32, 0)
    } else {
        let edge = right_edge_16(&neighbor.planes[0]);
        std::array::from_fn(|index| edge[index % 16])
    };
    let luma_top = [luma_left[0]; 16];
    let luma = if let Some(split) = lossy_luma_8x8_grid_split {
        reconstruct_lossy_luma_16x32_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_left[0],
            true,
            split,
        )?
    } else if let Some(coefficients) = lossy_luma_16x32_coefficients {
        reconstruct_lossy_luma_16x32_from_edges(
            luma_predictor,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_left[0],
            true,
            coefficients,
            lossy_luma_16x32_transform,
        )?
    } else {
        let prediction = match luma_predictor {
            LumaPredictor::Dc => [one_sided_dc_predictor_32(luma_left); 512],
            LumaPredictor::Vertical => std::array::from_fn(|index| luma_top[index % 16]),
            LumaPredictor::Horizontal => std::array::from_fn(|index| luma_left[index / 16]),
            LumaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 16], luma_left[index / 16], luma_left[0])
            }),
            _ => [luma_predictor.sample(); 512],
        };
        ReconstructedPlane {
            samples: prediction.to_vec(),
        }
    };
    let luma_samples = luma.samples.clone();

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let left: [u16; 32] = if neighbor.planes[plane].samples.len() >= 128 {
            right_edge_at::<32>(&neighbor.planes[plane], 8, 16, 0)
        } else {
            let edge = right_edge(&neighbor.planes[plane]);
            std::array::from_fn(|index| edge[index % 8])
        };
        let top = [left[0]; 16];
        let prediction = match chroma_predictor {
            ChromaPredictor::Dc => [one_sided_dc_predictor_32(left); 512],
            ChromaPredictor::Vertical => std::array::from_fn(|index| top[index % 16]),
            ChromaPredictor::Horizontal => std::array::from_fn(|index| left[index / 16]),
            ChromaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(top[index % 16], left[index / 16], left[0])
            }),
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                let dc = one_sided_dc_predictor_32(left);
                std::array::from_fn(|index| {
                    reconstruct_cfl_sample(
                        dc,
                        alpha,
                        i32::from(luma_samples[index]) - i32::from(dc),
                        0,
                    )
                })
            }
            _ => [128; 512],
        };

        if let Some(coefficients) = lossy_chroma_8x16_coefficients[plane - 1] {
            let reduced = reconstruct_lossy_full_8x16_chroma(
                chroma_predictor,
                chroma_angle,
                top[..8].try_into().map_err(|_| PortableUnavailable)?,
                left[..16].try_into().map_err(|_| PortableUnavailable)?,
                Some(coefficients),
                enable_intra_edge_filter,
            )?;
            let mut samples = Vec::with_capacity(512);
            for y in 0..32 {
                for x in 0..16 {
                    samples.push(reduced.samples[y / 2 * 8 + x / 2]);
                }
            }
            Ok(ReconstructedPlane { samples })
        } else {
            Ok(ReconstructedPlane {
                samples: prediction.to_vec(),
            })
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

fn reconstruct_following_lossy_full_horizontal_16x64_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle: _,
        lossy_luma_16x64_coefficients,
        ..
    } = syntax;

    let edge_64 = |plane: usize| -> [u16; 64] {
        if neighbor.planes[plane].samples.len() >= 16 * 64 {
            right_edge_at::<64>(&neighbor.planes[plane], 16, 64, 0)
        } else {
            let edge = right_edge(&neighbor.planes[plane]);
            std::array::from_fn(|index| edge[index.min(edge.len().saturating_sub(1))])
        }
    };
    let luma_left = edge_64(0);
    let luma_top = [luma_left[0]; 16];
    let dc = |edge: &[u16]| -> u16 {
        let sum: u32 = edge.iter().map(|&sample| u32::from(sample)).sum();
        u16::try_from(sum / u32::try_from(edge.len()).unwrap_or(1)).unwrap_or(128)
    };
    let luma_prediction: [u16; 1024] = match luma_predictor {
        LumaPredictor::Dc => [dc(&luma_left); 1024],
        LumaPredictor::Vertical => std::array::from_fn(|index| luma_top[index % 16]),
        LumaPredictor::Horizontal => std::array::from_fn(|index| luma_left[index / 16]),
        LumaPredictor::Paeth => std::array::from_fn(|index| {
            paeth_predictor(luma_top[index % 16], luma_left[index / 16], luma_left[0])
        }),
        LumaPredictor::Diagonal203 => {
            return reconstruct_lossy_luma_16x64_diagonal_z3(
                luma_left,
                luma_angle.ok_or(PortableUnavailable)?,
                lossy_luma_16x64_coefficients,
            )
            .map(|luma| ClosedLeaf {
                luma_predictor,
                planes: [
                    luma,
                    ReconstructedPlane {
                        samples: vec![128; 1024],
                    },
                    ReconstructedPlane {
                        samples: vec![128; 1024],
                    },
                ],
            });
        }
        LumaPredictor::DiagonalDownRight
        | LumaPredictor::Diagonal113
        | LumaPredictor::Diagonal157 => {
            let angle = luma_angle.ok_or(PortableUnavailable)?;
            return reconstruct_lossy_luma_16x64_diagonal_z2(
                luma_top,
                luma_left,
                angle,
                lossy_luma_16x64_coefficients,
            )
            .map(|luma| ClosedLeaf {
                luma_predictor,
                planes: [
                    luma,
                    ReconstructedPlane {
                        samples: vec![128; 1024],
                    },
                    ReconstructedPlane {
                        samples: vec![128; 1024],
                    },
                ],
            });
        }
        LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal => {
            let bottom = i32::from(luma_left[63]);
            let right = i32::from(luma_top[15]);
            std::array::from_fn(|index| {
                let row = index / 16;
                let column = index % 16;
                let vertical = i32::try_from(255_usize.saturating_sub(row.saturating_mul(4)))
                    .unwrap_or(0)
                    .clamp(0, 255);
                let horizontal = i32::try_from(255_usize.saturating_sub(column.saturating_mul(16)))
                    .unwrap_or(0)
                    .clamp(0, 255);
                let value = vertical
                    .saturating_mul(i32::from(luma_top[column]))
                    .saturating_add((256 - vertical).saturating_mul(bottom))
                    .saturating_add(horizontal.saturating_mul(i32::from(luma_left[row])))
                    .saturating_add((256 - horizontal).saturating_mul(right))
                    .saturating_add(256)
                    >> 9;
                u16::try_from(value.clamp(0, 255)).unwrap_or(128)
            })
        }
        _ => [luma_predictor.sample(); 1024],
    };
    let luma = reconstruct_lossy_predicted_plane(
        &luma_prediction,
        &transform::inverse_dct16x64(&lossy_luma_16x64_coefficients.unwrap_or([0; 512])),
    );
    let luma_samples = luma.samples.clone();

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let left = edge_64(plane);
        let top = [left[0]; 16];
        let prediction = match chroma_predictor {
            ChromaPredictor::Dc => [dc(&left); 1024],
            ChromaPredictor::Vertical => std::array::from_fn(|index| top[index % 16]),
            ChromaPredictor::Horizontal => std::array::from_fn(|index| left[index / 16]),
            ChromaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(top[index % 16], left[index / 16], left[0])
            }),
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                let predictor = dc(&left);
                std::array::from_fn(|index| {
                    reconstruct_cfl_sample(
                        predictor,
                        alpha,
                        i32::from(luma_samples[index]) - i32::from(predictor),
                        0,
                    )
                })
            }
            _ => [128; 1024],
        };
        Ok(ReconstructedPlane {
            samples: prediction.to_vec(),
        })
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

fn reconstruct_following_lossy_full_vertical_16x32_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_8x8_grid_split,
        lossy_luma_16x32_coefficients,
        lossy_luma_16x32_transform,
        lossy_chroma_8x16_coefficients,
        ..
    } = syntax;
    let luma_top: [u16; 16] = if std::ptr::eq(above_left, above_right) {
        bottom_edge_16(&above_left.planes[0])
    } else {
        let left = bottom_edge_8_for_16x4_chroma(&above_left.planes[0]);
        let right = bottom_edge_8_for_16x4_chroma(&above_right.planes[0]);
        std::array::from_fn(|index| {
            if index < 8 {
                left[index]
            } else {
                right[index - 8]
            }
        })
    };
    let luma_left: [u16; 32] = left_neighbor.map_or([luma_top[0]; 32], |neighbor| {
        if neighbor.planes[0].samples.len() >= 512 {
            right_edge_at::<32>(&neighbor.planes[0], 16, 32, 0)
        } else {
            let edge = right_edge_16(&neighbor.planes[0]);
            std::array::from_fn(|index| edge[index % 16])
        }
    });
    let luma = if let Some(split) = lossy_luma_8x8_grid_split {
        reconstruct_lossy_luma_16x32_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top[0],
            left_neighbor.is_some(),
            split,
        )?
    } else if let Some(coefficients) = lossy_luma_16x32_coefficients {
        reconstruct_lossy_luma_16x32_from_edges(
            luma_predictor,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top[0],
            left_neighbor.is_some(),
            coefficients,
            lossy_luma_16x32_transform,
        )?
    } else {
        let prediction = match luma_predictor {
            LumaPredictor::Dc => [rectangular_dc_predictor(&luma_top, &luma_left); 512],
            LumaPredictor::Vertical => std::array::from_fn(|index| luma_top[index % 16]),
            LumaPredictor::Horizontal => std::array::from_fn(|index| luma_left[index / 16]),
            LumaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 16], luma_left[index / 16], luma_top[0])
            }),
            _ => [luma_predictor.sample(); 512],
        };
        ReconstructedPlane {
            samples: prediction.to_vec(),
        }
    };
    let luma_samples = luma.samples.clone();

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top: [u16; 16] = if std::ptr::eq(above_left, above_right) {
            bottom_edge_16(&above_left.planes[plane])
        } else {
            let left = bottom_edge_8_for_16x4_chroma(&above_left.planes[plane]);
            let right = bottom_edge_8_for_16x4_chroma(&above_right.planes[plane]);
            std::array::from_fn(|index| {
                if index < 8 {
                    left[index]
                } else {
                    right[index - 8]
                }
            })
        };
        let left: [u16; 32] = left_neighbor.map_or([top[0]; 32], |neighbor| {
            if neighbor.planes[plane].samples.len() >= 128 {
                right_edge_at::<32>(&neighbor.planes[plane], 8, 16, 0)
            } else {
                let edge = right_edge(&neighbor.planes[plane]);
                std::array::from_fn(|index| edge[index % 8])
            }
        });
        let prediction = match chroma_predictor {
            ChromaPredictor::Dc => [rectangular_dc_predictor(&top, &left); 512],
            ChromaPredictor::Vertical => std::array::from_fn(|index| top[index % 16]),
            ChromaPredictor::Horizontal => std::array::from_fn(|index| left[index / 16]),
            ChromaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(top[index % 16], left[index / 16], top[0])
            }),
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                let dc = rectangular_dc_predictor(&top, &left);
                std::array::from_fn(|index| {
                    reconstruct_cfl_sample(
                        dc,
                        alpha,
                        i32::from(luma_samples[index]) - i32::from(dc),
                        0,
                    )
                })
            }
            _ => [128; 512],
        };

        if let Some(coefficients) = lossy_chroma_8x16_coefficients[plane - 1] {
            let reduced = reconstruct_lossy_full_8x16_chroma(
                chroma_predictor,
                chroma_angle,
                top[..8].try_into().map_err(|_| PortableUnavailable)?,
                left[..16].try_into().map_err(|_| PortableUnavailable)?,
                Some(coefficients),
                enable_intra_edge_filter,
            )?;
            let mut samples = Vec::with_capacity(512);
            for y in 0..32 {
                for x in 0..16 {
                    samples.push(reduced.samples[y / 2 * 8 + x / 2]);
                }
            }
            Ok(ReconstructedPlane { samples })
        } else {
            Ok(ReconstructedPlane {
                samples: prediction.to_vec(),
            })
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma(1)?, chroma(2)?],
    })
}

fn reconstruct_following_lossy_full_vertical_32x16_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        lossy_luma_16x16_horizontal_split,
        lossy_luma_8x8_grid_split,
        lossy_luma_32x16_coefficients,
        chroma_predictor,
        chroma_angle,
        lossy_chroma_16x8_coefficients,
        ..
    } = syntax;
    let luma_top: [u16; 32] = if std::ptr::eq(above_left, above_right) {
        let edge = bottom_edge_16(&above_left.planes[0]);
        std::array::from_fn(|index| edge[index % 16])
    } else {
        let left = bottom_edge_16(&above_left.planes[0]);
        let right = bottom_edge_16(&above_right.planes[0]);
        std::array::from_fn(|index| {
            if index < 16 {
                left[index]
            } else {
                right[index - 16]
            }
        })
    };
    let luma_left = left_neighbor.map_or([luma_top[0]; 16], |neighbor| {
        right_edge_16(&neighbor.planes[0])
    });
    let luma = if let Some(mode) = filter_intra_mode {
        reconstruct_filter_intra_prediction(mode, 32, 16, luma_top[0], &luma_top, &luma_left)?
            .try_into()
            .map_err(|_| PortableUnavailable)
            .map(|prediction: [u16; 512]| {
                reconstruct_lossy_luma_32x16_from_prediction(
                    prediction,
                    lossy_luma_32x16_coefficients,
                )
            })?
    } else if let Some(split) = lossy_luma_16x16_horizontal_split {
        reconstruct_lossy_luma_32x16_horizontal_split(
            luma_predictor,
            luma_angle,
            None,
            luma_top,
            luma_left,
            luma_top[0],
            left_neighbor.is_some(),
            split,
        )?
    } else if let Some(split) = lossy_luma_8x8_grid_split {
        reconstruct_lossy_luma_32x16_split(
            luma_predictor,
            luma_angle,
            None,
            luma_top,
            luma_left,
            luma_top[0],
            left_neighbor.is_some(),
            split,
        )?
    } else {
        let prediction = match luma_predictor {
            LumaPredictor::Dc => [rectangular_dc_predictor(&luma_top, &luma_left); 512],
            LumaPredictor::Vertical => std::array::from_fn(|index| luma_top[index % 32]),
            LumaPredictor::Horizontal => std::array::from_fn(|index| luma_left[index / 32]),
            LumaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 32], luma_left[index / 32], luma_top[0])
            }),
            LumaPredictor::Diagonal203 => {
                return reconstruct_lossy_luma_32x16_diagonal_z3(
                    luma_left,
                    luma_top[0],
                    luma_angle.ok_or(PortableUnavailable)?,
                    lossy_luma_32x16_coefficients,
                )
                .map(|luma| ClosedLeaf {
                    luma_predictor,
                    planes: [
                        luma,
                        ReconstructedPlane {
                            samples: vec![128; 512],
                        },
                        ReconstructedPlane {
                            samples: vec![128; 512],
                        },
                    ],
                });
            }
            _ => std::array::from_fn(|index| luma_top[index % 32]),
        };
        reconstruct_lossy_luma_32x16_from_prediction(prediction, lossy_luma_32x16_coefficients)
    };
    let mut leaf = ClosedLeaf {
        luma_predictor,
        planes: [
            luma,
            ReconstructedPlane {
                samples: Vec::new(),
            },
            ReconstructedPlane {
                samples: Vec::new(),
            },
        ],
    };
    let luma_samples = leaf.planes[0].samples.clone();

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top: [u16; 32] = if std::ptr::eq(above_left, above_right) {
            let edge = bottom_edge_16(&above_left.planes[plane]);
            std::array::from_fn(|index| edge[index % 16])
        } else {
            let left = bottom_edge_16(&above_left.planes[plane]);
            let right = bottom_edge_16(&above_right.planes[plane]);
            std::array::from_fn(|index| {
                if index < 16 {
                    left[index]
                } else {
                    right[index - 16]
                }
            })
        };
        let left = left_neighbor.map_or([top[0]; 16], |neighbor| {
            right_edge_16(&neighbor.planes[plane])
        });
        let prediction = match chroma_predictor {
            ChromaPredictor::Dc => [rectangular_dc_predictor(&top, &left); 512],
            ChromaPredictor::Vertical => std::array::from_fn(|index| top[index % 32]),
            ChromaPredictor::Horizontal => std::array::from_fn(|index| left[index / 32]),
            ChromaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(top[index % 32], left[index / 32], top[0])
            }),
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                let dc = rectangular_dc_predictor(&top, &left);
                std::array::from_fn(|index| {
                    reconstruct_cfl_sample(
                        dc,
                        alpha,
                        i32::from(luma_samples[index]) - i32::from(dc),
                        0,
                    )
                })
            }
            _ => [128; 512],
        };

        if let Some(coefficients) = lossy_chroma_16x8_coefficients[plane - 1] {
            let reduced = reconstruct_lossy_full_16x8_chroma(
                chroma_predictor,
                chroma_angle,
                top[..16].try_into().map_err(|_| PortableUnavailable)?,
                left[..8].try_into().map_err(|_| PortableUnavailable)?,
                Some(coefficients),
            )?;
            let mut samples = Vec::with_capacity(512);
            for y in 0..16 {
                for x in 0..32 {
                    samples.push(reduced.samples[y / 2 * 16 + x / 2]);
                }
            }
            Ok(ReconstructedPlane { samples })
        } else {
            Ok(ReconstructedPlane {
                samples: prediction.to_vec(),
            })
        }
    };

    leaf.planes[1] = chroma(1)?;
    leaf.planes[2] = chroma(2)?;
    Ok(leaf)
}

#[derive(Clone, Copy)]
struct FullSquare4Edges {
    top: [u16; 4],
    top_extended: [u16; 8],
    left: [u16; 4],
    bottom_left: Option<[u16; 4]>,
    top_left: u16,
    has_top: bool,
    has_left: bool,
}

fn reconstruct_lossy_full_4x4_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 16 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 16];
    let mut sum = 8_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 4;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }

    let residual = transform::inverse_dct4x4(&coefficients.unwrap_or([0_i32; 16]));
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "full-resolution 4x4 chroma prediction carries the complete AV1 edge and transform state"
)]
fn reconstruct_lossy_full_4x4_chroma(
    luma: &ReconstructedPlane,
    predictor: ChromaPredictor,
    cfl_alpha: Option<i32>,
    angle: Option<i32>,
    top: [u16; 4],
    top_extended: [u16; 8],
    left: [u16; 4],
    bottom_left: Option<[u16; 4]>,
    top_left: u16,
    has_top: bool,
    has_left: bool,
    coefficients: Option<TransformCoefficients>,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
) -> PortableResult<ReconstructedPlane> {
    let transform = chroma_transform_kind(predictor);
    match predictor {
        ChromaPredictor::Dc => Ok(reconstruct_lossy_4x4(
            dc_predictor_4_with_availability(top, left, has_top, has_left),
            coefficients,
            transform,
        )),
        ChromaPredictor::Cfl { .. } => reconstruct_lossy_full_4x4_cfl(
            luma,
            dc_predictor_4_with_availability(top, left, has_top, has_left),
            cfl_alpha.ok_or(PortableUnavailable)?,
            coefficients,
        ),
        ChromaPredictor::Vertical => match angle {
            None | Some(90) => Ok(reconstruct_lossy_4x4_from_prediction(
                std::array::from_fn(|index| top[index % 4]),
                coefficients,
                transform,
            )),
            Some(angle) if 0 < angle && angle < 90 => reconstruct_lossy_4x4_diagonal_z1_with_edge(
                top_extended,
                top_left,
                angle,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            ),
            Some(angle) if 90 < angle && angle < 180 => reconstruct_lossy_4x4_diagonal_z2(
                top,
                left,
                top_left,
                angle,
                smooth_edges,
                coefficients,
                transform,
            ),
            _ => Err(PortableUnavailable),
        },
        ChromaPredictor::Horizontal => Ok(reconstruct_lossy_4x4_from_prediction(
            std::array::from_fn(|index| left[index / 4]),
            coefficients,
            transform,
        )),
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1_with_edge(
                top_extended,
                top_left,
                angle.ok_or(PortableUnavailable)?,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            )
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_4x4_diagonal_z2(
            top,
            left,
            top_left,
            angle.ok_or(PortableUnavailable)?,
            smooth_edges,
            coefficients,
            transform,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3_with_bottom_left(
            left,
            bottom_left,
            top_left,
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Smooth => Ok(reconstruct_lossy_4x4_smooth(
            top,
            top[3],
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_4x4_smooth_vertical(
            top,
            left[3],
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_4x4_smooth_horizontal(
            left,
            top[3],
            coefficients,
            transform,
        )),
        ChromaPredictor::Paeth => {
            let prediction = if has_left {
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 4], left[index / 4], top_left)
                })
            } else {
                std::array::from_fn(|index| top[index % 4])
            };
            Ok(reconstruct_lossy_4x4_from_prediction(
                prediction,
                coefficients,
                transform,
            ))
        }
    }
}

#[expect(
    clippy::too_many_arguments,
    reason = "full-resolution 4x4 luma prediction carries the complete AV1 edge and transform state"
)]
fn reconstruct_lossy_full_4x4_luma(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 4],
    top_extended: [u16; 8],
    left: [u16; 4],
    bottom_left: Option<[u16; 4]>,
    top_left: u16,
    has_top: bool,
    has_left: bool,
    coefficients: Option<TransformCoefficients>,
    transform: LossyTransformKind,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
) -> PortableResult<ReconstructedPlane> {
    if let Some(mode) = filter_intra_mode {
        return Ok(reconstruct_lossy_4x4_from_prediction(
            reconstruct_filter_intra_4x4_prediction(mode, top_left, top, left),
            coefficients,
            transform,
        ));
    }

    match predictor {
        LumaPredictor::Dc => Ok(reconstruct_lossy_4x4(
            dc_predictor_4_with_availability(top, left, has_top, has_left),
            coefficients,
            transform,
        )),
        LumaPredictor::Vertical => match angle {
            None | Some(90) => Ok(reconstruct_lossy_4x4_from_prediction(
                std::array::from_fn(|index| top[index % 4]),
                coefficients,
                transform,
            )),
            Some(angle) if 0 < angle && angle < 90 => reconstruct_lossy_4x4_diagonal_z1_with_edge(
                top_extended,
                top_left,
                angle,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            ),
            Some(angle) if 90 < angle && angle < 180 => reconstruct_lossy_4x4_diagonal_z2(
                top,
                left,
                top_left,
                angle,
                smooth_edges,
                coefficients,
                transform,
            ),
            _ => Err(PortableUnavailable),
        },
        LumaPredictor::Horizontal => match angle {
            None | Some(180) => Ok(reconstruct_lossy_4x4_from_prediction(
                std::array::from_fn(|index| left[index / 4]),
                coefficients,
                transform,
            )),
            Some(angle) if 90 < angle && angle < 180 => reconstruct_lossy_4x4_diagonal_z2(
                top,
                left,
                top_left,
                angle,
                smooth_edges,
                coefficients,
                transform,
            ),
            Some(angle) if 180 < angle && angle < 270 => {
                reconstruct_lossy_chroma_4x4_diagonal_z3_with_bottom_left(
                    left,
                    bottom_left,
                    top_left,
                    angle,
                    coefficients,
                    transform,
                )
            }
            _ => Err(PortableUnavailable),
        },
        LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1_with_edge(
                top_extended,
                top_left,
                angle.ok_or(PortableUnavailable)?,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            )
        }
        LumaPredictor::DiagonalDownRight
        | LumaPredictor::Diagonal113
        | LumaPredictor::Diagonal157 => reconstruct_lossy_4x4_diagonal_z2(
            top,
            left,
            top_left,
            angle.ok_or(PortableUnavailable)?,
            smooth_edges,
            coefficients,
            transform,
        ),
        LumaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3_with_bottom_left(
            left,
            bottom_left,
            top_left,
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        LumaPredictor::Smooth => Ok(reconstruct_lossy_4x4_smooth(
            top,
            top[3],
            left,
            coefficients,
            transform,
        )),
        LumaPredictor::SmoothVertical => Ok(reconstruct_lossy_4x4_smooth_vertical(
            top,
            left[3],
            coefficients,
            transform,
        )),
        LumaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_4x4_smooth_horizontal(
            left,
            top[3],
            coefficients,
            transform,
        )),
        LumaPredictor::Paeth => {
            let prediction = if has_left {
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 4], left[index / 4], top_left)
                })
            } else {
                std::array::from_fn(|index| top[index % 4])
            };
            Ok(reconstruct_lossy_4x4_from_prediction(
                prediction,
                coefficients,
                transform,
            ))
        }
    }
}

fn reconstruct_lossy_full_square4_leaf(
    syntax: BlockSyntax,
    edges: [FullSquare4Edges; 3],
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
) -> PortableResult<ClosedLeaf> {
    let luma_coefficients = syntax
        .lossy_luma_coefficients
        .map(|coefficients| std::array::from_fn(|index| coefficients[index]));
    let luma = reconstruct_lossy_full_4x4_luma(
        syntax.luma_predictor,
        syntax.luma_angle,
        syntax.filter_intra_mode,
        edges[0].top,
        edges[0].top_extended,
        edges[0].left,
        edges[0].bottom_left,
        edges[0].top_left,
        edges[0].has_top,
        edges[0].has_left,
        luma_coefficients,
        syntax.lossy_luma_transform,
        enable_intra_edge_filter,
        smooth_edges,
    )?;
    let chroma = |plane: usize| {
        let edge = edges[plane];
        let alpha = match syntax.chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                Some(if plane == 1 { alpha_u } else { alpha_v })
            }
            _ => None,
        };
        reconstruct_lossy_full_4x4_chroma(
            &luma,
            syntax.chroma_predictor,
            alpha,
            syntax.chroma_angle,
            edge.top,
            edge.top_extended,
            edge.left,
            edge.bottom_left,
            edge.top_left,
            edge.has_top,
            edge.has_left,
            syntax.lossy_chroma_coefficients[plane - 1],
            enable_intra_edge_filter,
            smooth_edges,
        )
    };
    let chroma_u = chroma(1)?;
    let chroma_v = chroma(2)?;
    Ok(ClosedLeaf {
        luma_predictor: syntax.luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn checked_bottom_sample_at(plane: &ReconstructedPlane, width: u32, x_offset: u32) -> Option<u16> {
    let width = usize::try_from(width).ok()?;
    let x_offset = usize::try_from(x_offset).ok()?;
    if width == 0 || x_offset >= width {
        return None;
    }
    let height = plane.samples.len().checked_div(width)?;
    (height > 0).then(|| plane.samples[(height - 1) * width + x_offset])
}

fn checked_right_edge_at<const N: usize>(
    plane: &ReconstructedPlane,
    width: u32,
    height: u32,
    row_offset: u32,
) -> Option<[u16; N]> {
    let width = usize::try_from(width).ok()?;
    let height = usize::try_from(height).ok()?;
    let row_offset = usize::try_from(row_offset).ok()?;
    if width == 0 || row_offset.saturating_add(N) > height {
        return None;
    }
    let mut edge = [0_u16; N];
    for (index, sample) in edge.iter_mut().enumerate() {
        *sample = *plane
            .samples
            .get((row_offset + index) * width + width - 1)?;
    }
    Some(edge)
}

fn positioned_top_edge<const N: usize>(
    plane: usize,
    first: &FirstLeaf,
    first_offset: u32,
    second: &FirstLeaf,
    second_offset: u32,
) -> Option<[u16; N]> {
    let first_available = usize::try_from(first.width.saturating_sub(first_offset))
        .ok()?
        .min(N);
    let mut edge = [0_u16; N];
    let mut last = None;
    for (index, sample) in edge.iter_mut().enumerate() {
        let value = if index < first_available {
            checked_bottom_sample_at(
                &first.planes[plane],
                first.width,
                first_offset.saturating_add(u32::try_from(index).ok()?),
            )
        } else {
            checked_bottom_sample_at(
                &second.planes[plane],
                second.width,
                second_offset
                    .saturating_add(u32::try_from(index.saturating_sub(first_available)).ok()?),
            )
        };
        if let Some(value) = value {
            *sample = value;
            last = Some(value);
        } else {
            let value = last?;
            *sample = value;
        }
    }
    Some(edge)
}

fn full_square4_vertical_edges(
    neighbors: &VerticalNeighbors<'_>,
    plane: usize,
) -> PortableResult<FullSquare4Edges> {
    let (first, first_offset, extension, extension_offset) = if plane == 0 {
        (
            neighbors.above_left,
            neighbors.above_left_x_offset,
            neighbors.above_luma_extension,
            neighbors.above_luma_extension_x_offset,
        )
    } else if let Some(above) = neighbors.above_chroma {
        (
            above,
            neighbors.above_chroma_x_offset,
            neighbors.above_chroma_extension,
            neighbors.above_chroma_extension_x_offset,
        )
    } else {
        (
            neighbors.above_left,
            neighbors.above_left_x_offset,
            neighbors.above_luma_extension,
            neighbors.above_luma_extension_x_offset,
        )
    };
    let second = extension.unwrap_or(neighbors.above_right);
    let second_offset = if extension.is_some() {
        extension_offset
    } else {
        neighbors.above_right_x_offset
    };
    let top = positioned_top_edge::<4>(plane, first, first_offset, second, second_offset)
        .ok_or(PortableUnavailable)?;
    let top_extended = positioned_top_edge::<8>(plane, first, first_offset, second, second_offset)
        .ok_or(PortableUnavailable)?;

    let left_source = if plane == 0 {
        neighbors
            .left
            .map(|neighbor| (neighbor, neighbors.left_y_offset))
    } else {
        neighbors
            .left_chroma
            .map(|neighbor| (neighbor, neighbors.left_chroma_y_offset))
            .or_else(|| {
                neighbors
                    .left
                    .map(|neighbor| (neighbor, neighbors.left_y_offset))
            })
    };
    let left_edge = left_source.and_then(|(neighbor, row_offset)| {
        checked_right_edge_at::<4>(
            &neighbor.planes[plane],
            neighbor.width,
            neighbor.height,
            row_offset,
        )
    });
    let has_left = left_edge.is_some();
    let left = left_edge.unwrap_or([top[0]; 4]);
    let bottom_left = left_source.and_then(|(neighbor, row_offset)| {
        checked_right_edge_at::<4>(
            &neighbor.planes[plane],
            neighbor.width,
            neighbor.height,
            row_offset.saturating_add(4),
        )
    });
    let top_left = if has_left {
        full_resolution_chroma_top_left(neighbors, plane).ok_or(PortableUnavailable)?
    } else {
        top[0]
    };
    Ok(FullSquare4Edges {
        top,
        top_extended,
        left,
        bottom_left,
        top_left,
        has_top: true,
        has_left,
    })
}

fn reconstruct_following_lossy_full_square4_vertical_leaf(
    syntax: BlockSyntax,
    neighbors: &VerticalNeighbors<'_>,
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let edges = [
        full_square4_vertical_edges(neighbors, 0)?,
        full_square4_vertical_edges(neighbors, 1)?,
        full_square4_vertical_edges(neighbors, 2)?,
    ];
    let smooth_edges = matches!(
        neighbors.above_left.luma_predictor,
        LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
    ) || neighbors.left.is_some_and(|neighbor| {
        matches!(
            neighbor.luma_predictor,
            LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
        )
    });
    reconstruct_lossy_full_square4_leaf(syntax, edges, enable_intra_edge_filter, smooth_edges)
}

fn reconstruct_following_lossy_full_square4_horizontal_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
    neighbor_width: u32,
    neighbor_height: u32,
    chroma_left_edges_8: [Option<[u16; 8]>; 2],
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let mut edges = [
        FullSquare4Edges {
            top: [128; 4],
            top_extended: [128; 8],
            left: [128; 4],
            bottom_left: None,
            top_left: 128,
            has_top: false,
            has_left: true,
        },
        FullSquare4Edges {
            top: [128; 4],
            top_extended: [128; 8],
            left: [128; 4],
            bottom_left: None,
            top_left: 128,
            has_top: false,
            has_left: true,
        },
        FullSquare4Edges {
            top: [128; 4],
            top_extended: [128; 8],
            left: [128; 4],
            bottom_left: None,
            top_left: 128,
            has_top: false,
            has_left: true,
        },
    ];
    for plane in 0..=2 {
        let left = if plane == 0 {
            checked_right_edge_at::<4>(&neighbor.planes[plane], neighbor_width, neighbor_height, 0)
        } else {
            chroma_left_edges_8[plane - 1]
                .map(|edge| [edge[0], edge[1], edge[2], edge[3]])
                .or_else(|| {
                    checked_right_edge_at::<4>(
                        &neighbor.planes[plane],
                        neighbor_width,
                        neighbor_height,
                        0,
                    )
                })
        }
        .ok_or(PortableUnavailable)?;
        let bottom_left =
            checked_right_edge_at::<4>(&neighbor.planes[plane], neighbor_width, neighbor_height, 4);
        edges[plane] = FullSquare4Edges {
            top: [left[0]; 4],
            top_extended: [left[0]; 8],
            left,
            bottom_left,
            top_left: left[0],
            has_top: false,
            has_left: true,
        };
    }
    let smooth_edges = matches!(
        neighbor.luma_predictor,
        LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
    );
    reconstruct_lossy_full_square4_leaf(syntax, edges, enable_intra_edge_filter, smooth_edges)
}

// Every edge, availability flag, coefficient sentence, and predictor state in
// this kernel describes the same checked 8x8 chroma plane.
#[expect(
    clippy::too_many_arguments,
    reason = "8x8 chroma reconstruction carries one plane's complete AV1 edge and transform state"
)]
fn reconstruct_lossy_full_8x8_chroma(
    luma: &ReconstructedPlane,
    predictor: ChromaPredictor,
    cfl_alpha: Option<i32>,
    angle: Option<i32>,
    top: [u16; 8],
    top_extended: [u16; 16],
    left: [u16; 8],
    bottom_left: Option<[u16; 8]>,
    top_left: u16,
    has_top: bool,
    has_left: bool,
    coefficients: Option<LossyTransformCoefficients>,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
) -> PortableResult<ReconstructedPlane> {
    let transform = chroma_transform_kind(predictor);
    match predictor {
        ChromaPredictor::Dc => Ok(reconstruct_lossy_chroma_8x8(
            dc_predictor_8_with_availability(top, left, has_top, has_left),
            coefficients,
            transform,
        )),
        ChromaPredictor::Vertical => match angle {
            None | Some(90) => Ok(reconstruct_lossy_luma_8x8_vertical(
                top,
                coefficients,
                transform,
            )),
            Some(angle) if 0 < angle && angle < 90 => {
                reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                    top_extended,
                    top_left,
                    angle,
                    enable_intra_edge_filter,
                    smooth_edges,
                    coefficients,
                    transform,
                )
            }
            Some(angle) if 90 < angle && angle < 180 => reconstruct_lossy_luma_8x8_diagonal(
                top_extended,
                left,
                top_left,
                angle,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            ),
            _ => Err(PortableUnavailable),
        },
        ChromaPredictor::Horizontal => match angle {
            None | Some(180) => Ok(reconstruct_lossy_luma_8x8_horizontal(
                left,
                coefficients,
                transform,
            )),
            Some(angle) if 90 < angle && angle < 180 => reconstruct_lossy_luma_8x8_diagonal(
                top_extended,
                left,
                top_left,
                angle,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            ),
            Some(angle) if 180 < angle && angle < 270 => {
                reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
                    left,
                    top_left,
                    bottom_left,
                    angle,
                    enable_intra_edge_filter,
                    smooth_edges,
                    coefficients,
                    transform,
                )
            }
            _ => Err(PortableUnavailable),
        },
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                top_extended,
                top_left,
                angle.ok_or(PortableUnavailable)?,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            )
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
            top_extended,
            left,
            top_left,
            angle.ok_or(PortableUnavailable)?,
            enable_intra_edge_filter,
            smooth_edges,
            coefficients,
            transform,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
            left,
            top_left,
            bottom_left,
            angle.ok_or(PortableUnavailable)?,
            enable_intra_edge_filter,
            smooth_edges,
            coefficients,
            transform,
        ),
        ChromaPredictor::Smooth => Ok(reconstruct_lossy_luma_8x8_smooth(
            top,
            top[7],
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_luma_8x8_smooth_vertical(
            top,
            left[7],
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_luma_8x8_smooth_horizontal(
            left,
            top[7],
            coefficients,
            transform,
        )),
        ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_8x8_paeth(
            top,
            left,
            top_left,
            coefficients,
            transform,
        )),
        ChromaPredictor::Cfl { .. } => reconstruct_lossy_full_8x8_cfl(
            luma,
            dc_predictor_8_with_availability(top, left, has_top, has_left),
            cfl_alpha.ok_or(PortableUnavailable)?,
            coefficients,
        ),
    }
}

fn reconstruct_lossy_full_4x16_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy4x16TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 64 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 64];
    let mut sum = 32_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 6;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }
    let residual = transform::inverse_dct4x16(&coefficients.unwrap_or([0_i32; 64]));
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_full_4x16_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 4],
    left: [u16; 16],
    coefficients: Option<Lossy4x16TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    let transform = Lossy4x8TransformKind::DctDct;
    match predictor {
        ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_4x16_from_prediction(
            [rectangular_dc_predictor(&top, &left); 64],
            coefficients,
            transform,
        )),
        ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_4x16_from_prediction(
            std::array::from_fn(|index| top[index % 4]),
            coefficients,
            transform,
        )),
        ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_4x16_from_prediction(
            std::array::from_fn(|index| left[index / 4]),
            coefficients,
            transform,
        )),
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_4x16_diagonal_z2(
            top,
            left,
            top[0],
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_4x16_diagonal_z3(
            left,
            top[0],
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            Ok(reconstruct_lossy_luma_4x16_from_prediction(
                std::array::from_fn(|index| top[index % 4]),
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::Smooth => {
            let right = i32::from(top[3]);
            let bottom = i32::from(left[15]);
            let prediction = std::array::from_fn(|index| {
                let y = index / 4;
                let x = index % 4;
                let vertical = [
                    255_i32, 240, 225, 210, 196, 182, 169, 157, 145, 133, 122, 111, 101, 92, 83, 74,
                ][y];
                let horizontal = [255_i32, 149, 85, 64][x];
                let value = vertical
                    .saturating_mul(i32::from(top[x]))
                    .saturating_add((256 - vertical).saturating_mul(bottom))
                    .saturating_add(horizontal.saturating_mul(i32::from(left[y])))
                    .saturating_add((256 - horizontal).saturating_mul(right))
                    .saturating_add(256)
                    >> 9;
                #[expect(clippy::cast_sign_loss, reason = "smooth prediction is clamped")]
                {
                    value.clamp(0, 255) as u16
                }
            });
            Ok(reconstruct_lossy_luma_4x16_from_prediction(
                prediction,
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::SmoothVertical => {
            let bottom = i32::from(left[15]);
            let prediction = std::array::from_fn(|index| {
                let y = index / 4;
                let weight = [
                    255_i32, 240, 225, 210, 196, 182, 169, 157, 145, 133, 122, 111, 101, 92, 83, 74,
                ][y];
                let value = weight
                    .saturating_mul(i32::from(top[index % 4]))
                    .saturating_add((256 - weight).saturating_mul(bottom))
                    .saturating_add(128)
                    >> 8;
                #[expect(clippy::cast_sign_loss, reason = "smooth prediction is clamped")]
                {
                    value.clamp(0, 255) as u16
                }
            });
            Ok(reconstruct_lossy_luma_4x16_from_prediction(
                prediction,
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::SmoothHorizontal => {
            let right = i32::from(top[3]);
            let prediction = std::array::from_fn(|index| {
                let x = index % 4;
                let weight = [255_i32, 149, 85, 64][x];
                let value = weight
                    .saturating_mul(i32::from(left[index / 4]))
                    .saturating_add((256 - weight).saturating_mul(right))
                    .saturating_add(128)
                    >> 8;
                #[expect(clippy::cast_sign_loss, reason = "smooth prediction is clamped")]
                {
                    value.clamp(0, 255) as u16
                }
            });
            Ok(reconstruct_lossy_luma_4x16_from_prediction(
                prediction,
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_4x16_from_prediction(
            std::array::from_fn(|index| paeth_predictor(top[index % 4], left[index / 4], top[0])),
            coefficients,
            transform,
        )),
        ChromaPredictor::Cfl { .. } => Err(PortableUnavailable),
    }
}

fn reconstruct_lossy_full_16x16_chroma(
    predictor: ChromaPredictor,
    top: [u16; 16],
    left: [u16; 16],
    top_left: u16,
    has_left: bool,
    coefficients: Option<Lossy16x16TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    let prediction = match predictor {
        ChromaPredictor::Dc => {
            [if has_left {
                dc_predictor_16(top, left)
            } else {
                one_sided_dc_predictor_16(top)
            }; 256]
        }
        ChromaPredictor::Vertical => std::array::from_fn(|index| top[index % 16]),
        ChromaPredictor::Horizontal => std::array::from_fn(|index| left[index / 16]),
        ChromaPredictor::Paeth => std::array::from_fn(|index| {
            paeth_predictor(top[index % 16], left[index / 16], top_left)
        }),
        // The scalar 16x16 transform kernel is shared by all full-sampling
        // modes. The angular and smooth edge filters have dedicated smaller
        // kernels today; retaining their primary edge as the prediction keeps
        // the reconstructed extent and transform sentence correct until those
        // filters are generalized to 16x16.
        ChromaPredictor::Diagonal45
        | ChromaPredictor::Diagonal67
        | ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157
        | ChromaPredictor::Diagonal203
        | ChromaPredictor::Smooth
        | ChromaPredictor::SmoothVertical
        | ChromaPredictor::SmoothHorizontal => std::array::from_fn(|index| top[index % 16]),
        ChromaPredictor::Cfl { .. } => return Err(PortableUnavailable),
    };
    Ok(reconstruct_lossy_luma_16x16_from_prediction(
        prediction,
        coefficients,
        Lossy16x16TransformKind::DctDct,
    ))
}

/// Reconstruct a 16×16 full-resolution chroma transform with CFL.
///
/// I444 CFL has one luma sample for every chroma sample. The luma plane is
/// therefore doubled and centered directly into a 16×16 AC plane before the
/// signed alpha and DCT-DCT residual are applied.
fn reconstruct_lossy_full_16x16_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy16x16TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 256 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 256];
    let mut sum = 128_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 8;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }
    let residual = transform::inverse_dct16x16(&coefficients.unwrap_or([0_i32; 256]));
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_full_4x8_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 4],
    left: [u16; 8],
    top_left: u16,
    has_left: bool,
    coefficients: Option<Lossy4x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    let transform = chroma_rect_transform_kind(predictor);
    match predictor {
        ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_4x8(
            top,
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_4x8_from_prediction(
            std::array::from_fn(|index| top[index % 4]),
            coefficients,
            transform,
        )),
        ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_4x8_from_prediction(
            std::array::from_fn(|index| left[index / 4]),
            coefficients,
            transform,
        )),
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_4x8_diagonal_z1(
                top,
                top_left,
                angle.ok_or(PortableUnavailable)?,
                coefficients,
                transform,
            )
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_4x8_diagonal_z2(
            top,
            left,
            top_left,
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_4x8_diagonal_z3(
            left,
            top_left,
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Smooth => Ok(reconstruct_lossy_luma_4x8_smooth(
            top,
            top[3],
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_luma_4x8_smooth_vertical(
            top,
            left[7],
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_luma_4x8_smooth_horizontal(
            left,
            top[3],
            coefficients,
            transform,
        )),
        ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_4x8_from_prediction(
            std::array::from_fn(|index| paeth_predictor(top[index % 4], left[index / 4], top_left)),
            coefficients,
            transform,
        )),
        ChromaPredictor::Cfl { .. } => {
            let _ = has_left;
            Err(PortableUnavailable)
        }
    }
}

/// Reconstruct a 4×8 full-resolution chroma transform with CFL.
///
/// Full-sampling CFL has one luma sample for each chroma sample, so the
/// decoded 4×8 luma plane is doubled and centered directly into the
/// rectangular chroma AC plane.
fn reconstruct_lossy_full_4x8_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy4x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 32 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 32];
    let mut sum = 16_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 5;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }
    let residual = transform::inverse_dct4x8(&coefficients.unwrap_or([0_i32; 32]));
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

/// Reconstruct an 8×4 full-resolution chroma transform with CFL.
fn reconstruct_lossy_full_8x4_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy4x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 32 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 32];
    let mut sum = 16_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 5;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }
    let residual = transform::inverse_dct8x4(&coefficients.unwrap_or([0_i32; 32]));
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_full_16x8_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy16x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 128 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 128];
    // dav1d's cfl_ac_444 rounds the sum of 128 Q3 samples with N/2=64
    // before dividing by N. The previous 128 seed was the 4:2:0 value and
    // could shift the centered AC plane by one.
    let mut sum = 64_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 7;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }
    let residual = transform::inverse_dct16x8(&coefficients.unwrap_or([0_i32; 128]));
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_full_16x4_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy16x4TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 64 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 64];
    let mut sum = 32_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 6;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }
    let residual = transform::inverse_dct16x4(&coefficients.unwrap_or([0_i32; 64]));
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_full_16x8_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 16],
    left: [u16; 8],
    coefficients: Option<Lossy16x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    let transform = chroma_rect_transform_kind(predictor);
    match predictor {
        ChromaPredictor::Dc => Ok(reconstruct_lossy_chroma_16x8_from_prediction(
            [rectangular_dc_predictor(&top, &left); 128],
            coefficients,
            transform,
        )),
        ChromaPredictor::Vertical => Ok(reconstruct_lossy_chroma_16x8_from_prediction(
            std::array::from_fn(|index| top[index % 16]),
            coefficients,
            transform,
        )),
        ChromaPredictor::Horizontal => Ok(reconstruct_lossy_chroma_16x8_from_prediction(
            std::array::from_fn(|index| left[index / 16]),
            coefficients,
            transform,
        )),
        // The existing rectangular chroma predictor covers zone 2 and zone
        // 3. Zone 1 has no dedicated 16x8 helper yet; retaining its top edge
        // is a bounded, correctly sized fallback until that predictor is
        // integrated with the same edge filter used by the scalar decoder.
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            let _ = angle;
            Ok(reconstruct_lossy_chroma_16x8_from_prediction(
                std::array::from_fn(|index| top[index % 16]),
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_16x8_diagonal_z2(
            top,
            left,
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_16x8_diagonal_z3(
            left,
            top[0],
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Smooth => Ok(reconstruct_lossy_chroma_16x8_smooth(
            top,
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_chroma_16x8_smooth_vertical(
            top,
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_chroma_16x8_smooth_horizontal(
            top,
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::Paeth => Ok(reconstruct_lossy_chroma_16x8_from_prediction(
            std::array::from_fn(|index| paeth_predictor(top[index % 16], left[index / 16], top[0])),
            coefficients,
            transform,
        )),
        ChromaPredictor::Cfl { .. } => Err(PortableUnavailable),
    }
}

fn reconstruct_lossy_full_16x4_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 16],
    left: [u16; 4],
    coefficients: Option<Lossy16x4TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    let transform = chroma_rect_transform_kind(predictor);
    match predictor {
        ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_16x4(
            rectangular_dc_predictor(&top, &left),
            coefficients,
            transform,
        )),
        ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_16x4_vertical(
            top,
            coefficients,
            transform,
        )),
        ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_16x4_horizontal(
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_16x4_diagonal_z1(
                top,
                top[0],
                angle.ok_or(PortableUnavailable)?,
                coefficients,
                transform,
            )
        }
        ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_16x4_diagonal_z3(
            left,
            top[0],
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157
        | ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_luma_16x4_from_prediction(
            [top[0]; 64],
            coefficients,
            transform,
        )),
        ChromaPredictor::Smooth => Ok(reconstruct_lossy_luma_16x4_smooth(
            top,
            top[15],
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_luma_16x4_smooth_horizontal(
            left,
            top[15],
            coefficients,
            transform,
        )),
        ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_16x4_from_prediction(
            std::array::from_fn(|index| paeth_predictor(top[index % 16], left[index / 16], top[0])),
            coefficients,
            transform,
        )),
        ChromaPredictor::Cfl { .. } => Err(PortableUnavailable),
    }
}

fn reconstruct_lossy_full_32x8_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 32],
    left: [u16; 8],
    coefficients: Option<Lossy32x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    match predictor {
        ChromaPredictor::Dc => reconstruct_lossy_chroma_32x8_from_prediction(
            [rectangular_dc_predictor(&top, &left); 256],
            coefficients,
        ),
        ChromaPredictor::Vertical => reconstruct_lossy_chroma_32x8_from_prediction(
            std::array::from_fn(|index| top[index % 32]),
            coefficients,
        ),
        ChromaPredictor::Horizontal => {
            reconstruct_lossy_chroma_32x8_from_prediction_with_transform(
                std::array::from_fn(|index| left[index / 32]),
                coefficients,
                LossyTransformKind::DctAdst,
            )
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_32x8_diagonal_z2(
            top,
            left,
            angle.ok_or(PortableUnavailable)?,
            coefficients,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_32x8_diagonal_z3(
            left,
            angle.ok_or(PortableUnavailable)?,
            coefficients,
        ),
        ChromaPredictor::Smooth => Ok(reconstruct_lossy_luma_32x8_smooth(top, left, coefficients)),
        ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_luma_32x8_smooth_vertical(
            top,
            left,
            coefficients,
        )),
        ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_luma_32x8_smooth_horizontal(
            top,
            left,
            coefficients,
        )),
        ChromaPredictor::Paeth => reconstruct_lossy_chroma_32x8_from_prediction(
            std::array::from_fn(|index| paeth_predictor(top[index % 32], left[index / 32], top[0])),
            coefficients,
        ),
        // The large-transform zone-1 path uses the same top-edge extension
        // as the existing 32×8 scalar terminal until its dedicated edge
        // filter is needed. It preserves the coded extent and DCT residual.
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            Ok(reconstruct_lossy_luma_32x8_from_prediction(
                std::array::from_fn(|index| top[index % 32]),
                coefficients,
            ))
        }
        ChromaPredictor::Cfl { .. } => Err(PortableUnavailable),
    }
}

fn reconstruct_lossy_full_32x8_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy32x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 256 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 256];
    let mut sum = 128_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 8;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }
    let residual = transform::inverse_dct32x8(&coefficients.unwrap_or([0_i32; 256]));
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_full_8x32_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 8],
    left: [u16; 32],
    coefficients: Option<Lossy8x32TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    let coefficients = coefficients.unwrap_or([0_i32; 256]);
    let residual = match predictor {
        ChromaPredictor::Dc => transform::inverse_dct8x32(&coefficients),
        ChromaPredictor::Vertical => transform::inverse_dct8x32(&coefficients),
        ChromaPredictor::Horizontal => transform::inverse_dct8x32(&coefficients),
        ChromaPredictor::Paeth => transform::inverse_dct8x32(&coefficients),
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => {
            return reconstruct_lossy_chroma_8x32_diagonal_z2(
                top,
                left,
                angle.ok_or(PortableUnavailable)?,
                Some(coefficients),
            );
        }
        ChromaPredictor::Smooth => {
            return Ok(reconstruct_lossy_chroma_8x32_smooth(
                top,
                left,
                Some(coefficients),
            ));
        }
        ChromaPredictor::Diagonal45
        | ChromaPredictor::Diagonal67
        | ChromaPredictor::Diagonal203
        | ChromaPredictor::SmoothVertical
        | ChromaPredictor::SmoothHorizontal => transform::inverse_dct8x32(&coefficients),
        ChromaPredictor::Cfl { .. } => return Err(PortableUnavailable),
    };
    let prediction = match predictor {
        ChromaPredictor::Dc => [rectangular_dc_predictor(&top, &left); 256],
        ChromaPredictor::Vertical => std::array::from_fn(|index| top[index % 8]),
        ChromaPredictor::Horizontal => std::array::from_fn(|index| left[index / 8]),
        ChromaPredictor::Paeth => {
            std::array::from_fn(|index| paeth_predictor(top[index % 8], left[index / 8], top[0]))
        }
        _ => std::array::from_fn(|index| top[index % 8]),
    };
    Ok(reconstruct_lossy_predicted_plane(&prediction, &residual))
}

fn reconstruct_lossy_full_8x32_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy8x32TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 256 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 256];
    let mut sum = 128_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 8;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }
    let residual = transform::inverse_dct8x32(&coefficients.unwrap_or([0_i32; 256]));
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_full_8x16_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 8],
    left: [u16; 16],
    coefficients: Option<Lossy8x16TransformCoefficients>,
    enable_intra_edge_filter: bool,
) -> PortableResult<ReconstructedPlane> {
    reconstruct_lossy_full_8x16_chroma_with_edges(
        predictor,
        angle,
        top,
        left,
        None,
        top[0],
        true,
        coefficients,
        enable_intra_edge_filter,
        false,
    )
}

// The fixed-size edges and transform state are deliberately passed together:
// `top_left` and `bottom_left` are valid only for this same R8x16 plane.
#[expect(
    clippy::too_many_arguments,
    reason = "R8x16 chroma reconstruction carries one plane's complete AV1 edge and transform state"
)]
fn reconstruct_lossy_full_8x16_chroma_with_edges(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 8],
    left: [u16; 16],
    bottom_left: Option<[u16; 8]>,
    top_left: u16,
    has_left: bool,
    coefficients: Option<Lossy8x16TransformCoefficients>,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
) -> PortableResult<ReconstructedPlane> {
    let transform = chroma_transform_kind(predictor);
    match predictor {
        ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_8x16_from_prediction(
            [rectangular_dc_predictor(&top, &left); 128],
            coefficients,
            transform,
        )),
        ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_8x16_from_prediction(
            std::array::from_fn(|index| top[index % 8]),
            coefficients,
            transform,
        )),
        ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_8x16_from_prediction(
            std::array::from_fn(|index| left[index / 8]),
            coefficients,
            transform,
        )),
        ChromaPredictor::Paeth => {
            let prediction = if has_left {
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 8], left[index / 8], top_left)
                })
            } else {
                std::array::from_fn(|index| top[index % 8])
            };
            Ok(reconstruct_lossy_luma_8x16_from_prediction(
                prediction,
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_8x16_diagonal(
            std::array::from_fn(|index| top[index % 8]),
            left,
            angle.ok_or(PortableUnavailable)?,
            enable_intra_edge_filter,
            coefficients.unwrap_or([0_i32; 128]),
            transform,
        ),
        ChromaPredictor::Diagonal45
        | ChromaPredictor::Diagonal67
        | ChromaPredictor::Smooth
        | ChromaPredictor::SmoothVertical
        | ChromaPredictor::SmoothHorizontal => {
            let _ = angle;
            Ok(reconstruct_lossy_luma_8x16_from_prediction(
                std::array::from_fn(|index| top[index % 8]),
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_8x16_diagonal_z3(
            left,
            top_left,
            bottom_left,
            angle.ok_or(PortableUnavailable)?,
            enable_intra_edge_filter,
            smooth_edges,
            coefficients,
            transform,
        ),
        ChromaPredictor::Cfl { .. } => Err(PortableUnavailable),
    }
}

fn reconstruct_lossy_full_8x4_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 8],
    left: [u16; 4],
    coefficients: Option<Lossy4x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    let transform = chroma_rect_transform_kind(predictor);
    match predictor {
        ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_8x4(
            rectangular_dc_predictor(&top, &left),
            coefficients,
            transform,
        )),
        ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_8x4_from_prediction(
            std::array::from_fn(|index| top[index % 8]),
            coefficients,
            transform,
        )),
        ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_8x4_from_prediction(
            std::array::from_fn(|index| left[index / 8]),
            coefficients,
            transform,
        )),
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_8x4_diagonal_z1(
                top,
                top[0],
                angle.ok_or(PortableUnavailable)?,
                coefficients,
                transform,
            )
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_8x4_diagonal_z2(
            top,
            left,
            top[0],
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_8x4_diagonal_z3(
            left,
            top[0],
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Smooth => Ok(reconstruct_lossy_luma_8x4_smooth(
            top,
            top[7],
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_luma_8x4_smooth_vertical(
            top,
            left[3],
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_luma_8x4_smooth_horizontal(
            left,
            top[7],
            coefficients,
            transform,
        )),
        ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_8x4_from_prediction(
            std::array::from_fn(|index| paeth_predictor(top[index % 8], left[index / 8], top[0])),
            coefficients,
            transform,
        )),
        ChromaPredictor::Cfl { .. } => Err(PortableUnavailable),
    }
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 split reconstruction needs the predictor edges, filtering state, and decoded child syntax"
)]
fn reconstruct_lossy_luma_16x16_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 16],
    top_left: u16,
    has_top: bool,
    has_left: bool,
    split: LossyLuma8x8Split,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 256];
    for transform_index in 0_usize..4 {
        let row = transform_index / 2;
        let column = transform_index % 2;
        let offset_x = column.saturating_mul(8);
        let offset_y = row.saturating_mul(8);
        let top_edge: [u16; 8] = std::array::from_fn(|index| {
            if row == 0 {
                top[offset_x.saturating_add(index)]
            } else {
                samples[(offset_y - 1).saturating_mul(16) + offset_x + index]
            }
        });
        let top_extension: [u16; 16] = std::array::from_fn(|index| {
            if row == 0 {
                top[offset_x.saturating_add(index).min(15)]
            } else {
                samples[(offset_y - 1).saturating_mul(16) + (offset_x + index).min(15)]
            }
        });
        let left_edge: [u16; 8] = std::array::from_fn(|index| {
            if column == 0 {
                left[offset_y.saturating_add(index)]
            } else {
                samples[(offset_y + index).saturating_mul(16) + offset_x - 1]
            }
        });
        let block_top_left = match (row, column) {
            (0, 0) => top_left,
            (0, 1) => top[offset_x - 1],
            (1, 0) => left[offset_y - 1],
            _ => samples[(offset_y - 1).saturating_mul(16) + offset_x - 1],
        };
        let coefficients = split.coefficients[transform_index];
        let transform = split.transforms[transform_index];
        let block = if let Some(mode) = filter_intra_mode {
            let prediction = reconstruct_filter_intra_prediction(
                mode,
                8,
                8,
                block_top_left,
                &top_edge,
                &left_edge,
            )?;
            let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
            reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
        } else {
            match predictor {
                LumaPredictor::Dc => {
                    let value = match (has_top || row != 0, has_left || column != 0) {
                        (true, true) => dc_predictor_8(top_edge, left_edge),
                        (true, false) => one_sided_dc_predictor_8(top_edge),
                        (false, true) => one_sided_dc_predictor_8(left_edge),
                        (false, false) => 128,
                    };

                    reconstruct_lossy_luma_8x8(value, coefficients, transform)
                }
                LumaPredictor::Vertical => {
                    reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                }
                LumaPredictor::Horizontal => {
                    reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    reconstruct_lossy_luma_8x8_diagonal_z1(
                        top_edge,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        coefficients,
                        transform,
                    )?
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                    top_extension,
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                    top_edge,
                    top_extension[7],
                    left_edge,
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                    top_edge,
                    left_edge[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x8_smooth_horizontal(
                    left_edge,
                    top_extension[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                    top_edge,
                    left_edge,
                    block_top_left,
                    coefficients,
                    transform,
                ),
            }
        };
        for (row_offset, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
            let output_start = (offset_y + row_offset).saturating_mul(16) + offset_x;
            samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R16x64 split reconstruction carries the full vertical edges and child syntax"
)]
fn reconstruct_lossy_luma_16x64_vertical_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 64],
    top_left: u16,
    has_left: bool,
    split: LossyLuma16x16VerticalSplit,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    let mut samples = vec![0_u16; 1024];

    for row in 0_usize..4 {
        let offset_y = row.saturating_mul(16);
        let top_edge: [u16; 16] = if row == 0 {
            top
        } else {
            samples[(offset_y - 1).saturating_mul(16)..offset_y.saturating_mul(16)]
                .try_into()
                .map_err(|_| PortableUnavailable)?
        };
        let top_extension: [u16; 32] = if row == 0 {
            std::array::from_fn(|index| top[index.min(15)])
        } else {
            std::array::from_fn(|index| samples[(offset_y - 1).saturating_mul(16) + index.min(15)])
        };
        let left_edge: [u16; 16] = left[offset_y..offset_y + 16]
            .try_into()
            .map_err(|_| PortableUnavailable)?;
        let block_top_left = if row == 0 {
            top_left
        } else {
            left[offset_y - 1]
        };
        let coefficients = split.coefficients[row];
        let transform = split.transforms[row];
        let prediction: [u16; 256] = if let Some(mode) = filter_intra_mode {
            reconstruct_filter_intra_prediction(
                mode,
                16,
                16,
                block_top_left,
                &top_edge,
                &left_edge,
            )?
            .try_into()
            .map_err(|_| PortableUnavailable)?
        } else {
            match predictor {
                LumaPredictor::Dc => {
                    let value = if has_left {
                        dc_predictor_16(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor_16(top_edge)
                    };
                    [value; 256]
                }
                LumaPredictor::Vertical => std::array::from_fn(|index| top_edge[index % 16]),
                LumaPredictor::Horizontal => std::array::from_fn(|index| left_edge[index / 16]),
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (0 < angle && angle < 90).then_some(()).portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?)
                        .filter(|&&value| value > 0)
                        .portable()?;
                    let upsample = angle > 50;
                    let mut edge = [0_u16; 31];
                    let (max_base_x, dx, base_increment) = if upsample {
                        edge = upsample_intra_top_edge_16(top_edge, block_top_left);
                        (30, dx.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&top_edge);
                        (15, dx, 1)
                    };
                    let mut prediction = [0_u16; 256];
                    for (index, sample) in prediction.iter_mut().enumerate() {
                        *sample = diagonal_z1_predictor_sample(
                            &edge,
                            max_base_x,
                            dx,
                            base_increment,
                            index % 16,
                            index / 16,
                        )?;
                    }
                    prediction
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (90 < angle && angle < 180).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(angle.saturating_sub(90) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(180_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let mut edge = [0_u16; 65];
                    edge[32] = block_top_left;
                    for (index, value) in top_extension.into_iter().enumerate() {
                        edge[33 + index] = value;
                    }
                    for (index, value) in left_edge.into_iter().enumerate() {
                        edge[31 - index] = value;
                    }
                    let mut prediction = [0_u16; 256];
                    for (index, sample) in prediction.iter_mut().enumerate() {
                        *sample =
                            diagonal_predictor_sample(&edge, 32, dx, dy, index % 16, index / 16)?;
                    }
                    prediction
                }
                LumaPredictor::Diagonal203 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (180 < angle && angle < 270).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(270_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let upsample = angle < 220;
                    let mut edge = [0_u16; 31];
                    let (max_base_y, dy, base_increment) = if upsample {
                        edge = upsample_intra_left_edge_16(left_edge, block_top_left);
                        (30, dy.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&left_edge);
                        (15, dy, 1)
                    };
                    let mut prediction = [0_u16; 256];
                    for (index, sample) in prediction.iter_mut().enumerate() {
                        *sample = diagonal_z3_predictor_sample(
                            &edge,
                            max_base_y,
                            dy,
                            base_increment,
                            index % 16,
                            index / 16,
                        )?;
                    }
                    prediction
                }
                LumaPredictor::Smooth => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    let bottom = i32::from(left_edge[15]);
                    std::array::from_fn(|index| {
                        let x = index % 16;
                        let y = index / 16;
                        let vertical = i32::from(weights[y]);
                        let horizontal = i32::from(weights[x]);
                        let value = vertical
                            .saturating_mul(i32::from(top_edge[x]))
                            .saturating_add((256 - vertical).saturating_mul(bottom))
                            .saturating_add(horizontal.saturating_mul(i32::from(left_edge[y])))
                            .saturating_add((256 - horizontal).saturating_mul(right))
                            .saturating_add(256)
                            >> 9;
                        #[expect(
                            clippy::cast_sign_loss,
                            reason = "the smooth predictor is explicitly clamped"
                        )]
                        {
                            value.clamp(0, 255) as u16
                        }
                    })
                }
                LumaPredictor::SmoothVertical => {
                    let weights = smooth_weight_table(16)?;
                    let bottom = i32::from(left_edge[15]);
                    std::array::from_fn(|index| {
                        let weight = i32::from(weights[index / 16]);
                        let value = weight
                            .saturating_mul(i32::from(top_edge[index % 16]))
                            .saturating_add((256 - weight).saturating_mul(bottom))
                            .saturating_add(128)
                            >> 8;
                        #[expect(
                            clippy::cast_sign_loss,
                            reason = "the smooth predictor is explicitly clamped"
                        )]
                        {
                            value.clamp(0, 255) as u16
                        }
                    })
                }
                LumaPredictor::SmoothHorizontal => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    std::array::from_fn(|index| {
                        let weight = i32::from(weights[index % 16]);
                        let value = weight
                            .saturating_mul(i32::from(left_edge[index / 16]))
                            .saturating_add((256 - weight).saturating_mul(right))
                            .saturating_add(128)
                            >> 8;
                        #[expect(
                            clippy::cast_sign_loss,
                            reason = "the smooth predictor is explicitly clamped"
                        )]
                        {
                            value.clamp(0, 255) as u16
                        }
                    })
                }
                LumaPredictor::Paeth => std::array::from_fn(|index| {
                    paeth_predictor(top_edge[index % 16], left_edge[index / 16], block_top_left)
                }),
            }
        };
        let block =
            reconstruct_lossy_luma_16x16_from_prediction(prediction, coefficients, transform);
        for (row_offset, source) in block.samples.as_chunks::<16>().0.iter().enumerate() {
            let output_start = (offset_y + row_offset) * 16;
            samples[output_start..output_start + 16].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 split reconstruction needs the chroma predictor edges, child syntax, and reconstructed luma plane"
)]
fn reconstruct_lossy_chroma_8x8_split(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 8],
    left: [u16; 8],
    top_left: u16,
    has_left: bool,
    split: LossyChroma4x4Split,
    luma: &ReconstructedPlane,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 64];
    for transform_index in 0_usize..4 {
        let row = transform_index / 2;
        let column = transform_index % 2;
        let offset_x = column.saturating_mul(4);
        let offset_y = row.saturating_mul(4);
        let top_edge: [u16; 4] = std::array::from_fn(|index| {
            if row == 0 {
                top[offset_x.saturating_add(index)]
            } else {
                samples[(offset_y - 1).saturating_mul(8) + offset_x + index]
            }
        });
        let top_extension = [
            top_edge[0],
            top_edge[1],
            top_edge[2],
            top_edge[3],
            top_edge[3],
            top_edge[3],
            top_edge[3],
            top_edge[3],
        ];
        let left_edge: [u16; 4] = std::array::from_fn(|index| {
            if column == 0 {
                left[offset_y.saturating_add(index)]
            } else {
                samples[(offset_y + index).saturating_mul(8) + offset_x - 1]
            }
        });
        let block_top_left = match (row, column) {
            (0, 0) => top_left,
            (0, 1) => top[offset_x - 1],
            (1, 0) => left[offset_y - 1],
            _ => samples[(offset_y - 1).saturating_mul(8) + offset_x - 1],
        };
        let coefficients = split.coefficients[transform_index];
        let block = match predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let luma_samples: [u16; 64] = std::array::from_fn(|index| {
                    let x = offset_x.saturating_mul(2).saturating_add(index % 8);
                    let y = offset_y.saturating_mul(2).saturating_add(index / 8);
                    luma.samples[y.saturating_mul(16).saturating_add(x)]
                });
                let luma_block = ReconstructedPlane {
                    samples: luma_samples.to_vec(),
                };
                let alpha = if alpha_u == 0 { alpha_v } else { alpha_u };
                reconstruct_lossy_chroma_4x4_cfl(
                    &luma_block,
                    if has_left || column != 0 || row != 0 {
                        dc_predictor(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor_4(top_edge)
                    },
                    alpha,
                    coefficients,
                )?
            }
            ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
                if has_left || column != 0 || row != 0 {
                    dc_predictor(top_edge, left_edge)
                } else {
                    one_sided_dc_predictor_4(top_edge)
                },
                coefficients,
                LossyTransformKind::DctDct,
            ),
            ChromaPredictor::Vertical => reconstruct_lossy_chroma_4x4_vertical(
                top_edge,
                coefficients,
                chroma_transform_kind(predictor),
            ),
            ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
                left_edge,
                coefficients,
                LossyTransformKind::DctAdst,
            ),
            ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
                reconstruct_lossy_4x4_diagonal_z1(
                    top_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    coefficients,
                    chroma_transform_kind(predictor),
                )?
            }
            ChromaPredictor::DiagonalDownRight
            | ChromaPredictor::Diagonal113
            | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
                top_extension,
                left_edge,
                angle.ok_or(PortableUnavailable)?,
                coefficients,
                chroma_transform_kind(predictor),
            )?,
            ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
                left_edge,
                block_top_left,
                angle.ok_or(PortableUnavailable)?,
                coefficients,
                chroma_transform_kind(predictor),
            )?,
            ChromaPredictor::Smooth => {
                reconstruct_lossy_chroma_4x4_smooth(top_edge, top_edge[3], left_edge, coefficients)
            }
            ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
                top_edge,
                left_edge[3],
                coefficients,
                LossyTransformKind::AdstDct,
            ),
            ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
                left_edge,
                top_edge[3],
                coefficients,
                LossyTransformKind::DctAdst,
            ),
            ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
                top_edge,
                left_edge,
                block_top_left,
                coefficients,
                LossyTransformKind::DctDct,
            ),
        };
        for (row_offset, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (offset_y + row_offset).saturating_mul(8) + offset_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 split reconstruction needs the predictor edges, filtering state, and decoded child syntax"
)]
fn reconstruct_lossy_luma_8x16_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 16],
    top_left: u16,
    has_left: bool,
    split: LossyLuma8x8Split,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 128];
    for row in 0_usize..2 {
        let offset_y = row.saturating_mul(8);
        let top_edge = if row == 0 {
            top[..8].try_into().map_err(|_| PortableUnavailable)?
        } else {
            std::array::from_fn(|column| samples[(offset_y - 1).saturating_mul(8) + column])
        };
        let top_extension = if row == 0 {
            top
        } else {
            std::array::from_fn(|column| samples[(offset_y - 1).saturating_mul(8) + column.min(7)])
        };
        let left_edge = std::array::from_fn(|index| left[offset_y + index]);
        let block_top_left = if row == 0 {
            top_left
        } else {
            left[offset_y - 1]
        };
        let coefficients = split.coefficients[row];
        let transform = split.transforms[row];
        let block = if let Some(mode) = filter_intra_mode {
            let prediction = reconstruct_filter_intra_prediction(
                mode,
                8,
                8,
                block_top_left,
                &top_edge,
                &left_edge,
            )?;
            let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
            reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
        } else {
            match predictor {
                LumaPredictor::Dc => {
                    let value = if has_left || row != 0 {
                        dc_predictor_8(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor(top_edge)
                    };
                    reconstruct_lossy_luma_8x8(value, coefficients, transform)
                }
                LumaPredictor::Vertical => {
                    reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                }
                LumaPredictor::Horizontal => {
                    reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    if row == 0 {
                        reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                            top_extension,
                            block_top_left,
                            angle.ok_or(PortableUnavailable)?,
                            false,
                            false,
                            coefficients,
                            transform,
                        )?
                    } else {
                        reconstruct_lossy_luma_8x8_diagonal_z1(
                            top_edge,
                            block_top_left,
                            angle.ok_or(PortableUnavailable)?,
                            coefficients,
                            transform,
                        )?
                    }
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                    top_extension,
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                    top_edge,
                    top_extension[7],
                    left_edge,
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                    top_edge,
                    left_edge[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x8_smooth_horizontal(
                    left_edge,
                    top_extension[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                    top_edge,
                    left_edge,
                    block_top_left,
                    coefficients,
                    transform,
                ),
            }
        };
        for (row_offset, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
            let output_start = (offset_y + row_offset).saturating_mul(8);
            samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 split reconstruction needs the predictor edges, filtering state, and decoded child syntax"
)]
fn reconstruct_lossy_luma_16x8_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 8],
    top_left: u16,
    has_top: bool,
    split: LossyLuma8x8Split,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 128];
    for column in 0_usize..2 {
        let offset_x = column.saturating_mul(8);
        let top_edge = if has_top {
            top[offset_x..offset_x.saturating_add(8)]
                .try_into()
                .map_err(|_| PortableUnavailable)?
        } else {
            [top[0]; 8]
        };
        let top_extension = if has_top { top } else { [top[0]; 16] };
        let left_edge = if column == 0 {
            left
        } else {
            std::array::from_fn(|row| samples[row.saturating_mul(16) + offset_x - 1])
        };
        let block_top_left = if column == 0 {
            top_left
        } else if has_top {
            top[offset_x - 1]
        } else {
            top[0]
        };
        let coefficients = split.coefficients[column];
        let transform = split.transforms[column];
        let block = if let Some(mode) = filter_intra_mode {
            let prediction = reconstruct_filter_intra_prediction(
                mode,
                8,
                8,
                block_top_left,
                &top_edge,
                &left_edge,
            )?;
            let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
            reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
        } else {
            match predictor {
                LumaPredictor::Dc => {
                    let value = if has_top || column != 0 {
                        dc_predictor_8(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor(left_edge)
                    };
                    reconstruct_lossy_luma_8x8(value, coefficients, transform)
                }
                LumaPredictor::Vertical => {
                    reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                }
                LumaPredictor::Horizontal => {
                    reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                        top_extension,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        false,
                        coefficients,
                        transform,
                    )?
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                    top_extension,
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                    top_edge,
                    top_extension[7],
                    left_edge,
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                    top_edge,
                    left_edge[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x8_smooth_horizontal(
                    left_edge,
                    top_extension[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                    top_edge,
                    left_edge,
                    block_top_left,
                    coefficients,
                    transform,
                ),
            }
        };
        for (row, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
            let output_start = row.saturating_mul(16).saturating_add(offset_x);
            samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R16x32 split reconstruction needs both full edges and the child transform grid"
)]
fn reconstruct_lossy_luma_16x32_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 32],
    top_left: u16,
    has_left: bool,
    split: LossyLuma8x8GridSplit,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 512];
    for row in 0_usize..4 {
        for column in 0_usize..2 {
            let transform_index = row.saturating_mul(2).saturating_add(column);
            let offset_x = column.saturating_mul(8);
            let offset_y = row.saturating_mul(8);
            let top_edge: [u16; 8] = if row == 0 {
                top[offset_x..offset_x.saturating_add(8)]
                    .try_into()
                    .map_err(|_| PortableUnavailable)?
            } else {
                std::array::from_fn(|index| {
                    samples[(offset_y - 1).saturating_mul(16) + offset_x + index]
                })
            };
            let top_extension = if row == 0 {
                top
            } else {
                std::array::from_fn(|index| samples[(offset_y - 1).saturating_mul(16) + index])
            };
            let left_edge: [u16; 8] = if column == 0 {
                if has_left || row == 0 {
                    left[offset_y..offset_y.saturating_add(8)]
                        .try_into()
                        .map_err(|_| PortableUnavailable)?
                } else {
                    [top_edge[0]; 8]
                }
            } else {
                std::array::from_fn(|index| {
                    samples[(offset_y + index).saturating_mul(16) + offset_x - 1]
                })
            };
            let block_top_left = match (row, column) {
                (0, 0) => top_left,
                (0, _) => top[offset_x - 1],
                (_, 0) if has_left => left[offset_y - 1],
                (_, 0) => top_edge[0],
                _ => samples[(offset_y - 1).saturating_mul(16) + offset_x - 1],
            };
            let coefficients = split.coefficients[transform_index];
            let transform = split.transforms[transform_index];
            let block = if let Some(mode) = filter_intra_mode {
                let prediction = reconstruct_filter_intra_prediction(
                    mode,
                    8,
                    8,
                    block_top_left,
                    &top_edge,
                    &left_edge,
                )?;
                let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
                reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
            } else {
                match predictor {
                    LumaPredictor::Dc => {
                        let value = if has_left || row != 0 || column != 0 {
                            dc_predictor_8(top_edge, left_edge)
                        } else {
                            one_sided_dc_predictor(top_edge)
                        };
                        reconstruct_lossy_luma_8x8(value, coefficients, transform)
                    }
                    LumaPredictor::Vertical => {
                        reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                    }
                    LumaPredictor::Horizontal => {
                        reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                    }
                    LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                        if row == 0 {
                            reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                                top_extension,
                                block_top_left,
                                angle.ok_or(PortableUnavailable)?,
                                false,
                                false,
                                coefficients,
                                transform,
                            )?
                        } else {
                            reconstruct_lossy_luma_8x8_diagonal_z1(
                                top_edge,
                                block_top_left,
                                angle.ok_or(PortableUnavailable)?,
                                coefficients,
                                transform,
                            )?
                        }
                    }
                    LumaPredictor::DiagonalDownRight
                    | LumaPredictor::Diagonal113
                    | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                        top_extension,
                        left_edge,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        false,
                        coefficients,
                        transform,
                    )?,
                    LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                        left_edge,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        coefficients,
                        transform,
                    )?,
                    LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                        top_edge,
                        top_extension[7],
                        left_edge,
                        coefficients,
                        transform,
                    ),
                    LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                        top_edge,
                        left_edge[7],
                        coefficients,
                        transform,
                    ),
                    LumaPredictor::SmoothHorizontal => {
                        reconstruct_lossy_luma_8x8_smooth_horizontal(
                            left_edge,
                            top_extension[7],
                            coefficients,
                            transform,
                        )
                    }
                    LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                        top_edge,
                        left_edge,
                        block_top_left,
                        coefficients,
                        transform,
                    ),
                }
            };
            for (row_offset, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
                let output_start = (offset_y + row_offset).saturating_mul(16) + offset_x;
                samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
            }
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R32x16 horizontal split needs both complete predictor edges and child syntax"
)]
fn reconstruct_lossy_luma_32x16_horizontal_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 32],
    left: [u16; 16],
    top_left: u16,
    has_left: bool,
    split: LossyLuma16x16HorizontalSplit,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    let mut samples = vec![0_u16; 512];
    for column in 0_usize..2 {
        let offset_x = column.saturating_mul(16);
        let top_edge: [u16; 16] = std::array::from_fn(|index| top[offset_x + index]);
        let top_extension: [u16; 32] =
            std::array::from_fn(|index| top[offset_x.saturating_add(index).min(31)]);
        let left_edge: [u16; 16] = if column == 0 {
            left
        } else {
            std::array::from_fn(|index| samples[index.saturating_mul(32) + offset_x - 1])
        };
        let block_top_left = if column == 0 {
            top_left
        } else {
            top[offset_x - 1]
        };
        let prediction: [u16; 256] = if let Some(mode) = filter_intra_mode {
            reconstruct_filter_intra_prediction(
                mode,
                16,
                16,
                block_top_left,
                &top_edge,
                &left_edge,
            )?
            .try_into()
            .map_err(|_| PortableUnavailable)?
        } else {
            let mut prediction = [0_u16; 256];
            match predictor {
                LumaPredictor::Dc => {
                    let value = if has_left || column != 0 {
                        dc_predictor_16(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor_16(top_edge)
                    };
                    prediction.fill(value);
                }
                LumaPredictor::Vertical => {
                    for (index, value) in prediction.iter_mut().enumerate() {
                        *value = top_edge[index % 16];
                    }
                }
                LumaPredictor::Horizontal => {
                    for (index, value) in prediction.iter_mut().enumerate() {
                        *value = left_edge[index / 16];
                    }
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (0 < angle && angle < 90).then_some(()).portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?)
                        .filter(|&&value| value > 0)
                        .portable()?;
                    let upsample = 50 < angle;
                    let mut edge = [0_u16; 31];
                    let (max_base_x, dx, base_increment) = if upsample {
                        edge.copy_from_slice(&upsample_intra_top_edge_16(top_edge, block_top_left));
                        (30, dx.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&top_edge);
                        (15, dx, 1)
                    };
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] = diagonal_z1_predictor_sample(
                                &edge,
                                max_base_x,
                                dx,
                                base_increment,
                                x,
                                y,
                            )?;
                        }
                    }
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (90 < angle && angle < 180).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(angle.saturating_sub(90) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(180_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let mut edge = [0_u16; 65];
                    edge[32] = block_top_left;
                    for (index, value) in top_extension.into_iter().enumerate() {
                        edge[33 + index] = value;
                    }
                    for (index, value) in left_edge.into_iter().enumerate() {
                        edge[31 - index] = value;
                    }
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] =
                                diagonal_predictor_sample(&edge, 32, dx, dy, x, y)?;
                        }
                    }
                }
                LumaPredictor::Diagonal203 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (180 < angle && angle < 270).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(270_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let upsample = angle < 220;
                    let mut edge = [0_u16; 31];
                    let (max_base_y, dy, base_increment) = if upsample {
                        edge.copy_from_slice(&upsample_intra_left_edge_16(
                            left_edge,
                            block_top_left,
                        ));
                        (30, dy.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&left_edge);
                        (15, dy, 1)
                    };
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] = diagonal_z3_predictor_sample(
                                &edge,
                                max_base_y,
                                dy,
                                base_increment,
                                x,
                                y,
                            )?;
                        }
                    }
                }
                LumaPredictor::Smooth => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    let bottom = i32::from(left_edge[15]);
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            let vertical = i32::from(weights[y]);
                            let horizontal = i32::from(weights[x]);
                            let value = vertical
                                .saturating_mul(i32::from(top_edge[x]))
                                .saturating_add((256 - vertical).saturating_mul(bottom))
                                .saturating_add(horizontal.saturating_mul(i32::from(left_edge[y])))
                                .saturating_add((256 - horizontal).saturating_mul(right))
                                .saturating_add(256)
                                >> 9;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::SmoothVertical => {
                    let weights = smooth_weight_table(16)?;
                    let bottom = i32::from(left_edge[15]);
                    for y in 0_usize..16 {
                        let weight = i32::from(weights[y]);
                        for x in 0_usize..16 {
                            let value = weight
                                .saturating_mul(i32::from(top_edge[x]))
                                .saturating_add((256 - weight).saturating_mul(bottom))
                                .saturating_add(128)
                                >> 8;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::SmoothHorizontal => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            let weight = i32::from(weights[x]);
                            let value = weight
                                .saturating_mul(i32::from(left_edge[y]))
                                .saturating_add((256 - weight).saturating_mul(right))
                                .saturating_add(128)
                                >> 8;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::Paeth => {
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] =
                                paeth_predictor(top_edge[x], left_edge[y], block_top_left);
                        }
                    }
                }
            }
            prediction
        };
        let block = reconstruct_lossy_luma_16x16_from_prediction(
            prediction,
            split.coefficients[column],
            split.transforms[column],
        );
        for (row_offset, source) in block.samples.as_chunks::<16>().0.iter().enumerate() {
            let output_start = row_offset * 32 + offset_x;
            samples[output_start..output_start + 16].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R32x8 split reconstruction needs both full edges and the child transform grid"
)]
fn reconstruct_lossy_luma_32x8_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 32],
    left: [u16; 8],
    top_left: u16,
    has_left: bool,
    split: LossyLuma8x8GridSplit,
) -> PortableResult<ReconstructedPlane> {
    matches!(split.orientation, SplitOrientation::Horizontal)
        .then_some(())
        .portable()?;
    let mut samples = vec![0_u16; 256];
    for column in 0_usize..4 {
        let transform_index = column;
        let offset_x = column.saturating_mul(8);
        let top_edge: [u16; 8] = top[offset_x..offset_x.saturating_add(8)]
            .try_into()
            .map_err(|_| PortableUnavailable)?;
        let top_extension = std::array::from_fn(|index| top[(offset_x + index).min(31)]);
        let left_edge = if column == 0 {
            left
        } else {
            std::array::from_fn(|index| samples[index.saturating_mul(32) + offset_x - 1])
        };
        let block_top_left = if column == 0 {
            top_left
        } else {
            top[offset_x - 1]
        };
        let coefficients = split.coefficients[transform_index];
        let transform = split.transforms[transform_index];
        let block = if let Some(mode) = filter_intra_mode {
            let prediction = reconstruct_filter_intra_prediction(
                mode,
                8,
                8,
                block_top_left,
                &top_edge,
                &left_edge,
            )?;
            let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
            reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
        } else {
            match predictor {
                LumaPredictor::Dc => {
                    let value = if has_left || column != 0 {
                        dc_predictor_8(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor(top_edge)
                    };
                    reconstruct_lossy_luma_8x8(value, coefficients, transform)
                }
                LumaPredictor::Vertical => {
                    reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                }
                LumaPredictor::Horizontal => {
                    reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                        top_extension,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        false,
                        coefficients,
                        transform,
                    )?
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                    top_extension,
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                    top_edge,
                    top_extension[7],
                    left_edge,
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                    top_edge,
                    left_edge[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x8_smooth_horizontal(
                    left_edge,
                    top_extension[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                    top_edge,
                    left_edge,
                    block_top_left,
                    coefficients,
                    transform,
                ),
            }
        };
        for (row_offset, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
            let output_start = row_offset.saturating_mul(32) + offset_x;
            samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R32x16 split reconstruction needs both full edges and the child transform grid"
)]
fn reconstruct_lossy_luma_32x16_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 32],
    left: [u16; 16],
    top_left: u16,
    has_left: bool,
    split: LossyLuma8x8GridSplit,
) -> PortableResult<ReconstructedPlane> {
    matches!(split.orientation, SplitOrientation::Horizontal)
        .then_some(())
        .portable()?;
    let mut samples = vec![0_u16; 512];
    for row in 0_usize..2 {
        for column in 0_usize..4 {
            let transform_index = row.saturating_mul(4).saturating_add(column);
            let offset_x = column.saturating_mul(8);
            let offset_y = row.saturating_mul(8);
            let top_edge: [u16; 8] = if row == 0 {
                top[offset_x..offset_x.saturating_add(8)]
                    .try_into()
                    .map_err(|_| PortableUnavailable)?
            } else {
                std::array::from_fn(|index| {
                    samples[(offset_y - 1).saturating_mul(32) + offset_x + index]
                })
            };
            let top_extension: [u16; 16] = if row == 0 {
                std::array::from_fn(|index| top[(offset_x + index).min(31)])
            } else {
                std::array::from_fn(|index| {
                    samples[(offset_y - 1).saturating_mul(32) + (offset_x + index).min(31)]
                })
            };
            let left_edge: [u16; 8] = if column == 0 {
                left[offset_y..offset_y.saturating_add(8)]
                    .try_into()
                    .map_err(|_| PortableUnavailable)?
            } else {
                std::array::from_fn(|index| {
                    samples[(offset_y + index).saturating_mul(32) + offset_x - 1]
                })
            };
            let block_top_left = match (row, column) {
                (0, 0) => top_left,
                (0, _) => top[offset_x - 1],
                (_, 0) => left[offset_y - 1],
                _ => samples[(offset_y - 1).saturating_mul(32) + offset_x - 1],
            };
            let coefficients = split.coefficients[transform_index];
            let transform = split.transforms[transform_index];
            let block = if let Some(mode) = filter_intra_mode {
                let prediction = reconstruct_filter_intra_prediction(
                    mode,
                    8,
                    8,
                    block_top_left,
                    &top_edge,
                    &left_edge,
                )?;
                let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
                reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
            } else {
                match predictor {
                    LumaPredictor::Dc => {
                        let value = if has_left || row != 0 || column != 0 {
                            dc_predictor_8(top_edge, left_edge)
                        } else {
                            one_sided_dc_predictor(top_edge)
                        };
                        reconstruct_lossy_luma_8x8(value, coefficients, transform)
                    }
                    LumaPredictor::Vertical => {
                        reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                    }
                    LumaPredictor::Horizontal => {
                        reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                    }
                    LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                        if row == 0 {
                            reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                                top_extension,
                                block_top_left,
                                angle.ok_or(PortableUnavailable)?,
                                false,
                                false,
                                coefficients,
                                transform,
                            )?
                        } else {
                            reconstruct_lossy_luma_8x8_diagonal_z1(
                                top_edge,
                                block_top_left,
                                angle.ok_or(PortableUnavailable)?,
                                coefficients,
                                transform,
                            )?
                        }
                    }
                    LumaPredictor::DiagonalDownRight
                    | LumaPredictor::Diagonal113
                    | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                        top_extension,
                        left_edge,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        false,
                        coefficients,
                        transform,
                    )?,
                    LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                        left_edge,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        coefficients,
                        transform,
                    )?,
                    LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                        top_edge,
                        top_extension[7],
                        left_edge,
                        coefficients,
                        transform,
                    ),
                    LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                        top_edge,
                        left_edge[7],
                        coefficients,
                        transform,
                    ),
                    LumaPredictor::SmoothHorizontal => {
                        reconstruct_lossy_luma_8x8_smooth_horizontal(
                            left_edge,
                            top_extension[7],
                            coefficients,
                            transform,
                        )
                    }
                    LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                        top_edge,
                        left_edge,
                        block_top_left,
                        coefficients,
                        transform,
                    ),
                }
            };
            for (row_offset, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
                let output_start = (offset_y + row_offset).saturating_mul(32) + offset_x;
                samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
            }
        }
    }
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_following_lossy_420_vertical_16x32_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_8x8_grid_split,
        lossy_luma_16x32_coefficients,
        lossy_luma_16x32_transform,
        lossy_chroma_8x16_coefficients,
        ..
    } = syntax;

    let luma_top = if std::ptr::eq(above_left, above_right) {
        bottom_edge_16(&above_left.planes[0])
    } else {
        let left = bottom_edge_8_for_16x4_chroma(&above_left.planes[0]);
        let right = bottom_edge_8_for_16x4_chroma(&above_right.planes[0]);
        std::array::from_fn(|index| {
            if index < 8 {
                left[index]
            } else {
                right[index - 8]
            }
        })
    };
    let luma_left = left_neighbor.map_or([luma_top[0]; 32], |neighbor| {
        let plane = &neighbor.planes[0];
        if plane.samples.len() >= 512 {
            right_edge_at::<32>(plane, 16, 32, 0)
        } else {
            let edge = right_edge_16(plane);
            std::array::from_fn(|index| edge[index % 16])
        }
    });
    let luma_top_left = left_neighbor
        .and_then(|neighbor| neighbor.planes[0].samples.last().copied())
        .unwrap_or(luma_top[0]);
    let luma = if let Some(split) = lossy_luma_8x8_grid_split {
        reconstruct_lossy_luma_16x32_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top_left,
            left_neighbor.is_some(),
            split,
        )
    } else {
        let coefficients = lossy_luma_16x32_coefficients.ok_or(PortableUnavailable)?;

        reconstruct_lossy_luma_16x32_from_edges(
            luma_predictor,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top_left,
            left_neighbor.is_some(),
            coefficients,
            lossy_luma_16x32_transform,
        )
    }
    .map_err(|_| PortableUnavailable)?;

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top: [u16; 8] = if std::ptr::eq(above_left, above_right) {
            bottom_edge_8_for_16x4_chroma(&above_left.planes[plane])
        } else {
            let left = bottom_edge_4(&above_left.planes[plane]);
            let right = bottom_edge_4(&above_right.planes[plane]);
            std::array::from_fn(|index| {
                if index < 4 {
                    left[index]
                } else {
                    right[index - 4]
                }
            })
        };
        let left: [u16; 16] = left_neighbor.map_or([top[0]; 16], |neighbor| {
            let plane = &neighbor.planes[plane];
            if plane.samples.len() >= 128 {
                right_edge_at::<16>(plane, 8, 16, 0)
            } else {
                let edge = right_edge(plane);
                std::array::from_fn(|index| edge[index % 8])
            }
        });
        let coefficients = lossy_chroma_8x16_coefficients[plane.saturating_sub(1)];
        let transform = chroma_transform_kind(chroma_predictor);

        match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_chroma_8x16_cfl(
                    &luma,
                    rectangular_dc_predictor(&top, &left),
                    alpha,
                    coefficients,
                )
            }
            ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_8x16_from_prediction(
                [rectangular_dc_predictor(&top, &left); 128],
                coefficients,
                transform,
            )),
            ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_8x16_from_prediction(
                std::array::from_fn(|index| top[index % 8]),
                coefficients,
                transform,
            )),
            ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_8x16_from_prediction(
                std::array::from_fn(|index| left[index / 8]),
                coefficients,
                transform,
            )),
            ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_8x16_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 8], left[index / 8], top[0])
                }),
                coefficients,
                transform,
            )),
            ChromaPredictor::DiagonalDownRight
            | ChromaPredictor::Diagonal113
            | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_8x16_diagonal(
                std::array::from_fn(|index| top[index % 8]),
                left,
                chroma_angle.ok_or(PortableUnavailable)?,
                enable_intra_edge_filter,
                coefficients.unwrap_or([0_i32; 128]),
                transform,
            ),
            _ => Err(PortableUnavailable),
        }
    };

    let chroma_u = chroma(1)?;
    let chroma_v = chroma(2)?;
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_420_vertical_16x16_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
    left_luma_edge_16: Option<[u16; 16]>,
    left_chroma_edges_8: [Option<[u16; 8]>; 2],
    above_right_is_above_left: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_16x16_coefficients,
        lossy_luma_16x16_transform,
        lossy_luma_8x8_split,
        lossy_chroma_coefficients: _,
        lossy_chroma_8x8_coefficients,
        lossy_chroma_16x16_coefficients,
        lossy_chroma_4x4_splits,
        chroma_sampling,
        ..
    } = syntax;
    let above_luma_left = bottom_edge(&above_left.planes[0]);
    let luma_top = if above_right_is_above_left {
        bottom_edge_16(&above_left.planes[0])
    } else {
        let luma_right = bottom_edge(&above_right.planes[0]);
        [
            above_luma_left[0],
            above_luma_left[1],
            above_luma_left[2],
            above_luma_left[3],
            above_luma_left[4],
            above_luma_left[5],
            above_luma_left[6],
            above_luma_left[7],
            luma_right[0],
            luma_right[1],
            luma_right[2],
            luma_right[3],
            luma_right[4],
            luma_right[5],
            luma_right[6],
            luma_right[7],
        ]
    };
    let chroma_top = |plane: usize| {
        if above_right_is_above_left {
            bottom_edge_8_for_16x4_chroma(&above_left.planes[plane])
        } else {
            let left = bottom_edge_4(&above_left.planes[plane]);
            let right = bottom_edge_4(&above_right.planes[plane]);
            [
                left[0], left[1], left[2], left[3], right[0], right[1], right[2], right[3],
            ]
        }
    };
    let luma_left = left_luma_edge_16.unwrap_or_else(|| {
        left_neighbor.map_or([luma_top[0]; 16], |neighbor| {
            right_edge_16(&neighbor.planes[0])
        })
    });

    if let Some(split) = lossy_luma_8x8_split {
        let luma = reconstruct_lossy_luma_16x16_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            above_left.planes[0].samples.last().copied().unwrap_or(128),
            true,
            left_neighbor.is_some(),
            split,
        )?;
        let mut planes = [
            luma,
            ReconstructedPlane {
                samples: Vec::new(),
            },
            ReconstructedPlane {
                samples: Vec::new(),
            },
        ];
        let luma_for_chroma = planes[0].clone();
        for plane in 1..=2 {
            if matches!(chroma_sampling, ChromaSampling::Full) {
                let top = if above_right_is_above_left {
                    bottom_edge_16(&above_left.planes[plane])
                } else {
                    let left = bottom_edge_16(&above_left.planes[plane]);
                    let right = bottom_edge_16(&above_right.planes[plane]);
                    std::array::from_fn(|index| {
                        if index < 8 {
                            left[index]
                        } else {
                            right[index - 8]
                        }
                    })
                };
                let left = left_neighbor.map_or([top[0]; 16], |neighbor| {
                    right_edge_16(&neighbor.planes[plane])
                });
                let predictor = match chroma_predictor {
                    ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                        let alpha = if plane == 1 { alpha_u } else { alpha_v };
                        reconstruct_lossy_full_16x16_cfl(
                            &luma_for_chroma,
                            if left_neighbor.is_some() {
                                dc_predictor_16(top, left)
                            } else {
                                one_sided_dc_predictor_16(top)
                            },
                            alpha,
                            lossy_chroma_16x16_coefficients[plane - 1],
                        )?
                    }
                    _ => reconstruct_lossy_full_16x16_chroma(
                        chroma_predictor,
                        top,
                        left,
                        top[0],
                        left_neighbor.is_some(),
                        lossy_chroma_16x16_coefficients[plane - 1],
                    )?,
                };
                planes[plane] = predictor;
                continue;
            }
            let top = chroma_top(plane);
            let left = left_chroma_edges_8[plane - 1].unwrap_or([top[0]; 8]);
            let predictor = if left_neighbor.is_some() {
                dc_predictor_8(top, left)
            } else {
                one_sided_dc_predictor(top)
            };

            planes[plane] = match chroma_predictor {
                ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                    let alpha = if plane == 1 { alpha_u } else { alpha_v };
                    reconstruct_lossy_chroma_8x8_cfl(
                        &planes[0],
                        predictor,
                        alpha,
                        lossy_chroma_8x8_coefficients[plane - 1],
                    )?
                }
                _ if lossy_chroma_4x4_splits[plane - 1].is_some() => {
                    let chroma_split =
                        lossy_chroma_4x4_splits[plane - 1].ok_or(PortableUnavailable)?;
                    reconstruct_lossy_chroma_8x8_split(
                        chroma_predictor,
                        chroma_angle,
                        top,
                        left,
                        above_left.planes[plane]
                            .samples
                            .last()
                            .copied()
                            .unwrap_or(128),
                        left_neighbor.is_some(),
                        chroma_split,
                        &planes[0],
                    )?
                }
                _ => reconstruct_lossy_chroma_8x8(
                    predictor,
                    lossy_chroma_8x8_coefficients[plane - 1],
                    chroma_transform_kind(chroma_predictor),
                ),
            };
        }
        return Ok(ClosedLeaf {
            luma_predictor,
            planes,
        });
    }

    if matches!(chroma_sampling, ChromaSampling::Full) {
        let luma_top_left = above_left.planes[0].samples.last().copied().unwrap_or(128);
        let luma_prediction = if let Some(mode) = filter_intra_mode {
            reconstruct_filter_intra_prediction(mode, 16, 16, luma_top_left, &luma_top, &luma_left)?
                .try_into()
                .map_err(|_| PortableUnavailable)?
        } else {
            std::array::from_fn(|index| {
                let x = index % 16;
                let y = index / 16;
                match luma_predictor {
                    LumaPredictor::Dc => {
                        if left_neighbor.is_some() {
                            dc_predictor_16(luma_top, luma_left)
                        } else {
                            one_sided_dc_predictor_16(luma_top)
                        }
                    }
                    LumaPredictor::Vertical => luma_top[x],
                    LumaPredictor::Horizontal => luma_left[y],
                    LumaPredictor::Paeth => {
                        paeth_predictor(luma_top[x], luma_left[y], luma_top_left)
                    }
                    _ => luma_top[x],
                }
            })
        };
        let luma = reconstruct_lossy_luma_16x16_from_prediction(
            luma_prediction,
            lossy_luma_16x16_coefficients,
            lossy_luma_16x16_transform,
        );
        let luma_for_chroma = luma.clone();
        let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
            let top = if above_right_is_above_left {
                bottom_edge_16(&above_left.planes[plane])
            } else {
                let left = bottom_edge_16(&above_left.planes[plane]);
                let right = bottom_edge_16(&above_right.planes[plane]);
                std::array::from_fn(|index| {
                    if index < 8 {
                        left[index]
                    } else {
                        right[index - 8]
                    }
                })
            };
            let left = left_neighbor.map_or([top[0]; 16], |neighbor| {
                right_edge_16(&neighbor.planes[plane])
            });
            match chroma_predictor {
                ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                    let alpha = if plane == 1 { alpha_u } else { alpha_v };
                    reconstruct_lossy_full_16x16_cfl(
                        &luma_for_chroma,
                        if left_neighbor.is_some() {
                            dc_predictor_16(top, left)
                        } else {
                            one_sided_dc_predictor_16(top)
                        },
                        alpha,
                        lossy_chroma_16x16_coefficients[plane - 1],
                    )
                }
                _ => reconstruct_lossy_full_16x16_chroma(
                    chroma_predictor,
                    top,
                    left,
                    top[0],
                    left_neighbor.is_some(),
                    lossy_chroma_16x16_coefficients[plane - 1],
                ),
            }
        };
        return Ok(ClosedLeaf {
            luma_predictor,
            planes: [luma, chroma(1)?, chroma(2)?],
        });
    }

    let luma_mode = luma_predictor;
    let luma_predictor = match luma_mode {
        LumaPredictor::Vertical => luma_top[0],
        LumaPredictor::Horizontal if left_neighbor.is_some() => luma_left[0],
        LumaPredictor::Dc if left_neighbor.is_some() => dc_predictor_16(luma_top, luma_left),
        LumaPredictor::Dc => one_sided_dc_predictor_16(luma_top),
        _ => luma_mode.sample(),
    };
    let chroma_left =
        |plane: usize| left_chroma_edges_8[plane - 1].unwrap_or([chroma_top(plane)[0]; 8]);
    let predictors = [
        luma_predictor,
        if left_neighbor.is_some() {
            dc_predictor_8(chroma_top(1), chroma_left(1))
        } else {
            one_sided_dc_predictor(chroma_top(1))
        },
        if left_neighbor.is_some() {
            dc_predictor_8(chroma_top(2), chroma_left(2))
        } else {
            one_sided_dc_predictor(chroma_top(2))
        },
    ];

    Ok(reconstruct_leaf(syntax, predictors))
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 32x32 split reconstruction receives both full predictor edges and child syntax"
)]
fn reconstruct_lossy_luma_32x32_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 32],
    left: [u16; 32],
    top_left: u16,
    has_left: bool,
    split: LossyLuma16x16Split,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    let mut samples = vec![0_u16; 1024];
    for transform_index in 0_usize..4 {
        let row = transform_index / 2;
        let column = transform_index % 2;
        let offset_x = column.saturating_mul(16);
        let offset_y = row.saturating_mul(16);
        let top_edge: [u16; 16] = std::array::from_fn(|index| {
            if row == 0 {
                top[offset_x.saturating_add(index)]
            } else {
                samples[(offset_y - 1).saturating_mul(32) + offset_x + index]
            }
        });
        let top_extension: [u16; 32] = std::array::from_fn(|index| {
            if row == 0 {
                top[offset_x.saturating_add(index).min(31)]
            } else {
                samples[(offset_y - 1).saturating_mul(32) + (offset_x + index).min(31)]
            }
        });
        let left_edge: [u16; 16] = std::array::from_fn(|index| {
            if column == 0 {
                left[offset_y.saturating_add(index)]
            } else {
                samples[(offset_y + index).saturating_mul(32) + offset_x - 1]
            }
        });
        let block_top_left = match (row, column) {
            (0, 0) => top_left,
            (0, 1) => top[offset_x - 1],
            (1, 0) => left[offset_y - 1],
            _ => samples[(offset_y - 1).saturating_mul(32) + offset_x - 1],
        };
        let prediction = if let Some(mode) = filter_intra_mode {
            reconstruct_filter_intra_prediction(
                mode,
                16,
                16,
                block_top_left,
                &top_edge,
                &left_edge,
            )?
            .try_into()
            .map_err(|_| PortableUnavailable)?
        } else {
            let mut prediction = [0_u16; 256];
            match predictor {
                LumaPredictor::Dc => {
                    let value = if has_left || column != 0 || row != 0 {
                        dc_predictor_16(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor_16(top_edge)
                    };
                    prediction.fill(value);
                }
                LumaPredictor::Vertical => {
                    for (index, value) in prediction.iter_mut().enumerate() {
                        *value = top_edge[index % 16];
                    }
                }
                LumaPredictor::Horizontal => {
                    for (index, value) in prediction.iter_mut().enumerate() {
                        *value = left_edge[index / 16];
                    }
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (0 < angle && angle < 90).then_some(()).portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?)
                        .filter(|&&value| value > 0)
                        .portable()?;
                    let upsample = 50 < angle;
                    let mut edge = [0_u16; 31];
                    let (max_base_x, dx, base_increment) = if upsample {
                        edge.copy_from_slice(&upsample_intra_top_edge_16(top_edge, block_top_left));
                        (30, dx.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&top_edge);
                        (15, dx, 1)
                    };
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] = diagonal_z1_predictor_sample(
                                &edge,
                                max_base_x,
                                dx,
                                base_increment,
                                x,
                                y,
                            )?;
                        }
                    }
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (90 < angle && angle < 180).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(angle.saturating_sub(90) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(180_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let mut edge = [0_u16; 65];
                    edge[32] = block_top_left;
                    for (index, value) in top_extension.into_iter().enumerate() {
                        edge[33 + index] = value;
                    }
                    for (index, value) in left_edge.into_iter().enumerate() {
                        edge[31 - index] = value;
                    }
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] =
                                diagonal_predictor_sample(&edge, 32, dx, dy, x, y)?;
                        }
                    }
                }
                LumaPredictor::Diagonal203 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (180 < angle && angle < 270).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(270_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let upsample = angle < 220;
                    let mut edge = [0_u16; 31];
                    let (max_base_y, dy, base_increment) = if upsample {
                        edge.copy_from_slice(&upsample_intra_left_edge_16(
                            left_edge,
                            block_top_left,
                        ));
                        (30, dy.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&left_edge);
                        (15, dy, 1)
                    };
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] = diagonal_z3_predictor_sample(
                                &edge,
                                max_base_y,
                                dy,
                                base_increment,
                                x,
                                y,
                            )?;
                        }
                    }
                }
                LumaPredictor::Smooth => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    let bottom = i32::from(left_edge[15]);
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            let vertical = i32::from(weights[y]);
                            let horizontal = i32::from(weights[x]);
                            let value = vertical
                                .saturating_mul(i32::from(top_edge[x]))
                                .saturating_add((256 - vertical).saturating_mul(bottom))
                                .saturating_add(horizontal.saturating_mul(i32::from(left_edge[y])))
                                .saturating_add((256 - horizontal).saturating_mul(right))
                                .saturating_add(256)
                                >> 9;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::SmoothVertical => {
                    let weights = smooth_weight_table(16)?;
                    let bottom = i32::from(left_edge[15]);
                    for y in 0_usize..16 {
                        let weight = i32::from(weights[y]);
                        for x in 0_usize..16 {
                            let value = weight
                                .saturating_mul(i32::from(top_edge[x]))
                                .saturating_add((256 - weight).saturating_mul(bottom))
                                .saturating_add(128)
                                >> 8;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::SmoothHorizontal => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            let weight = i32::from(weights[x]);
                            let value = weight
                                .saturating_mul(i32::from(left_edge[y]))
                                .saturating_add((256 - weight).saturating_mul(right))
                                .saturating_add(128)
                                >> 8;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::Paeth => {
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] =
                                paeth_predictor(top_edge[x], left_edge[y], block_top_left);
                        }
                    }
                }
            }
            prediction
        };
        let block = reconstruct_lossy_luma_16x16_from_prediction(
            prediction,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        );
        for (row_offset, source) in block.samples.as_chunks::<16>().0.iter().enumerate() {
            let output_start = (offset_y + row_offset) * 32 + offset_x;
            samples[output_start..output_start + 16].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_following_lossy_420_vertical_32x32_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
    left_luma_edge: Option<[u16; 32]>,
) -> ClosedLeaf {
    let luma_top = if std::ptr::eq(above_left, above_right) {
        bottom_edge_32(&above_left.planes[0])
    } else {
        let left = bottom_edge_16(&above_left.planes[0]);
        let right = bottom_edge_16(&above_right.planes[0]);
        std::array::from_fn(|index| {
            if index < 16 {
                left[index]
            } else {
                right[index - 16]
            }
        })
    };
    let luma_left = left_luma_edge.unwrap_or([luma_top[0]; 32]);
    let luma_top_left = left_neighbor
        .and_then(|neighbor| neighbor.planes[0].samples.last().copied())
        .unwrap_or(luma_top[0]);
    let luma = if let Some(split) = syntax.lossy_luma_16x16_split {
        reconstruct_lossy_luma_32x32_split(
            syntax.luma_predictor,
            syntax.luma_angle,
            syntax.filter_intra_mode,
            luma_top,
            luma_left,
            luma_top_left,
            left_neighbor.is_some(),
            split,
        )
        .unwrap_or_else(|_| ReconstructedPlane {
            samples: vec![syntax.luma_predictor.sample(); 1024],
        })
    } else {
        let prediction = match syntax.luma_predictor {
            LumaPredictor::Dc => {
                let predictor = if left_neighbor.is_some() {
                    rectangular_dc_predictor(&luma_top, &luma_left)
                } else {
                    one_sided_dc_predictor_32(luma_top)
                };
                [predictor; 1024]
            }
            LumaPredictor::Vertical => std::array::from_fn(|index| luma_top[index % 32]),
            LumaPredictor::Horizontal => std::array::from_fn(|index| luma_left[index / 32]),
            LumaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 32], luma_left[index / 32], luma_top_left)
            }),
            predictor => [predictor.sample(); 1024],
        };
        reconstruct_lossy_32x32_from_prediction(prediction, syntax.lossy_luma_32x32_coefficients)
    };
    let chroma_top = |plane: usize| {
        if std::ptr::eq(above_left, above_right) {
            bottom_edge_32(&above_left.planes[plane])
        } else {
            let left = bottom_edge_16(&above_left.planes[plane]);
            let right = bottom_edge_16(&above_right.planes[plane]);
            std::array::from_fn(|index| {
                if index < 16 {
                    left[index]
                } else {
                    right[index - 16]
                }
            })
        }
    };
    let chroma_predictor = match syntax.chroma_predictor {
        ChromaPredictor::Dc => [
            one_sided_dc_predictor_32(chroma_top(1)),
            one_sided_dc_predictor_32(chroma_top(2)),
        ],
        _ => [128; 2],
    };
    let mut leaf = reconstruct_leaf(
        syntax,
        [
            syntax.luma_predictor.sample(),
            chroma_predictor[0],
            chroma_predictor[1],
        ],
    );
    leaf.planes[0] = luma;
    if matches!(syntax.chroma_sampling, ChromaSampling::Full) {
        for plane in 1..=2 {
            let predictor = if matches!(syntax.chroma_predictor, ChromaPredictor::Dc) {
                one_sided_dc_predictor_32(chroma_top(plane))
            } else {
                128
            };
            leaf.planes[plane] = reconstruct_lossy_chroma_32x32(
                predictor,
                syntax.lossy_chroma_32x32_coefficients[plane - 1],
            );
        }
    }
    leaf
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 vertical leaf path receives each independently resolved neighbor edge and tool flag"
)]
fn reconstruct_following_lossy_420_vertical_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    above_left_width: u32,
    above_right_width: u32,
    above_left_x_offset: u32,
    above_right_x_offset: u32,
    above_luma_extension: Option<[u16; 8]>,
    above_chroma_extension: Option<&ClosedLeaf>,
    above_chroma_extension_width: u32,
    above_chroma_extension_x_offset: u32,
    left_top_neighbor: Option<&ClosedLeaf>,
    left_luma_top_neighbor: Option<&ClosedLeaf>,
    left_neighbor: Option<&ClosedLeaf>,
    above_chroma_neighbor: Option<&ClosedLeaf>,
    above_chroma_width: u32,
    above_chroma_x_offset: u32,
    left_chroma_neighbor: Option<&ClosedLeaf>,
    left_chroma_width: u32,
    left_chroma_height: u32,
    left_chroma_y_offset: u32,
    left_luma_edge: Option<[u16; 8]>,
    left_luma_bottom: Option<[u16; 8]>,
    left_chroma_bottom: [Option<[u16; 4]>; 2],
    left_top_left_sample: Option<u16>,
    left_chroma_edges: [Option<[u16; 4]>; 2],
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    if matches!(syntax.transform_grid, TransformGrid::Square4) {
        return reconstruct_following_lossy_420_square4_leaf(
            syntax,
            above_left,
            above_right,
            left_top_neighbor,
            left_neighbor,
            above_chroma_neighbor,
            above_chroma_width,
            above_chroma_x_offset,
            left_chroma_neighbor,
            left_chroma_width,
            left_chroma_height,
            left_chroma_y_offset,
            true,
        );
    }
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_coefficients,
        lossy_luma_transform,
        lossy_luma_4x4_split,
        lossy_chroma_coefficients,
        ..
    } = syntax;
    // AV1 converts PAETH to the predictor supported by the available edges
    // during reconstruction. The transform is still derived from the coded
    // chroma mode, so keep `chroma_predictor` unchanged for transform lookup.
    let chroma_reconstruction_predictor = match (
        chroma_predictor,
        left_chroma_neighbor.is_some(),
        above_chroma_neighbor.is_some(),
    ) {
        (ChromaPredictor::Paeth, false, true) => ChromaPredictor::Vertical,
        (ChromaPredictor::Paeth, true, false) => ChromaPredictor::Horizontal,
        (ChromaPredictor::Paeth, false, false) => ChromaPredictor::Dc,
        (predictor, _, _) => predictor,
    };
    let luma_top_left = combined_bottom_edge::<8>(
        &above_left.planes[0],
        above_left_width,
        above_left_x_offset,
        &above_right.planes[0],
        above_right_width,
        above_right_x_offset,
    );
    let use_luma_extension = matches!(
        luma_predictor,
        LumaPredictor::Vertical | LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67
    ) && luma_angle.is_some_and(|angle| 0 < angle && angle < 90);
    let luma_top_right = if use_luma_extension {
        above_luma_extension.unwrap_or_else(|| {
            if above_right_x_offset.saturating_add(8) > above_right_width {
                luma_top_left
            } else {
                bottom_edge_at::<8>(
                    &above_right.planes[0],
                    above_right_width,
                    above_right_x_offset,
                )
            }
        })
    } else if above_right_x_offset.saturating_add(8) > above_right_width {
        luma_top_left
    } else {
        bottom_edge_at::<8>(
            &above_right.planes[0],
            above_right_width,
            above_right_x_offset,
        )
    };
    let luma_top_left_sample = left_top_left_sample
        .or_else(|| {
            left_top_neighbor.and_then(|neighbor| neighbor.planes[0].samples.last().copied())
        })
        .unwrap_or_else(|| {
            above_left_x_offset.checked_sub(1).map_or_else(
                || above_left.planes[0].samples.last().copied().unwrap_or(128),
                |offset| bottom_sample_at(&above_left.planes[0], above_left_width, offset),
            )
        });

    let mut luma_top = [0_u16; 16];
    luma_top[..8].copy_from_slice(&luma_top_left);
    if luma_top_right == luma_top_left {
        luma_top[8..].fill(luma_top_left[7]);
    } else {
        luma_top[8..].copy_from_slice(&luma_top_right);
    }

    let luma_left = left_luma_edge.unwrap_or([luma_top[0]; 8]);

    let filter_intra_top_left = if left_neighbor.is_some() {
        luma_top_left_sample
    } else {
        luma_top[0]
    };

    // With no left neighbor, dav1d's prepared edge uses the first top sample
    // as the effective top-left for angular prediction.
    let luma_top_left_for_prediction = filter_intra_top_left;
    let smooth_edges = |predictor: LumaPredictor| {
        matches!(
            predictor,
            LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
        )
    };
    let smooth_neighbor_edges = smooth_edges(above_left.luma_predictor)
        || left_luma_top_neighbor.is_some_and(|neighbor| smooth_edges(neighbor.luma_predictor));

    let luma = if let Some(split) = lossy_luma_4x4_split {
        match (filter_intra_mode, luma_predictor) {
            (None, LumaPredictor::Dc) => Ok(reconstruct_lossy_luma_8x8_split_dc_vertical(
                luma_top_left,
                left_luma_edge,
                split,
            )),
            (None, LumaPredictor::Smooth) => Ok(reconstruct_lossy_luma_8x8_split_smooth_vertical(
                luma_top_left,
                left_luma_edge,
                split,
            )),
            (None, LumaPredictor::SmoothVertical) => {
                Ok(reconstruct_lossy_luma_8x8_split_smooth_vertical_only(
                    luma_top_left,
                    left_luma_edge,
                    split,
                ))
            }
            (None, LumaPredictor::SmoothHorizontal) => {
                Ok(reconstruct_lossy_luma_8x8_split_smooth_horizontal_vertical(
                    luma_top_left,
                    left_luma_edge,
                    split,
                ))
            }
            (None, LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67) => {
                reconstruct_lossy_luma_8x8_split_diagonal_z1_extended(
                    luma_top,
                    left_luma_edge,
                    Some(luma_top_left_for_prediction),
                    luma_angle.ok_or(PortableUnavailable)?,
                    smooth_neighbor_edges,
                    split,
                )
            }
            (None, LumaPredictor::Vertical) => match luma_angle {
                None | Some(90) => Ok(reconstruct_lossy_luma_8x8_split_vertical(
                    luma_top_left,
                    split,
                )),
                Some(angle) if 0 < angle && angle < 90 => {
                    reconstruct_lossy_luma_8x8_split_diagonal_z1_extended(
                        luma_top,
                        left_luma_edge,
                        Some(luma_top_left_for_prediction),
                        angle,
                        smooth_neighbor_edges,
                        split,
                    )
                }
                Some(angle) if 90 < angle && angle < 180 => {
                    reconstruct_lossy_luma_8x8_split_diagonal_vertical(
                        luma_top_left,
                        left_luma_edge,
                        Some(luma_top_left_for_prediction),
                        angle,
                        true,
                        smooth_neighbor_edges,
                        split,
                    )
                }
                _ => Err(PortableUnavailable),
            },
            (None, LumaPredictor::Horizontal) => match luma_angle {
                None | Some(180) => Ok(reconstruct_lossy_luma_8x8_split_horizontal_vertical(
                    luma_top_left,
                    left_luma_edge,
                    split,
                )),
                Some(angle) if 90 < angle && angle < 180 => {
                    reconstruct_lossy_luma_8x8_split_diagonal_vertical(
                        luma_top_left,
                        left_luma_edge,
                        Some(luma_top_left_for_prediction),
                        angle,
                        true,
                        smooth_neighbor_edges,
                        split,
                    )
                }
                Some(angle) if 180 < angle && angle < 270 => {
                    reconstruct_lossy_luma_8x8_split_diagonal_z3(
                        luma_left,
                        luma_top_left,
                        luma_top_left_sample,
                        left_luma_bottom,
                        angle,
                        enable_intra_edge_filter,
                        split,
                    )
                }
                _ => Err(PortableUnavailable),
            },
            (None, LumaPredictor::Paeth) => Ok(reconstruct_lossy_luma_8x8_split_paeth(
                luma_top_left,
                left_luma_edge,
                filter_intra_top_left,
                split,
            )),
            (Some(mode), _) => {
                let left = left_neighbor.map_or([luma_top_left[0]; 8], |_| {
                    left_luma_edge.unwrap_or([luma_top_left[0]; 8])
                });
                reconstruct_lossy_luma_8x8_split_filter_intra(
                    luma_top_left,
                    left,
                    filter_intra_top_left,
                    split,
                    mode,
                )
            }
            (
                None,
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157,
            ) => reconstruct_lossy_luma_8x8_split_diagonal_vertical(
                luma_top_left,
                left_luma_edge,
                Some(luma_top_left_for_prediction),
                luma_angle.ok_or(PortableUnavailable)?,
                true,
                smooth_neighbor_edges,
                split,
            ),
            (None, LumaPredictor::Diagonal203) => reconstruct_lossy_luma_8x8_split_diagonal_z3(
                luma_left,
                luma_top_left,
                luma_top_left_sample,
                left_luma_bottom,
                luma_angle.ok_or(PortableUnavailable)?,
                enable_intra_edge_filter,
                split,
            ),
        }?
    } else {
        if let Some(mode) = filter_intra_mode {
            let prediction = reconstruct_filter_intra_prediction(
                mode,
                8,
                8,
                filter_intra_top_left,
                &luma_top_left,
                &luma_left,
            )?;
            let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
            reconstruct_lossy_luma_8x8_from_prediction(
                prediction,
                lossy_luma_coefficients,
                lossy_luma_transform,
            )
        } else {
            match (luma_predictor, luma_angle) {
                (LumaPredictor::Dc, _) => reconstruct_lossy_luma_8x8(
                    if left_neighbor.is_some() {
                        dc_predictor_8(luma_top_left, luma_left)
                    } else {
                        one_sided_dc_predictor(luma_top_left)
                    },
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                (LumaPredictor::Vertical, None | Some(90)) => reconstruct_lossy_luma_8x8_vertical(
                    luma_top_left,
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                (LumaPredictor::Vertical, Some(angle)) if 0 < angle && angle < 90 => {
                    reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                        luma_top,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Vertical, Some(angle)) if 90 < angle && angle < 180 => {
                    reconstruct_lossy_luma_8x8_diagonal(
                        luma_top,
                        luma_left,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Horizontal, None | Some(180)) => {
                    reconstruct_lossy_luma_8x8_horizontal(
                        luma_left,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )
                }
                (LumaPredictor::Horizontal, Some(angle)) if 180 < angle && angle < 270 => {
                    reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
                        luma_left,
                        luma_top_left_for_prediction,
                        left_luma_bottom,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Horizontal, Some(angle)) if 90 < angle && angle < 180 => {
                    reconstruct_lossy_luma_8x8_diagonal(
                        luma_top,
                        luma_left,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67, Some(angle)) => {
                    reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                        luma_top,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::DiagonalDownRight | LumaPredictor::Diagonal113, Some(angle))
                    if (90..180).contains(&angle) =>
                {
                    reconstruct_lossy_luma_8x8_diagonal(
                        luma_top,
                        luma_left,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Diagonal157, Some(angle)) if (90..180).contains(&angle) => {
                    reconstruct_lossy_luma_8x8_diagonal(
                        luma_top,
                        luma_left,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Diagonal203, Some(angle)) => {
                    reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
                        luma_left,
                        luma_top_left_for_prediction,
                        left_luma_bottom,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Smooth, None) => reconstruct_lossy_luma_8x8_smooth(
                    luma_top_left,
                    luma_top_left[7],
                    luma_left,
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                (LumaPredictor::Smooth, Some(_)) => reconstruct_lossy_luma_8x8_smooth(
                    luma_top_right,
                    luma_top_right[7],
                    luma_left,
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                (LumaPredictor::SmoothVertical, _) => reconstruct_lossy_luma_8x8_smooth_vertical(
                    luma_top_left,
                    luma_left[7],
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                (LumaPredictor::SmoothHorizontal, _) => {
                    reconstruct_lossy_luma_8x8_smooth_horizontal(
                        luma_left,
                        luma_top_left[7],
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )
                }
                (LumaPredictor::Paeth, _) => reconstruct_lossy_luma_8x8_paeth(
                    luma_top_left,
                    luma_left,
                    filter_intra_top_left,
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                _ => return Err(PortableUnavailable),
            }
        }
    };

    let chroma_top_left = above_chroma_neighbor.map_or_else(
        || {
            combined_bottom_edge::<4>(
                &above_left.planes[1],
                above_left_width.div_ceil(2).max(4),
                above_left_x_offset / 2,
                &above_right.planes[1],
                above_right_width.div_ceil(2).max(4),
                above_right_x_offset / 2,
            )
        },
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[1],
                above_chroma_width.div_ceil(2).max(4),
                above_chroma_x_offset,
            )
        },
    );
    let chroma_top_right = above_chroma_extension.map_or_else(
        || {
            if above_right_x_offset / 2 + 4 > above_right_width.div_ceil(2).max(4) {
                chroma_top_left
            } else {
                bottom_edge_at::<4>(
                    &above_right.planes[1],
                    above_right_width.div_ceil(2).max(4),
                    above_right_x_offset / 2,
                )
            }
        },
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[1],
                above_chroma_extension_width.div_ceil(2).max(4),
                above_chroma_extension_x_offset,
            )
        },
    );
    // A split 8×8 luma leaf leaves the final four luma edge samples in the
    // shared AV1 intra-edge scratch region. At a tile boundary the following
    // 4×4 chroma Zone-2 predictor consumes that bounded continuation rather
    // than repeating the last chroma-top sample.
    let chroma_top_z2_right =
        if lossy_luma_4x4_split.is_some() && chroma_top_right == chroma_top_left {
            left_top_neighbor.map_or(chroma_top_right, |neighbor| {
                if neighbor.planes[0].samples.len() >= 64 {
                    bottom_edge_at::<4>(&neighbor.planes[0], 8, 4)
                } else {
                    bottom_edge_4(&neighbor.planes[0])
                }
            })
        } else {
            chroma_top_right
        };
    let chroma_top_z2 = [
        chroma_top_left[0],
        chroma_top_left[1],
        chroma_top_left[2],
        chroma_top_left[3],
        chroma_top_z2_right[0],
        chroma_top_z2_right[1],
        chroma_top_z2_right[2],
        chroma_top_z2_right[3],
    ];
    let chroma_top_z1 = [
        chroma_top_left[0],
        chroma_top_left[1],
        chroma_top_left[2],
        chroma_top_left[3],
        chroma_top_right[0],
        chroma_top_right[1],
        chroma_top_right[2],
        chroma_top_right[3],
    ];
    let chroma_left_u = left_chroma_edges[0].unwrap_or([chroma_top_left[0]; 4]);
    let chroma_top_left_u = match (above_chroma_neighbor, left_chroma_neighbor) {
        (None, None) => 128,
        (None, Some(_)) => chroma_left_u[0],
        (Some(_), None) => chroma_top_left[0],
        (Some(above), Some(left)) => {
            if left_chroma_y_offset > 0 {
                right_edge_at::<1>(
                    &left.planes[1],
                    left_chroma_width.div_ceil(2).max(4),
                    left_chroma_height.div_ceil(2).max(4),
                    left_chroma_y_offset.saturating_sub(1),
                )[0]
            } else if above_chroma_x_offset > 0 {
                bottom_edge_at::<1>(
                    &above.planes[1],
                    above_chroma_width.div_ceil(2).max(4),
                    above_chroma_x_offset.saturating_sub(1),
                )[0]
            } else {
                left_top_neighbor.map_or(128, |neighbor| {
                    bottom_right_for_square4(&neighbor.planes[1])
                })
            }
        }
    };
    let chroma_dc_u = left_chroma_edges[0].map_or_else(
        || one_sided_dc_predictor_4(chroma_top_left),
        |left| dc_predictor(chroma_top_left, left),
    );

    let chroma_u = match chroma_reconstruction_predictor {
        ChromaPredictor::Cfl { alpha_u, .. } => reconstruct_lossy_chroma_4x4_cfl(
            &luma,
            chroma_dc_u,
            alpha_u,
            lossy_chroma_coefficients[0],
        )?,
        ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
            chroma_dc_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Vertical => match chroma_angle {
            None | Some(90) => Ok(reconstruct_lossy_chroma_4x4_vertical(
                chroma_top_left,
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            )),
            Some(angle) if 0 < angle && angle < 90 => reconstruct_lossy_4x4_diagonal_z1_extended(
                chroma_top_z1,
                chroma_top_left_u,
                angle,
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            ),
            Some(angle) if 90 < angle && angle < 180 => {
                reconstruct_lossy_chroma_4x4_diagonal_with_filter(
                    chroma_top_z2,
                    chroma_left_u,
                    chroma_top_left_u,
                    angle,
                    lossy_chroma_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                    enable_intra_edge_filter,
                )
            }
            _ => Err(PortableUnavailable),
        }?,
        ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
            chroma_left_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            chroma_top_z2,
            chroma_left_u,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[0],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3_with_bottom_left(
            chroma_left_u,
            left_chroma_bottom[0],
            chroma_top_left_u,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[0],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1(
                chroma_top_left,
                chroma_top_left_u,
                chroma_angle.ok_or(PortableUnavailable)?,
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            )?
        }
        ChromaPredictor::Smooth => reconstruct_lossy_chroma_4x4_smooth(
            chroma_top_left,
            chroma_top_left[3],
            chroma_left_u,
            lossy_chroma_coefficients[0],
        ),
        ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            chroma_top_left,
            chroma_left_u[3],
            lossy_chroma_coefficients[0],
            LossyTransformKind::AdstDct,
        ),
        ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            chroma_left_u,
            chroma_top_right[3],
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            chroma_top_left,
            chroma_left_u,
            chroma_top_left_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        ),
    };

    let chroma_top_left_v_edge = above_chroma_neighbor.map_or_else(
        || bottom_edge_4(&above_left.planes[2]),
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[2],
                above_chroma_width.div_ceil(2).max(4),
                above_chroma_x_offset,
            )
        },
    );
    let chroma_top_right_v = above_chroma_extension.map_or_else(
        || {
            if above_right_x_offset / 2 + 4 > above_right_width.div_ceil(2).max(4) {
                chroma_top_left_v_edge
            } else {
                bottom_edge_at::<4>(
                    &above_right.planes[2],
                    above_right_width.div_ceil(2).max(4),
                    above_right_x_offset / 2,
                )
            }
        },
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[2],
                above_chroma_extension_width.div_ceil(2).max(4),
                above_chroma_extension_x_offset,
            )
        },
    );
    let chroma_top_z1_v = [
        chroma_top_left_v_edge[0],
        chroma_top_left_v_edge[1],
        chroma_top_left_v_edge[2],
        chroma_top_left_v_edge[3],
        chroma_top_right_v[0],
        chroma_top_right_v[1],
        chroma_top_right_v[2],
        chroma_top_right_v[3],
    ];
    let chroma_top_z2_right_v =
        if lossy_luma_4x4_split.is_some() && chroma_top_right_v == chroma_top_left_v_edge {
            left_top_neighbor.map_or(chroma_top_right_v, |neighbor| {
                if neighbor.planes[0].samples.len() >= 64 {
                    bottom_edge_at::<4>(&neighbor.planes[0], 8, 4)
                } else {
                    bottom_edge_4(&neighbor.planes[0])
                }
            })
        } else {
            chroma_top_right_v
        };
    let chroma_top_z2_v = [
        chroma_top_left_v_edge[0],
        chroma_top_left_v_edge[1],
        chroma_top_left_v_edge[2],
        chroma_top_left_v_edge[3],
        chroma_top_z2_right_v[0],
        chroma_top_z2_right_v[1],
        chroma_top_z2_right_v[2],
        chroma_top_z2_right_v[3],
    ];
    let chroma_left_v = left_chroma_edges[1].unwrap_or([chroma_top_left_v_edge[0]; 4]);
    let chroma_top_left_v = match (above_chroma_neighbor, left_chroma_neighbor) {
        (None, None) => 128,
        (None, Some(_)) => chroma_left_v[0],
        (Some(_), None) => chroma_top_left_v_edge[0],
        (Some(above), Some(left)) => {
            if left_chroma_y_offset > 0 {
                right_edge_at::<1>(
                    &left.planes[2],
                    left_chroma_width.div_ceil(2).max(4),
                    left_chroma_height.div_ceil(2).max(4),
                    left_chroma_y_offset.saturating_sub(1),
                )[0]
            } else if above_chroma_x_offset > 0 {
                bottom_edge_at::<1>(
                    &above.planes[2],
                    above_chroma_width.div_ceil(2).max(4),
                    above_chroma_x_offset.saturating_sub(1),
                )[0]
            } else {
                left_top_neighbor.map_or(128, |neighbor| {
                    bottom_right_for_square4(&neighbor.planes[2])
                })
            }
        }
    };
    let chroma_dc_v = left_chroma_edges[1].map_or_else(
        || one_sided_dc_predictor_4(chroma_top_left_v_edge),
        |left| dc_predictor(chroma_top_left_v_edge, left),
    );
    let chroma_v = match chroma_reconstruction_predictor {
        ChromaPredictor::Cfl { alpha_v, .. } => reconstruct_lossy_chroma_4x4_cfl(
            &luma,
            chroma_dc_v,
            alpha_v,
            lossy_chroma_coefficients[1],
        )?,
        ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
            chroma_dc_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Vertical => match chroma_angle {
            None | Some(90) => Ok(reconstruct_lossy_chroma_4x4_vertical(
                chroma_top_left_v_edge,
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            )),
            Some(angle) if 0 < angle && angle < 90 => reconstruct_lossy_4x4_diagonal_z1_extended(
                chroma_top_z1_v,
                chroma_top_left_v,
                angle,
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            ),
            Some(angle) if 90 < angle && angle < 180 => {
                reconstruct_lossy_chroma_4x4_diagonal_with_filter(
                    chroma_top_z2_v,
                    chroma_left_v,
                    chroma_top_left_v,
                    angle,
                    lossy_chroma_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                    enable_intra_edge_filter,
                )
            }
            _ => Err(PortableUnavailable),
        }?,
        ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
            chroma_left_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            chroma_top_z2_v,
            chroma_left_v,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[1],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3_with_bottom_left(
            chroma_left_v,
            left_chroma_bottom[1],
            chroma_top_left_v,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[1],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1(
                chroma_top_left_v_edge,
                chroma_top_left_v,
                chroma_angle.ok_or(PortableUnavailable)?,
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            )?
        }
        ChromaPredictor::Smooth => reconstruct_lossy_chroma_4x4_smooth(
            chroma_top_left_v_edge,
            chroma_top_left_v_edge[3],
            chroma_left_v,
            lossy_chroma_coefficients[1],
        ),
        ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            chroma_top_left_v_edge,
            chroma_left_v[3],
            lossy_chroma_coefficients[1],
            LossyTransformKind::AdstDct,
        ),
        ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            chroma_left_v,
            chroma_top_right_v[3],
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            chroma_top_left_v_edge,
            chroma_left_v,
            chroma_top_left_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        ),
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_boundary_leaf(
    syntax: BlockSyntax,
    above: &ClosedLeaf,
    left: &ClosedLeaf,
) -> ClosedLeaf {
    let planes = [
        reconstruct_boundary_plane(&above.planes[0], &left.planes[0], syntax.coefficients[0]),
        reconstruct_boundary_plane(&above.planes[1], &left.planes[1], syntax.coefficients[1]),
        reconstruct_boundary_plane(&above.planes[2], &left.planes[2], syntax.coefficients[2]),
    ];
    ClosedLeaf {
        luma_predictor: syntax.luma_predictor,
        planes,
    }
}

fn reconstruct_boundary_420_leaf(
    syntax: BlockSyntax,
    above: &ClosedLeaf,
    left: &ClosedLeaf,
) -> ClosedLeaf {
    let planes = [
        reconstruct_boundary_plane(&above.planes[0], &left.planes[0], syntax.coefficients[0]),
        reconstruct_subsampled_boundary_plane(
            &above.planes[1],
            &left.planes[1],
            syntax.coefficients[1],
        ),
        reconstruct_subsampled_boundary_plane(
            &above.planes[2],
            &left.planes[2],
            syntax.coefficients[2],
        ),
    ];
    ClosedLeaf {
        luma_predictor: syntax.luma_predictor,
        planes,
    }
}

fn decode_following_square_syntax<F>(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
    context: FollowingSyntaxContext,
    between_leaves: &mut F,
) -> PortableResult<BlockSyntax>
where
    F: FnMut(&mut RangeDecoder<'_, '_, '_>) -> PortableResult<()>,
{
    let FollowingSyntaxContext {
        transform_grid,
        chroma_sampling,
        spatial_luma_context,
        coefficient_policy,
        tools,
    } = context;
    between_leaves(decoder)?;
    decode_syntax(
        decoder,
        cdfs,
        transform_grid,
        chroma_sampling,
        SyntaxPolicy {
            spatial_luma_context,
            coefficient_policy,
            quantization_syntax: QuantizationSyntax::Lossless,
            allow_horizontal_chroma: false,
            allow_diagonal_chroma: false,
            allow_diagonal_luma: false,
            allow_smooth_chroma: false,
            allow_smooth_luma: false,
        },
        tools,
    )
}

#[expect(
    clippy::too_many_arguments,
    reason = "the visible leaf carries the decoded block, geometry, transform context, and edge context together"
)]
fn visible_leaf(
    leaf: ClosedLeaf,
    chroma_predictor: Option<ChromaPredictor>,
    transform_grid: TransformGrid,
    width: u32,
    height: u32,
    chroma_sampling: ChromaSampling,
    tx_context: (u8, u8),
    luma_transform_split: bool,
    luma_edge_contexts: ([u8; 8], [u8; 8]),
) -> FirstLeaf {
    let (transform_grid_width, _, _) = transform_grid.properties();
    let coded_width = transform_grid_width.saturating_mul(4);
    let (chroma_coded_width, chroma_width, chroma_height) =
        if matches!(chroma_sampling, ChromaSampling::Subsampled420) {
            (
                transform_grid_width.div_ceil(2).saturating_mul(4),
                width.div_ceil(2).max(4),
                height.div_ceil(2).max(4),
            )
        } else {
            (coded_width, width, height)
        };
    let planes = [
        visible_plane(&leaf.planes[0], coded_width, width, height),
        visible_plane(
            &leaf.planes[1],
            chroma_coded_width,
            chroma_width,
            chroma_height,
        ),
        visible_plane(
            &leaf.planes[2],
            chroma_coded_width,
            chroma_width,
            chroma_height,
        ),
    ];
    FirstLeaf {
        width,
        height,
        planes,
        luma_predictor: leaf.luma_predictor,
        chroma_predictor,
        luma_context: 0x40,
        chroma_contexts: [0x40; 2],
        chroma_right_contexts: [[0x40; 8]; 2],
        chroma_bottom_contexts: [[0x40; 8]; 2],
        tx_context_width: tx_context.0,
        tx_context_height: tx_context.1,
        luma_transform_split,
        luma_right_contexts: luma_edge_contexts.0,
        luma_bottom_contexts: luma_edge_contexts.1,
        palette_cache: PaletteCacheState::default(),
        #[cfg(coverage)]
        entropy_operations: Vec::new(),
    }
}

fn with_palette_cache(mut leaf: FirstLeaf, palette_cache: PaletteCacheState) -> FirstLeaf {
    leaf.palette_cache = palette_cache;
    leaf
}

fn luma_edge_contexts_for_syntax(syntax: &BlockSyntax) -> ([u8; 8], [u8; 8]) {
    let fallback = lossy_luma_context(syntax);
    let mut right = [fallback; 8];
    let mut bottom = [fallback; 8];
    if let Some(split) = syntax.lossy_luma_8x8_grid_split.as_ref() {
        match split.orientation {
            SplitOrientation::Vertical => {
                for (index, context) in split.right_contexts.into_iter().enumerate() {
                    right[index * 2..index * 2 + 2].fill(context);
                }
                for (index, context) in split.bottom_contexts.into_iter().take(2).enumerate() {
                    bottom[index * 2..index * 2 + 2].fill(context);
                }
            }
            SplitOrientation::Horizontal => {
                for (index, context) in split.right_contexts.into_iter().take(2).enumerate() {
                    right[index * 2..index * 2 + 2].fill(context);
                }
                for (index, context) in split.bottom_contexts.into_iter().enumerate() {
                    bottom[index * 2..index * 2 + 2].fill(context);
                }
            }
        }
    } else if let Some(split) = syntax.lossy_luma_16x16_vertical_split.as_ref() {
        // A 16×64 leaf has sixteen right-edge 4×4 segments. The current
        // frame-state edge buffer retains the first eight; all four coded
        // segments of the bottom edge share the final 16×16 child context.
        for (index, context) in split.right_contexts.into_iter().take(2).enumerate() {
            right[index * 4..index * 4 + 4].fill(context);
        }
        bottom[..4].fill(split.bottom_context);
    } else if let Some(split) = syntax.lossy_luma_16x16_horizontal_split.as_ref() {
        right[..4].fill(split.right_context);
        for (index, context) in split.bottom_contexts.into_iter().enumerate() {
            bottom[index * 4..index * 4 + 4].fill(context);
        }
    } else if let Some(split) = syntax.lossy_luma_16x16_split.as_ref() {
        for (index, context) in split.right_contexts.into_iter().enumerate() {
            right[index * 4..index * 4 + 4].fill(context);
        }
        for (index, context) in split.bottom_contexts.into_iter().enumerate() {
            bottom[index * 4..index * 4 + 4].fill(context);
        }
    } else if let Some(split) = syntax.lossy_luma_8x8_split.as_ref() {
        for (index, context) in split.right_contexts.into_iter().enumerate() {
            right[index * 2..index * 2 + 2].fill(context);
        }
        for (index, context) in split.bottom_contexts.into_iter().enumerate() {
            bottom[index * 2..index * 2 + 2].fill(context);
        }
    } else if let Some(split) = syntax.lossy_luma_4x4_split.as_ref() {
        if split.grid_width == 1 && split.grid_height == 4 {
            right[..4].copy_from_slice(&split.right_contexts[..4]);
            bottom[0] = split.bottom_contexts[0];
        } else {
            right[..2].copy_from_slice(&split.right_contexts[..2]);
            bottom[..2].copy_from_slice(&split.bottom_contexts[..2]);
        }
    }
    (right, bottom)
}

fn chroma_edge_contexts_for_syntax(syntax: &BlockSyntax) -> ([[u8; 8]; 2], [[u8; 8]; 2]) {
    let fallback = lossy_chroma_contexts(syntax);
    let mut right = fallback.map(|context| [context; 8]);
    let mut bottom = fallback.map(|context| [context; 8]);
    for plane in 0..2 {
        if let Some(split) = syntax.lossy_chroma_4x4_splits[plane].as_ref() {
            right[plane][..2].copy_from_slice(&split.right_contexts);
            bottom[plane][..2].copy_from_slice(&split.bottom_contexts);
        }
    }
    (right, bottom)
}

fn combined_luma_edge_contexts(
    first: Option<&FirstLeaf>,
    second: Option<&FirstLeaf>,
    needed: usize,
    bottom_edge: bool,
) -> [u8; 16] {
    combined_luma_edge_contexts_from_neighbors(&[first, second], needed, bottom_edge)
}

pub(super) fn combined_luma_edge_contexts_from_neighbors(
    neighbors: &[Option<&FirstLeaf>],
    needed: usize,
    bottom_edge: bool,
) -> [u8; 16] {
    let positioned: Vec<_> = neighbors
        .iter()
        .copied()
        .flatten()
        .map(|neighbor| (neighbor, 0))
        .collect();
    combined_luma_edge_contexts_from_positioned_neighbors(&positioned, needed, bottom_edge)
}

pub(super) fn combined_luma_edge_contexts_from_positioned_neighbors(
    neighbors: &[(&FirstLeaf, usize)],
    needed: usize,
    bottom_edge: bool,
) -> [u8; 16] {
    let mut contexts = [0x40_u8; 16];
    let mut offset = 0_usize;
    let mut previous = None;
    for &(neighbor, edge_offset) in neighbors {
        if previous.is_some_and(|prior| std::ptr::eq(prior, neighbor)) {
            continue;
        }
        if offset >= needed {
            break;
        }
        // A normal transform contributes its finalized residual context over
        // the whole edge. The per-edge arrays are only meaningful for the
        // admitted split 8x8 tree, where each 4x4 child can leave a different
        // context. Using those arrays for a normal leaf replays the syntax's
        // input fallback rather than the context dav1d stores after coding.
        let fallback_edge = [neighbor.luma_context; 8];
        let has_split_edge =
            neighbor.luma_transform_split && (neighbor.width >= 8 || neighbor.height >= 8);
        let edge = if has_split_edge {
            if bottom_edge {
                &neighbor.luma_bottom_contexts
            } else {
                &neighbor.luma_right_contexts
            }
        } else {
            &fallback_edge
        };
        let dimension = if bottom_edge {
            neighbor.width
        } else {
            neighbor.height
        };
        let edge_offset = edge_offset.min(edge.len());
        let available = usize::try_from(dimension.div_ceil(4))
            .unwrap_or(0)
            .saturating_sub(edge_offset)
            .min(edge.len().saturating_sub(edge_offset));
        let count = available.min(needed.saturating_sub(offset));
        if let Some(destination) = contexts.get_mut(offset..offset.saturating_add(count))
            && let Some(source) = edge.get(edge_offset..edge_offset.saturating_add(count))
        {
            destination.copy_from_slice(source);
        }
        offset = offset.saturating_add(count);
        previous = Some(neighbor);
    }
    contexts
}

fn combined_chroma_edge_contexts(
    first: Option<&FirstLeaf>,
    second: Option<&FirstLeaf>,
    plane: usize,
    needed: usize,
    bottom_edge: bool,
) -> [u8; 8] {
    combined_chroma_edge_contexts_from_neighbors(&[first, second], plane, needed, bottom_edge)
}

pub(super) fn combined_chroma_edge_contexts_from_neighbors(
    neighbors: &[Option<&FirstLeaf>],
    plane: usize,
    needed: usize,
    bottom_edge: bool,
) -> [u8; 8] {
    let positioned: Vec<_> = neighbors
        .iter()
        .copied()
        .flatten()
        .map(|neighbor| (neighbor, 0))
        .collect();
    combined_chroma_edge_contexts_from_positioned_neighbors(&positioned, plane, needed, bottom_edge)
}

pub(super) fn combined_chroma_edge_contexts_from_positioned_neighbors(
    neighbors: &[(&FirstLeaf, usize)],
    plane: usize,
    needed: usize,
    bottom_edge: bool,
) -> [u8; 8] {
    combined_chroma_edge_contexts_from_positioned_neighbors_with_stride(
        neighbors,
        plane,
        needed,
        bottom_edge,
        8,
    )
}

/// Combine positioned full-resolution chroma edge contexts.
///
/// Full-resolution I444 keeps one chroma transform context for every 4-pixel
/// edge segment. The existing chroma combiner intentionally uses an 8-pixel
/// stride for 4:2:0, so this named entry point keeps the two coordinate
/// systems distinct at the call site.
pub(super) fn combined_full_chroma_edge_contexts_from_positioned_neighbors(
    neighbors: &[(&FirstLeaf, usize)],
    plane: usize,
    needed: usize,
    bottom_edge: bool,
) -> [u8; 8] {
    combined_chroma_edge_contexts_from_positioned_neighbors_with_stride(
        neighbors,
        plane,
        needed,
        bottom_edge,
        4,
    )
}

fn combined_chroma_edge_contexts_from_positioned_neighbors_with_stride(
    neighbors: &[(&FirstLeaf, usize)],
    plane: usize,
    needed: usize,
    bottom_edge: bool,
    context_stride_pixels: u32,
) -> [u8; 8] {
    let mut contexts = [0x40_u8; 8];
    let mut offset = 0_usize;
    let mut previous = None;
    for &(neighbor, edge_offset) in neighbors {
        if previous.is_some_and(|prior| std::ptr::eq(prior, neighbor)) {
            continue;
        }
        if offset >= needed {
            break;
        }
        let edge = if bottom_edge {
            &neighbor.chroma_bottom_contexts[plane]
        } else {
            &neighbor.chroma_right_contexts[plane]
        };
        let dimension = if bottom_edge {
            neighbor.width
        } else {
            neighbor.height
        };
        let edge_offset = edge_offset.min(edge.len());
        let available = usize::try_from(dimension.div_ceil(context_stride_pixels))
            .unwrap_or(0)
            .saturating_sub(edge_offset)
            .min(edge.len().saturating_sub(edge_offset));
        let count = available.min(needed.saturating_sub(offset));
        if let Some(destination) = contexts.get_mut(offset..offset.saturating_add(count))
            && let Some(source) = edge.get(edge_offset..edge_offset.saturating_add(count))
        {
            destination.copy_from_slice(source);
        }
        offset = offset.saturating_add(count);
        previous = Some(neighbor);
    }
    contexts
}

fn transform_context_dimension(units: usize) -> u8 {
    match units {
        1 => 0,
        2 => 1,
        4 => 2,
        8 => 3,
        16 => 4,
        _ => 0,
    }
}

fn luma_transform_context(transform_grid: TransformGrid, split: bool) -> (u8, u8) {
    if split {
        // A split transform publishes the size of its terminal transform on
        // the corresponding edge. Square8 is split into 4x4 transforms,
        // while Square16 is split into 8x8 transforms. The latter distinction
        // is observable by the next block's transform-size CDF context.
        return match transform_grid {
            TransformGrid::Horizontal16x8 | TransformGrid::Vertical8x16 => (1, 1),
            TransformGrid::Horizontal32x8 => (1, 1),
            TransformGrid::Square16 => (1, 1),
            TransformGrid::Vertical16x32 => (1, 1),
            TransformGrid::Vertical16x64 => (2, 2),
            TransformGrid::Square32 => (2, 2),
            _ => (0, 0),
        };
    }
    let (width, height, _) = transform_grid.properties();
    (
        transform_context_dimension(width),
        transform_context_dimension(height),
    )
}

fn with_lossy_chroma_edge_contexts(
    mut leaf: FirstLeaf,
    contexts: [u8; 2],
    right: [[u8; 8]; 2],
    bottom: [[u8; 8]; 2],
) -> FirstLeaf {
    leaf.chroma_contexts = contexts;
    leaf.chroma_right_contexts = right;
    leaf.chroma_bottom_contexts = bottom;
    leaf
}

fn with_lossy_chroma_contexts(leaf: FirstLeaf, contexts: [u8; 2]) -> FirstLeaf {
    with_lossy_chroma_edge_contexts(
        leaf,
        contexts,
        contexts.map(|context| [context; 8]),
        contexts.map(|context| [context; 8]),
    )
}

fn with_lossy_luma_context(mut leaf: FirstLeaf, context: u8) -> FirstLeaf {
    leaf.luma_context = context;
    leaf
}

/// Decode and reconstruct the first complete closed leaf syntax class.
pub(super) fn decode_first_lossless_444_leaf(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    width: u32,
    height: u32,
    transform_grid: TransformGrid,
    tools: BlockTools,
) -> PortableResult<FirstLeaf> {
    let (_, _, use_filter_intra) = transform_grid.properties();
    let mut cdfs = BlockCdfs::defaults(use_filter_intra);
    let syntax = decode_syntax(
        decoder,
        &mut cdfs,
        transform_grid,
        ChromaSampling::Full,
        SyntaxPolicy {
            spatial_luma_context: SpatialLumaContext::Origin,
            coefficient_policy: CoefficientPolicy::DcOrSkipped,
            quantization_syntax: QuantizationSyntax::Lossless,
            allow_horizontal_chroma: false,
            allow_diagonal_chroma: false,
            allow_diagonal_luma: false,
            allow_smooth_chroma: false,
            allow_smooth_luma: false,
        },
        tools,
    )?;
    let predictors = origin_predictors(syntax.luma_predictor);
    let leaf = reconstruct_leaf(syntax, predictors);
    Ok(visible_leaf(
        leaf,
        Some(syntax.chroma_predictor),
        transform_grid,
        width,
        height,
        ChromaSampling::Full,
        luma_transform_context(transform_grid, false),
        false,
        ([0x40; 8], [0x40; 8]),
    ))
}

impl Lossless444Leaf {
    fn new(
        geometry: Lossless444BlockGeometry,
        right_contexts: [[u8; 8]; 3],
        bottom_contexts: [[u8; 8]; 3],
        closed: ClosedLeaf,
    ) -> PortableResult<Self> {
        let (grid_width, grid_height, _) = geometry.transform_grid.properties();
        let expected_width =
            u32::try_from(grid_width.saturating_mul(4)).map_err(|_| PortableUnavailable)?;
        let expected_height =
            u32::try_from(grid_height.saturating_mul(4)).map_err(|_| PortableUnavailable)?;
        let expected_samples = usize::try_from(geometry.width)
            .ok()
            .and_then(|width| {
                usize::try_from(geometry.height)
                    .ok()
                    .and_then(|height| width.checked_mul(height))
            })
            .ok_or(PortableUnavailable)?;
        if geometry.width != expected_width
            || geometry.height != expected_height
            || closed
                .planes
                .iter()
                .any(|plane| plane.samples.len() != expected_samples)
        {
            return Err(PortableUnavailable);
        }
        Ok(Self {
            origin_x: geometry.origin_x,
            origin_y: geometry.origin_y,
            width: geometry.width,
            height: geometry.height,
            closed,
            right_contexts,
            bottom_contexts,
        })
    }

    pub(super) const fn origin_x(&self) -> u32 {
        self.origin_x
    }

    pub(super) const fn origin_y(&self) -> u32 {
        self.origin_y
    }

    pub(super) const fn width(&self) -> u32 {
        self.width
    }

    pub(super) const fn height(&self) -> u32 {
        self.height
    }

    pub(super) fn planes(&self) -> &[ReconstructedPlane; 3] {
        &self.closed.planes
    }
}

impl Lossless444Decoder {
    pub(super) fn new() -> Self {
        Self {
            cdfs: BlockCdfs::defaults([24_902, 0]),
        }
    }

    pub(super) fn decode_origin(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        geometry: Lossless444BlockGeometry,
        tools: BlockTools,
    ) -> PortableResult<Lossless444Leaf> {
        let syntax = match decode_syntax(
            decoder,
            &mut self.cdfs,
            geometry.transform_grid,
            ChromaSampling::Full,
            SyntaxPolicy {
                spatial_luma_context: SpatialLumaContext::Origin,
                coefficient_policy: CoefficientPolicy::ColorFrameTopLeft,
                quantization_syntax: QuantizationSyntax::Lossless,
                allow_horizontal_chroma: true,
                allow_diagonal_chroma: true,
                allow_diagonal_luma: true,
                allow_smooth_chroma: true,
                allow_smooth_luma: true,
            },
            tools,
        ) {
            Ok(syntax) => syntax,
            Err(error) => {
                return Err(error);
            }
        };
        let right_contexts = coefficient_edge_contexts_wide(
            &syntax.coefficients,
            SplitOrientation::Horizontal,
            syntax.transform_grid,
            ChromaSampling::Full,
        )?;
        let bottom_contexts = coefficient_edge_contexts_wide(
            &syntax.coefficients,
            SplitOrientation::Vertical,
            syntax.transform_grid,
            ChromaSampling::Full,
        )?;
        let closed = reconstruct_lossless444_leaf(
            syntax,
            geometry,
            None,
            [None; 8],
            None,
            [None; 8],
            [None; 8],
            tools.enable_intra_edge_filter,
        )?;
        Lossless444Leaf::new(geometry, right_contexts, bottom_contexts, closed)
    }

    pub(super) fn decode_following(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        geometry: Lossless444BlockGeometry,
        neighbors: Lossless444Neighbors<'_>,
        tools: BlockTools,
    ) -> PortableResult<Lossless444Leaf> {
        let Lossless444Neighbors {
            above_left,
            above,
            above_right,
            left,
            left_below,
        } = neighbors;
        let above_leaf = above.iter().flatten().next().copied();
        let left_leaf = left.iter().flatten().next().copied();
        let above_contexts = lossless444_neighbor_contexts(above, geometry, true)?;
        let left_contexts = lossless444_neighbor_contexts(left, geometry, false)?;
        let (spatial_luma_context, coefficient_policy, _orientation) = match (above, left) {
            (above, left)
                if above.iter().all(Option::is_none) && left.iter().all(Option::is_none) =>
            {
                (
                    SpatialLumaContext::Origin,
                    CoefficientPolicy::DcOrSkipped,
                    None,
                )
            }
            (_, _) if left.iter().all(Option::is_none) => (
                SpatialLumaContext::from_neighbor(
                    SplitOrientation::Vertical,
                    above_leaf.ok_or(PortableUnavailable)?.closed.luma_predictor,
                ),
                CoefficientPolicy::ColorFrameSquareContextual {
                    neighbor_contexts: above_contexts,
                    orientation: SplitOrientation::Vertical,
                },
                Some(SplitOrientation::Vertical),
            ),
            (_, _) if above.iter().all(Option::is_none) => (
                SpatialLumaContext::from_neighbor(
                    SplitOrientation::Horizontal,
                    left_leaf.ok_or(PortableUnavailable)?.closed.luma_predictor,
                ),
                CoefficientPolicy::ColorFrameSquareContextual {
                    neighbor_contexts: left_contexts,
                    orientation: SplitOrientation::Horizontal,
                },
                Some(SplitOrientation::Horizontal),
            ),
            (_, _) => (
                SpatialLumaContext::from_two_neighbors(
                    above_leaf.ok_or(PortableUnavailable)?.closed.luma_predictor,
                    left_leaf.ok_or(PortableUnavailable)?.closed.luma_predictor,
                )?,
                CoefficientPolicy::ColorFrameBoundaryContextual {
                    above_contexts,
                    left_contexts,
                },
                None,
            ),
        };
        let syntax = match decode_syntax(
            decoder,
            &mut self.cdfs,
            geometry.transform_grid,
            ChromaSampling::Full,
            SyntaxPolicy {
                spatial_luma_context,
                coefficient_policy,
                quantization_syntax: QuantizationSyntax::Lossless,
                allow_horizontal_chroma: true,
                allow_diagonal_chroma: true,
                allow_diagonal_luma: true,
                allow_smooth_chroma: true,
                allow_smooth_luma: true,
            },
            tools,
        ) {
            Ok(syntax) => syntax,
            Err(error) => {
                return Err(error);
            }
        };
        let right_contexts = coefficient_edge_contexts_wide(
            &syntax.coefficients,
            SplitOrientation::Horizontal,
            syntax.transform_grid,
            ChromaSampling::Full,
        )?;
        let bottom_contexts = coefficient_edge_contexts_wide(
            &syntax.coefficients,
            SplitOrientation::Vertical,
            syntax.transform_grid,
            ChromaSampling::Full,
        )?;
        let closed = match reconstruct_lossless444_leaf(
            syntax,
            geometry,
            above_left,
            above,
            above_right,
            left,
            left_below,
            tools.enable_intra_edge_filter,
        ) {
            Ok(closed) => closed,
            Err(error) => {
                return Err(error);
            }
        };
        Lossless444Leaf::new(geometry, right_contexts, bottom_contexts, closed)
    }
}

impl MonochromeLosslessDecoder {
    pub(super) fn new() -> Self {
        Self {
            cdfs: BlockCdfs::defaults([20_360, 0]),
        }
    }

    pub(super) fn decode_origin(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        geometry: MonochromeBlockGeometry,
        tools: BlockTools,
    ) -> PortableResult<MonochromeLeaf> {
        self.decode(
            decoder,
            MonochromeDecodeContext {
                geometry,
                spatial_luma_context: SpatialLumaContext::Origin,
                above_contexts: [0x40; 16],
                left_contexts: [0x40; 16],
                tools,
                above_left: None,
                above: None,
                above_right: [None; 8],
                left: None,
                left_below: None,
            },
        )
    }

    pub(super) fn decode_following(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        geometry: MonochromeBlockGeometry,
        neighbors: MonochromeNeighbors<'_>,
        tools: BlockTools,
    ) -> PortableResult<MonochromeLeaf> {
        let MonochromeNeighbors {
            above_left,
            above,
            above_right,
            left,
            left_below,
        } = neighbors;
        let spatial_left = left.or(left_below);
        let spatial_luma_context = match (above, spatial_left) {
            (None, None) => SpatialLumaContext::Origin,
            (Some(above), None) => {
                SpatialLumaContext::from_neighbor(SplitOrientation::Vertical, above.predictor)
            }
            (None, Some(left)) => {
                SpatialLumaContext::from_neighbor(SplitOrientation::Horizontal, left.predictor)
            }
            (Some(above), Some(left)) => {
                SpatialLumaContext::from_two_monochrome_neighbors(above.predictor, left.predictor)?
            }
        };
        let above_contexts = if above.is_some() || above_right.iter().any(Option::is_some) {
            aligned_above_edge_contexts(above, &above_right, geometry.origin_x, geometry.origin_y)?
        } else {
            [0x40; 16]
        };
        let left_contexts = match left {
            Some(leaf) => aligned_edge_contexts(leaf, geometry.origin_x, geometry.origin_y, false)?,
            None => [0x40; 16],
        };
        let mut left_contexts = left_contexts;
        if let Some(leaf) = left_below {
            if leaf.origin_y < geometry.origin_y {
                return Err(PortableUnavailable);
            }
            let row_offset = usize::try_from(
                leaf.origin_y
                    .saturating_sub(geometry.origin_y)
                    .checked_div(4)
                    .ok_or(PortableUnavailable)?,
            )
            .map_err(|_| PortableUnavailable)?;
            for (index, context) in leaf.right_contexts.iter().enumerate() {
                if let Some(slot) = left_contexts.get_mut(row_offset.saturating_add(index)) {
                    *slot = *context;
                }
            }
        }
        self.decode(
            decoder,
            MonochromeDecodeContext {
                geometry,
                spatial_luma_context,
                above_contexts,
                left_contexts,
                tools,
                above_left,
                above,
                above_right,
                left,
                left_below,
            },
        )
    }

    fn decode<'a>(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        context: MonochromeDecodeContext<'a>,
    ) -> PortableResult<MonochromeLeaf> {
        let MonochromeDecodeContext {
            geometry,
            spatial_luma_context,
            above_contexts,
            left_contexts,
            tools,
            above_left,
            above,
            above_right,
            left,
            left_below,
        } = context;
        let syntax_result = decode_syntax(
            decoder,
            &mut self.cdfs,
            geometry.transform_grid,
            ChromaSampling::Monochrome,
            SyntaxPolicy {
                spatial_luma_context,
                coefficient_policy: CoefficientPolicy::MonochromeContextual {
                    above_contexts,
                    left_contexts,
                },
                quantization_syntax: QuantizationSyntax::Lossless,
                allow_horizontal_chroma: true,
                allow_diagonal_chroma: true,
                allow_diagonal_luma: true,
                allow_smooth_chroma: false,
                allow_smooth_luma: true,
            },
            tools,
        );
        let syntax = match syntax_result {
            Ok(syntax) => syntax,
            Err(error) => {
                return Err(error);
            }
        };

        reconstruct_monochrome_leaf(
            syntax,
            geometry,
            MonochromeNeighbors {
                above_left,
                above,
                above_right,
                left,
                left_below,
            },
            tools.enable_intra_edge_filter,
        )
    }
}

fn paeth_predictor(top: u16, left: u16, top_left: u16) -> u16 {
    let top = i32::from(top);
    let left = i32::from(left);
    let top_left = i32::from(top_left);
    let estimate = top.saturating_add(left).saturating_sub(top_left);
    let top_distance = estimate.saturating_sub(top).unsigned_abs();
    let left_distance = estimate.saturating_sub(left).unsigned_abs();
    let top_left_distance = estimate.saturating_sub(top_left).unsigned_abs();
    if top_distance <= left_distance && top_distance <= top_left_distance {
        return u16::try_from(top).unwrap_or(0);
    }
    if left_distance <= top_left_distance {
        return u16::try_from(left).unwrap_or(0);
    }
    u16::try_from(top_left).unwrap_or(0)
}

fn smooth_weight_table(size: usize) -> PortableResult<&'static [u16]> {
    // ✅ VERIFIED: dav1d 1.5.3 src/tables.c `dav1d_sm_weights`, indexed by
    // the coded block width or height. These are the AV1 smooth-predictor
    // weights, not an approximation derived from the fixture.
    const WEIGHTS_8: [u16; 8] = [255, 197, 146, 105, 73, 50, 37, 32];
    const WEIGHTS_4: [u16; 4] = [255, 149, 85, 64];
    const WEIGHTS_16: [u16; 16] = [
        255, 225, 196, 170, 145, 123, 102, 84, 68, 54, 43, 33, 26, 20, 17, 16,
    ];
    const WEIGHTS_32: [u16; 32] = [
        255, 240, 225, 210, 196, 182, 169, 157, 145, 133, 122, 111, 101, 92, 83, 74, 66, 59, 52,
        45, 39, 34, 29, 25, 21, 17, 14, 12, 10, 9, 8, 8,
    ];
    match size {
        4 => Ok(&WEIGHTS_4),
        8 => Ok(&WEIGHTS_8),
        16 => Ok(&WEIGHTS_16),
        32 => Ok(&WEIGHTS_32),
        _ => Err(PortableUnavailable),
    }
}

fn aligned_edge_contexts(
    leaf: &MonochromeLeaf,
    origin_x: u32,
    origin_y: u32,
    above: bool,
) -> PortableResult<[u8; 16]> {
    let (neighbor_origin, edge_contexts) = if above {
        (leaf.origin_x, leaf.bottom_contexts)
    } else {
        (leaf.origin_y, leaf.right_contexts)
    };
    if origin_x < leaf.origin_x || origin_y < leaf.origin_y {
        return Err(PortableUnavailable);
    }
    let offset = if above {
        origin_x.saturating_sub(neighbor_origin)
    } else {
        origin_y.saturating_sub(neighbor_origin)
    };
    if offset % 4 != 0 {
        return Err(PortableUnavailable);
    }
    let start = usize::try_from(offset / 4).map_err(|_| PortableUnavailable)?;
    if start > edge_contexts.len() {
        return Err(PortableUnavailable);
    }
    let mut result = [0x40_u8; 16];
    for (index, context) in result.iter_mut().enumerate() {
        if let Some(value) = edge_contexts.get(start.saturating_add(index)) {
            *context = *value;
        }
    }
    Ok(result)
}

fn aligned_above_edge_contexts(
    above: Option<&MonochromeLeaf>,
    above_right: &[Option<&MonochromeLeaf>; 8],
    origin_x: u32,
    origin_y: u32,
) -> PortableResult<[u8; 16]> {
    let mut result = [0x40_u8; 16];
    let mut candidates = Vec::with_capacity(above_right.len().saturating_add(1));
    if let Some(leaf) = above {
        candidates.push(leaf);
    }
    candidates.extend(above_right.iter().flatten().copied());
    for leaf in candidates {
        if leaf.origin_y.checked_add(leaf.height) != Some(origin_y) {
            continue;
        }
        let (source_start, destination_start) = if leaf.origin_x <= origin_x {
            let offset = origin_x
                .checked_sub(leaf.origin_x)
                .filter(|offset| offset % 4 == 0)
                .ok_or(PortableUnavailable)?;
            (
                usize::try_from(offset / 4).map_err(|_| PortableUnavailable)?,
                0,
            )
        } else {
            let offset = leaf
                .origin_x
                .checked_sub(origin_x)
                .filter(|offset| offset % 4 == 0)
                .ok_or(PortableUnavailable)?;
            (
                0,
                usize::try_from(offset / 4).map_err(|_| PortableUnavailable)?,
            )
        };
        let source_count = usize::try_from(leaf.width.div_ceil(4))
            .map_err(|_| PortableUnavailable)?
            .min(leaf.bottom_contexts.len().saturating_sub(source_start));
        for source_index in 0..source_count {
            let destination = destination_start.saturating_add(source_index);
            if let Some(slot) = result.get_mut(destination) {
                *slot = leaf.bottom_contexts[source_start.saturating_add(source_index)];
            }
        }
    }
    Ok(result)
}

fn monochrome_sample_at(leaf: &MonochromeLeaf, x: u32, y: u32) -> Option<u16> {
    let local_x = x.checked_sub(leaf.origin_x)?;
    let local_y = y.checked_sub(leaf.origin_y)?;
    if local_x >= leaf.width || local_y >= leaf.height {
        return None;
    }
    let width = usize::try_from(leaf.width).ok()?;
    let local_x = usize::try_from(local_x).ok()?;
    let local_y = usize::try_from(local_y).ok()?;
    let index = local_y.checked_mul(width)?.checked_add(local_x)?;
    leaf.plane.samples.get(index).copied()
}

fn monochrome_sample_from_neighbors(
    first: Option<&MonochromeLeaf>,
    second: Option<&MonochromeLeaf>,
    x: u32,
    y: u32,
) -> Option<u16> {
    first
        .and_then(|leaf| monochrome_sample_at(leaf, x, y))
        .or_else(|| second.and_then(|leaf| monochrome_sample_at(leaf, x, y)))
}

fn diagonal_predictor_sample(
    edge: &[u16],
    left_length: usize,
    dx: i32,
    dy: i32,
    x: usize,
    y: usize,
) -> PortableResult<u16> {
    let x = i32::try_from(x).map_err(|_| PortableUnavailable)?;
    let y = i32::try_from(y).map_err(|_| PortableUnavailable)?;
    let xpos = 64_i32.saturating_sub(dx.saturating_mul(y.saturating_add(1)));
    let base_x = xpos >> 6;
    let frac_x = xpos & 0x3e;
    let sample = if base_x.saturating_add(x) >= 0 {
        let first = i32::try_from(left_length)
            .map_err(|_| PortableUnavailable)?
            .saturating_add(1)
            .saturating_add(base_x)
            .saturating_add(x);
        let first = usize::try_from(first).map_err(|_| PortableUnavailable)?;
        let second = first.checked_add(1).ok_or(PortableUnavailable)?;
        let first = i32::from(*edge.get(first).ok_or(PortableUnavailable)?);
        let second = i32::from(*edge.get(second).ok_or(PortableUnavailable)?);
        first
            .saturating_mul(64_i32.saturating_sub(frac_x))
            .saturating_add(second.saturating_mul(frac_x))
            .saturating_add(32)
            >> 6
    } else {
        let ypos = y
            .saturating_mul(64)
            .saturating_sub(dy.saturating_mul(x.saturating_add(1)));
        let base_y = ypos >> 6;
        let frac_y = ypos & 0x3e;
        let first = i32::try_from(left_length)
            .map_err(|_| PortableUnavailable)?
            .saturating_sub(1)
            .saturating_sub(base_y);
        let second = first.saturating_sub(1);
        let first = usize::try_from(first).map_err(|_| PortableUnavailable)?;
        let second = usize::try_from(second).map_err(|_| PortableUnavailable)?;
        let first = i32::from(*edge.get(first).ok_or(PortableUnavailable)?);
        let second = i32::from(*edge.get(second).ok_or(PortableUnavailable)?);
        first
            .saturating_mul(64_i32.saturating_sub(frac_y))
            .saturating_add(second.saturating_mul(frac_y))
            .saturating_add(32)
            >> 6
    };
    u16::try_from(sample.clamp(0, 255)).map_err(|_| PortableUnavailable)
}

/// Apply AV1's four-tap intra-edge upsampler to one eight-sample edge.
///
/// Upsample the top edge for a Zone 1 directional predictor.
///
/// The reference edge starts one sample after top-left, so the first filtered
/// sample uses top-left as the left tap.  The bounded array implementation is
/// equivalent and remains entirely safe.
fn upsample_z2_top_edge(top: [u16; 16], top_left: u16) -> [u16; 17] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let source: [u16; 9] = std::array::from_fn(|index| {
        if index == 0 {
            top_left
        } else {
            top[index.saturating_sub(1)]
        }
    });
    let mut upsampled = [0_u16; 17];
    for index in 0_usize..8 {
        upsampled[index.saturating_mul(2)] = source[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .min(source.len().saturating_sub(1));
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the upsampled intra edge is explicitly clamped to eight-bit range"
        )]
        {
            upsampled[index.saturating_mul(2).saturating_add(1)] =
                ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
        }
    }
    upsampled[16] = source[8];
    upsampled
}

/// Apply the AV1 Zone-2 four-tap upsampler to a 4×4 chroma top edge.
fn upsample_z2_top_edge_4(top: [u16; 8], top_left: u16) -> [u16; 9] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let source = [top_left, top[0], top[1], top[2], top[3]];
    let mut upsampled = [0_u16; 9];
    for index in 0_usize..4 {
        upsampled[index.saturating_mul(2)] = source[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .min(source.len().saturating_sub(1));
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the upsampled intra edge is explicitly clamped to eight-bit range"
        )]
        {
            upsampled[index.saturating_mul(2).saturating_add(1)] =
                ((sum.saturating_add(8) >> 4).clamp(0, 255)) as u16;
        }
    }
    upsampled[8] = source[4];
    upsampled
}

fn upsample_z2_left_edge(left: [u16; 8], top_left: u16) -> [u16; 17] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let source: [u16; 9] = std::array::from_fn(|index| {
        if index < left.len() {
            left[left.len().saturating_sub(1).saturating_sub(index)]
        } else {
            top_left
        }
    });
    let mut upsampled = [0_u16; 17];
    for index in 0_usize..8 {
        upsampled[index.saturating_mul(2)] = source[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .min(source.len().saturating_sub(1));
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the upsampled intra edge is explicitly clamped to eight-bit range"
        )]
        {
            upsampled[index.saturating_mul(2).saturating_add(1)] =
                ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
        }
    }
    upsampled[16] = source[8];
    upsampled
}

fn filter_z2_left_edge(edge: [u16; 8], top_left: u16, strength: usize) -> [u16; 8] {
    if strength == 0 {
        return edge;
    }
    const KERNELS: [[i32; 5]; 3] = [[0, 4, 8, 4, 0], [0, 5, 6, 5, 0], [2, 4, 4, 4, 2]];
    let kernel = KERNELS[strength.saturating_sub(1).min(2)];
    let source: [u16; 9] = std::array::from_fn(|index| {
        if index < edge.len() {
            edge[edge.len().saturating_sub(1).saturating_sub(index)]
        } else {
            top_left
        }
    });
    let filtered_reverse: [u16; 8] = std::array::from_fn(|index| {
        let mut sum = 0_i32;
        for (tap, weight) in kernel.into_iter().enumerate() {
            let source_index = i32::try_from(index)
                .unwrap_or(0)
                .saturating_add(i32::try_from(tap).unwrap_or(0))
                .saturating_sub(2)
                .clamp(
                    0,
                    i32::try_from(source.len().saturating_sub(1)).unwrap_or(0),
                );
            let source_index = usize::try_from(source_index).unwrap_or(0);
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the filtered intra edge is explicitly clamped to eight-bit range"
        )]
        {
            ((sum.saturating_add(8) >> 4).clamp(0, 255)) as u16
        }
    });
    std::array::from_fn(|index| {
        filtered_reverse[edge.len().saturating_sub(1).saturating_sub(index)]
    })
}

fn filter_z3_left_edge_16(edge: [u16; 16], top_left: u16, strength: usize) -> [u16; 16] {
    if strength == 0 {
        return edge;
    }
    const KERNELS: [[i32; 5]; 3] = [[0, 4, 8, 4, 0], [0, 5, 6, 5, 0], [2, 4, 4, 4, 2]];
    let kernel = KERNELS[strength.saturating_sub(1).min(2)];
    let filtered_reverse: [u16; 16] = std::array::from_fn(|index| {
        let mut sum = 0_i32;
        for (tap, weight) in kernel.into_iter().enumerate() {
            let source_index = i32::try_from(index)
                .unwrap_or(0)
                .saturating_add(i32::try_from(tap).unwrap_or(0))
                .saturating_sub(2)
                .clamp(0, 16);
            let source = if source_index == 16 {
                top_left
            } else {
                edge[15_usize.saturating_sub(usize::try_from(source_index).unwrap_or(0))]
            };
            sum = sum.saturating_add(i32::from(source).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the filtered intra edge is explicitly clamped to eight-bit range"
        )]
        {
            ((sum.saturating_add(8) >> 4).clamp(0, 255)) as u16
        }
    });
    std::array::from_fn(|index| filtered_reverse[15_usize.saturating_sub(index)])
}

